INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ABD', 'Anthology of Biosurveillance Diseases', 'Our disease ontology provides information on infectious diseases, disease synonyms, transmission pathways, disease agents, affected populations and disease properties. Diseases have been grouped into syndromic disease categories, such that programmers can look through relevant categories, as well as at specific diseases. Organisms, linked to both agents and populations, are structured hierarchically, to provide multiple levels of organism resolution. In addition, both disease transmission and relevant disease properties are available to search. Disease properties include tags like ''notifiable diseases'' and ''economic importance'' to flag particular disease characteristics that may be of interest, but are not captured elsewhere.', 'All_Organisms;Health;Human;Plant', 'OWL', 4, NULL, '2016-09-13T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ABD', '25c157c4fdfa682d80181abf7556bea2a4c177a8bfcdccb3551cd59a9e1b92a7', 'scored', NULL, 9.99, 0.01, 0.01, 'same_as_strict (1.0 result, not re-checked)', 1.62, 9.0, 5.155, 5.155, NULL, NULL, NULL, 10419, 1446, 1446, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:21+00:00', '2026-09-23T23:25:10+00:00');
