INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ACGT-MO', 'Cancer Research and Management ACGT Master Ontology', 'The intention of the ACGT Master Ontology (MO) is to represent the domain of cancer research and management in a computationally tractable manner.', 'Health', 'OWL', 2, '1.1', '2010-01-03T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/ACGT-MO', '8d9f24f0d6790aac2f6c765a98a974a19dd185bb94936e7d859231e2f57b8f09', 'scored', NULL, 9.79, 1.24, 1.24, 'same_as_strict (1.0 result, not re-checked)', 2.73, 10.0, 5.94, 5.94, NULL, NULL, NULL, 13381, 1815, 1770, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:21+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ACVD_ONTOLOGY', 'Atherosclerotic Cerebrovascular Disease Ontology', 'The ontology describes the related aspects of atherosclerotic cerebrovascular disease, and provides a clear set of cross-lingual concepts and terms with an explicit hierarchical structure, helping scientific researchers to quickly retrieve relevant medical literature, assisting data scientists to efficiently identify relevant contents in electronic health records, and providing a clear domain framework for academic reference. The current ontology included 10 top-level classes, respectively clinical manifestation, comorbidity, complication, diagnosis, model of atherosclerotic cerebrovascular disease, pathogenesis, prevention, rehabilitation, risk factor, and treatment. Totally, there are 1715 concepts in the 11-level ontology, covering 4588 Chinese terms, 6617 English terms, and 972 definitions.', 'Neurological_Disorder', 'OWL', 4, '2.0', '2023-06-08T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ACVD_ONTOLOGY', 'def38082c696e85dc8219882ddce9ceb87a79116be52064e173c1d0788c09f03', 'scored', NULL, 9.99, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 4.9975, 4.9975, NULL, NULL, NULL, 21112, 1720, 1720, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:10:24+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'AD-CDO', 'Alzheimer''s Disease Common Data Element Ontology for Clinical Trials', 'The Alzheimer’s Disease Common Data Element Ontology for Clinical Trials (AD-CDO) is a semantically enriched, lightweight ontology designed to represent and standardize key eligibility criteria concepts in Alzheimer’s disease (AD) clinical trials. It bridges the gap between broad biomedical ontologies and the task-specific needs of trial modeling. AD-CDO was constructed by extracting high-frequency concepts from over 1,500 AD interventional trials registered on ClinicalTrials.gov. To balance coverage with manageability, the ontology utilizes the Jenks Natural Breaks method to identify the most representative concepts. The key feature of AD-CDO is its extensive mapping to standardized biomedical vocabularies to support data integration and phenotyping.', 'Biomedical_Resources;Neurologic_Disease;Vocabularies', 'OWL', 2, NULL, '2026-05-21T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/AD-CDO', '4aacdc9c978ea122d71d573d3ec0d28bfcf39a4ef609a5d66c7ffa40b4758e61', 'scored', NULL, 9.97, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.19, 10.0, 5.04, 5.04, NULL, NULL, NULL, 1427, 292, 292, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:05:39+00:00', '2026-09-23T23:25:10+00:00');
