INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ADAR', 'Autism DSM-ADI-R ontology', 'The autism DSM-ADI-R (ADAR) ontology extends an ontology by Tu et al. with additional SWRL rules to infer phenotypes from ADI-R items.
It includes OWL class definitions representing DSM IV diagnostic criteria for autistic disorder and ASD criteria for Autism Spectrum Disorder
OWL Reasoners can thus infer autism-related phenotypes from ADI-R questionnaire results 

Tu SW, Tennakoon L, Connor MO, Das A. Using an Integrated Ontology and Information Model for Querying and Reasoning about Phenotypes : The Case of Autism. AMIA Annu Symp Proc 2008;727–31
', 'Health', 'OWL', 1, '1.1', '2015-03-27T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ADAR', 'b7dbb70681347e51ae81ab88ba4831477efe6b3efdd9f2a14c0f4515399231ac', 'scored', NULL, 5.64, 1.0, 1.0, 'same_as_strict (1.0 result, not re-checked)', 4.0, 10.0, 5.16, 5.16, NULL, NULL, NULL, 62672, 1401, 791, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:19:08+00:00', '2026-09-23T23:25:10+00:00');
