INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ADMO', 'Alzheimer Disease Map Ontology', 'Alzheimer’s disease (AD) pathophysiology is still imperfectly understood and current paradigms have not led to curative outcome. Omics technologies offer great promises for improving our understanding and generating new hypotheses. However, integration and interpretation of such data pose major challenges, calling for adequate knowledge models. AlzPathway is a disease map that gives a detailed and broad account of AD pathophysiology. However, AlzPathway lacks formalism, which can lead to ambiguity and misinterpretation. Ontologies are an adequate framework to overcome this limitation, through their axiomatic definitions and logical reasoning prop-erties. We introduce the AD Map Ontology (ADMO), an ontological upper model based on systems biology terms. We then propose to convert AlzPathway into an ontology and to integrate it into ADMO.', 'Biological_Process;Human', 'OWL', 4, 'beta', '2018-10-17T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ADMO', '0c0fbbfecdf0ace09158ccc0507e0ed244d6b4d374252edf2f911f9e17a90aef', 'scored', NULL, 10.0, 0.02, 0.02, 'same_as_strict (1.0 result, not re-checked)', 7.92, 10.0, 6.985, 6.985, NULL, NULL, NULL, 127673, 10944, 10944, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:20:33+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ADO', 'Alzheimer''s Disease Ontology', 'Alzheimer''s Disease Ontology is a knowledge-based ontology that encompasses varieties of concepts related to Alzheimer''s Disease, structured by upper level Basic Formal Ontology (BFO). This ontology is enriched by the interrelated entities that demonstrate the network of the understanding on Alzheimer''s disease and can be readily applied for text mining.', 'Health;Human;Neurologic_Disease;Neurological_Disorder', 'OWL', 4, '2.0.1', '2023-09-09T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ADO', '98127d34e968a46e742df4127fd6ad3c44156fbdf59c7c92d05e08f1b72bd883', 'scored', NULL, 9.99, 3.98, 3.98, 'same_as_strict (1.0 result, not re-checked)', 0.64, 10.0, 6.1525, 6.1525, NULL, NULL, NULL, 42936, 1964, 1964, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:15:28+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ADW', 'Animal Natural History and Life History Ontology', 'An ontology for animal life history and natural history characteristics suitable for populations and higher taxonomic entities.', 'Anatomy', 'OWL', 2, '10/11/04', '2010-08-31T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/ADW', 'd347739ece9a332a26fa80ccfd59782c9cd0db0d74561872f4288926c3586f89', 'scored', NULL, 9.86, 3.28, 3.28, 'same_as_strict (1.0 result, not re-checked)', 1.65, 10.0, 6.1975, 6.1975, NULL, NULL, NULL, 2188, 369, 365, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:07+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'AEO', 'Anatomical Entity Ontology', 'AEO is an ontology of anatomical structures that expands CARO, the Common Anatomy Reference Ontology, to about 200 classes using the is_a relationship; it thus provides a detailed type classification for tissues. The new classes were chosen for their use in categorizing the major vertebrate and invertebrate anatomy ontologies at a granularity adequate for tissues of a single cell type. The ontology should be useful in increasing the amount of knowledge in anatomy ontologies, facilitating annotation and enabling interoperability across anatomy ontologies', 'Anatomy', 'OWL', 8, NULL, '2026-01-14T18:00:05.000-08:00', 'https://bioportal.bioontology.org/ontologies/AEO', '312cba32bfb983b63f3b35d5a8a806d54f0e2b6f70a2a015c70091e06743a03e', 'scored', NULL, 9.98, 3.51, 3.51, 'same_as_strict (1.0 result, not re-checked)', 4.52, 10.0, 7.0025, 7.0025, NULL, NULL, NULL, 4807, 431, 431, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:09+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'AERO', 'Adverse Event Reporting Ontology', 'The Adverse Event Reporting Ontology (AERO) is an ontology aimed at supporting clinicians at the time of data entry, increasing quality and accuracy of reported adverse events.', 'Biomedical_Resources;Health', 'OWL', 45, 'unknown', '2013-09-12T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/AERO', '09333b6347509f14d150b25e943fc9d65f997b08bdacfe1067adc55524c82367', 'scored', NULL, 10.0, 3.83, 3.83, 'same_as_strict (1.0 result, not re-checked)', 4.94, 10.0, 7.1925, 7.1925, NULL, NULL, NULL, 9820, 524, 497, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:34+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'AFO', 'Allotrope Merged Ontology Suite', '<p><strong>Allotrope Merged Ontology Suite</strong></p>

<p>The AFO is an ontology suite that provides a standard vocabulary and semantic model for the representation of laboratory analytical processes. The AFO suite is aligned at the upper layer to the Basic Formal Ontology (BFO). The core domains modeled include: Equipment, Material, Process, and Results.</p>

<p>license: http://purl.allotrope.org/voc/creative-commons-attribution-license<br/>
rights: http://purl.allotrope.org/voc/copyright<br/></p>', 'Chemical', 'OWL', 45, 'REC/2026/06', '2026-07-07T12:58:41.000+00:00', 'https://bioportal.bioontology.org/ontologies/AFO', '16a26a961d1893fc3aa8e892cb16e77b91c736cff0bb0e8994e12f0a4ff3223e', 'scored', NULL, 10.0, 6.56, 6.56, 'same_as_strict (1.0 result, not re-checked)', 3.36, 10.0, 7.48, 7.48, NULL, NULL, NULL, 49396, 3697, 3641, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:14:40+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'AFPO', 'African Population Ontology', 'AfPO is a tool which enables to annotate the African individuals, and brings together knowledge accumulated about existing populations with their genetic fingerprint in a standardized format.', 'All_Organisms', 'OWL', 1, '2024-03-21', '2024-03-21T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/AFPO', 'c46726d29930f9f76ba76026f39b53bb61bfd4c763094cfb87cee4d1386ababd', 'scored', NULL, 9.98, 4.47, 4.47, 'same_as_strict (1.0 result, not re-checked)', 8.04, 10.0, 8.1225, 8.1225, NULL, NULL, NULL, 18170, 493, 474, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:35+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'AGRO', 'AGRonomy Ontology', 'AGRO, the AGRonomy Ontology, describes agronomic practices, agronomic techniques, and agronomic variables used in agronomic experiments. AGRO is being built using traits identified by agronomists, the ICASA variables, and other existing ontologies such as ENVO, UO, and PATO, IAO, and CHEBI. Further, AGRO will power an Agronomy Management System and fieldbook modeled on a CGIAR Breeding Management System to capture agronomic data.', '', 'OWL', 6, NULL, '2022-11-02T18:00:07.000-07:00', 'https://bioportal.bioontology.org/ontologies/AGRO', 'eae219f3813e5f7d77792b643cb8dcf2c5364ff28b3c00a9e760def3e03dedad', 'scored', NULL, 9.42, 4.24, 4.24, 'same_as_strict (1.0 result, not re-checked)', 5.51, 10.0, 7.2925, 7.2925, NULL, NULL, NULL, 81505, 4437, 4163, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:18:05+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'AGROCYMAC', 'Control y Monitoreo de afecciones en los cultivos', 'Agrocymac es una ontología creada para estructurar información sobre el control y monitoreo de plagas, malezas y enfermedades que afectan específicamente a los cultivos de Arroz, Café y Cacao.', 'Other;Plant;Plant_Development;Vocabularies', 'OWL', 2, NULL, '2019-02-17T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/AGROCYMAC', '060a832fd5cc13d87580eff0940cdd3b5afbbd013d18514963bd28fe0f00ec46', 'scored', NULL, 0.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 8.27, 6.0, 3.5675, 3.5675, NULL, NULL, NULL, 959, 160, 14, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:05:13+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'AGROMOP', 'Control de Cacao', 'Ontologia con información relevante al cuidado del cacao de manera orgánica contra plagas y enfermedades.', 'Plant;Plant_Development', 'OWL', 1, '1.1', '2020-02-28T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/AGROMOP', 'ed21565205d4d91228cf1c1f166253d162e84303ab06c1e5ec1d4c684c94d73e', 'scored', NULL, 0.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 6.7, 4.0, 2.675, 2.675, NULL, NULL, NULL, 316, 67, 10, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:32+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'AHOL', 'Animal Health Ontology for Livestock', 'AHOL (Animal Health Ontology for Livestock) is an ontology of characteristics defining health issues of livestock in their environment (EOL) linked to their phenotypes (ATOL). AHOL aims to: - provide a reference ontology of health traits of farm animals for the international scientific and educational - communities, farmers, etc.; - deliver this reference ontology in a language which can be used by computers in order to support database management, semantic analysis and modeling; - represent traits as generic as possible for livestock vertebrates; - make the AHOL ontology as operational as possible and closely related to measurement techniques; - structure the ontology in relation to animal production ', '', 'OWL', 1, '1.0', '2018-10-23T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/AHOL', 'a868916541a3a9077d8352352c92bb1ce9d5d4b60b279658d6e700aad6fbb584', 'scored', NULL, 9.97, 0.02, 0.02, 'same_as_strict (1.0 result, not re-checked)', 3.29, 10.0, 5.82, 5.82, NULL, NULL, NULL, 4634, 340, 340, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:49+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'AHSO', 'Animal Health Surveillance Ontology', '(Work in progress - please contact ahso@datadrivensurveillance.org before using this ontology)

This is an ontology for health surveillance, assuming that surveillance data is recorded at three main levels:

SAMPLE data - data about specific collected samples; OBSERVATIONS, which can aggregate several samples; and OBSERVATIONAL CONTEXT, which is the context in which the observations were made (for instance clinical observation, surveillance sampling, etc). 

HEALTH EVENT is the occurrence in the real World to be modeled. This occurrence is an abstract concept, as it generally cannot be determined what are its boundaries in time, space, or population units. 

We assume that several OBSERVATIONS are derived from each health event, and recorded in the same or different databases - for instance clinical journal, laboratory database, abattoir. At the same time or not. 

AHSO attempts to model these time specific observations. The ontology is focused on the modeling of the animal and health information connected to a single observation, made at a specific point on time. All the information recorded is relative to that specific point in time.

For instance, an animal belongs to a herd, which belongs to an owner, AT THE TIME OF THE OBSERVATION. We do not attempt to model how that animal changed herds on time. Similarly, we do not model clinical progression. It is up to those using the data to create definitions of when two observations should be connected to the same event.', 'Biomedical_Resources;Health', 'OWL', 1, '0.1.0', '2018-07-30T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/AHSO', 'b23d7457d8aa926e1624be586c673e7857e2b1adde7995361ccc7b900f32c3bd', 'scored', NULL, 9.74, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 8.0, 4.435, 4.435, NULL, NULL, NULL, 519, 39, 39, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:25+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'AI', 'Artificial Intelligence', 'An ontology for artificial intelligence, specifically focused on generative AI, aiming to support and facilitate new research in this domain by providing a structured representation of key concepts, methods, and technologies.', 'Other', 'OWL', 1, '2024-08-14', '2024-10-24T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/AI', 'eff84c7e5c5571e0f8d408b693664604e4b9ccb945ba9d58fae2399513b12e26', 'scored', NULL, 10.0, 6.94, 6.94, 'same_as_strict (1.0 result, not re-checked)', 6.58, 10.0, 8.38, 8.38, NULL, NULL, NULL, 5582, 444, 444, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:21+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'AI-RHEUM', 'Artificial Intelligence Rheumatology Consultant System Ontology', 'AI/RHEUM is used for the diagnosis of rheumatologic diseases. AI/RHEUM contains findings, such as clinical signs, symptoms, laboratory test results, radiologic observations, tissue biopsy results, and intermediate diagnosis hypotheses. Findings and hypotheses, which include definitions, are used to reach diagnostic conclusions with definite, probable, or possible certainty. AI/RHEUM is used by clinicians and informatics researchers.', 'Health', 'UMLS', 1, 'AIR93', '2013-05-08T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/AI-RHEUM', 'b22adb891e74bc5a08bceb60dc2ed5646f850c0d9c8695757b4c7b64d1df29db', 'scored', NULL, 9.99, 1.39, 1.39, 'same_as_strict (1.0 result, not re-checked)', 6.71, 10.0, 7.0225, 7.0225, NULL, NULL, NULL, 5968, 809, 809, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:43+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'AIDENTIFYAGE', 'AIdentifyAGE', 'The AIdentifyAGE ontology provides a comprehensive vocabulary description for forensic age assessment using dental biological markers, promoting the transparent assessment processes in forensic odontology and age diagnostics. It formalizes expert knowledge according to IOFOS, AGFAD, ABFO, ADA and ISO standards, ensuring semantic interoperability and ethical AI integration. This ontology is a work in progress developed under the AIdentifyAGE project (FCT Grant 2024.07444.IACDC), within the national investment RE-C05-i08 – More Digital Science, measure RE-C05-i08.M04 – Support to R&D projects for advanced cybersecurity, artificial intelligence and data science systems in public administration. This work is being developed in collaboration with researchers from the University of Lisbon (Portugal), the University of Münster (Germany), and the University of Zagreb (Croatia), within the framework of the AIdentifyAGE international consortium. This ontology is described in detail in this preprint https://doi.org/10.48550/arXiv.2602.16714
Base Ontology for use in AIdentifyAGE Project, within the framework of the AIdentifyAGE international consortium., Base Ontology for use in AIdentifyAGE Project', 'Health;Human;Taxonomic_Classification;Vocabularies', 'OWL', 11, 'v1.0.9-beta', '2026-05-20T18:00:08.000-07:00', 'https://bioportal.bioontology.org/ontologies/AIDENTIFYAGE', '59d9e8604381ba7d4ef13b6087b3ea7ab0bba61c6ddf308dce03cf68a94913ca', 'scored', NULL, 9.79, 0.78, 0.78, 'same_as_strict (1.0 result, not re-checked)', 4.88, 9.0, 6.1125, 6.1125, NULL, NULL, NULL, 23963, 1669, 1446, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:11:04+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'AIO', 'Artificial Intelligence Ontology', 'This ontology models classes and relationships describing deep learning networks, their component layers and activation functions, as well as potential biases., The Artificial Intelligence Ontology (AIO) is a systematization of artificial intelligence concepts, methodologies, and their interrelations, spanning networks, layers, functions, large language models, preprocessing, and bias.', 'Other', 'OWL', 25, '2026-07-22', '2024-03-31T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/AIO', '861949aab2f3833cb1b3c541f0a15ac6a3fc469423a46342d010adf4b8c2baff', 'scored', NULL, 10.0, 6.93, 6.93, 'same_as_strict (1.0 result, not re-checked)', 6.58, 10.0, 8.3775, 8.3775, NULL, NULL, NULL, 5603, 443, 443, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:22+00:00', '2026-09-23T23:25:10+00:00');
