INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ALTPROTON', 'An Ontology for integration and interoperability of multi-aspect data of Protein food production chains', 'The ALTPROTON ontology is the foundation of a cloud-based interoperable data platform specifically tailored to address the complexities of the protein food production chain. The ALTPROTON consists of three main domains food quality, sustainability, and food processing. The multi-aspect data generated within each domain are connected via the most representative concepts to effectively integrate and interoperable for future advancement in the food industry and protein food research sector. The paper describes the concepts, classes, and relationships used in ALTPROTON to fill the gaps in existing food ontologies and databases.', 'Protein;Taxonomic_Classification', 'OWL', 4, 'The Ontology was revised after the reviews from the reviewers of Journal of Scientific Data.', '2025-11-18T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ALTPROTON', 'b98cb9f5aee5d64a86f19191cc1fa93276fefd8cdd0bac9e3ea788139828583a', 'scored', NULL, 9.97, 2.02, 2.02, 'same_as_strict (1.0 result, not re-checked)', 3.72, 10.0, 6.4275, 6.4275, NULL, NULL, NULL, 5745, 355, 279, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:01+00:00', '2026-09-23T23:25:10+00:00');
