INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ATOL', 'Animal Trait Ontology for Livestock', 'ATOL (Animal Trait Ontology for Livestock) is an ontology of characteristics defining phenotypes of livestock in their environment (EOL).
ATOL aims to:
- provide a reference ontology of phenotypic traits of farm animals for the international scientific and educational - communities, farmers, etc.;
- deliver this reference ontology in a language which can be used by computers in order to support database management, semantic analysis and modeling;
- represent traits as generic as possible for livestock vertebrates;
- make the ATOL ontology as operational as possible and closely related to measurement techniques;
- structure the ontology in relation to animal production

', '', 'OWL', 2, '6.0', '2014-10-22T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ATOL', 'a8bf97f69dacdddd9dde00ded6eec3adbe0d4708f481b375671eb0cf21af4620', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 5.0, 5.0, NULL, NULL, NULL, 56707, 2353, 2353, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:16:28+00:00', '2026-09-23T23:25:10+00:00');
