INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'AURA', 'KB_Bio_101', 'KB_Bio_101 is the ontology of the AURA + Inquire project @ SRI International, Menlo Park. 

This work is owned by Vulcan Inc. and is licensed for use under the Creative Commons Attribution-NonCommerical-ShareAlike 3.0 license (http://creativecommons.org/licenses/by-nc-sa/3.0/). Vulcan Inc., June 2013', '', 'OWL', 1, '1.0', '2014-01-21T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/AURA', 'f1ab06b9288532b41a982fbf9401656cee9b79b4176b86c378715deeb44ca3d3', 'scored', NULL, 9.77, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 6.78, 10.0, 6.6375, 6.6375, NULL, NULL, NULL, 1091651, 28031, 27397, '0.10.0', 'core4-1.0', NULL, '2026-09-23T07:15:19+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'AZDONTO', ' Alzheimer''s Disease Ontology', 'The Alzheimer''s Disease Ontology (AZDOnto) is a specialized knowledge representation framework developed to support the integration and analysis of clinical data related to Alzheimer''s disease (AD). This ontology is primarily designed to leverage Electronic Health Record (EHR) data, providing a standardized structure for the representation of patient information. The AZDOnto facilitates the effective integration of data from a variety of sources, enabling clinicians, researchers, and data scientists to gain insights into the clinical, genetic, and therapeutic aspects of Alzheimer''s disease.', 'Biomedical_Resources;Neurologic_Disease', 'OWL', 1, '0.1', '2026-08-22T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/AZDONTO', '69314d8b3959b8b8be53c93cb3665bf6de5dd66200f4759040bdd728b53b1304', 'scored', NULL, 9.64, 0.45, 0.45, 'same_as_strict (1.0 result, not re-checked)', 4.48, 8.0, 5.6425, 5.6425, NULL, NULL, NULL, 635, 28, 28, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:44+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BAO', 'BioAssay Ontology', 'The BioAssay Ontology (BAO) describes chemical biology screening assays and their results including high-throughput screening (HTS) data for the purpose of categorizing assays and data analysis.  BAO is an extensible, knowledge-based, highly expressive (currently SHOIQ(D)) description of biological assays making use of descriptive logic based features of the Web Ontology Language (OWL).  BAO currently has over 1000 classes and also makes use of several other ontologies.  It describes several concepts related to biological screening, including Perturbagen, Format, Meta Target, Design,  Detection Technology, and Endpoint.  Perturbagens are perturbing agents that are screened in an assay; they are mostly small molecules. Assay Meta Target describes what is known about the biological system and / or its components interrogated in the assay (and influenced by the Perturbagen).  Meta target can be directly described as a molecular entity (e.g. a purified protein or a protein complex), or indirectly by a biological process or event (e.g. phosphorylation).  Format describes the biological or chemical features common to each test condition in the assay and includes biochemical, cell-based, organism-based, and variations thereof.  The assay Design describes the assay methodology and implementation of how the perturbation of the biological system is translated into a detectable signal.  Detection Technology relates to the physical method and technical details to detect and record a signal.  Endpoints are the final HTS results as they are usually published (such as IC50, percent inhibition, etc.).  BAO has been designed to accommodate multiplexed assays.  All main BAO components include multiple levels of sub-categories and specification classes, which are linked via object property relationships forming an expressive knowledge-based representation.', 'Biological_Process;Cell;Chemical;Molecule;Other;Physicochemical;Protein;Subcellular;Vocabularies', 'OWL', 68, '2.8.19', '2026-05-06T18:00:20.000-07:00', 'https://bioportal.bioontology.org/ontologies/BAO', '98b479d24c7f777d277c9255c53a376ee54874e5b3b6b9612bc761ce5ed66ce6', 'scored', NULL, 10.0, 4.68, 4.68, 'same_as_strict (1.0 result, not re-checked)', 0.75, 10.0, 6.3575, 6.3575, NULL, NULL, NULL, 121254, 7918, 7918, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:21:29+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BAO-GPCR', 'G Protein-Coupled Receptor BioAssays Ontology', 'The G protein-coupled receptors (GPCRs) ontology (http://www.bioassayontology.org/bao_gpcr) describes pharmacology, biochemistry and physiology of these important and therapeutically promising class of academic and pharmaceutical research targets. Incorporation and comparison of various small molecule screening data sets, such as those deposited in PubChem, ChEMBL, KEGG, PDSP, and/or IUPHAR databases, requires a formalized electronic organization system. In order to bridge the gap between the overflow of HTS data and the bottleneck of integrated analysis tools, herein, we provide the first comprehensive GPCR ontology. The development and utility of GPCR ontology was based on previously developed BioAssay Ontology (BAO). The GPCR ontology contains information about biochemical, pharmacological, and functional properties of individual GPCRs as well as GPCR-selective ligands inclusive of their HTS screening results and other records. This provides the first all-inclusive GPCR ontology with all available data to model the relationship between the GPCR binding sites and their physiologic and pharmacologic role in physiology via small molecule chemical structures. We developed this system using emerging semantic technologies, by leveraging existing and descriptive domain level ontologies.', 'Biological_Process;Chemical;Molecule;Other;Physicochemical;Protein;Subcellular;Vocabularies', 'OWL', 23, '1.1', '2013-10-28T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/BAO-GPCR', '3ce86213becfb8726444d946b6b15af4e97832baaf5e815dcf860b0a871dcbdc', 'scored', NULL, 10.0, 0.3, 6.68, 'http://www.bioassayontology.org/bao_gpcr#definition [bioportal_definitionProperty]; http://www.bioassayontology.org/bao#definition [detected_by_name (885 uses)]', 0.64, 10.0, 5.235, 6.83, NULL, NULL, NULL, 9689, 904, 904, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T22:57:13+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BBO', 'Biomedical Burden Ontology', 'The Biomedical Burden Ontology (BBO) is a BFO-aligned OWL ontology for representing and integrating burden-related aspects of patient experience in biomedicine. It models burden as an affective, appraisal-based process that links situations (e.g., symptom, treatment, disease-course, and side-effect processes) to their perceived impacts on goals and expectations, informed by predictive processing/active inference accounts of cognition. BBO reuses and extends MFO, MFOEM, OGMS, and CCO/IAO, and provides patterns to annotate questionnaire-based measurements (e.g., PETS, MTBQ, MDASI), enabling semantic interoperability, automated reasoning, and analysis of burden across research and clinical settings. , The Biomedical Burden Ontology is an ontology of biomedical burdens. It includes support for burden-related entities, such as treatment burden, symptom burden, and burden appraisals.', 'Health;Human', 'OWL', 3, '2025-09-27', '2025-09-27T18:00:19.000-07:00', 'https://bioportal.bioontology.org/ontologies/BBO', '3abb47a33bc34b29920a4e99f69ee5e78e339d57c145531841eb66a6ef1cfc7d', 'scored', NULL, 10.0, 5.59, 5.59, 'same_as_strict (1.0 result, not re-checked)', 0.91, 10.0, 6.625, 6.625, NULL, NULL, NULL, 23135, 2561, 2192, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:12:14+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BCGO', 'Breast Cancer Grading Ontology', 'assigns a grade to a tumor starting from the 3 criteria of the NGS', 'Biological_Process', 'OWL', 2, '1.5', '2010-11-06T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/BCGO', '0bec702c7f78458f0f1963e44d88f7e414c53814cb18189aee33d835741d563f', 'scored', NULL, 4.62, 0.6, 0.6, 'same_as_strict (1.0 result, not re-checked)', 3.53, 9.0, 4.4375, 4.4375, NULL, NULL, NULL, 3016, 314, 133, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:30+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BCI-O', 'Brain-Computer Interaction (BCI) Ontology', 'The BCI ontology specifies a foundational metadata model set for real-world multimodal Brain-Computer Interaction (BCI) data capture activities.  Its structure depicts a conceptual framework that BCI applications can extend and use in their implementations, to define core concepts that capture a relevant and interoperable metadata vocabulary.

This ontology is aligned to the Semantic Sensor Network Ontology (SSN): a domain-independent and end-to-end model for sensor/actuator applications.  Hence, its structure has been normalized to assist its use in conjunction with other ontologies or linked data resources to specify any particular definitions (such as units of measurement, time and time series, and location and mobility), that specialized applications in the BCI domain might need.

Its spec provides general alignment data modeling guidelines for core concepts, to help BCI applications in their design.', 'Biomedical_Resources;Experimental_Conditions;Health;Human;Imaging;Neurologic_Disease;Neurological_Disorder;Upper_Level_Ontology;Vocabularies', 'OWL', 6, '0.9.6', '2018-06-06T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/BCI-O', '9032e412d98b6c0a85aac21ddea00561ccb2dfad6b7f51e78dcadb90713da61f', 'scored', NULL, 9.89, 5.5, 5.5, 'same_as_strict (1.0 result, not re-checked)', 4.5, 10.0, 7.4725, 7.4725, NULL, NULL, NULL, 6944, 188, 182, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:30+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BCIO', 'Behaviour Change Intervention Ontology', 'The Human Behaviour Change Project (HBCP) funded by the Wellcome Trust, and the Advancing Prevention Research in Cancer through Ontology Tools (APRICOT) Project funded by the US National Institutes of Health, are developing the Behaviour Change Intervention Ontology and associated tools and resources to be used in reporting research; linking datasets and synthesising evidence; and AI/machine learning algorithms to predict intervention outcomes in novel scenarios.

The overall aim of these projects is to automate evidence searching, synthesis and interpretation to rapidly address questions from policy-makers, practitioners and others to answer ‘What works, compared with what, how well, with what exposure, with what behaviours (for how long), for whom, in what settings and why?’. To achieve this, ontologies can help structure evidence, i.e., link evidence with a shared formal description of classes and relationships capturing domain knowledge in order to enable aggregation and semantic querying. We are developing and maintaining the Behaviour Change Intervention Ontology (BCIO) to do this.', 'Health;Human', 'OWL', 1, NULL, '2025-07-09T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/BCIO', 'c56fcd14707d0cff9dd5733729c4d1bd60e6aa6c343c4d1b9c67e26859f548fe', 'scored', NULL, 10.0, 6.37, 6.37, 'same_as_strict (1.0 result, not re-checked)', 0.43, 10.0, 6.7, 6.7, NULL, NULL, NULL, 18380, 2524, 2524, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:10:27+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BCLION', 'Breast Cancer Lifestyle Ontology', 'The Breast Cancer Lifestyle Ontology (BCLION) captures various factors related to lifestyle choices and behaviors that may influence the risk of developing breast cancer. It provides a structured representation of these factors in a hierarchical manner, allowing for a comprehensive understanding of the different aspects of breast cancer lifestyle.', 'Health;Human', 'OWL', 1, '1.0', '2024-01-02T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/BCLION', '026c648f67094b836de3ab437156c6f27cbd9dc2be8add05274f54bdff5bba31', 'scored', NULL, 0.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 4.96, 9.0, 3.49, 3.49, NULL, NULL, NULL, 115, 31, 31, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:03:47+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BCMO', 'Breast Cancer-Microbiome Ontology ', 'The aim of BCMO is to construct a comprehensive and standardized data collection method to study the interaction between the microbiome and breast cancer, including clinical data, pathology, epidemiology, demographic characteristics and lifestyle of breast cancer. Through standardized methods, research results in related research fields can be structured, shareable and comparable. It will contribute to the study of how the microbiome interacts with breast cancer.', 'Experimental_Conditions;Human', 'OWL', 1, NULL, '2024-12-23T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/BCMO', NULL, 'not_downloadable', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BCO', 'Biological Collections Ontology', 'BCO supports the interoperability of biodiversity data, including data on museum collections, environmental/metagenomic samples, and ecological surveys. A key feature of BCO is an ontological interpretation of Darwin Core terms.', 'All_Organisms', 'OWL', 11, '2021-11-14', '2021-11-14T18:00:37.000-08:00', 'https://bioportal.bioontology.org/ontologies/BCO', '8bc2c9fc1744234411b962c93168f7d0f08649932e5c3e3a2dfddc77c12833c5', 'scored', NULL, 9.93, 4.58, 4.58, 'same_as_strict (1.0 result, not re-checked)', 3.67, 9.0, 6.795, 6.795, NULL, NULL, NULL, 7603, 289, 254, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:28+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BCON', 'Breast Cancer Ontology', 'The Breast Cancer Ontology (BCON) aims to capture the diverse aspects of breast cancer, including its molecular biology, pathology, epidemiology, clinical data, and lifestyle factors. By representing this knowledge in a standardized and machine-readable format, the ontology enables researchers, clinicians, and other stakeholders to access, share, and analyze breast cancer-related information more effectively. It serves as a valuable resource for organizing existing knowledge, discovering new insights, and supporting decision-making processes in the field of breast cancer research and healthcare.', 'Health;Human', 'OWL', 2, '1.0', '2024-01-02T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/BCON', '43c44e2f25516d6c106f82ddc8514498673937c6e6e9cc0e30a04f53632e7fd7', 'scored', NULL, 0.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 7.46, 8.0, 3.865, 3.865, NULL, NULL, NULL, 287, 67, 67, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:13+00:00', '2026-09-23T23:25:10+00:00');
