INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BDO', 'Bone Dysplasia Ontology', 'The Bone Dysplasia ontology provides a comprehensive and formal representation of the different domain concepts involved in documenting the full complexity of the skeletal dysplasia domain. It captures and combines the genetic features that discriminate the bone dysplasias with the multitude of phenotypic characteristics manifested by patients and required to be taken into account in order to support the diagnosis process.', 'Health;Human', 'OWL', 9, '1.5', '2012-02-08T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/BDO', 'edba3c93797e738579ef92a7953d98c8a8566c0fd1f8443520d2ea6e540fbe1c', 'scored', NULL, 10.0, 0.06, 0.06, 'same_as_strict (1.0 result, not re-checked)', 7.03, 10.0, 6.7725, 6.7725, NULL, NULL, NULL, 45836, 3668, 3668, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:12:59+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BDPM', 'Base de Données Publique des Médicaments', '1. Description:	LA BDPM est un des référentiels du médicament gérée et distribuée par l’ANSM. Elle recense l’ensemble des spécialités et des présentations effectivement commercialisées durant les 5 dernières années. De ce fait, elle ne propose pas un historique exhaustif des codes de présentation et spécialités, celui-ci peut être obtenu grâce à la base RCP disponible sur le site de l’ANSM<br/>
2. Version: 2025-03-04<br/>
3. Champs sémantique: Terminologie<br/>
4. Usage: Exploitation de données<br/>
5. Nombre de concepts: 41 213<br/>
6. Domaine: Interventions de santé<br/>
7. Utilisateur(s) cible(s): Data scientists, Décideurs publics, Professionnels de santé, Éditeurs de logiciels<br/>
8. Langue(s): FRA<br/>
9. Format(s): OWL<br/>
10. Site(s) de publication: https://base-donnees-publique.medicaments.gouv.fr/<br/>
11. Licence: LOv2<br/>
12. Pratiques de gestion: Non<br/>
13. Accord de transfert: Non<br/>
14. Thème principal: Médicaments<br/>
15. Publication: 2025-03-06', 'Biomedical_Resources;Chemical;Health;Human;Immunology;Molecule;Phenotype;Physicochemical', 'OWL', 1, '2025-03-04', '2025-03-12T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/BDPM', '908c004e5a7d3a0086a1b1c78f78a981ab4aa1f32363036613e2ee947770ca43', 'scored', NULL, 9.98, 0.04, 0.04, 'same_as_strict (1.0 result, not re-checked)', 0.05, 10.0, 5.0175, 5.0175, NULL, NULL, NULL, 762910, 41603, 41330, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:51:12+00:00', '2026-09-23T23:25:10+00:00');
