INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BERVO', 'The Biological and Environmental Research Variable Ontology', 'The Biological and Environmental Research Variable Ontology (BERVO) is a model of the experimental variables, conditions, and concepts used in the study of environmental research, including studies in earth science, plant science, and geochemistry.  , None, "An ontology of variables for earth system simulation, partially derived from the EcoSIM framework."', 'Biological_Process;Chemical;Experimental_Conditions;Physicochemical;Plant_Anatomy;Plant_Development', 'OWL', 7, '2026-09-03', '2026-09-03T18:00:23.000-07:00', 'https://bioportal.bioontology.org/ontologies/BERVO', 'a110ab885775abda2a52d504d8ab7ec9b7e710b93fda1bd171e917191ec9b33f', 'scored', NULL, 10.0, 7.21, 7.21, 'same_as_strict (1.0 result, not re-checked)', 0.17, 10.0, 6.845, 6.845, NULL, NULL, NULL, 34856, 2368, 2368, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:13:14+00:00', '2026-09-23T23:25:10+00:00');
