INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BFO', 'Basic Formal Ontology', 'BFO grows out of a philosophical orientation which overlaps with that of DOLCE and SUMO. Unlike these, however, it is narrowly focused on the task of providing a genuine upper ontology which can be used in support of domain ontologies developed for scientific research, as for example in biomedicine within the framework of the OBO Foundry. Thus BFO does not contain physical, chemical, biological or other terms which would properly fall within the special sciences domains.', 'Upper_Level_Ontology', 'OWL', 2, '2.0', '2015-08-29T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/BFO', '7f9154d695fb0d82b5f4f45ef890b50f950b50a10bbd28e840dbc269159f8125', 'scored', NULL, 9.72, 1.56, 1.56, 'same_as_strict (1.0 result, not re-checked)', 7.54, 9.0, 6.955, 6.955, NULL, NULL, NULL, 1268, 36, 36, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:32+00:00', '2026-09-23T23:25:10+00:00');
