INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BIBFRAME', 'BIBFRAME 2.0', 'Initiated by the Library of Congress, BIBFRAME provides a foundation for the future of bibliographic description, both on the web, and in the broader networked world. In addition to being a replacement for MARC, BIBFRAME serves as a general model for expressing and connecting bibliographic data. A major focus of the initiative will be to determine a transition path for the MARC 21 formats while preserving a robust data exchange that has supported resource sharing and cataloging cost savings in recent decades.', 'Other;Upper_Level_Ontology', 'OWL', 11, '
   2.2.0
  ', '2025-08-12T18:00:35.000-07:00', 'https://bioportal.bioontology.org/ontologies/BIBFRAME', '846ab3b83f40d46555d82545402e8253fc4778965cbf8e25a9b763b755ea4f33', 'scored', NULL, 9.95, 6.38, 6.38, 'same_as_strict (1.0 result, not re-checked)', 0.0, 8.0, 6.0825, 6.0825, NULL, NULL, NULL, 4606, 217, 217, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:47+00:00', '2026-09-23T23:25:10+00:00');
