INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BIFO', 'Biofilm Ontology', 'BIFO is intended to provide a biofilm ontology capable of understanding fundamental terminologies the relations between common biofilm terminologies following the guidelines of the Basic Formal Ontology (BFO).', 'Biological_Process;Biomedical_Resources', 'OWL', 1, NULL, '2020-10-24T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/BIFO', '592a83ab21788a374528f5f0cc1fe28f384f8b71fffea47415eb1fc1d99038df', 'scored', NULL, 9.24, 4.02, 4.02, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 5.815, 5.815, NULL, NULL, NULL, 470, 79, 79, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:41+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BIM', 'Biomedical Image Ontology', 'Biomedical images published within the scientific literature play a central role in reporting and facilitating life science discoveries. Existing ontologies and vocabularies describing biomedical images, particularly sequence images, do not provide sufficient semantic representation for image annotations generated automatically and/or semi-automatically. We present an open ontology for the annotation of biomedical images (BIM) scripted in OWL/RDF. The BIM ontology provides semantic vocabularies to describe the manually curated image annotations as well as annotations generated by online bioinformatics services using content extracted from images by the Semantic Enrichment of Biomedical Images (SEBI) system. The BIM ontology is represented in three parts; (i) image vocabularies - which holds vocabularies for the annotation of an image and/or region of interests (ROI) inside an image, as well as vocabularies to represent the pre and post processing states of an image, (ii) text entities - covers annotations from the text that are associated with an image (e.g. image captions) and provides semantic representation for NLP algorithm outputs, (iii) a provenance model  - that contributes towards the maintenance of annotation versioning. To illustrate the BIM ontology’s utility, we provide three annotation cases generated by BIM in conjunction with the SEBI image annotation engine., The BIM ontology provides semantic vocabularies to describe the manually curated image annotations as well as annotations generated by online bioinformatics services using content extracted from images by the Semantic Enrichment of Biomedical Images (SEBI) system. The BIM ontology is represented in three parts; (i) image vocabularies - which holds vocabularies for the annotation of an image and/or region of interests (ROI) inside an image, (iii) a provenance model  - that contributes towards the maintenance of annotation versioning.', 'Imaging', 'OWL', 6, '1.3', '2014-09-26T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/BIM', 'f7c2a3fdce752c9479dfa226216eb5840c7d0a7da8affc3e2a36251804f5b603', 'scored', NULL, 9.56, 1.94, 1.94, 'same_as_strict (1.0 result, not re-checked)', 0.0, 9.0, 5.125, 5.125, NULL, NULL, NULL, 725, 159, 125, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:57+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BIN', 'Body in Numbers project terminology', 'This ontology was created as a part of Vítězslav Vacek''s masters thesis and is describing the terminology used within the Body in Numbers (BiN) project that is currently underway (as of 2019-05-01) at the University of West Bohemia, Czech Republic and focuses on the terminology used during the data collection process.', 'Taxonomic_Classification;Vocabularies', 'OWL', 2, '1.1', '2019-05-02T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/BIN', '6e91cd2c0dfb01fe98355d93e47c6b711864a273a6fe91314778d32669fb3efa', 'scored', NULL, 9.93, 6.59, 6.59, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 6.63, 6.63, NULL, NULL, NULL, 1755, 139, 139, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:56+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BIODIVTHES', 'Biodiversity Thesaurus', 'This bilingual thesaurus organizes the key concepts of biodiversity sciences, in their basic and applied ecological components. It uses polyhierarchy and includes 818 reciprocal associative relationships. The 1654 French and English descriptors (designating 827 concepts) are enriched with a large number of synonyms (1860) and hidden variants (7020) in both languages. Concepts are grouped into 82 collections, by semantic categories, thematic fields and EBV classes (Essential Biodiversity Variables). Definitions are given with their sources. This resource is aligned with the international thesauri AGROVOC, GEMET (GEneral Multilingual Environmental Thesaurus) and EnvThes (Environmental Thesaurus), as well as with the ontology ENVO (Environment Ontology).', 'All_Organisms', 'SKOS', 1, '2.1', '2023-04-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/BIODIVTHES', '539d1e71b74c9a8d4b519b4ba0d3df315fd7fc3afd53bdf4536ed82cfdcbd7a6', 'scored', NULL, 9.99, 2.05, 2.05, 'same_as_strict (1.0 result, not re-checked)', 8.3, 0.0, 5.085, 5.085, NULL, NULL, NULL, 25425, 920, 836, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:10:40+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BIOLINK', 'Biolink Model', 'A high level datamodel of biological entities (genes, diseases, phenotypes, pathways, individuals, substances, etc) and their associations', 'All_Organisms;Biological_Process;Cell;Chemical;Gene_Product;Phenotype', 'OWL', 85, '4.4.4', '2026-09-18T18:00:32.000-07:00', 'https://bioportal.bioontology.org/ontologies/BIOLINK', '23982f3f30a5490a17256ac503f18cad1b1651f9463cb348fce8a176f154a52b', 'scored', NULL, 10.0, 5.07, 5.07, 'same_as_strict (1.0 result, not re-checked)', 6.7, 10.0, 7.9425, 7.9425, NULL, NULL, NULL, 22953, 706, 706, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:10:47+00:00', '2026-09-23T23:25:10+00:00');
