INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BP', 'BioPAX Ontology of Biological Pathways', 'The BioPAX ontology (www.biopax.org) is a standard language for formally representing biological pathways. BioPAX Level 3 supports the representation of metabolic pathways, signal transduction pathways, protein-protein interaction networks, gene regulatory networks and genetic interactions.', 'Biological_Process', 'OWL', 1, 'Level3 v1.0', '2010-07-02T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/BP', '3b45f029a78b5b1ec310445c7299c89323382799d0bd9f39e054aec743503088', 'scored', NULL, 10.0, 6.73, 6.73, 'same_as_strict (1.0 result, not re-checked)', 4.75, 9.0, 7.62, 7.62, NULL, NULL, NULL, 1249, 69, 69, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:43+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BP-METADATA', 'BioPortal Metadata Ontology', 'This ontology represents the structure that BioPortal uses to represent all of its metadata (ontology details, mappings, notes, reviews, views)', 'Other', 'OWL', 6, '0.9.5', '2013-08-20T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/BP-METADATA', 'bdb81ad172a19739d5e0afbcf29c2620f87eed27bce037090768399ebc7a8f16', 'scored', NULL, 9.02, 0.63, 0.63, 'same_as_strict (1.0 result, not re-checked)', 1.2, 10.0, 5.2125, 5.2125, NULL, NULL, NULL, 1214, 123, 102, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:25+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BPFORMS', 'Ontology of chemically concrete, composable DNA, RNA, and protein residue and crosslinks', 'BpForms is an ontology of molecularly-concrete DNA, RNA, and protein residues and crosslinks which can be composed into molecularly-concrete forms of DNA, RNA, proteins, and complexes. The ontology can be used with the BpForms grammar and software tools for polymers and the BcForms grammar and software tools for complexes. See https://www.bpforms.org and https://www.bcforms.org for more information.', 'All_Organisms;Chemical;Gene_Product;Genomic_and_Proteomic;Molecule;Physicochemical;Protein', 'OBO', 1, '0.0.9', '2019-08-26T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/BPFORMS', 'de29d41b94c692e444f3dc5f1cf3e845f056ba1680671f3a99a9b40992b02efc', 'parse_failed', 'unsupported_format:obo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-23T21:06:58+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BPT', 'Biological Pathway Taxonomy', 'Biological Pathway Taxonomy (BPT) - hierarchical taxonomy of cellular and molecular mechanisms, metabolic reactions, and diseases that can be shown as signaling pathways. BPT was created manually based on the Elsevier Pathway Collection available for public usage.

 There are 3 types of entities in BPT – pathway, group, and folder of pathways and groups. 
 Group is the list of genes and proteins associated with biological function and diseases. 
 Pathway is an interactive model of molecular interactions in human and mammalian cells described in the literature. Each model was reconstructed based on facts published in peer-reviewed journals, with manually quality control.

 BPT pathway entity includes several properties such as link to the model in Pathway Studio software which allows reading supported sentences from published articles and additional information about members. A list of members for each model can be provided by request. Property “network” describes maps without logical causal relationships between members to distinguish them from actual models of molecular mechanisms (“signaling”).

 The index folder contains all pathways and groups sorted alphabetically.', 'Biological_Process;Cell;Health;Immunology;Protein;Subcellular', 'OBO', 2, 'synonymes2022', '2022-03-29T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/BPT', '79125d841e98f51f4e9cd2a44bee19f12dfda564efd79d726960958b2c72be82', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 8.2, 10.0, 7.05, 7.05, NULL, NULL, NULL, 249029, 3876, 3876, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:30:03+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BRAIN-COF', 'Computational Ontology Framework for Brain Profiles', 'BRAIN-COF is an ontology for representing neuroanatomical concepts aligned with the Desikan–Killiany–Tourville (DKT) brain atlas. Using hierarchical relationships, our ontology explicitly encodes a priori neuroanatomical relationships amongst brain regions. Brain-COF implements computationally efficient calculation of volumetric deviation indicative of disease pathology.', 'Anatomy;Neurologic_Disease', 'OWL', 2, '3', '2024-04-08T18:00:30.000+00:00', 'https://bioportal.bioontology.org/ontologies/BRAIN-COF', '76d323ac17a2d88b6e19860e484b6f26e3c08e3287b4b1751ebb2ec916bf2b23', 'scored', NULL, 9.76, 6.53, 6.53, 'same_as_strict (1.0 result, not re-checked)', 6.47, 10.0, 8.19, 8.19, NULL, NULL, NULL, 994, 126, 126, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:12+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BRCT', 'Brain Region & Cell Type terminology', 'The BRCT stands for Brain Region and Cell Type terminology, which was built with the purpose of organizing the knowledge domain of brain anatomy with a top-down granularity, from
gross regions to cell types. This resource has been created for use in the IMI-funded AETIONOMY project (www.aetionomy.org).', '', 'OWL', 1, '3.0', '2015-06-17T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/BRCT', '8c54e0a6941c5045de8926c7fe6276766c15302c6105aabd0b83a93c3544cfc6', 'scored', NULL, 9.99, 0.01, 0.01, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 5.0, 5.0, NULL, NULL, NULL, 11239, 1654, 1654, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:34+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BRIDG', 'Biomedical Research Integrated Domain Group Model', 'The Biomedical Research Integrated Domain Group (BRIDG) Model is a collaborative effort engaging stakeholders from the Clinical Data Interchange Standards Consortium (CDISC), the HL7 Regulated Clinical Research Information Management Technical Committee (RCRIM TC), the National Cancer Institute (NCI) and its Cancer Biomedical Informatics Grid (caBIG®), and the US Food and Drug Administration (FDA). The BRIDG model is an instance of a Domain Analysis Model (DAM). The goal of the BRIDG Model is to produce a shared view of the dynamic and static semantics for the domain of protocol-driven research and its associated regulatory artifacts. This domain of interest is further defined as:

Protocol-driven research and its associated regulatory artifacts: i.e. the data, organization, resources, rules, and processes involved in the formal assessment of the utility, impact, or other pharmacological, physiological, or psychological effects of a drug, procedure, process, or device on a human, animal, or other subject or substance plus all associated regulatory artifacts required for or derived from this effort, including data specifically associated with post-marketing adverse event reporting.

This OWL version of the BRIDG model is create by the National Cancer Institute (NCI). 

Source repository: https://ncisvn.nci.nih.gov/WebSVN/listing.php?repname=bridg-model&path=%2Ftrunk%2FModel+-+OWL%2F&', 'Health', 'OWL', 1, '3.2', '2012-08-30T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/BRIDG', 'bf49c10bdb66048f94fbb5d0e16ac558a13dd96b3b6cc0ac5bb5324d064e6866', 'scored', NULL, 9.8, 5.26, 5.26, 'same_as_strict (1.0 result, not re-checked)', 6.13, 10.0, 7.7975, 7.7975, NULL, NULL, NULL, 52596, 349, 325, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:15:05+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'BRO', 'Biomedical Resource Ontology', 'A controlled terminology of resources, which is used to improve the sensitivity and specificity of web searches.', 'Biomedical_Resources', 'OWL', 14, '3.2.1', '2010-08-31T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/BRO', 'c813aa0a5bfcf67118b6f1240a4e2fa75a8d3a9eacaa129b65d8ee1368ed8a3c', 'scored', NULL, 9.96, 0.15, 6.33, 'http://bioontology.org/ontologies/biositemap.owl#definition [bioportal_definitionProperty + detected_by_name]', 0.06, 10.0, 5.0425, 6.5875, NULL, NULL, NULL, 3353, 490, 489, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T22:57:09+00:00', '2026-09-23T23:25:10+00:00');
