INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CAO', 'Clusters of Orthologous Groups (COG) Analysis Ontology', 'CAO ontology is designed for supporting the COG enrichment study by using Fisher''s exact test', 'Gene_Product', 'OWL', 3, '1.4', '2011-10-10T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/CAO', '944f340f780aef327575bb5266106b8131721fbde0dba219de102d2a0f76f834', 'scored', NULL, 10.0, 2.39, 2.39, 'same_as_strict (1.0 result, not re-checked)', 6.11, 9.0, 6.875, 6.875, NULL, NULL, NULL, 2831, 205, 205, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:15+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CARE-AI-CO-VI0-1', 'CARE-AI Initial Capability Ontology v0.1 ', 'CARE-AI Initial Capability Ontology v0.1 is a preliminary semantic prototype developed to explore the representation of organisational capabilities relevant to trustworthy AI implementation in healthcare. It is a feasibility and capability demonstration and does not represent the empirically validated final CARE-AI ontology. The final ontology will be derived from evidence synthesis, theory development and empirical refinement conducted during the CARE-AI fellowship., A preliminary research ontology prototype for representing organisational capabilities, capability configurations, capability evolution and implementation-related outcomes in trustworthy AI adoption in healthcare. This version is a feasibility-oriented prototype and is not presented as a final or empirically validated theory. The final CARE-AI Capability Ontology is intended to be refined through evidence synthesis, expert refinement and empirical organisational research in WP1-WP3 before formalisation in WP4.', 'Development;Health;Other', 'OWL', 1, '0.1.0', '2026-08-29T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CARE-AI-CO-VI0-1', '05e5031fc8c9c4eb6c5e80488916bed99871d333af26d51304b7329ec9c21a8f', 'scored', NULL, 9.82, 5.09, 5.09, 'same_as_strict (1.0 result, not re-checked)', 2.59, 7.0, 6.125, 6.125, NULL, NULL, NULL, 411, 55, 38, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:30+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CARELEX', 'Content Archive Resource Exchange Lexicon', 'Contains controlled vocabulary terms from National Cancer Institute used to classify clinical trial electronic content (documents, images, etc).     A Content model contains content classification categories (classes) and metadata properties (data properties).  Data properties should be assigned to each Content Type.   This model has been published as part of the new OASIS eTMF Standard, a draft specification available at: http://oasis-open.org/committees/etmf. CareLex is a non-profit organization formed to promote eClinical application and content interoperability for the life sciences and healthcare industries. For more info go to www.CareLex.Org', 'Vocabularies', 'OWL', 46, '1.02', '2024-12-30T18:00:42.000-08:00', 'https://bioportal.bioontology.org/ontologies/CARELEX', '315a059a07e4f77199178934fc8341d841792389f64a8b4f944974a63c719603', 'scored', NULL, 9.97, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 4.9925, 4.9925, NULL, NULL, NULL, 8624, 340, 340, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:08:08+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CARESSES', 'CARESSES Ontology', 'The CARESSES Ontology encodes guidelines defined by experts in Transcultural Nursing, with the aim of offering a specific tool for endowing social assistive robots (assisting older adults) with cultural competence.', '', 'OWL', 1, '1.0', '2019-06-10T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CARESSES', 'c1ac800004c80d67a8bcc43c4377d34c550691cd1abba3beeecfd9fbb572b922', 'scored', NULL, 9.9, 3.16, 3.16, 'same_as_strict (1.0 result, not re-checked)', 5.92, 10.0, 7.245, 7.245, NULL, NULL, NULL, 1821, 99, 99, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:38+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CARO', 'Common Anatomy Reference Ontology', 'The Common Anatomy Reference Ontology (CARO) is being developed to facilitate interoperability between existing anatomy ontologies for different species, and will provide a template for building new anatomy ontologies. CARO will be described in Anatomy Ontologies for Bioinformatics: Principles and Practice Albert Burger, Duncan Davidson and Richard Baldock (Editors)', 'Anatomy', 'OWL', 16, '2023-03-15', '2023-03-15T18:01:04.000-07:00', 'https://bioportal.bioontology.org/ontologies/CARO', '07a02a6efcb9059d52144161227798667b496b2947612a736e362478486f143c', 'scored', NULL, 9.99, 6.0, 6.0, 'same_as_strict (1.0 result, not re-checked)', 7.74, 9.0, 8.1825, 8.1825, NULL, NULL, NULL, 103747, 722, 722, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:19:17+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CAROLIO', 'Caroli''s Disease and Syndrome Ontology', 'We present CaroliO, an ontology for Caroli''s disease and syndrome, aimed at enhancing the diagnosis and treatment of these rare liver conditions. Our work addresses the pressing need for structured knowledge resources in the field of rare diseases, which often present significant diagnostic and treatment challenges due to limited information.

We developed our ontology in two versions: CaroliO VB, which is the Basic ontology; and CaroliO VA, the Applied Version, which includes more complex axioms i.e. closure axioms and axioms that indicate combinations of scenarios among symptoms, signs, treatments, and outcomes. The Basic Version follows the underlying Open World Assumption and is suitable for ontologists and future researches, while the Applied Version includes more complex axioms to better reflect real world decision making in diagnosis and choosing treatments for Caroli’s disease and syndrome based on our current knowledge.', 'Health;Human', 'OWL', 1, '2.2', '2023-12-12T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CAROLIO', 'e6d764f0799eee76911b67bb57d39efde43909853d0ae0517028e805da77051f', 'scored', NULL, 10.0, 6.01, 6.01, 'same_as_strict (1.0 result, not re-checked)', 5.72, 9.0, 7.6825, 7.6825, NULL, NULL, NULL, 1484, 87, 87, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:11+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CARRE', 'CARRE Risk Factor ontology', 'Clinical risk factors, evidence and observables', 'Health', 'OWL', 3, '0.2', '2014-09-30T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CARRE', '386238aafa611c498c2ccc5007437f6adb30148a4287110f51cdef378573f4ea', 'scored', NULL, 9.94, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 3.94, 9.0, 5.72, 5.72, NULL, NULL, NULL, 2029, 176, 176, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:05:52+00:00', '2026-09-23T23:25:10+00:00');
