INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CBCTX', 'CalendarBench Context', 'Curated dictionary of *momentary* context-feature IRIs for persona-based simulation. Stable user characteristics (full Big Five score, identity, etc.) belong in persona `characteristics:`, NOT here. Trait STATES (e.g. currently behaving in a high-extraversion manner) are included under `trait_state`. behaviour_state and capability_opportunity entries carry theory_mappings tying the IRI to TDF / COM-B / HAPA / TTM / SDT.', 'Health;Human', 'OWL', 1, '2026.05.26', '2026-05-26T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CBCTX', '1a1d5467e0b136608e1b174230d515c612cb5475a26d54685a2a9551abc98bee', 'scored', NULL, 9.98, 6.35, 6.35, 'same_as_strict (1.0 result, not re-checked)', 7.56, 7.0, 7.7225, 7.7225, NULL, NULL, NULL, 4729, 563, 18, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:15+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CBHA', 'CalendarBench Human Activities', 'Hierarchy of the Compendium of Physical Activities (https://doi.org/10.1016/j.jshs.2023.10.001; 1210 rows), grouped by the seven top-level event categories (Sports, Work, Social, Education, Everyday Tasks, Health, Leisure). Each Activity Description is a named individual with its Activity Code and MET Value preserved verbatim, OWL hierarchy of the Compendium of Physical Activities (1210 rows), Leisure). Each Activity Description is a named individual with its Activity Code and MET Value preserved verbatim.', 'Health;Human', 'OWL', 1, '2026.05.03', '2026-09-10T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CBHA', 'da94fc6823cc9377e5a4b5b5cf35a990302dc698a8b52e5730db8db1458bfb29', 'scored', NULL, 9.99, 0.16, 0.16, 'same_as_strict (1.0 result, not re-checked)', 0.0, 8.0, 4.5375, 4.5375, NULL, NULL, NULL, 6248, 1248, 38, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:17+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CBHT', 'CalendarBench Health Tasks', 'Health task benchmark organised as Domain, Challenge, Difficulty, Task. Each task carries title, description, isConcurrent, isDividable, estimatedDurationMinutes, matchedActivity (Compendium of Physical Activities bridge) and contextLink edges into the curated context IRI dictionary (mood, energy, location, weather, behaviour-theory categories).', 'Health;Human', 'OWL', 1, '2026.05.19', '2026-07-05T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CBHT', '50ee5cfa079c42006d897c324e9ff8f46d93ba34c7abd9d37a8ae79bec6ee5c1', 'scored', NULL, 9.96, 6.28, 6.28, 'same_as_strict (1.0 result, not re-checked)', 5.3, 9.0, 7.635, 7.635, NULL, NULL, NULL, 10908, 269, 107, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:38+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CBO', 'Cell Behavior Ontology', 'The Cell Behavior Ontology (CBO) describes multi-cell computational models. In particular to describe both the existential behaviors of cells (spatiality, growth, movement, adhesion, death, ...) and computational models of those behaviors.

Funding: US National Institute of Health grant R01GM76692,
US Environmental Protection Agency grant R835001, Indiana
University, Bloomington (IUB) and the Biocomplexity Institute
at IUB all provided support for this work. 

This work used the Protege resource, supported by grant LM007885 
from the US National Library of Medicine to Stanford University.', 'All_Organisms;Biological_Process;Cell', 'OWL', 25, 'Version 1.1.2 added license info.
Version 1.1.1 added fuding sources.
Version 1.1.0 added classes for OMERO-Tiff files similar to those for VTK files 
Version 1.0.0 is the initial release of the Cell Behavior Ontology (CBO). 
Version 1.0.1 added Journal citation for the Cell Behavior Ontology (CBO). 
Version 1.0.2 corrected a few annotations that had "snap:process" that should be "span:process".
Version 1.0.3 corrected/changed class "SpacialExclusive" to "SpatialExclusive" and property "has_Quality" to "has_quality".', '2021-09-22T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CBO', '8041a03e39f5b1cc4ae847557d802b4cf03a72ce5becab2af4542b634fe925a0', 'scored', NULL, 9.96, 0.03, 6.52, 'http://purl.org/dc/elements/1.1/description [bioportal_definitionProperty]; http://www.geneontology.org/formats/oboInOwl#def [detected_by_name (15 uses)]', 5.23, 10.0, 6.305, 7.9275, NULL, NULL, NULL, 2400, 247, 247, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T22:57:07+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CCF', 'Human Reference Atlas Common Coordinate Framework Ontology', 'The Common Coordinate Framework (CCF) Ontology is an application ontology built to support the development of the Human Reference Atlas (HRA).  It unifies vocabulary for HRA construction and usage—making it possible to ingest external data sources; supporting uniform tissue sample registration that includes the spatial positioning and semantic annotations within 3D reference organs; and supporting user-formulated cross-domain queries over tissue donor properties, anatomical structures, cell types, biomarkers, and 3D space. The CCF Ontology consists of three major ontologies. The Biological Structure Ontology records anatomical structures, cell types, and biomarkers (ASCT+B) and the relationships between them.  The ASCT+B tables are authored by human experts using templated Google Sheets. The biomarkers, cell types, and anatomical structures are mapped to existing ontologies (Uberon/FMA, CL, HGNC) whenever possible.  All relationships between anatomical structures and from cell types to anatomical structures are valid Uberon and CL relationships. The Spatial Ontology defines the shape, size, location, and rotation of experimental tissue and data major anatomical structures in the 3D Reference Object Library. The Specimen Ontology captures the sex, age, and other information on donors that provided tissue data used in the construction of the HRA.', 'Anatomy;Biomedical_Resources;Cell;Human', 'OWL', 16, '3.0.0', '2024-06-14T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CCF', '6abef7d694771c3d697ba0e5c0d54816e4fe8a9d882d8710f9fd6bef49c589b1', 'scored', NULL, 9.76, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 6.0, 3.94, 3.94, NULL, NULL, NULL, 532, 42, 42, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:38+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CCO', 'Cell Cycle Ontology', 'An application ontology integrating knowledge about the eukaryotic cell cycle.', 'Arabadopsis;Biological_Process;Human;Protein;Yeast', 'OBO', 6, '2.10', '2014-06-24T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CCO', 'ec1f84cff9da3d72bbc04b404d18d3b46ab828581d7ffc170155b29a9c99203c', 'parse_failed', 'unsupported_format:obo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-23T21:07:04+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CCON', 'Cerrado concepts and plant community dynamics', 'The ontology of Cerrado wood plant dynamics was created in order to represent the set of concepts about the dynamics, that is, changes over time of the wood vegetation structure, of Cerrado. Ccon describes the main parameters used to measure the changes, such as mortality rate and recruitment rate.', '', 'OWL', 8, '0.9.3', '2014-01-29T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CCON', '7064f50e6361b9a532d549d50eeb3689c8dbe506bfe597bb486f6790df3acc02', 'scored', NULL, 10.0, 3.28, 3.28, 'same_as_strict (1.0 result, not re-checked)', 1.31, 9.0, 5.8975, 5.8975, NULL, NULL, NULL, 1837, 169, 86, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:40+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CCONT', 'Cell Culture Ontology', 'CCONT is an ontology for the formal representation of cell lines and their correspnding culture conditions.', 'Biological_Process;Experimental_Conditions;Vocabularies', 'OWL', 3, '1.1', '2014-07-23T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CCONT', '68cd770e11395871a7df42ac5057fdc42e7da2662034611c2281be245ea674ed', 'scored', NULL, 10.0, 5.15, 5.15, 'same_as_strict (1.0 result, not re-checked)', 4.86, 10.0, 7.5025, 7.5025, NULL, NULL, NULL, 2717404, 58013, 58013, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T07:33:42+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CCTOO', 'Cancer Care: Treatment Outcome Ontology', 'The Cancer Care: Treatment Outcomes Ontology (CCTOO) catalogues various clinical endpoints used in evaluating outcomes of cancer treatment. In addition to a vocabulary list, CCTOO also curates the dependencies between individual concepts, in form of production rules, for translating clinical findings recorded in the electronic medical records (EMR) into literature-based concepts. An earlier version of this ontology was presented as a scientific abstract alongside the American Society of Clinical Oncology annual meeting 2017, Chicago, USA (J Clin Oncol 2017; 35 suppl; abstr e18137). Full paper on http://ascopubs.org/doi/abs/10.1200/CCI.18.00026', 'Biomedical_Resources;Health;Human', 'OBO', 2, 'releases/2018-05-11', '2018-05-11T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CCTOO', '30555aff3b45b09f9787ec3dd5c6049c5834691c2d0ac303ae52cf889610fe89', 'scored', NULL, 9.99, 4.96, 4.96, 'same_as_strict (1.0 result, not re-checked)', 8.66, 10.0, 8.4025, 8.4025, NULL, NULL, NULL, 40434, 1134, 1134, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:13:51+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CDAO', 'Comparative Data Analysis Ontology', 'A formalization of concepts and relations relevant to evolutionary comparative analysis, such as phylogenetic trees, OTUs (operational taxonomic units) and compared characters (including molecular characters as well as other types). CDAO is being developed by scientists in biology, evolution, and computer science.', 'Experimental_Conditions', 'OWL', 7, '$Revision$', '2013-08-20T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CDAO', '2e538ae35f479624ffc3c5449c15b40c09194e50a2e9b0f8a1ab8eb7d39263da', 'scored', NULL, 10.0, 1.32, 1.32, 'same_as_strict (1.0 result, not re-checked)', 3.18, 10.0, 6.125, 6.125, NULL, NULL, NULL, 2196, 191, 165, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:55+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CDMONTO', 'Common Diabetes Medications Ontology', 'The Common Diabetes Medications Ontology (CDMOnto) is an ontology-based decision support system that has been developed with the objective of providing appropriate treatment suggestions for diabetic patients. The CDMOnto Ontology serves as a foundation for shared semantics, domain-specific, standard, and interoperable knowledge pertinent to common diabetes medications. It encompasses the knowledge of diabetes medications and offers a unified terminology that can be disseminated and processed by medical professionals, pharmacists, and diabetic patients.', 'Anatomy;Biomedical_Resources;Health;Human;Other;Taxonomic_Classification', 'OWL', 2, NULL, '2025-07-09T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CDMONTO', '289290e7d59a0f631907f5b7bf2c12482f4fe653b1ffdf3cfd81c6741378fe67', 'scored', NULL, 7.71, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 4.4275, 4.4275, NULL, NULL, NULL, 1418, 385, 303, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:05:45+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CDNO', 'Compositional Dietary Nutrition Ontology', 'CDNO provides structured terminologies to describe nutritional attributes of material entities that contribute to human diet., The CDNO provides structured terminologies to describe nutritional attributes of material entities that contribute to human diet. These terms are intended primarily to be associated with datasets that quantify concentration of chemical nutritional components derived from samples taken from any stage in the production of food raw materials (including from crops, livestock, fisheries) and through processing and supply chains. Additional knowledge associated with these dietary sources may be represented by terms that describe functional, physical and other attributes. Whilst recognising that dietary nutrients within food substrates may be present as complex and dynamic physical and chemical structures or mixtures, CDNO focuses on components typically quantified in an analytical chemistry laboratory. The primary CDNO class ‘dietary nutritional component’ contains hierarchical sets of terms organised to reflect commonly used classifications of chemical food composition. This class does not represent an exhaustive classification of chemical components, but focuses on structuring terms according to widely accepted categories. This class is independent of, but may be used in conjunction with, classes that describe ‘analytical methods’ for quantification, ‘physical properties’ or ‘dietary function’. Quantification data may be used and reported in research literature, to inform food composition tables and labelling, or for supply chain quality assurance and control. More specifically, terms within the ‘nutritional component concentration’ class may be used to represent quantification of components described in the ‘dietary nutritional component’ class. Concentration data are intended to be described in conjunction with post-composed metadata concepts, such as represented by the Food Ontology (FoodOn) ‘Food product by organism’, which derives from some', 'Other', 'OWL', 21, NULL, '2026-06-11T18:01:05.000-07:00', 'https://bioportal.bioontology.org/ontologies/CDNO', '65cf3f0d7b1c1674bad83dfb97219cba1ae740c63bce3a5b677416d4e055511f', 'scored', NULL, 10.0, 6.19, 6.19, 'same_as_strict (1.0 result, not re-checked)', 8.07, 10.0, 8.565, 8.565, NULL, NULL, NULL, 148107, 2110, 2110, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:20:40+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CDO', 'Chinese Diabetes Mellitus Ontology', 'Note: The abbreviation of Chinese Diabetes Mellitus Ontology was changed to CDMO.
CDMO is an OWL 2 ontology designed to cover the diabetes mellitus knowledge represented in Chinese language. The ontology is based on BFO and OGMS. In addition, the top hierarchical structure was adapted from SNOMED-CT, and strive for mapping with other medical ontologies in English, such as SNOMED-CT, HPO, DOID, DRON.
', 'Health;Human', 'OWL', 6, '3.0', '2022-03-24T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CDO', '1f140e6d815a48d4e0908ec5efee180430d7f8d795c092fd7479a50b406b7e5d', 'scored', NULL, 10.0, 6.71, 6.71, 'same_as_strict (1.0 result, not re-checked)', 1.04, 10.0, 6.9375, 6.9375, NULL, NULL, NULL, 57312, 3752, 3752, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:21:20+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CDOH', 'Commercial determinant of Health Ontology', 'Commercial factors including the production, distribution, and marketing of goods and services, may exert a substantial influence on health outcomes. This ontology covers concepts and relationships relevant to non-clinical factors resulting from commercial determinants of health(CDoH).', '', 'OWL', 1, 'v1', '2023-09-13T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CDOH', 'f9d93db4e5421af0690fe4829761e2c2bcaa4610ca18d9747f9d23ee46b76a7d', 'scored', NULL, 0.97, 0.37, 0.37, 'same_as_strict (1.0 result, not re-checked)', 5.94, 10.0, 4.32, 4.32, NULL, NULL, NULL, 2704, 371, 357, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:15+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CDPEO', 'Chronic Disease Patient Education Ontology', 'This ontology is used to recommend personalized education materials to chronic disease patients. The constructed ontology mainly consists of two levels. Level 1 includes 5 terms: demographic, disease, vital sign, lifestyle and medication, which describe the characteristics contained in the patient data, as well as the topics of education materials. Leve 2 contains the detailed elements for each Level 1 class. The patient profile class is used to generate the instance of patient data, using object properties to connect to the specific characteristic class. The patient data will be mapped to a vector space generated from the Level 2 classes. SWRL rules are added to implement the semantic logic of mapping from patient original data to the ontology vector space. The pulblication of the ontology is in preperation.', 'Health', 'OWL', 1, '1.0.0', '2019-12-18T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CDPEO', '4654a48d20cf9991302e49220e283039d176e5b58cd3db189f7c13e52bcfe641', 'scored', NULL, 5.48, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 7.33, 7.0, 4.9525, 4.9525, NULL, NULL, NULL, 4892, 73, 41, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:07:42+00:00', '2026-09-23T23:25:10+00:00');
