INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CHEAR', 'Children''s Health Exposure Analysis Resource', 'Children''s health and wellbeing are influenced by interactions between environmental and genetic factors. NIEHS is establishing an infrastructure, the Children''s Health Exposure Analysis Resource (CHEAR), to provide the extramural research community access to laboratory and data analyses that add or expand the inclusion of environmental exposures in children''s health research. The goal of CHEAR is to provide tools so researchers can assess the full range of environmental exposures which may affect children''s health. We anticipate that CHEAR will be used by children''s health researchers conducting epidemiological or clinical studies that currently have limited consideration of environmental exposures, or those who have collected exposure data but seek more extensive analyses.', 'Health;Human', 'OWL', 15, '2.8', '2019-09-10T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CHEAR', '9cea9821d7eb93472949154ce55f0069a17d29e2b3ae8c04bb54ef4552fb294e', 'scored', NULL, 10.0, 4.74, 4.74, 'same_as_strict (1.0 result, not re-checked)', 4.17, 10.0, 7.2275, 7.2275, NULL, NULL, NULL, 194782, 16648, 14864, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T03:26:50+00:00', '2026-09-23T23:25:10+00:00');
