INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CIDO', 'Coronavirus Infectious Disease Ontology', 'The Ontology of Coronavirus Infectious Disease (CIDO) is a community-driven open-source biomedical ontology in the area of coronavirus infectious disease. The CIDO is developed to provide standardized human- and computer-interpretable annotation and representation of various coronavirus infectious diseases, including their etiology, transmission, pathogenesis, diagnosis, prevention, and treatment.', 'All_Organisms;Health;Human', 'OWL', 42, '2024-02-16', '2024-02-16T18:02:33.000-08:00', 'https://bioportal.bioontology.org/ontologies/CIDO', 'c60b908e8d5acf995bb6dfebfa7359f79c80d619f15857cfa8868cce4e89c9f5', 'scored', NULL, 10.0, 5.69, 5.69, 'same_as_strict (1.0 result, not re-checked)', 8.52, 10.0, 8.5525, 8.5525, NULL, NULL, NULL, 621226, 31959, 31924, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:40:38+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CIDOC-CRM', 'CIDOC Conceptual Reference Model', 'The CIDOC Conceptual Reference Model (CRM) provides definitions and a formal structure for describing the implicit and explicit concepts and relationships used in cultural heritage documentation.

The CIDOC CRM is intended to promote a shared understanding of cultural heritage information by providing a common and extensible semantic framework that any cultural heritage information can be mapped to. It is intended to be a common language for domain experts and implementers to formulate requirements for information systems and to serve as a guide for good practice of conceptual modelling. In this way, it can provide the "semantic glue" needed to mediate between different sources of cultural heritage information, such as that published by museums, libraries and archives.', '', 'OWL', 2, 'v6.2', '2015-08-19T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CIDOC-CRM', '6cf7159474fcb06e6afb72d31dfa56d2b4e902844cce15f38a1ed7a112ea993a', 'scored', NULL, 9.77, 6.59, 6.59, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 6.59, 6.59, NULL, NULL, NULL, 3794, 86, 86, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:51+00:00', '2026-09-23T23:25:10+00:00');
