INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CL', 'Cell Ontology', 'The Cell Ontology is a structured controlled vocabulary for cell types in animals. The Cell Ontology is designed as a structured controlled vocabulary for cell types. This ontology was constructed for use by the model organism and other bioinformatics databases, where there is a need for a controlled vocabulary of cell types. This ontology is not organism specific. It covers cell types from prokaryotes to mammals. However, it excludes plant cell types, which are covered by PO.
, An ontology of cell types.', 'Anatomy;Cell', 'OWL', 129, '2026-06-08', '2026-06-08T18:05:15.000-07:00', 'https://bioportal.bioontology.org/ontologies/CL', '0b09d177c1a6060b660b1236b405215e0fb2429866183ab5e680c354bd5f8873', 'scored', NULL, 10.0, 5.79, 5.79, 'same_as_strict (1.0 result, not re-checked)', 8.39, 10.0, 8.545, 8.545, NULL, NULL, NULL, 835080, 19345, 19168, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:46:44+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CLAO', 'Collembola Anatomy Ontology', 'Collembola Anatomy Ontology (CLAO) includes anatomical terms to refer to sclerites, anatomical systems, cell components, and chaetotaxy. CLAO is directed towards building semantic annotations or the production of morphological data employing a standardized language. CLAO is intended as a complementary tool to morhological descriptions during taxonomic work, before obtaining phylogenetic characters.', 'Anatomy;Animal_Gross_Anatomy;Vocabularies', 'OWL', 2, '2021-09-27', '2021-05-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CLAO', 'be3a305cfd411eafab7f9e0ce69a7d4460509e364a5edcf85be8609b047efef0', 'scored', NULL, 9.99, 6.34, 6.34, 'same_as_strict (1.0 result, not re-checked)', 6.44, 10.0, 8.1925, 8.1925, NULL, NULL, NULL, 23432, 1517, 1517, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:10:22+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CLO', 'Cell Line Ontology', 'The Cell Line Ontology (CLO) is a community-based ontology in domain of biological cell lines with a focus on permanent cell lines from culture collections. Upper ontology structures that frame the skeleton of CLO include Basic Formal Ontology and Relation Ontology. Cell lines contained in CLO are associated with terms from other ontologies such as Cell Type Ontology, NCBI Taxonomy, and Ontology for Biomedical Investigation. A common design pattern for the cell line is used to model cell lines and their attributes, the Jurkat cell line provides ane xample.  Currently CLO contains over 36,000 cell line entries obtained from ATCC, HyperCLDB, Coriell, and bymanual curation. The cell lines are derived from 194 cell types, 656 anatomical entries, and 217 organisms. The OWL-based CLO is machine-readable and can be used in various applications., The Cell Line Ontology (CLO) is a community-based ontology of cell lines. The CLO is developed to unify publicly available cell line entry data from multiple sources to a standardized logically defined format based on consensus design patterns.', 'All_Organisms;Anatomy;Biological_Process;Biomedical_Resources;Cell;Experimental_Conditions;Phenotype;Taxonomic_Classification;Vocabularies', 'OWL', 67, '2026-06-19', '2026-06-20T18:01:32.000-07:00', 'https://bioportal.bioontology.org/ontologies/CLO', '6cfa3860ab0889a6d2316534122a0a7995daef444062cf628466ea851697ceb9', 'scored', NULL, 10.0, 5.45, 5.45, 'same_as_strict (1.0 result, not re-checked)', 3.73, 10.0, 7.295, 7.295, NULL, NULL, NULL, 541949, 40880, 40852, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:36:43+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CLYH', 'Clytia hemisphaerica Development and Anatomy Ontology', 'The Clytia hemisphaerica Development and Anatomy Ontology (CLYH) describes the anatomical and developmental features of the Clytia hemisphaerica life cycle.', 'Anatomy', 'OWL', 4, NULL, '2020-05-29T18:01:43.000-07:00', 'https://bioportal.bioontology.org/ontologies/CLYH', 'ee0613fe4f3169f58e0ba6125d328591e7e61606fe7030f2b4edf495f859c584', 'scored', NULL, 9.96, 5.1, 5.1, 'same_as_strict (1.0 result, not re-checked)', 7.72, 10.0, 8.195, 8.195, NULL, NULL, NULL, 4435, 266, 266, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:44+00:00', '2026-09-23T23:25:10+00:00');
