INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CMPO', 'Cellular microscopy phenotype ontology', 'The Cellular Microscopy Phenotype Ontology (CMPO) is a species neutral ontology for describing general phenotypic observations relating to the whole cell, cellular components, cellular processes and cell populations. CMPO is an application ontology developed in OWL that contains precomposed phenotypes descriptions that are defined using the Gene Ontology (GO) and the Phenotype Trait Ontology (PATO).', 'Cell;Cellular_anatomy_;Phenotype', 'OWL', 14, '1.3', '2015-06-24T18:01:45.000-07:00', 'https://bioportal.bioontology.org/ontologies/CMPO', 'b53ac516a20c4477bfd446e7ceae0cbe49d813e6d842d66e340f8220bfe892f7', 'scored', NULL, 9.99, 6.43, 6.43, 'same_as_strict (1.0 result, not re-checked)', 5.15, 10.0, 7.8925, 7.8925, NULL, NULL, NULL, 34117, 814, 814, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:13:46+00:00', '2026-09-23T23:25:10+00:00');
