INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'COB', 'Core Ontology for Biology and Biomedicine', 'The Core Ontology for Biology and Biomedicine (COB) brings together key terms from a wide range of OBO projects into a single, small ontology. The goal is to improve interoperabilty and reuse across the OBO community through better coordination of key terms., COB brings together key terms from a wide range of OBO projects to improve interoperability.', 'Upper_Level_Ontology', 'OWL', 21, '2025-12-15', '2026-05-04T18:01:55.000-07:00', 'https://bioportal.bioontology.org/ontologies/COB', 'e4448e61713271ce96b14226039ce3bcc59b603d83c15c12db069bdc8d5d0d08', 'scored', NULL, 9.86, 4.43, 4.43, 'same_as_strict (1.0 result, not re-checked)', 2.82, 9.0, 6.5275, 6.5275, NULL, NULL, NULL, 612, 70, 70, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:40+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'COCHRANE', 'Cochrane Core Vocabulary Ontology', 'The Cochrane Core ontology describes the entities and concepts that exist in the domain of evidence based healthcare. It is used for the construction of the Cochrane Linked Data Vocabulary containing some 400k terms including Interventions (Drugs, Procedures etc), Populations (Age, Sex, Condition), and clinical Outcomes., The Cochrane Core ontology describes the entities and concepts that exist in the domain of evidence based healthcare.', '', 'OWL', 1, '2.0.1', '2014-02-06T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/COCHRANE', 'ffc34356d65fa4fe05aebb4864379c8a872e339917732b523b52897ade13be6a', 'scored', NULL, 9.62, 5.14, 5.14, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 6.19, 6.19, NULL, NULL, NULL, 254, 26, 26, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:11+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CODO', 'CODO: an Ontology for collection and analysis of COviD-19 data', 'The initial version, CODO ontology v1.0 to v1.3, encompasses pivotal features such as classes like patients, clinical findings, symptoms, and properties like relationships between patients, travel history, and test results. It facilitates tracking specific pandemic cases, detailing how patients may have been infected, and identifying potential contacts at risk due to their connection with the infected individual. CODO also enables monitoring of clinical tests, travel history, available resources, and actual needs like ICU beds and invasive ventilators. With capabilities for advanced analytics, contact tracing, trend studies, and growth projections based on daily COVID-19 data, CODO supports the organization and representation of COVID-19 data on a daily basis. It allows semantic querying and data retrieval and aids in behavior analysis of the disease and transmission routes.

In contrast, Version 1.4, also known as CODO_COVIDRO 1.4 or COVID-19 Drug and Risk Ontology (COViDRO), presents a formal model specifically designed to tackle the multifaceted challenges associated with COVID-19 treatment, risk factors, and drug interactions. The knowledge embedded in the COViDRO model is extracted from diverse medical literature and treatment guidelines provided by reputable organizations such as the World Health Organization (WHO), the National Institutes of Health (NIH), the Food and Drug Administration (FDA), and the Centers for Disease Control and Prevention (CDC). The model incorporates information on therapeutics, adverse effects, and drug interactions from authoritative medical literature, making a significant contribution to patient care, research, and public health strategies.

COViDRO, or COVID-19 Drug and Risk Ontology 1.4, seamlessly integrates into knowledge graph information systems or recommender systems. It assists healthcare professionals in suggesting appropriate treatments by considering a comprehensive set of factors, abbreviated as "PRADiCT" (Patient R', 'Genomic_and_Proteomic;Health;Human;Vocabularies', 'OWL', 6, '1.5', '2023-07-26T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CODO', 'd84a88531a1f6012e6b863231082d756e249354e208c7672e02f95f6f07d55fd', 'scored', NULL, 7.16, 2.41, 2.41, 'same_as_strict (1.0 result, not re-checked)', 4.09, 10.0, 5.915, 5.915, NULL, NULL, NULL, 11214, 1135, 385, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:39+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'COG', 'Common Ontology of Genome', 'The Common Ontology of Genome (COG) is the upper level of the conceptual layer of a genome metamodel and is associated with the next levels of the subdomain ontologies of different type genomes. The taxonomy of COG includes two sub-concepts of the main concept Genome – Structure of genome and Function of genome, and name label Type of genome. These sub-concepts define the mereology part and the name label – the classification part of the taxonomy. The links to the main external knowledge areas are shown, namely, biology and chemistry (as ontologies). ', 'Genomic_and_Proteomic;Upper_Level_Ontology', 'OWL', 1, NULL, '2026-04-25T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/COG', '503f1693dc3c4fd1acfe05af9a98749d6bcde5fe22b33893b9b5ba6289f27eaa', 'scored', NULL, 9.57, 5.66, 5.66, 'same_as_strict (1.0 result, not re-checked)', 0.66, 10.0, 6.4725, 6.4725, NULL, NULL, NULL, 594, 116, 111, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:53+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'COGAT', 'Cognitive Atlas Ontology', 'The Cognitive Atlas is a collaborative knowledge building project that aims to develop an ontology that characterizes the state of current thought in cognitive science.  It defines a set of mental concepts along with a set of mental tasks, and the measurement relations between those classes.', 'Human;Phenotype;Vocabularies', 'OWL', 8, '0.4', '2012-04-03T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/COGAT', '4622b0378bcc6f80ba7d15df1f745f54f9ba43aff2e96ffcd11d4043606a1644', 'scored', NULL, 9.34, 3.73, 3.73, 'same_as_strict (1.0 result, not re-checked)', 1.06, 5.0, 4.7825, 4.7825, NULL, NULL, NULL, 31970, 4054, 4054, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:11:54+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'COGITO', 'Cognitive Task Ontology', 'CogiTO forms a semantic bridge between tasks from Cognitive Atlas and Hierarchical Event Descriptor (HED) in the form of equivalent class axioms. In other words, terms for cognitive tasks are defined by their relation to HED tags.
The purpose of this ontology is to enable querying partially annotated datasets either by a Cognitive Task or by HED tags. ', 'Biomedical_Resources;Experimental_Conditions;Human;Imaging;Vocabularies', 'OWL', 3, '1.1.0', '2025-12-10T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/COGITO', '169a79d7333a638540c13f9fcc36499ac6d98317525da98c1f17695fcdcb8ede', 'scored', NULL, 9.04, 2.92, 2.92, 'same_as_strict (1.0 result, not re-checked)', 4.67, 10.0, 6.6575, 6.6575, NULL, NULL, NULL, 110434, 4690, 4681, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:18:38+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'COGMEMO', 'Thesaurus of the Cognitive Psychology of Human Memory', 'The Thesaurus of the Cognitive Psychology of Human Memory (CogMemo), developed at Inist-CNRS, is a bilingual (French-English) terminological resource covering concepts from cognitive research on human memory: memory systems and processes, empirical effects, memory disorders, study methods, measures, theories, and models. The majority of concepts are documented with a definition and a selective bibliography. Some entries are further enriched with scope notes, examples, moderating variables, and images. References to open datasets and replication studies are also provided. The architecture of the thesaurus is based on hierarchical (broader/narrower), associative, and equivalence (synonyms) relations. To reflect the structure of knowledge in the field of memory, other relations specify the links between concepts.', 'Biological_Process;Health;Human;Neurologic_Disease;Vocabularies', 'SKOS', 1, '2.6', '2026-04-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/COGMEMO', '6e739c7dd27754ed5d316e8a3b9766e85b9ff8631c6f4ddd912fbf12e9de978e', 'scored', NULL, 10.0, 7.23, 7.23, 'same_as_strict (1.0 result, not re-checked)', 8.89, 4.0, 7.53, 7.53, NULL, NULL, NULL, 45333, 1544, 1520, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:15:11+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'COGPO', 'Cognitive Paradigm Ontology', 'This ontology is used to describe the experimental conditions within cognitive/behavioral experiments, primarily in humans.', 'Experimental_Conditions;Human;Imaging', 'OWL', 1, '1', '2010-11-17T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/COGPO', '41fdbb4a786985e873a59c462dfa597e3ad33c0edea3fed566965edaaec5d661', 'scored', NULL, 10.0, 5.88, 5.88, 'same_as_strict (1.0 result, not re-checked)', 5.15, 10.0, 7.7575, 7.7575, NULL, NULL, NULL, 2162, 202, 199, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:55+00:00', '2026-09-23T23:25:10+00:00');
