INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'COID', 'Combined Ontology for Inflammatory Diseases', 'A domain ontology for inflammatory diseases, with ICD-10 used as a foundation. Ontology is expanded to include medical therapies, anatomy, and symptoms. With the addition of synonyms and lay terms derived from embedding models.', 'Anatomy;Human;Phenotype;Vocabularies', 'OWL', 1, '1.0.0', '2022-04-20T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/COID', 'd25f332d2bf68256348e934847d66f45f8f75002a297cfbc61ca3d33869a5e53', 'scored', NULL, 9.99, 4.04, 4.04, 'same_as_strict (1.0 result, not re-checked)', 0.53, 10.0, 6.14, 6.14, NULL, NULL, NULL, 10239, 1186, 1186, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:26+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'COKPME', 'COKPME - COVID19 Ontology for analyzing the Karnataka Private Medical Establishments Data  ', 'The ontology will be used by analysts for finding the relative and precautionary measures that can be put in action for controlling the spread. Also, it should be able to handle the competence question like:
 Which properties of the patient should be considered for modeling
 Which properties of patient changes
 Which properties of patient confirm COVID positive
 Do the symptom of the patient change over time ***
 Do the treatment provided depends on the category of patient
 Do other comorbid conditions derive any interestingness ****
 Which symptom is high in a particular district? (Or) Does the geographical location influence the patient category
These keep change over an iterative process of ontology development', 'Biomedical_Resources;Health', 'OWL', 1, '1.0', '2021-07-09T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/COKPME', '96b16d0086612a0a5e1fb217fa7a37892a90969cc6997df768d8ca2de240b7ec', 'scored', NULL, 4.48, 2.55, 2.55, 'same_as_strict (1.0 result, not re-checked)', 1.11, 7.0, 3.785, 3.785, NULL, NULL, NULL, 480, 58, 26, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:34+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'COLAO', 'Coleoptera Anatomy Ontology', 'The Coleoptera Anatomy Ontology contains terms used for describing the anatomy and phenotype of beetles in biodiversity research. It has been built using the Ontology Develoment Kit with the Ontology for the Anatomy of the Insect SkeletoMuscular system (AISM) as a backbone. The project is open for collaboration.', 'Anatomy;Animal_Gross_Anatomy;Phenotype', 'OWL', 8, '2024-06-21', '2024-06-28T18:03:12.000+00:00', 'https://bioportal.bioontology.org/ontologies/COLAO', '9c5f807dd462e58d19be8e8e1926550cae1c102b9b2b9dc267abdc2071f335ed', 'scored', NULL, 9.99, 6.08, 6.08, 'same_as_strict (1.0 result, not re-checked)', 9.02, 10.0, 8.7725, 8.7725, NULL, NULL, NULL, 41915, 895, 895, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:12:39+00:00', '2026-09-23T23:25:10+00:00');
