INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'COMO', 'Context and Measurement Ontology', 'Ontological terms to describe experimental data, probably useful for other environmental microbiology projects.  Used in several CORAL (Contextual Ontology-based Repository Analysis Library) deployments.  See more about this platfom at https://github.com/jmchandonia/CORAL', 'Biological_Process;Cell;Chemical;Experimental_Conditions', 'OBO', 8, '2025-08-13', '2025-12-15T18:01:55.000-08:00', 'https://bioportal.bioontology.org/ontologies/COMO', 'e4023549008f0f5b630a0886f6b01f1e9af794727697a9b595b2888e6f630387', 'scored', NULL, 9.98, 5.97, 5.97, 'same_as_strict (1.0 result, not re-checked)', 4.45, 10.0, 7.6, 7.6, NULL, NULL, NULL, 6026, 532, 532, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:44+00:00', '2026-09-23T23:25:10+00:00');
