INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CONDOR', 'Liver Cancer Ontology Diagnosis Treatment', 'The CONDOR is a comprehensive framework designed to encapsulate the multifaceted aspects of liver cancer patient care. It encompasses essential elements ranging from patient profiles to disease classifications and treatment options. This ontology aims to streamline the process of liver cancer analysis and treatment, enabling more personalized and effective patient care strategies.', 'Health', 'OWL', 1, '0.1', '2023-11-23T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CONDOR', '0d26fbbff58fce58f45f31dffbf3749218f0b354de884094743ecef4511471a1', 'scored', NULL, 9.82, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 4.955, 4.955, NULL, NULL, NULL, 254, 56, 56, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:20+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CONTSONTO', 'Continuity of care', 'The Ontology of Continuity of care (ContSOnto) is an emerging research area consisting of the extension of a healthcare ontology to inform the continuity of care domain. This field is positioned at the confluence of health informatics, nursing informatics, process modelling, and artificial intelligence. This research relating to ContSOnto is underpinned by health informatics standard ISO 13940 Systems of Concepts for Continuity of Care ContSOnto focuses on how information flows from different information systems across and between services for clinical applications and health care professionals to use. Figure 14.2 provides an illustration (see https://contsys.org/pages/Guest%20blog/FormalOntology)of how the different classes and relationships in the standard are represented. The subject of care refers to the individual service user and health care actors can be human or non-human, for example, a health care professional or an organization. We have added concepts related to social determinants of health (SDH) in version 1.6.  ', 'Biomedical_Resources;Health', 'OWL', 7, 'Version 2.1 (2026)', '2026-07-18T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CONTSONTO', 'fe347f96e5780bcce433d4958c12e373903d09388950ad2b43da7ac410ded0c3', 'scored', NULL, 9.73, 5.53, 5.53, 'same_as_strict (1.0 result, not re-checked)', 4.61, 10.0, 7.4675, 7.4675, NULL, NULL, NULL, 2993, 188, 184, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:22+00:00', '2026-09-23T23:25:10+00:00');
