INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'COSTART', 'Coding Symbols for a Thesaurus of Adverse Reaction Terms', 'Coding Symbols for Thesaurus of Adverse Reaction Terms (COSTART). 5th ed. Rockville (MD). COSTART is used for coding, filing, and retrieving post-marketing adverse drug and biologic experience reports. COSTART is organized in body system and pathophysiology hierarchies, as well as a separate fetal/neonatal category of less than 20 terms.

COSTART has been superseded by the Medical Dictionary for Regulatory Activities (MedDRA) Terminology. For more information about MedDRA in the Metathesaurus, see the MedDRA source synopsis.

COSTART was last updated in the Metathesaurus in 1999.', 'Health', 'UMLS', 1, 'CSP2006', '2013-05-08T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/COSTART', 'a62deabeec032639707834fb2f96460d4496d86641d6248a896aeb1aa154e7f0', 'scored', NULL, 10.0, 0.01, 0.01, 'same_as_strict (1.0 result, not re-checked)', 7.38, 10.0, 6.8475, 6.8475, NULL, NULL, NULL, 23646, 1713, 1713, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:11:07+00:00', '2026-09-23T23:25:10+00:00');
