INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'COVID-19-ONT-PM', 'COVID-19OntologyInPatternMedicine', 'This ontology will focus on the COVID-19 fields in order to help the hard efforts against the outbreak of the pandemic. It is expected, through the ontology, to understand the medical events or conditions and make medical decisions in more integrated or systematic ways, based on more engineered or calculation methods.
This ontology will also be involved in the explorations on the Pattern Medicines (PMs) and so called the Generalized Biology Mechanics (GBM), raised by the author in his Biomedical Knowledge Integration (BMKI), a pilot topic full of challenges.  
', 'Biomedical_Resources', 'OWL', 9, '007', '2021-08-20T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/COVID-19-ONT-PM', '9a3cb1cb8921f34d58dd777675d73464e3fd18ebdb2b1daff2b88ca8f0fe9520', 'scored', NULL, 9.54, 0.11, 0.11, 'same_as_strict (1.0 result, not re-checked)', 2.18, 10.0, 5.4575, 5.4575, NULL, NULL, NULL, 1908, 306, 300, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:01+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'COVID19', 'COVID-19 Surveillance Ontology', 'The COVID-19 Surveillance Ontology is an application ontology used to support SARS-CoV-2 (severe acute respiratory syndrome coronavirus 2)  surveillance in primary care. The ontology facilitates monitoring of COVID-19 cases and related respiratory conditions using data from multiple brands of computerised medical record systems.', 'Health;Human', 'OWL', 3, 'V1.0', '2020-08-05T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/COVID19', 'edb7b1a14bcea636eabea466257cd155dc9214848a5e1d0b291e01249bc0be38', 'scored', NULL, 9.7, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 7.0, 4.175, 4.175, NULL, NULL, NULL, 166, 33, 33, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:03:58+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'COVID19-IBO', 'Covid19 Impact on Banking Ontology', 'Covid19 Impact on Banking Ontology (Covid19-IBO) provides semantic information about the impact of the Covid-19 on the banking sector of India', 'Other', 'OWL', 6, '1.5', '2021-06-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/COVID19-IBO', '0f1e37dc9ad9727255838d857ba5df0883ed68e0d74a13f873d3b8fcc0445e9d', 'scored', NULL, 7.5, 0.17, 0.17, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 4.4175, 4.4175, NULL, NULL, NULL, 714, 160, 160, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:59+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'COVIDCRFRAPID', 'WHO COVID-19 Rapid Version CRF semantic data model', 'This is a semantic data model for the WHO''s COVID-19 case record form RAPID version from April 8 2020. It aims at providing semantic references to the questions and answers of the form.

Changes in the version 1.1.4:
- Corrected: Urea_(BUN) to remove the "()", which may cause resolution and validation issues;

Changes in the version 1.1.3:
- Corrected: Chloroquine/hydroxychloroquine to remove the "/", which may cause resolution issues;

Changes in version 1.1.2:
- Corrected: Cough with haemoptysis because the IRI was mispelled;
- Corrected: CPAP/NIV Mask to remove the "/", which may cause resolution issues;
- Added: missing "part of" property for section 1g.
- Added: "has other measurement unit label" property for the laboratory results that may use a different unit than specified in the CRF;
- Added: missing "has value" for the Which coronavirus question;
- Added: missing possibility to enter the name of a specific antibiotic in section 3c of the CRF;
- Added: missing question on testing the presence of other pathogenic of public health interest from section 3a of the CRF.

Changes in version 1.1.1:
- Added: Facility Name to identify the care facility in which the case is reported from.

Changes in version 1.1.0:
- This version covers the modifications introduced by the WHO COVID-19 Rapid CRF from April 8, 2020. The model maintains backward compatibility with the WHO COVID-19 Rapid CRF from March 23, 2020.', 'Health', 'OWL', 12, '1.1.4', '2020-06-24T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/COVIDCRFRAPID', '715622801c96b2bca8735f6b28b6bbdb077581f65d02a6c047d900fc7d214c46', 'scored', NULL, 9.85, 0.91, 0.91, 'same_as_strict (1.0 result, not re-checked)', 6.2, 10.0, 6.74, 6.74, NULL, NULL, NULL, 4855, 480, 397, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:59+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CPRO', 'Computer-Based Patient Record Ontology', 'A uniform core set of data elements (whose formal semantics are captured in OWL) for use in a Computer-Based Patient Record (CPR)', 'Health', 'OWL', 3, 'Last modification: July 31th, 2011 Chimezie Ogbuji', '2013-04-24T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/CPRO', '6905dd4e09b9e7dd474003be1ca61208110770d4b05e7f417a1743f897a234ef', 'scored', NULL, 10.0, 4.94, 4.94, 'same_as_strict (1.0 result, not re-checked)', 4.53, 9.0, 7.1175, 7.1175, NULL, NULL, NULL, 1977, 128, 128, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:50+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CPT', 'CPT - Current Procedural Terminology', 'CPT is a list of descriptive terms and identifying numeric codes for medical services and procedures that are provided by physicians and health care professionals.', 'Other', 'UMLS', 3, '2020AB', '2020-11-02T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CPT', NULL, 'not_downloadable', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CPTAC', 'CPTAC Proteomics Pipeline Infrastructure Ontology', 'a basic ontology which describes the proteomics pipeline infrastructure for CPTAC project', 'Genomic_and_Proteomic', 'OWL', 3, 'alpha 1.1', '2009-05-20T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/CPTAC', '282746a61f3f537ed147656e7240f50efcaf2f48b5dc65ea561ae0cdde78cd51', 'scored', NULL, 9.5, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.375, 2.375, NULL, NULL, NULL, 1607, 20, 20, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:05:42+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CRENO', 'Culture, Race, Ethnicity and Nationality Ontology', 'This work undertakes the possibility of using the Web Ontology Language (OWL2) to describe concepts related to "culture", "race", "ethnicity", and "nationality" - concepts that are sometimes misunderstood/misused due to lack of standardization and biases. The project also attempts to link data relating to these broad concepts to health data, like cancer rates, and shed light on understanding health disparities that impact certain communities. This work is early in development and preliminary. ', 'Human;Other', 'OWL', 2, '0.6', '2024-02-05T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CRENO', 'e18ddb25b690efffaa94b5fb8ca3d0ad58a79abc5051e5d943693bb92542b757', 'scored', NULL, 9.74, 3.7, 3.7, 'same_as_strict (1.0 result, not re-checked)', 1.82, 10.0, 6.315, 6.315, NULL, NULL, NULL, 11100, 1136, 1108, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:11+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CRISP', 'Computer Retrieval of Information on Scientific Projects Thesaurus', 'The Computer Retrieval of Information on Scientific Projects (CRISP) Thesaurus was developed by the National Institutes of Health for use in the CRISP database of research projects funded by the U.S. Public Health Service (PHS).

CRISP contains over 8,000 preferred terms that are grouped hierarchically into 11 domains. The 11 domains are:

- anatomy
- behavioral/social science
- biology
- chemical
- disease/disorder
- food science/technology
- medicine
- named group
- organism
- physical science
