INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CTCAE', 'Common Terminology Criteria for Adverse Events', 'Common Terminology Criteria for Adverse Events (CTCAE) is widely accepted throughout the oncology community as the standard classification and severity grading scale for adverse events in cancer therapy clinical trials and other oncology settings. Version 6 was published by the NCI Cancer Therapy Evaluation Program (CTEP) in July 2025. It is organized by MedDRA System Organ Class and mapped to MedDRA LLTs with corresponding MedDRA codes, and harmonized with MedDRA at the Adverse Event (AE) level including revised AE terms and severity indicators to reflect clinical effects identified with current oncology interventions. Severity grades are assigned and most are defined to clarify the meaning of the term. CTCAE is designed to integrate into information networks for safety data exchange, and is the primary standard for data management for AE data collection, analysis, and patient outcomes associated with cancer research and care.', '', 'OWL', 4, '6.0', '2026-08-12T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CTCAE', '1ff73c119bbbd401e8d0e31995de3f4a189ff37206d6a83ae5da7552194a585e', 'scored', NULL, 10.0, 0.0, 6.68, 'http://ncicb.nci.nih.gov/xml/owl/EVS/ctcae5.owl#DEFINITION [bioportal_definitionProperty]; http://ncicb.nci.nih.gov/xml/owl/EVS/Thesaurus.owl#P97 [detected_by_name (4124 uses)]', 8.14, 9.0, 6.785, 8.455, NULL, NULL, NULL, 172367, 4113, 4113, '0.10.0', 'core4-1.1.1', NULL, '2026-09-23T22:58:05+00:00', '2026-09-23T23:25:10+00:00');
