INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CVDO', 'Cardiovascular Disease Ontology', 'CVDO is an ontology based on the OGMS model of disease, designed to describe entities related to cardiovascular diseases (including the diseases themselves, the underlying disorders, and the related pathological processes). It is being developed at Sherbrooke University (Canada) and the INSERM research institute (Institut National de la Santé et de la Recherche Médicale).', 'Health', 'OWL', 5, '2024-05-17', '2024-06-17T18:03:20.000+00:00', 'https://bioportal.bioontology.org/ontologies/CVDO', 'f09effd1666b2a3eb627c2c23332df867d106cf01a46fc2197e70c79ed487457', 'scored', NULL, 9.99, 1.31, 1.31, 'same_as_strict (1.0 result, not re-checked)', 2.31, 10.0, 5.9025, 5.9025, NULL, NULL, NULL, 16230, 721, 721, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:24+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CWD', 'Consumer Wearable Device', 'Consumer Wearable Devices (CWD) enable passive, low-burden, longitudinal collection of data relevant to health behaviors, human performance, and biometrics.   Such data are increasingly used to tailor clinical and public health interventions and as outcome measures in clinical trials.  The uptake of CWD in research applications warrants an examination of the data collected from these products.  This ontology was developed based on a review of publicly available documentation and data sets from three CWD vendors and is open for researchers to modify + extend as new features become available.  




', 'Health', 'OWL', 1, NULL, '2018-04-19T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CWD', 'e88deea57b2ce9f562523452d0df9714053b02044219a4f581e3557a53c356f0', 'scored', NULL, 9.36, 4.38, 4.38, 'same_as_strict (1.0 result, not re-checked)', 0.65, 9.0, 5.8475, 5.8475, NULL, NULL, NULL, 205, 47, 47, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:06+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CXSO', 'Cathexis Somatic Ontology', 'A formal vocabulary for representing body-based therapeutic experience in computational systems. The Cathexis Somatic Ontology (CSO) defines 29 anatomical zones, 20 sensation qualities, 7 primary affect systems, 19 brain regions, 11 functional networks, 5 ecological context layers, and 16 territories of human experience. Designed for digital mental health platforms, AI agent integration via Model Context Protocol (MCP), and clinical research. Grounded in constructed emotion theory (Barrett), predictive processing (Friston), primary affect systems (Panksepp), somatic markers (Damasio), neuropsychoanalysis (Solms), the entangled brain (Pessoa), and memory systems and reconsolidation (Kandel)., A formal vocabulary and relational schema for encoding body-based therapeutic experience computationally. Defines entity classes for anatomical zones, sensation qualities, neurobiological organization patterns (territories), therapeutic change mechanisms, brain regions, ecological layers, and intervention architectures, organized within a Markov blanket framework.', 'Anatomy;Biological_Process;Health;Human;Neurological_Disorder;Phenotype', 'OWL', 2, '1.1', '2026-05-29T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CXSO', 'c1e61ed52207f44382d64de39568944638f0878ff11f9e0881af04e9bbe2c68e', 'scored', NULL, 9.94, 6.02, 6.02, 'same_as_strict (1.0 result, not re-checked)', 2.42, 7.0, 6.345, 6.345, NULL, NULL, NULL, 869, 154, 18, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:00+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'CYTO', 'CYTOKINE', 'It is flat ontology showing cytokine synonyms. It has been produced by merging cytokine branches, using SOMA (Synonym Ontology Mapping Approach) method, of 10 Bioportal ontologies.', 'Protein', 'OWL', 27, 'Cytokines', '2015-06-24T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/CYTO', 'ee046790557724de0f6fbc1d09b14acda27cf7a13bced3977cd459cfe893f59d', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 7.0, 4.25, 4.25, NULL, NULL, NULL, 5705, 318, 317, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:07:41+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'D3O', 'DSMZ Digital Diversity Ontology', 'The DSMZ Digital Diversity Ontology (D3O) is an ontology designed to standardize and integrate data related to microbial diversity and associated resources within the context of the DSMZ’s Digital Diversity Knowledge Graph. This ontology provides a structured framework to represent various aspects of microbial data, including taxonomic information, strain properties, cultivation conditions, and media links. D3O facilitates cross-referencing between internal DSMZ datasets and external biological resources, supporting enhanced data discovery, interoperability, and research in microbiology, genomics, and metabolomics.

The ontology includes both object properties, which link entities such as bacterial strains to external resources (e.g., literature references or media descriptions), and data properties, which associate entities with literal values (e.g., taxonomic identifiers, growth conditions). Designed for use in RDF-based knowledge graphs, D3O supports flexible integration with other life science ontologies, promoting consistency and reuse in the broader scientific community.', 'Biomedical_Resources;Microbial_Anatomy;Phenotype;Upper_Level_Ontology', 'OWL', 3, '1.1', '2024-09-23T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/D3O', '1f98a5b1a2dfbf5e4e7e5da3e461646dd0dc94798366d97a317d26da843fda5e', 'scored', NULL, 9.97, 6.4, 6.4, 'same_as_strict (1.0 result, not re-checked)', 5.19, 10.0, 7.89, 7.89, NULL, NULL, NULL, 2137, 295, 295, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:57+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DATACITE', 'SPAR DataCite Ontology', 'The DataCite Ontology (DataCite) is an ontology that enables the metadata properties of the DataCite Metadata Schema Specification (i.e., a list of metadata properties for the accurate and consistent identification of a resource for citation and retrieval purposes) to be described in RDF., The DataCite Ontology is an ontology written in OWL 2 DL to enable the metadata properties of the [DataCite Metadata Kernel Specification version 3.1](https://www.datacite.org/sites/default/files/document/DataCite-MetadataSchema_V31_Final_8-24-2015_0.pdf) to be described in RDF.  

This version of the DataCite Ontology has been completely revised and significantly expanded to permit accurate mapping of this new version of the DataCite Metadata Kernel Specification to RDF., http://purl.org/spar/datacite/datacite.png, 
## Description

The _DataCite Ontology_ (or simply DataCite) is an ontology written in OWL 2 DL to enable the metadata properties of the [DataCite Metadata Schema (version 4.7)](https://datacite-metadata-schema.readthedocs.io/en/4.7/) to be described in RDF. 

![A diagram of the DataCite Ontology.](datacite.png)

The main intent of the DataCite Ontology is to provide a flexible mechanism to define identifiers for bibliographic resources (e.g., papers and datasets) and related entities (e.g., authors). To this end, DataCite uses the object property `datacite:hasIdentifier`, which has as its object a member of the class `datacite:Identifier` or of one of its sub-classes (`datacite:ResourceIdentifier`, `datacite:AgentIdentifier` or `datacite:RightsIdentifier`). 
In turn, `datacite:AgentIdentifier` is further sub-classed by three additional classes, i.e., `datacite:PersonalIdentifier`, `datacite:OrganizationIdentifier`, and `datacite:FunderIdentifier`. 
The exact nature of the identifier is then defined using the second DataCite object property `datacite:usesIdentifierScheme`, which has as its object the class `datacite:IdentifierScheme` or one of its sub-classes: `dataci', 'Other', 'OWL', 4, '1.3.1', '2016-01-21T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DATACITE', '5e95934e3937a33617deaba8f937f840cc9b57ef18d56e53e6011b8c0b2f2b97', 'scored', NULL, 10.0, 6.4, 6.4, 'same_as_strict (1.0 result, not re-checked)', 0.83, 8.0, 6.3075, 6.3075, NULL, NULL, NULL, 1111, 104, 25, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:32+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DATACITE-VOCAB', 'DATACITE V4.4', 'Controlled vocabularies allow an accurate and controlled approach in describing physical and digital assets (e.g., data). One of such controlled vocabulary is Datacite Controlled Vocabulary. This controlled vocabulary is produced based on description of Datacite Schema V4.4. The work of creating this controlled vocabulary is part of FAIRware project which if funded by RoRi.

sheet2rdf is used to build Datacite Controlled Vocabulary, while PURL, is used to persist and resolve identifiers via BioPortal for the vocabulary terms.', '', 'SKOS', 5, '0.1.0', '2022-05-13T18:03:34.000-07:00', 'https://bioportal.bioontology.org/ontologies/DATACITE-VOCAB', '3fb6f5a0986a481a90e94fb8af12ab4b14eaac0f16128ebfcb6e01f086b24406', 'scored', NULL, 9.93, 0.1, 0.1, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.5075, 2.5075, NULL, NULL, NULL, 817, 135, 134, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:45+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DATAHUB', 'RADx Data Hub Ontology', 'The RADx Data Hub Ontology provides a formally structured vocabulary to describe key concepts within the RADx Data Hub. <br><br>

The primary purpose of the ontology is to:

1) Document key terms used in the Data Hub
The ontology lists and organizes the main types of entities and relationships that are relevant to the RADx Data Hub. This helps ensure that core terms are recorded in a consistent and reusable way.

2) Clarify the meaning of those terms
Each term is defined to reduce confusion and make its intended meaning clear to both technical and non-technical users. This helps support consistent use across teams and tools.

3) Provide synonyms and alternate labels to support consistent usage
The ontology includes common synonyms or alternative names for terms to account for variation in how different groups of users refer to the same thing. This supports alignment across documentation, user interfaces, and data submission processes.

4) Maintain a glossary of acronyms commonly used in RADx
Frequently used acronyms are included as part of the ontology, linked to their full forms and definitions. This helps reduce ambiguity and supports clearer communication across documentation, interfaces, and stakeholder groups.
<br><br>
This shared vocabulary, that is provided and defined by the ontology, serves as the source of truth for terminology used across metadata records, user interfaces, documentation, and program communications.
', '', 'OWL', 4, '0.9.3', '2025-03-25T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DATAHUB', '14d7e038620be6316e6c134207434d6c501efcf1199cfca1f49b226c25d444cd', 'scored', NULL, 9.92, 5.93, 5.93, 'same_as_strict (1.0 result, not re-checked)', 0.5, 9.0, 6.3375, 6.3375, NULL, NULL, NULL, 769, 123, 113, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:52+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DBM', 'DBM Ontology', 'An ontology for the Drug Bureau of Macedonia (DBM)., An ontology for describing brand-name drugs.', '', 'OWL', 1, '1.1', '2014-09-01T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DBM', 'e2a1d686800c2947f7039321423a7b9748336e83be5e51e57ab679d0d5ac7125', 'scored', NULL, 6.67, 2.16, 2.16, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.2075, 2.2075, NULL, NULL, NULL, 149, 3, 3, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:03:58+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DC', 'Dublin Core', 'The Dublin Core Schema is a small set of vocabulary terms that can be used to describe several kinds of resources. Dublin Core Metadata may be used for multiple purposes, from simple resource description, to combining metadata vocabularies of different metadata standards, to providing interoperability for metadata vocabularies in the Linked Data cloud and Semantic Web implementations.', 'Other', 'OWL', 3, NULL, '2017-02-17T18:01:47.000-08:00', 'https://bioportal.bioontology.org/ontologies/DC', 'a72096ffa67e4d2eb62c1e1ad460fbe3f1f0ff0c7153e7500d0ae332c5406bb7', 'scored', NULL, 9.74, 6.16, 6.16, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 3.975, 3.975, NULL, NULL, NULL, 782, 38, 12, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:48+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DCAT', 'Data Catalog Vocabulary', 'DCAT is an RDF vocabulary designed to facilitate interoperability between data catalogs published on the Web.', 'Other', 'OWL', 2, NULL, '2014-01-16T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DCAT', 'e8f4296424fd0391771caee4180d63cf9d11319616f01f33893b40af655860d7', 'scored', NULL, 9.41, 2.77, 2.77, 'same_as_strict (1.0 result, not re-checked)', 0.0, 5.0, 4.295, 4.295, NULL, NULL, NULL, 270, 17, 16, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:21+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DCAT-FDC', 'Data Catalog Vocabulary (DCAT)', 'DCAT is an RDF vocabulary designed to facilitate interoperability between data catalogs published on the Web. This document defines the schema and provides examples for its use.

DCAT enables a publisher to describe datasets and data services in a catalog using a standard model and vocabulary that facilitates the consumption and aggregation of metadata from multiple catalogs. This can increase the discoverability of datasets and data services. It also makes it possible to have a decentralized approach to publishing data catalogs and makes federated search for datasets across catalogs in multiple sites possible using the same query mechanism and structure. Aggregated DCAT metadata can serve as a manifest file as part of the digital preservation process.

The namespace for DCAT terms is http://www.w3.org/ns/dcat#

The suggested prefix for the DCAT namespace is dcat', '', 'OWL', 1, 'Toto je aktualizovaná kopie slovníku DCAT verze 2.0, převzatá z https://www.w3.org/ns/dcat.ttl', '2021-09-23T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DCAT-FDC', '2f035f8c7a44f0ba3ba247b1baf71aa6767fdfba24aa164749bf56c8d8ae3f04', 'scored', NULL, 9.88, 5.07, 5.07, 'same_as_strict (1.0 result, not re-checked)', 1.41, 8.0, 6.09, 6.09, NULL, NULL, NULL, 3651, 83, 73, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:56+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DCAT3', 'DCAT3', 'Data Catalog Vocabulary (DCAT) - Version 3 is an RDF vocabulary designed to facilitate interoperability between data catalogs published on the Web. By using DCAT to describe datasets in data catalogs, publishers increase discoverability and enable applications easily to consume metadata from multiple catalogs. It further enables decentralized publishing of catalogs and facilitates federated dataset search across sites. Aggregated DCAT metadata can serve as a manifest file to facilitate digital preservation., هي أنطولوجية تسهل تبادل البيانات بين مختلف الفهارس على الوب. استخدام هذه الأنطولوجية يساعد على اكتشاف قوائم  البيانات المنشورة على الوب و يمكن التطبيقات المختلفة من الاستفادة أتوماتيكيا من البيانات المتاحة من مختلف الفهارس., Το DCAT είναι ένα RDF λεξιλόγιο που σχεδιάσθηκε για να κάνει εφικτή τη διαλειτουργικότητα μεταξύ καταλόγων δεδομένων στον Παγκόσμιο Ιστό. Χρησιμοποιώντας το DCAT για την περιγραφή συνόλων δεδομένων, οι εκδότες αυτών αυξάνουν την ανακαλυψιμότητα και επιτρέπουν στις εφαρμογές την εύκολη κατανάλωση μεταδεδομένων από πολλαπλούς καταλόγους. Επιπλέον, δίνει τη δυνατότητα για αποκεντρωμένη έκδοση και διάθεση καταλόγων και επιτρέπει δυνατότητες ενοποιημένης αναζήτησης μεταξύ διαφορετικών πηγών. Συγκεντρωτικά μεταδεδομένα που έχουν περιγραφεί με το DCAT μπορούν να χρησιμοποιηθούν σαν ένα δηλωτικό αρχείο (manifest file) ώστε να διευκολύνουν την ψηφιακή συντήρηση., DCATは、ウェブ上で公開されたデータ・カタログ間の相互運用性の促進を目的とするRDFの語彙です。このドキュメントでは、その利用のために、スキーマを定義し、例を提供します。データ・カタログ内のデータセットを記述するためにDCATを用いると、公開者が、発見可能性を増加させ、アプリケーションが複数のカタログのメタデータを容易に利用できるようになります。さらに、カタログの分散公開を可能にし、複数のサイトにまたがるデータセットの統合検索を促進します。集約されたDCATメタデータは、ディジタル保存を促進するためのマニフェスト・ファイルとして使用できます。, DCAT è un vocabolario RDF progettato per facilitare l''interoperabilità tra i cataloghi di dati pubblicati nel Web. Utilizzando DCAT per descrivere i dataset nei cataloghi di dati, i fornitori migliorano la capacità di individuazione dei dati e abilitano le  applicazioni al consumo di dati provenienti da cataloghi differ', '', 'OWL', 3, '3', '2020-12-17T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DCAT3', '845b5ba1b99f882d2395235e437990942c3ce19006abf08d8596522093fdcee6', 'scored', NULL, 10.0, 4.41, 4.41, 'same_as_strict (1.0 result, not re-checked)', 1.77, 8.0, 6.045, 6.045, NULL, NULL, NULL, 4012, 97, 75, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:08+00:00', '2026-09-23T23:25:10+00:00');
