INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DCO', 'Dispedia Core Ontology', 'Dispedia Core Ontology is a schema for information brokering and knowledge management in the complex field of rare diseases. On the one hand, the Dispedia schema uses semantic technologies to describe patients affected by rare diseases, and on the other hand, to record expertise concerning these particular diseases in machine-processable form. In addition to the differentiated attribution of facts to the individual need for information, Dispedia enables information brokering which adjusts to the type of recipient, its character as well as its personal attitude. The schema was initially geared to an exemplified disease, Amyotrophe Lateralsclerose (ALS).', 'Health;Human;Other;Vocabularies', 'OWL', 34, '0.7.0.0002', '2015-03-05T10:11:07.000-08:00', 'https://bioportal.bioontology.org/ontologies/DCO', '8911008cce1b461cc019a6541a46525ee5c6264069caba306afb9d78506ae201', 'scored', NULL, 5.4, 0.43, 0.43, 'same_as_strict (1.0 result, not re-checked)', 0.0, 7.0, 3.2075, 3.2075, NULL, NULL, NULL, 648, 50, 50, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:39+00:00', '2026-09-23T23:25:10+00:00');
