INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DDI', 'Ontology for Drug Discovery Investigations', 'The goal of DDI project is to develop an ontology for the description of drug discovery investigations. DDI aims to follow to the OBO (Open Biomedical Ontologies) Foundry principles, uses relations laid down in the OBO Relation Ontology, and be compliant with Ontology for biomedical investigations (OBI).', '', 'OWL', 2, '$Revision$', '2011-01-01T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/DDI', '43b39e5fee7c8fc4b88a2a6ea2edf66e7ba6ee2feecb8a8ea51b3a0329fe29ff', 'scored', NULL, 9.81, 5.7, 5.7, 'same_as_strict (1.0 result, not re-checked)', 3.96, 10.0, 7.3675, 7.3675, NULL, NULL, NULL, 2064, 159, 156, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:01+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DDIEM', 'Drug Database for Inborn Errors of Metabolism (DDIEM) Ontology', 'DDIEM Ontology for the Drug Database for Inborn Errors of Metabolism. The DDIEM database is a database of therapeutic strategies and treatments for inborn errors of metabolism. These strategies are classified by mechanism and outcome using the DDIEM Ontology. The DDIEM database also includes descriptions of the phenotypes addressed by the treatment, together with drugs and procedures applied.', 'Biomedical_Resources', 'OWL', 4, '1.2', '2019-12-30T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DDIEM', 'a5c212b02637d8de909a34b093cbff54b0fc71d94b96bcde4f63c9c04e55fbb6', 'scored', NULL, 10.0, 5.15, 5.15, 'same_as_strict (1.0 result, not re-checked)', 1.8, 10.0, 6.7375, 6.7375, NULL, NULL, NULL, 2856, 225, 208, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:23+00:00', '2026-09-23T23:25:10+00:00');
