INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DDSIO', 'Diabetic Drug Side Effects and Interactions Ontology', 'The Diabetic Drug Side Effects and Interactions Ontology (DDSIO) is a domain ontology for representing knowledge related to antidiabetic drugs, drug classes, adverse effects, drug-drug interactions, drug-food interactions, drug-disease interactions, and patient-drug relationships. DDSIO is designed to support knowledge representation and medication-safety assessment in diabetes-related prescription decision-support applications.', 'Health', 'OWL', 1, '1.0.0', '2026-08-21T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DDSIO', 'd383c59c1eda0d1a34690daa48699142c590d70e59fb11f58a3f27b0f75a5245', 'scored', NULL, 5.83, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 6.28, 8.0, 5.0275, 5.0275, NULL, NULL, NULL, 1073, 192, 22, '0.10.0', 'core4-1.0', NULL, '2026-09-23T03:26:19+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DDSS', 'Health_ontology', 'This resource encompasses mappings from different ontologies: the Disease Ontology (DOID), the Symptom Ontology (SYMP), the Drug Ontology (DRON), and entities from OpenFDA for side effects.', '', 'OWL', 1, NULL, '2024-07-04T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DDSS', 'df1668ff20ff018b9fedfe6c2b073bc15649538c60a4c341e3087b7d311c9108', 'scored', NULL, 9.96, 0.15, 0.15, 'same_as_strict (1.0 result, not re-checked)', 7.45, 10.0, 6.89, 6.89, NULL, NULL, NULL, 10971092, 767030, 767011, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T08:32:44+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DEB', 'Devices, Experimental scaffolds and Biomaterials Ontology', 'An ontology developed to facilitate information curation in the area of medical devices, experimental scaffolds and biomaterials. The ontology was designed to complement existing medical vocabularies, with emphasis on material processing, structures and features associated with biomaterials and experimental scaffolds. It is used as part of an automated text mining pipeline which populates the database of Experimental Biomaterials and their Biological Effect (DEBBIE). 
DEBBIE is an EU Horizon 2020 funded project. For more information visit https://projectdebbie.github.io/ ', 'Biomedical_Resources', 'OWL', 7, '4.0', '2021-06-02T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DEB', '65dab359afada180509bec42d25fa094b4245e237971723ad443d4ecca8bea18', 'scored', NULL, 9.95, 0.41, 0.41, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 5.09, 5.09, NULL, NULL, NULL, 2963, 602, 602, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:36+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DECIDE', 'DECIDE ONTOLOGY', 'DECIDE ontology provides a semantic framework for describing and integrating knowledge related to both aquaculture and terrestrial livestock species.
This ontology was developed as part of the DECIDE EU 2020 project to support data integration, classification, and knowledge modeling in the domain of aquaculture. It provides a structured, upper-level framework for representing species (such as salmon, cattle, poultry, and pigs), production systems, measurement events, and health-related information including clinical signs, diagnostics, and interventions. 

The ontology is designed to be modular and extensible, and it can be adapted or reused for terrestrial livestock species such as cattle, poultry, and pigs.
 
seeAlso: LivestockHealthOntology
https://bioportal.bioontology.org/ontologies/LHO 

Its purpose is to facilitate harmonized data representation for improved disease surveillance, risk assessment, and decision support across livestock sectors.', 'All_Organisms', 'OWL', 2, 'Version 1.2', '2022-12-03T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DECIDE', '43b57854e75adcb5c070d63389ba5cc395ee0337ca52e36caba9d9212cad09c3', 'scored', NULL, 6.12, 3.23, 3.23, 'same_as_strict (1.0 result, not re-checked)', 0.0, 7.0, 4.0875, 4.0875, NULL, NULL, NULL, 368, 49, 24, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:24+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DEMLAB', 'Dem@Care Lab Ontology for Dementia Assessment', 'The ontology has been developed in the framework of the Dem@Care project for representing the experimentation protocol towards diagnostic support and assessment of Dementia in a controlled environment. The aim of the protocol is to provide a brief overview of their health status of the participants during consultation (cognition, behaviours and function), and to correlate the system (sensor) data with the data collected using typical dementia care assessment tools., and to correlate the system (sensor) data with the data collected using typical dementia care assessment tools.

The ontology describes the basic Steps of the experimentation protocol (Directed Activities, Semi-directed Activities and Free Discussion with the Clinician), the Tasks that are involved, as well as the measurement types relevant to each Task. The defined protocol can be reused and further extended, adding new steps, tasks and measured data.

Documentation regarding the ontology vocabulary can be found at http://www.demcare.eu/ontologies/demlab.html', '', 'OWL', 1, '1.0', '2014-09-02T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DEMLAB', '96f5282e4f86c9669a321bd03278c83337cc8db82b9894531f4dfadc0fd56ec9', 'scored', NULL, 9.31, 5.08, 5.08, 'same_as_strict (1.0 result, not re-checked)', 3.77, 9.0, 6.79, 6.79, NULL, NULL, NULL, 3220, 130, 101, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:31+00:00', '2026-09-23T23:25:10+00:00');
