INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DIAGONT', 'Diagnostic Ontology', 'We built a computational diagnostic ontology containing 91 elements, including classes and sub-classes, which are required to conduct SR-MA (Systematic Review - Meta Analysis) for diagnostic studies, that will assist in standardized reporting of diagnostic articles. We also report high percentage of agreement among five observers as a result of the inter-observer agreement that we conducted among them to tag 13 articles using the diagnostic ontology. Moreover, we extend our existing repository CERR-N (Center of Excellence in Research Reporting in Neurosurgery) to include diagnostic studies.', '', 'OWL', 1, '2.0', '2011-12-15T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/DIAGONT', '436dbf1e5cac9672ca10ffc685e49e0b16b7ce8d0f384dcb621ec30ac9f81cd4', 'scored', NULL, 9.42, 1.7, 1.7, 'same_as_strict (1.0 result, not re-checked)', 1.35, 10.0, 5.6175, 5.6175, NULL, NULL, NULL, 615, 103, 97, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:47+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DICOM', 'Healthcare metadata - DICOM ontology', 'Ontology for healthcare metadata - especially metadata found in DICOM files (Digital Imaging and Communications in Medicine, see http://dicom.nema.org/). Author: Michael Brunnbauer, Bonubase GmbH (www.bonubase.com). The author''s email address is brunni@netestate.de. See http://purl.org/healthcarevocab/v1help for explanations.', '', 'OWL', 2, 'v2015-01-11', '2013-04-29T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DICOM', 'ba9f5d0bd5f523fd2eec71c75d3d4eec3ba1d3cadc59df05faba517576238eab', 'scored', NULL, 9.99, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 3.27, 4.0, 4.315, 4.315, NULL, NULL, NULL, 71280, 1594, 1594, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:16:36+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DIDEO', 'Drug Interaction and Evidence Ontology', 'The Potential Drug-drug Interaction and Potential Drug-drug Interaction Evidence Ontology. DIDEO is created as part of an NIH-funded project aiming towards developing a new knowledge base for potential drug drug interaction information. In DIDEO we represent PDDIs as information content entities and we aim to also provide the evidence for those entities using nano- and micro publication approaches.', 'Health', 'OWL', 48, 'release version 2017-11-17', '2017-10-15T18:01:33.000-07:00', 'https://bioportal.bioontology.org/ontologies/DIDEO', 'a705ecb93d35dbd34f1a0ebea04334ec79d011ea75f700c66a2864d99d7356f2', 'scored', NULL, 10.0, 5.45, 5.45, 'same_as_strict (1.0 result, not re-checked)', 2.63, 10.0, 7.02, 7.02, NULL, NULL, NULL, 13848, 636, 617, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:49+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DIKB', 'Drug Interaction Knowledge Base Ontology', 'An evidence taxonomy for pharmacologic studies that, when combined with a set of inclusion criteria, enable drug experts to specify what their confidence in a drug mechanism assertion would be if it were supported by a specific set of evidence.

Boyce R, Collins C, Horn J, Kalet I. Computing with evidence Part I: A drug-mechanism evidence taxonomy oriented toward confidence assignment. J Biomed Inform. 2009 Dec;42(6):979-89. Epub 2009 May 10. PubMed PMID: 19435613; PubMed Central PMCID: PMC2783801. ', 'Vocabularies', 'OWL', 5, 'Version 1.6', '2015-05-18T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DIKB', 'f0cfc30aa3718d58e16ed7b855e38d7463ee2c96e347131b74ce3aee245cb6ed', 'scored', NULL, 9.35, 6.2, 6.2, 'same_as_strict (1.0 result, not re-checked)', 3.42, 9.0, 6.9925, 6.9925, NULL, NULL, NULL, 2920, 170, 161, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:52+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DILON', 'Dietary lifestyle ontology', 'DILON was created to represent dietary lifestyle data.  Concepts were pulled from Korean dietary assessment scales and English assessment scales. Concepts are labeled in English and Korean translations are also provided.', 'Health;Human', 'OWL', 2, '2', '2021-11-02T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DILON', 'bb8e12a2d3a29e519b9e1ebfdb0afc4ef4d6df5f37cb1ed04b91f718832c3a00', 'scored', NULL, 9.64, 0.06, 0.06, 'same_as_strict (1.0 result, not re-checked)', 2.21, 10.0, 5.4775, 5.4775, NULL, NULL, NULL, 5117, 775, 262, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:04+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DINTO', 'The Drug-Drug Interactions Ontology', 'DINTO is an OWL ontology that systematically organizes all drug-drug interaction (DDI) related information.

Drug-drug interactions (DDIs) form a significant risk group for adverse effects associated with pharmaceutical treatment. These interactions are often reported in the literature, however, they are sparsely represented in machine-readable resources, such as online databases, thesauri or ontologies. DINTO is an ontology that describes and categorizes DDIs and all the possible mechanisms that can lead to them (including both pharmacodynamic and pharmacokinetic DDI mechanisms).', 'Health', 'OWL', 5, '1.3', '2015-08-26T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DINTO', '7b99c997329dc0fa64f1bd27e8ab43346eaec16e633f120ade311bfd776660cc', 'scored', NULL, 9.99, 0.05, 2.53, 'http://purl.obolibrary.org/obo#Definition [bioportal_definitionProperty]; http://purl.obolibrary.org#Definition [detected_by_name (11731 uses)]', 5.86, 10.0, 6.475, 7.095, NULL, NULL, NULL, 1148018, 28178, 28178, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T23:00:19+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DISDRIV', 'Disease Drivers Ontology', 'Ontology for drivers and triggers of human diseases, built to classify ExO ontology exposure stressors. An application ontology. Built in collaboration with EnvO, ExO, ECTO and ChEBI., Drivers of human diseases including environmental, maternal and social exposures.', 'Other', 'OWL', 5, '2026-03-31', '2026-03-31T18:02:28.000-07:00', 'https://bioportal.bioontology.org/ontologies/DISDRIV', '32b1c913161dbd1bbdefd0ff31595a89780bd4ed6f3778254ab276b8c2c75d14', 'scored', NULL, 9.88, 6.46, 6.46, 'same_as_strict (1.0 result, not re-checked)', 7.51, 10.0, 8.4625, 8.4625, NULL, NULL, NULL, 1053, 85, 85, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:04+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DLORO', 'Dependency Layered Ontology for Radiation Oncology', 'Dependency Layered Ontology for Radiation Oncology', 'Human;Vocabularies', 'OWL', 3, '1.3', '2025-09-25T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DLORO', 'b04ce54f842c881b9db6d018fc50de2547645f09c8ea404fe15164a8936f9283', 'scored', NULL, 9.97, 1.62, 1.62, 'same_as_strict (1.0 result, not re-checked)', 3.01, 10.0, 6.15, 6.15, NULL, NULL, NULL, 3553, 354, 354, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:54+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DMDSONT', 'Diabetes Mellitus Diagnosis and Support Ontology ', 'Diabetes Mellitus Diagnosis and Support Ontology (DMDSOnt) is created using OWL 2.0 according to the directions given in the IDF’s guidelines (2022). As required and directed in the IDF’s guidelines, DMDSOnt contains concepts and relations about the signs and symptoms observed in DM, active lifestyle expected from patients, genetic conditions of patients, physical activities to be followed, laboratory tests, other factors/criteria in the diagnosis of DM, and supportive treatment recommendations for the proper management of DM risk.

IDF:	American Diabetes Association Professional Practice Committee. (2022). 2.Classification and diagnosis of diabetes: standards of medical care in diabetes—2022. Diabetes Care, 45, (Supplement_1), S17-S38, DOI: /10.2337/dc22-S002, http://diabetesjournals.org/care/article-pdf/45/Supplement_1/S17/637547/dc22s002.pdf. ', 'Health', 'OWL', 1, 'ver 1.0', '2022-09-27T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DMDSONT', '25dc716f9f5af1f59980576fa7cd75993b4679a45c1049bf8a21e2eb55d2ec86', 'scored', NULL, 4.75, 2.54, 2.54, 'same_as_strict (1.0 result, not re-checked)', 5.4, 0.0, 3.1725, 3.1725, NULL, NULL, NULL, 3577, 80, 9, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:08+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DMTO', 'Diabetes Mellitus Treatment Ontology', 'DMTO is an OWL 2 ontology for creating customized treatment plans for diabetic patients. The ontology is based on BFO and OGMS. In addition, it extends the DDO ontology by adding the treatment classes and axioms to the existing diagnosis part. ', 'Health;Human', 'OWL', 5, '2015-11-20', '2017-05-10T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DMTO', 'd05fc9649e4ce0bc8efba641157ccca1952da260b372489061c9ce2d35d53d28', 'scored', NULL, 9.77, 0.14, 1.52, 'http://purl.obolibrary.org#Definition [detected_by_name (2340 uses)]; http://purl.obolibrary.org/obo/DDO.owl#DDO_0099998 [detected_by_name (3 uses)]', 0.35, 10.0, 5.065, 5.41, NULL, NULL, NULL, 93027, 10762, 10700, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T22:57:50+00:00', '2026-09-23T23:25:10+00:00');
