INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DREAMDNPTO', 'Dementia-Related Emotional And Mood Disturbance Non-Pharmacological Treatment Ontology', 'DREAMDNPTO represents the domain knowledge specific to the non-pharmacological treatment of emotional and mood disturbances (e.g., depression and anxiety in dementia) in people with dementia living in the long-term care setting.', 'Health;Taxonomic_Classification;Vocabularies', 'OWL', 1, 'v1.0', '2022-06-12T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DREAMDNPTO', '9b1473e300c85ab7d595739548fba7498d1894abce9a7cdf68cf4f5528a9aacd', 'scored', NULL, 9.99, 6.45, 6.45, 'same_as_strict (1.0 result, not re-checked)', 0.83, 10.0, 6.8175, 6.8175, NULL, NULL, NULL, 7506, 1259, 1259, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:35+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DREDTO', 'Ontology of cyberdiseases - diseases resulting from exposure to digital technologies', 'The ontology of cyberdiseases - diseases resulting from exposure to digital technologies (DREDTO) represents cyberdiseases and adverse health effects associated with digital technology exposure. Based on a scoping review published in npj Digital Public Health and expert input, it covers digital technologies, associated diseases, pathogenesis, prevention, digital biomarkers and other relevant aspects. DREDTO cross-references relevant concepts to ICD-11 and links literature-derived terms to source publications. It is an evolving, terminology-oriented OWL ontology supporting annotation, knowledge sharing, and data integration. DREDTO ontology co-authors: Marcin Golec; Izabela Rosinska, Pawel Barczyk, Tomasz Wieczorek, Marek Tomaszewski, Kamil Kogut, Hanna Mycka, Julia Suchcicka, Cezary Dmowski, Patryk Banski, Julia Janas, Julia Bogucka, Dominika Dachnij, Amelia Kolomanska, Jan Wieczorek, Katarzyna Matczyszyn and Sandra Barteit.', 'Health;Human', 'OWL', 1, '1.0', '2026-09-08T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DREDTO', '31d25a8de7238f3462707fce7c5d34862d9ff4edff1a107344dcd859c2fd5c8e', 'scored', NULL, 9.97, 0.13, 0.13, 'same_as_strict (1.0 result, not re-checked)', 6.83, 10.0, 6.7325, 6.7325, NULL, NULL, NULL, 3039, 399, 399, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:22+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DRMO', 'Dental Restorative Material Ontology', 'The DrMO ontology is a domain ontology that represents knowledge underlying the composition, characterization and standardization of different materials involved in the dental restoration procedure. It will assist dentists in selecting appropriate materials based on up-to-date scientific knowledge to satisfy a patient’s specific requirements, without jeopardizing their clinical time. It reuses several ontologies from the OBO foundry, especially the Oral Health and Disease (OHD) Ontology. However, the dental restoration domain is complex and also requires concepts from materials science and engineering. Thus, DrMO also incorporates knowledge from the Devices, Experimental scaffolds, and Biomaterials (DEB) and Functionally Graded Materials (FGM) ontologies to provide more comprehensive knowledge of this area of dental material than previous ontologies. However, much of the terminology from FGM is different than that used in clinical dentistry. Thus, DrMO has changed the appropriate classes to make them consistent with terminology common in dentistry.  DrMO also follows ontology design best practices by reusing meta-data properties from the Dublin Core vocabulary. It captures knowledge from a large set of the most recent and influential papers in Dental Materials and related fields. Links to these papers are included in the ontology as meta-data defined with Dublin Core. It is implemented in OWL2 and was developed with the Protégé 5.5 ontology editor.  The ontology was created using the Ontology Development 101 methodology by Natalya et.al. Several domain experts in addition to Dr. Dutta also provided their expertise. The ontology is available on GitHub and licensed via an open source license. The GitHub project includes a corresponding file of SPARQL queries that answer the competency questions defined as part of the ontology development methodology.', 'Health', 'OWL', 1, NULL, '2023-05-09T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DRMO', '5caf3459e015adc69fc1177718bf4acbce248472fe21f1deac40989562164694', 'parse_failed', 'unsupported format (tried turtle, auto, xml, n3, nt, trig, trix). Last error: file:///C:/owl4_run/downloads/DRMO/1/DRMO_1_original-submission.rdf:1:0: not well-formed (invalid token)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-23T21:36:31+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DRON', 'The Drug Ontology', 'We built this ontology primarily to support comparative effectiveness researchers studying claims data. They need to be able to query U.S. National Drug Codes (NDCs) by ingredient, mechanism of action (beta-adrenergic blockade), physiological effect (diuresis), and therapeutic intent (anti-hypertensive).', 'Health;Human', 'OWL', 35, '2026-09-19', '2026-09-20T18:02:57.000-07:00', 'https://bioportal.bioontology.org/ontologies/DRON', '93e92b3c83b5a5585b2f9c804213098b39ac21094005e3ebd47fd0d85529ad76', 'scored', NULL, 10.0, 0.05, 0.05, 'same_as_strict (1.0 result, not re-checked)', 7.52, 10.0, 6.8925, 6.8925, NULL, NULL, NULL, 10750724, 792820, 792799, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T08:24:30+00:00', '2026-09-23T23:25:10+00:00');
