INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DSIP_FL_7', 'DSIP_FL_7', 'The Human Trafficking Vocabulary is an essential resource for researchers and analysts working with raw interview data gathered from refugees affected by human trafficking. It offers a standardized framework for categorizing and understanding various aspects of human trafficking incidents. The vocabulary includes terms for describing the nationality and location of human traffickers, the number of times traffickers are mentioned by independent sources, the type of observation obtained (first-hand or second-hand), and more. This vocabulary was created as part of Data Science in Practice Fieldlab-7, with guidance from Kai Smiths. It is continuously updated to reflect new insights and developments in the field of human trafficking research.', '', 'OWL', 1, 'v1', '2023-11-02T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DSIP_FL_7', 'bafad18fecdbee38967b55633d46a173b3f394081d026bc0613bbc389b6c1a4d', 'scored', NULL, 9.63, 5.41, 5.41, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 3.76, 3.76, NULL, NULL, NULL, 187, 27, 26, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:01+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DTO', 'Drug Target Ontology', 'Drug Target Ontology (DTO) is being developed at the University of Miami in the research group of Stephan Schürer. DTO is supported by grant U54CA189205 (Illuminating the Druggable Genome Knowledge Management Center, Tudor Oprea, PI) awarded by the NCI through the NIH Common Fund. It is a component of the Illuminating the Druggable Genome (IDG) project (https://commonfund.nih.gov/idg). The DTO project develops a novel semantic framework to formalize knowledge about drug targets with a focus on the current IDG protein families. The DTO is developed as a reference for drug targets with the longer-term goal to create a community standard that will facilitate the integration of diverse drug discovery information from numerous heterogeneous resources. The first version of the DTO consists of asserted class hierarchies of the four IDG protein families, GPCRs, kinases, ion channels, and nuclear hormone receptors. Protein classes are linked to tissue and disease via different levels of confidence. DTO also contains drug target development level classifications developed in the IDG project (http://targetcentral.ws/), and functional and qualitative annotations and classifications for kinase proteins, GPCR ligands and ion channels. DTO is modeled in OWL2-DL to enable further classification by inference reasoning and SPARQL queries. DTO is implemented following a modularization approach. DTO is used as the organizational framework for drug targets in the IDG PHAROS User Interface Portal (https://pharos.nih.gov) and also the Tin-X Target Importance and Novelty Explorer (http://newdrugtargets.org).', 'Chemical;Gene_Product;Human;Molecule;Other;Protein', 'OWL', 5, '1.1.1', '2018-02-15T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/DTO', '46fcf14128a1325cf78bc3f8c7981c9dada5c788b75aa77071a57cdff82b6916', 'scored', NULL, 10.0, 4.61, 4.61, 'same_as_strict (1.0 result, not re-checked)', 4.09, 10.0, 7.175, 7.175, NULL, NULL, NULL, 286490, 10076, 10076, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:28:37+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'DUO', 'The Data Use Ontology', 'An ontology based on the consent codes decsription from the Dyke et al. paper at http://dx.doi.org/10.1371/journal.pgen.1005772. It allows to semantically tag datasets with restriction about their usage, making them discoverable automatically based on the authorization level of users, or intended usage. This resource is based on the OBO Foundry principles, and its use is under review by the Broad Institute ad the European Genome-phenome Archive (EGA) at EMBL-EBI.', '', 'OWL', 8, NULL, '2021-02-23T18:04:53.000-08:00', 'https://bioportal.bioontology.org/ontologies/DUO', '1e13eb1155ca226c1f4deb894c90e219775ecbf0e1ea7e7476ad427973086a41', 'scored', NULL, 10.0, 5.59, 5.59, 'same_as_strict (1.0 result, not re-checked)', 3.73, 10.0, 7.33, 7.33, NULL, NULL, NULL, 5760, 325, 307, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:43+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'E-PPO', 'Enhanced Personal Profile Ontology', 'The Enhanced Personal Profile Ontology (e-PPO) provides personal profile of personnel that are required for software requirement engineering task selection. Properties of the ontology includes static and dynamic features. Name, gender, date of birth, etc. are static in nature and may not change. Other static properties such as educational qualification and skills acquired can be updated while others including area of specialization and profession are dynamic and can be changed. Also, areas of specializations cannot be out of the scope of one’s profession, although one personnel can have multiple profession and skills, more than one profession can share things in common such as the same professional qualification may be required.', 'Human', 'OWL', 1, NULL, '2021-09-24T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/E-PPO', '1761db0ceaedb39233b56145b2ec01b82156ea58b9fd44fc5c0181f945005896', 'scored', NULL, 0.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 2.5, 2.5, NULL, NULL, NULL, 112, 55, 55, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:03:57+00:00', '2026-09-23T23:25:10+00:00');
