INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ECP', 'Electronic Care Plan', 'Our focus in this work is to define in a formal way (ontology-based) and platform independent representative metadata and relationships of care plans. This approach has as goal to work as an umbrella over all these systems and provides some advantages regarding the management, the organization and the searching of formal care plans.', 'Health;Taxonomic_Classification;Vocabularies', 'OWL', 2, '0.6', '2015-10-13T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ECP', '0772595de2a637b0619283e430b1bdc9f4bfb5a86ab7df1035f4703aa384db41', 'scored', NULL, 9.78, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 2.41, 9.0, 5.2975, 5.2975, NULL, NULL, NULL, 473, 46, 33, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:30+00:00', '2026-09-23T23:25:10+00:00');
