INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ECTO', 'Environmental conditions, treatments and exposures ontology', 'ECTO describes exposures to experimental treatments of plants and model organisms (e.g. exposures to modification of diet, lighting levels, temperature); exposures of humans or any other organisms to stressors through a variety of routes, for purposes of public health, environmental monitoring etc, stimuli, natural and experimental, any kind of environmental condition or change in condition that can be experienced by an organism or population of organisms on earth. The scope is very general and can include for example plant treatment regimens, as well as human clinical exposures (although these may better be handled by a more specialized ontology).', 'Other', 'OWL', 13, '2026-07-28', '2026-07-28T18:03:20.000-07:00', 'https://bioportal.bioontology.org/ontologies/ECTO', '45026dad07685ac872735853dff782cb3394336ae186fe781a6c4901eed0a180', 'scored', NULL, 10.0, 5.04, 5.04, 'same_as_strict (1.0 result, not re-checked)', 6.59, 10.0, 7.9075, 7.9075, NULL, NULL, NULL, 404415, 19658, 19658, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:30:48+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EDAM', 'EDAM - The ontology of data analysis and management', 'EDAM is a domain ontology of data analysis and data management in bio- and other sciences, and science-based applications. It comprises concepts related to analysis, modelling, optimisation, and data life cycle. Targetting usability by diverse users, the structure of EDAM is relatively simple, divided into 4 main sections: Topic, Operation, Data (incl. Identifier), and Format.

EDAM is particularly suitable for semantic annotations and categorisation of diverse resources related to data analysis and management: e.g. tools, workflows, learning materials, or standards. EDAM is also useful in data management itself, for recording provenance metadata of processed data.', 'All_Organisms;Biomedical_Resources;Genomic_and_Proteomic;Other', 'OWL', 44, '1.25-20260626T1230Z', '2026-06-26T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EDAM', '4fe64f91f82513068ff28ab261d5181cc84b2e30cc5e6de470318c3b7c180890', 'scored', NULL, 10.0, 6.57, 6.57, 'same_as_strict (1.0 result, not re-checked)', 1.07, 10.0, 6.91, 6.91, NULL, NULL, NULL, 42499, 3540, 3540, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:13:28+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EDAM-BIOIMAGING', 'EDAM Bioimaging ontology', 'An ontology of imaging and related techniques and technologies, image processing and analysis, image data and formats, within bio- and other sciences.

EDAM Bioimaging is an extension to the EDAM ontology (edamontology.org), dedicated to imaging and (bio)image informatics. It has been developed by an open, global community of contributors, including consortia and projects such as NEUBIAS/GloBIAS, COMULIS, ELIXIR, Euro-BioImaging, vEM, QUAREP-LiMi, foundingGIDE, EOSC OSCARS, and more, within bio- and other sciences.', 'All_Organisms;Imaging;Other', 'OWL', 7, '1.0alpha_pre-pre-release-20251026T0104Z', '2025-10-26T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EDAM-BIOIMAGING', '9de5bb3f500ea9b8eb82f03f101010f662d9fd846cd639d8d3ca46b0206bf86e', 'scored', NULL, 9.98, 2.02, 2.02, 'same_as_strict (1.0 result, not re-checked)', 0.71, 10.0, 5.6775, 5.6775, NULL, NULL, NULL, 4847, 474, 474, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:57+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EDDA', 'EDDA Study Designs Taxonomy', 'The EDDA Study Designs Taxonomy (v2.0) was developed by the Evidence in Documents, Discovery, and Analytics (EDDA) Group: Tanja Bekhuis (Principal Scientist); Eugene Tseytlin (Systems Developer); Ashleigh Faith (Taxonomist); Faina Linkov (Epidemiologist). The EDDA Group is a division of TCB Research & Indexing LLC. This work was made possible, in part, by the US National Library of Medicine, National Institutes of Health, grant no. R00LM010943. 

Foundational research is described in Bekhuis T, Demner Fushman D, Crowley RS. Comparative effectiveness research designs: an analysis of terms and coverage in Medical Subject Headings (MeSH) and Emtree. Journal of the Medical Library Association (JMLA). 2013 April;101(2):92-100. PMC3634392. 

Coverage of the terminology appearing in JMLA was extended with terms from MeSH, NCI Thesaurus (NCI), Emtree, the HTA Database Canadian Repository [international repository for health technology assessment], and Robert Sandieson''s synonym ring for research synthesis. Collected terms were enriched with terms from the NCI Metathesaurus. Variants include synonyms for preferred terms, singular and plural forms, and American and British spellings. Definitions, if they exist, are mainly from MeSH, NCI, Emtree, and medical dictionaries.

A PDF of this taxonomy is available in ResearchGate DOI: 10.13140/RG.2.1.3769.2406/1.

The EDDA Study Designs Taxonomy by Tanja Bekhuis and Eugene Tseytlin is licensed under a Creative Commons Attribution–NonCommercial–ShareAlike 4.0 International License (CC BY-NC-SA 4.0). For information about this license, see https://creativecommons.org/licenses/by-nc-sa/4.0/.', 'Experimental_Conditions;Vocabularies', 'OWL', 11, '2.0', '2016-07-16T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EDDA', '315cb770244bad86370e25614560cc13010a7a734880a527fb7095194a28f749', 'scored', NULL, 9.98, 0.0, 2.69, 'http://ontologies.dbmi.pitt.edu/edda/TermMapping.owl#Definition [bioportal_definitionProperty + detected_by_name]', 0.03, 10.0, 5.0025, 5.675, NULL, NULL, NULL, 6145, 503, 503, '0.10.0', 'core4-1.1.1', NULL, '2026-09-23T22:57:11+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EDDA_PT', 'EDDA Publication Types Taxonomy', 'The EDDA Publication Types Taxonomy (v1.0) was developed by Tanja Bekhuis (Principal Scientist) and Eugene Tseytlin (Systems Developer) of the Evidence in Documents, Discovery, and Analytics (EDDA) Group. The EDDA Group is a division of TCB Research & Indexing LLC. Variants include synonyms for preferred terms, singular and plural forms, and American and British spellings. Definitions, if they exist, are mainly from MeSH, NCIT, Emtree, and dictionaries. 

The EDDA Publication Types Taxonomy by Tanja Bekhuis and Eugene Tseytlin is licensed under a Creative Commons Attribution–NonCommercial–ShareAlike 4.0 International License (CC BY-NC-SA 4.0). For information about this license, see https://creativecommons.org/licenses/by-nc-sa/4.0/.', 'Experimental_Conditions;Vocabularies', 'OWL', 1, '1.0', '2016-07-18T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EDDA_PT', 'b361965992082c7aebfc508bcdd5b89e15cf89b0c82948d58185559c3029bf86', 'scored', NULL, 9.89, 0.07, 2.89, 'http://ontologies.dbmi.pitt.edu/edda/TermMapping.owl#Definition [bioportal_definitionProperty + detected_by_name]', 0.0, 10.0, 4.99, 5.695, NULL, NULL, NULL, 1038, 94, 94, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T22:57:06+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EDEM-CONNECTONTO', 'eDEM-Connect: Ontology of Dementia-related Agitation and Relationship between Informal Caregivers and Persons with Dementia', 'The EDEM-CONNECTONTO has been created to incorporate domain knowledge about the various types of agitation observed in people with dementia (PwD), as well as the dyadic relationship existing between PwD and their informal caregivers. Furthermore, it offers a structured framework for non-pharmacological interventions, enabling caregivers to effectively manage and mitigate the bidirectional effects of agitation in PwD.', 'Health;Taxonomic_Classification;Vocabularies', 'OWL', 2, 'Version_2.0', '2025-12-29T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EDEM-CONNECTONTO', '41131c070a59f2020574148512a143f3ec7ce1b702b00803a3b05446ce572c4b', 'scored', NULL, 10.0, 3.29, 3.29, 'same_as_strict (1.0 result, not re-checked)', 0.05, 10.0, 5.835, 5.835, NULL, NULL, NULL, 3415, 493, 252, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:54+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EDONTOLOGY', 'Emergency Department Ontology', 'This research work contributes in the field of Information logistics and ontology development in healthcare. An ontology based model that can fix information flow problems in the ward-round process of hospital unit. The ontology based model can be used to provide relevant information to the domain users according to their needs and demands. The ontology based model projects domain users profiling and describes their roles, information demands with competencies: skills, qualifications and experiences. The ontology based model will be implemented in OWL language that can be used in an application to support ward-round activities for achieving effective patient’s treatment process. For ontology development is concerned, different ontology development methodologies have been reviewed from literature review by the author to analyze the existing problems in the ward-round. This thesis incorporates Hybrid Methodology (HM) that helps to develop ontology based model that addresses information flow problems in ward-round. The proposed ontology based model is developed in web Ontology Language (OWL) supported tool protégé 4.0.2 that can be considered as foundation to develop a software product with the help of IT practitioners and developers to fulfill medical practitioner’s demands in ward-round’s context.', 'Health;Vocabularies', 'OWL', 2, NULL, '2025-12-13T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EDONTOLOGY', '7c67229a5ec6707fe7307eb2fcdecad1ee65dbd75d7070b1369af528cf6d9758', 'scored', NULL, 4.22, 0.07, 0.07, 'same_as_strict (1.0 result, not re-checked)', 5.62, 10.0, 4.9775, 4.9775, NULL, NULL, NULL, 15896, 649, 271, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:10:03+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EFO', 'Experimental Factor Ontology', 'The Experimental Factor Ontology (EFO) is an application focused ontology modelling the experimental variables in multiple resources at the EBI and Open Targets. The ontology has been developed to increase the richness of the annotations that are currently made in resources and to promote consistent annotation, to facilitate automatic annotation and to integrate external data. The ontology pulls together classes from reference ontologies such as disease, cell line, cell type and anatomy and adds axiomatisation as necessary to connect areas such as disease to phenotype. Contact EFO users list for information: efo-users@ebi.ac.uk., The Experimental Factor Ontology (EFO) provides a systematic description of many experimental variables available in EBI databases, and for projects such as the NHGRI-EBI GWAS catalog. It combines parts of several biological ontologies, such as UBERON anatomy, ChEBI chemical compounds, Cell Ontology and the Monarch Disease Ontology (MONDO). The scope of EFO is to support the annotation, analysis and visualization of data handled by many groups at the EBI and as the core ontology for Open Targets.', 'Biological_Process;Experimental_Conditions', 'OWL', 292, '3.94.0', '2026-09-15T18:03:17.000-07:00', 'https://bioportal.bioontology.org/ontologies/EFO', 'e3c2d6254a61c064ab767d1bb3ead5530a602beac01c7706d0e24363b541dedb', 'scored', NULL, 10.0, 5.71, 5.71, 'http://www.ebi.ac.uk/efo/definition [bioportal_definitionProperty]', 7.0, 10.0, 8.1775, 8.1775, NULL, NULL, NULL, 4490775, 94313, 94313, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T23:13:20+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EGO', 'Epigenome Ontology', 'The Epigenome Ontology (EGO) a biomedical ontology for integrative epigenome knowledge representation and data analysis.', 'Genomic_and_Proteomic;Health;Molecule', 'OWL', 1, 'Arbor version; 1.0.1', '2016-06-30T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EGO', 'e7e6f807b11f25ad48ffbbafd1d9a239abe8295b2e650d2474fdabfd3403d2e5', 'scored', NULL, 9.95, 6.37, 6.37, 'same_as_strict (1.0 result, not re-checked)', 3.77, 10.0, 7.5225, 7.5225, NULL, NULL, NULL, 57092, 3125, 2952, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:15:47+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EHDA', 'Human Developmental Anatomy Ontology, timed version', 'A structured controlled vocabulary of stage-specific anatomical structures of the human. It has been designed to mesh with the mouse anatomy and incorporates each Carnegie stage of development (CS1-20). The timed version of the human developmental anatomy ontology gives all the tissues present at each Carnegie Stage (CS) of human development (1-20) linked by a part-of rule. Each term is mentioned only once so that the embryo at each stage can be seen as the simple sum of its parts. Users should note that tissues that are symmetric (e.g. eyes, ears, limbs) are only mentioned once.', 'Anatomy;Animal_Gross_Anatomy;Gross_Anatomy;Human_Developmental_Anatomy', 'OBO', 7, 'unknown', '2011-02-15T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/EHDA', '08ac33c5e9219bc5b40d5229022d9373ca29a53a33e032dd74094a7aeeac20c3', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 7.67, 9.0, 6.6675, 6.6675, NULL, NULL, NULL, 108363, 8341, 8341, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:20:05+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EHDAA', 'Human Developmental Anatomy Ontology, abstract version 1', 'A structured controlled vocabulary of stage-specific anatomical structures of the human. It has been designed to mesh with the mouse anatomy and incorporates each Carnegie stage of development (CS1-20). The abstract version of the human developmental anatomy ontology compresses all the tissues present over Carnegie stages 1-20 into a single hierarchy. The heart, for example, is present from Carnegie Stage 9 onwards and is thus represented by 12 EHDA IDs (one for each stage). In the abstract mouse, it has a single ID so that the abstract term given as just <i>heart</i> really means <i>heart (CS 9-20)</i>. Timing details will be added to the abstract version of the ontology in a future release.', 'Anatomy;Animal_Gross_Anatomy;Gross_Anatomy;Human_Developmental_Anatomy', 'OBO', 7, 'unknown', '2011-02-15T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/EHDAA', 'e77c642684d4a7bb0f5ce0d0f15cb3a0086ce5fbbd69dbd8ba0ddca0aa11278b', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 7.68, 10.0, 6.92, 6.92, NULL, NULL, NULL, 25663, 2315, 2315, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:11:01+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EHDAA2', 'Human Developmental Anatomy Ontology, abstract version 2', 'A structured controlled vocabulary of stage-specific anatomical structures of the human. It has been designed to mesh with the mouse anatomy and incorporates each Carnegie stage of development (CS1-20). The abstract version of the human developmental anatomy ontology compresses all the tissues present over Carnegie stages 1-20 into a single hierarchy. The heart, for example, is present from Carnegie Stage 9 onwards and is thus represented by 12 EHDA IDs (one for each stage). In the abstract mouse, it has a single ID so that the abstract term given as just <i>heart</i> really means <i>heart (CS 9-20)</i>. Timing details will be added to the abstract version of the ontology in a future release.', 'Anatomy;Animal_Gross_Anatomy;Gross_Anatomy;Human_Developmental_Anatomy', 'OBO', 34, 'releases/2024-01-11', '2024-01-11T18:05:36.000-08:00', 'https://bioportal.bioontology.org/ontologies/EHDAA2', 'a055e5177c3cb8ad016acb07e60aa4ba6891fdae62ed4e7413ea5ae7e725ce86', 'scored', NULL, 10.0, 0.55, 0.55, 'same_as_strict (1.0 result, not re-checked)', 8.85, 10.0, 7.35, 7.35, NULL, NULL, NULL, 71035, 2744, 2744, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:16:25+00:00', '2026-09-23T23:25:10+00:00');
