INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EOL', 'Environment Ontology for Livestock', 'L''ontologie EOL décrit les conditions d''environnement des élevages d''animaux domestiques. Elle décrit plus particulièrement les modalités de l''alimentation, de l''environnement, de la structure des élevages et des systèmes d''élevage', '', 'OWL', 1, NULL, '2014-10-22T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EOL', 'd0bd685f9d17de654ab3b5117febd0f1d46c0a400f2bd1c68b3210feac9cd28e', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.02, 10.0, 5.005, 5.005, NULL, NULL, NULL, 5276, 649, 649, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:07:42+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EP', 'Cardiac Electrophysiology Ontology', 'The Cardiac Electrophysiology Ontology contains terms describing single-channel electrophysiological experiments and data obtained using voltage-clamp, current clamp and fluorescence imaging techniques applied at the cell level and multi-channel fluorescence imaging techniques applied at the cell, tissue and whole heart levels.', 'Experimental_Conditions', 'OWL', 2, '1', '2008-12-10T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/EP', '74d056c873558e8bbb585aa89e850f4d425e4c289abe164b672aa7e7c1585f3c', 'scored', NULL, 9.91, 5.87, 5.87, 'same_as_strict (1.0 result, not re-checked)', 0.23, 10.0, 6.5025, 6.5025, NULL, NULL, NULL, 1180, 234, 233, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:43+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EPIE', 'Epigenetic Entity', 'Biological entities associated with changes in the regulation of gene activity without alteration of genetic structure. Development of this terminology was funded by the National Institute of Child Health and Human Development in support of the Placental Atlas Tool (PAT) with final verification by the PAT External Scientific Panel. This terminology was developed through a combination of resources including existing biomedical ontology resources, such as the Gene Ontology and the National Cancer Institute Thesaurus, web-based content, and epigenetic literature.', 'Other', 'OWL', 4, '1.3', '2019-05-01T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EPIE', 'deccdfb0afee9118014e37279d155a351f54154f4664a1932e9154150edce9f4', 'scored', NULL, 10.0, 5.73, 5.73, 'same_as_strict (1.0 result, not re-checked)', 1.92, 10.0, 6.9125, 6.9125, NULL, NULL, NULL, 4394, 392, 392, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:40+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EPILONT', 'Epilepsy Ontology', 'Ontology about the epilepsy domain and epileptic seizures. Based on the diagnosis proposed by the International League Against Epilepsy (ILAE).', 'Biomedical_Resources;Development;Health;Human;Neurologic_Disease;Neurological_Disorder;Vocabularies', 'OWL', 2, 'V1', '2011-07-18T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/EPILONT', '28de6063ddbddfa201009dee70c304e489e136ad7e7f6c4bf4ea459df939c1ec', 'scored', NULL, 10.0, 2.5, 2.5, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 5.625, 5.625, NULL, NULL, NULL, 873, 138, 138, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:03+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EPIO', 'EpilepsyOntology', 'The Epilepsy Ontology (EPO) is an assembly of structured knowledge on various aspects of epilepsy, developed according to basic formal ontology (BFO) and Open Biological and Biomedical Ontology (OBO) Foundry principles. Entities and definitions are collected from the latest International League against Epilepsy (ILAE) classification, as well as from domain-specific ontologies such as Epilepsy Ontology (EPILONT), Epilepsy Syndrome Seizure Ontology (ESSO), Epilepsy Semiology(EPISEM) and Epilepsy and Seizure Ontology (EPSO) and scientific literature.

This ontology is intended to be used for data management and for text mining purposes. The current release of the ontology is publicly available and is a community based effort to assemble various facets of the complex disease Epilepsy.', 'Neurological_Disorder', 'OWL', 1, 'Version Release: 1.0.0', '2021-11-08T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EPIO', '9ce72e39da32a840704952adc0d6efee78247d5dd19e04c022da4d5af6d57ce7', 'scored', NULL, 10.0, 5.84, 5.84, 'same_as_strict (1.0 result, not re-checked)', 2.49, 10.0, 7.0825, 7.0825, NULL, NULL, NULL, 32859, 1916, 1916, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:12:32+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EPIP', 'Epigenetic Process', 'Biological processes associated with changes in the regulation of gene activity without alteration of genetic structure. Development of this terminology was funded by the National Institute of Child Health and Human Development in support of the Placental Atlas Tool (PAT) with final verification by the PAT External Scientific Panel. This terminology was developed through a combination of resources including existing biomedical ontology resources, such as the Gene Ontology and the National Cancer Institute Thesaurus, web-based content, and epigenetic literature.', 'Biological_Process', 'OWL', 4, '1.3', '2019-05-01T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EPIP', '8cadf17ab3d7b8680e21af1a1ffc29034c6d8d595121dfa4c26c085d9071cfc5', 'scored', NULL, 10.0, 6.42, 6.42, 'same_as_strict (1.0 result, not re-checked)', 2.98, 10.0, 7.35, 7.35, NULL, NULL, NULL, 2855, 263, 263, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:04+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EPISEM', 'Epilepsy Semiology', 'An ontology designed to capture the semiology of epilepsy including ictal, post-ictal, inter-ictal, and aura signs.   For the branches entitled "disease", "etiologic factor", "epidemiologic factor"--see ESSO ontology on this website for origin of terms.', 'Neurological_Disorder', 'OWL', 8, '5.0', '2019-11-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EPISEM', '2d245130a6b10fcf667683303a488c57af3324ead5149076dad34a254dc82ba6', 'scored', NULL, 10.0, 0.02, 0.02, 'same_as_strict (1.0 result, not re-checked)', 0.07, 10.0, 5.0225, 5.0225, NULL, NULL, NULL, 8656, 1595, 1595, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:00+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EPO', 'Early Pregnancy Ontology', 'The early pregnancy ontology contains the concepts to describe ectopic pregnancy ultrasound images, organized into several subsumption hierarchies for types of ectopic pregnancies and the signs, anatomical structures and technical elements of imaging associated with ectopic pregnancy.
Version 1.1 was used for ultrasound image annotations (Dhombres et al. Developing a knowledge base to support the annotation of ultrasound images of ectopic pregnancy. J Biomed Semantics, 2017)
', 'Imaging', 'OWL', 1, '1.1', '2016-05-28T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EPO', '941b4bbf2f4eba8fa05d5abc93dbd0f090c6d7316e9213ac844ebb5181f9be07', 'scored', NULL, 10.0, 2.39, 2.39, 'same_as_strict (1.0 result, not re-checked)', 1.88, 10.0, 6.0675, 6.0675, NULL, NULL, NULL, 9906, 1388, 1388, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:57+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EPSO', 'Epilepsy and Seizure Ontology', 'The Epilepsy Ontology models seizure types, syndromes, etiology, electrophysiology, medication, neuropathology, including  immunohistochemistry, microscopy, and anatomical description, together with terms describing preclinical model systems. The Epilepsy Ontology has been integrated with generative artificial intelligence (AI)/LLMs and machine learning models for natural language processing (NLP), drug efficacy analysis, and translational research.', 'All_Organisms;Human;Neurologic_Disease;Neurological_Disorder;Taxonomic_Classification', 'OWL', 8, '3.1', '2025-05-29T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EPSO', 'b6ff70dffca1910b7a7a87195720ef51828962d392c69586ee3f8fdb87c50ff2', 'scored', NULL, 9.99, 1.59, 1.59, 'same_as_strict (1.0 result, not re-checked)', 2.3, 10.0, 5.97, 5.97, NULL, NULL, NULL, 16246, 2200, 2198, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:54+00:00', '2026-09-23T23:25:10+00:00');
