INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ESFO', 'Enzyme Structure Function Ontology', 'The ESFO provides a new paradigm for organizing enzyme sequence, structure, and function information, whereby specific elements of enzyme sequence and structure are mapped to specific conserved aspects of function, thus facilitating the functional annotation of uncharacterized enzymes. The ESFO helps prevent misannotation by emphasizing annotation of enzymes only at the level of functional granularity warranted by available information.', 'Protein', 'OWL', 1, '1', '2016-10-24T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ESFO', '901d0889d959ba74095b513d713babe367b406a47a4dc67bebccd5171b660baf', 'scored', NULL, 10.0, 5.92, 5.92, 'same_as_strict (1.0 result, not re-checked)', 6.64, 7.0, 7.39, 7.39, NULL, NULL, NULL, 1220, 22, 22, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:21+00:00', '2026-09-23T23:25:10+00:00');
