INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EUPATH', 'VEuPathDB Ontology', 'The VEuPathDB ontology is an application ontology developed to encode our understanding of what data is about in the public resources developed and maintained by the Eukaryotic Pathogen, Host & Vector Genomics Resource (VEuPathDB; https://veupathdb.org). The VEuPathDB ontology was previously named the EuPathDB ontology prior to EuPathDB joining with VectorBase.The ontology was built based on the Ontology of Biomedical Investigations (OBI) with integration of other OBO ontologies such as PATO, OGMS, DO, etc. as needed for coverage. Currently the VEuPath ontology is primarily intended to be used for support of the VEuPathDB sites. Terms with VEuPathDB ontology IDs that are not specific to VEuPathDB will be submitted to OBO Foundry ontologies for subsequent import and replacement of those terms when they are available.', 'Biomedical_Resources', 'OWL', 19, '2023-05-30', '2023-06-01T18:11:19.000-07:00', 'https://bioportal.bioontology.org/ontologies/EUPATH', '3ee51f326cf1379762eb02f5f426e70607db9bcbf91e3b1ad27c0551367530e7', 'scored', NULL, 10.0, 4.74, 4.74, 'same_as_strict (1.0 result, not re-checked)', 1.74, 10.0, 6.62, 6.62, NULL, NULL, NULL, 68846, 5170, 5110, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:16:09+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EVI', 'Evidence Graph Ontology', 'The Evidence Graph ontology extends core concepts from the W3C Provenance Ontology PROV-O and Bioschemas'' Profiles to describe evidence for correctness of findings in biomedical publications. The semantic data model in EVI is expressed using OWL2 Web Ontology Language., The Evidence Graph ontology extends core concepts from the W3C Provenance Ontology PROV-O and Bioschemas'' Profiles to describe evidence for correctness of findings in biomedical publications. The semantic data model in EVI is expressed using OWL2 Web Ontology Language (OWL2)., The Evidence Graph ontology extends core concepts from the W3C Provenance Ontology PROV-O, Schema.org, and Bioschemas'' Profiles to describe evidence for correctness of findings in biomedical publications. The semantic data model in EVI is expressed using OWL2 Web Ontology Language (OWL2)., The Evidence Graph Ontology (EVI) is an OWL 2 vocabulary for recording how a biomedical result was produced and what evidence currently bears on its correctness. A published finding does not stand alone: it often relies on a dataset, a description of that dataset''s schema, the software and computation that transformed the data, and the article that reports the result. EVI models those objects and the relations among them as an evidence graph from which a person or a program can follow how the source data, software, and computation support the finding. EVI is a biomedical domain extension of W3C PROV-O, built on PROV-O''s core classes. Where PROV-O supplies general provenance for what was used, generated, and attributed, EVI adds the concepts needed in biomedical research and represents their relations as evidence for a published result, claim, or finding. When new evidence, assertions, or other information about the data, or article become available, they can be added to the same graph as annotations, so both current and past evidence remain visible and transparent. The resulting graphs improve interpretability of biomedical research and provi', 'Biological_Process;Biomedical_Resources;Experimental_Conditions;Other', 'OWL', 14, '1.6', '2020-07-27T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EVI', '10e50676feb34050323f728ad890342b3ba997db4ef5623775e6f3bbb00784f3', 'scored', NULL, 10.0, 6.3, 6.3, 'same_as_strict (1.0 result, not re-checked)', 0.67, 10.0, 6.7425, 6.7425, NULL, NULL, NULL, 705, 37, 37, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:41+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EVORAO', 'European Viral Outbreak Response Alliance Ontology', 'EVORAO is an ontology for standardized metadata supporting the sharing of pathogens as biological materials, their derived products, and associated services, organized into collections. While initially focused on virology, it is designed for interoperability and is extensible to other pathogens. EVORAO is compatible with DCAT, making it well-suited for efficiently cataloguing pathogen collections and related resources., The EVORAO Ontology provides a structured and harmonized vocabulary for describing shareable pathogens as characterized biological materials, along with their derived products and associated services, organized into collections. Developed within the EVORA project, it supports consistent metadata annotation across research infrastructures, promoting findability, accessibility, interoperability, and reusability (FAIR). By aligning with relevant standards and ontologies, EVORAO facilitates cross-domain collaboration, integration, and sharing of pathogenic resources and services to enhance pandemic preparedness and response. While initially focused on virology, EVORAO is designed to be extensible and also supports metadata harmonization for other pathogens. EVORAO is compatible with DCAT', 'Other', 'OWL', 28, '1.2.0', '2024-12-12T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EVORAO', 'f3aeec65e2b972d8bce99882f522f4c3acc04cc1dff8d7a5a5ccae940caf30dc', 'scored', NULL, 10.0, 5.87, 5.87, 'same_as_strict (1.0 result, not re-checked)', 4.03, 9.0, 7.225, 7.225, NULL, NULL, NULL, 6872, 86, 83, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:49+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EVS', 'Exposure Value Set', 'A collection of curated and standardized values used in metadata specifications produced by ADAMS (Accelerating DAta and Metadata Standards in the Environmental Health Sciences Study of Emerging Water Contaminants) group. These values are designed to ensure uniformity in the description of the various metadata standards produced by the group. ', 'Chemical;Experimental_Conditions;Human;Vocabularies', 'SKOS', 6, '0.0.6', '2025-06-20T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EVS', 'd6292cd923cf71b1b462ce6e8196573e670815c4a81704290a14b74041a14628', 'scored', NULL, 9.87, 5.68, 5.68, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 3.8875, 3.8875, NULL, NULL, NULL, 542, 75, 74, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:31+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EXACT', 'An ontology for experimental actions', 'EXACT aims to explicitly define the semantics of experimental protocols in order to ensure their reproducibility, and to support computer applications that assist biologists in the preparation, maintenance, submission and sharing of experimental protocols. ', '', 'OWL', 2, '2', '2014-09-18T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EXACT', 'fe566f94824c0b65dd6146db98dedccaff1be3c174abaa7c263eab8f9b3d5318', 'scored', NULL, 8.6, 1.68, 1.68, 'same_as_strict (1.0 result, not re-checked)', 5.12, 10.0, 6.35, 6.35, NULL, NULL, NULL, 1785, 171, 163, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:47+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EXMO', 'Exercise Medicine Ontology', 'A core reference ontology built upon BFO about exercise medicine. This ontology contains the related terms for healthy people, people with chronic conditions and people living with diability to exercise.', 'Health;Human', 'OWL', 6, '2025-06-05', '2025-06-05T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EXMO', '95186b557277bf9fdec6c82c05f2067764676c7db94a1119bc6988e06542c16e', 'scored', NULL, 9.98, 6.01, 6.01, 'same_as_strict (1.0 result, not re-checked)', 8.15, 10.0, 8.535, 8.535, NULL, NULL, NULL, 16280, 450, 450, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:10:02+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EXO', 'Exposure Ontology', 'Significant progress has been made over the last several years in collecting and improving access to genomic, toxicology, and health data to promote understanding about environmental influences on human health. The resulting information resources, however, lack extensive and reliable exposure data, which are required to translate molecular insights, elucidate environmental contributions to diseases, and assess human health risks at the individual and population levels. We report our development of an Exposure Ontology, ExO, designed to address this information gap by facilitating centralization and integration of exposure data to inform understanding of environmental health. Like other widely used ontologies, ExO is intended to bridge the gap between exposure science and diverse environmental health disciplines including toxicology, epidemiology, disease surveillance, and epigenetics.', '', 'OBO', 12, '2025-08-29', '2025-09-09T09:05:46.000-07:00', 'https://bioportal.bioontology.org/ontologies/EXO', '80bad78664825786f1a075c8f260ebc951b4d998bb2f4a14333409abd5e37d7d', 'scored', NULL, 9.94, 6.2, 6.2, 'same_as_strict (1.0 result, not re-checked)', 4.23, 10.0, 7.5925, 7.5925, NULL, NULL, NULL, 2597, 169, 169, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:18+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EXON', 'Experimental Ontology', 'Experiment focused in the compatibility with proteg''e software to create and upload ontologies on Bioportal', '', 'OWL', 1, NULL, '2017-11-30T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/EXON', '730e83a6b7387f132d816568400a25c6d066a9628c1a0a3f79e725e1df1c54c3', 'scored', NULL, 6.36, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 6.0, 3.09, 3.09, NULL, NULL, NULL, 31, 11, 6, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:03:35+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'EXTRACT', 'EXTeRnAl Conditions Taxonomy (EXTRACT)', 'Controlled vocabularies such as taxonomies allow an accurate and controlled approach in describing datasets. One of such controlled vocabulary is Wind Energy Taxonomy of External Conditions. This taxonomy is the result of EERA JP WIND IRPWind Open Data initiative that took place in 2017 in which wind energy experts generated the first version of the taxonomy as an input for defining and structuring wind energy metadata.', '', 'SKOS', 2, 'v0.1.0', '2023-05-23T18:05:38.000-07:00', 'https://bioportal.bioontology.org/ontologies/EXTRACT', '4e923f2e0d8611b030316fe204dbefbb6934bc339d1445605101f5dc2a3e3516', 'scored', NULL, 9.57, 1.36, 1.36, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.7325, 2.7325, NULL, NULL, NULL, 155, 23, 23, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:03:48+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'FALDO', 'Feature Annotation Location Description Ontology ', 'FALDO is the Feature Annotation Location Description Ontology. It is a simple ontology to describe sequence feature positions and regions as found in GFF3, DBBJ, EMBL, GenBank files, UniProt, and many other bioinformatics resources.

The aim of this ontology is to describe the position of a sequence region or a feature. It does not aim to describe features or regions itself, but instead depends on resources such as the Sequence Ontology or the UniProt core ontolgy.', 'Other;Protein;Vocabularies', 'OWL', 18, 'Created at the Biohackathon 2012 and 2013', '2022-09-07T18:25:43.000-07:00', 'https://bioportal.bioontology.org/ontologies/FALDO', '530a617f70b8943f53a6570d5d0378663718ede99774bbce2be94b15862a7c4f', 'scored', NULL, 10.0, 5.35, 5.35, 'same_as_strict (1.0 result, not re-checked)', 2.15, 7.0, 6.125, 6.125, NULL, NULL, NULL, 251, 19, 19, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:10+00:00', '2026-09-23T23:25:10+00:00');
