INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'FAST-CHRONO', 'FAST (Faceted Access of Subject Terminology) Chronological Facet', 'FAST is an enumerative, faceted subject heading schema derived from the Library of Congress Subject Headings (LCSH). The purpose of adapting the LCSH with a simplified syntax to create FAST is to retain the very rich vocabulary of LCSH while making the schema easier to understand, control, apply, and use. This facet includes chronological terms derived from LCSH.', '', 'SKOS', 1, NULL, '2018-05-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/FAST-CHRONO', 'd46daf1af2014a2b8c3a81e3b940df12f25d115a823923fd62e7a8236c530193', 'scored', NULL, 9.91, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.4775, 2.4775, NULL, NULL, NULL, 6236, 683, 4, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:07:45+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'FAST-EVENT', 'FAST (Faceted Application of Subject Terminology) Event', 'FAST is an enumerative, faceted subject heading schema derived from the Library of Congress Subject Headings (LCSH). The purpose of adapting the LCSH with a simplified syntax to create FAST is to retain the very rich vocabulary of LCSH while making the schema easier to understand, control, apply, and use. The schema maintains upward compatibility with LCSH, and any valid set of LC subject headings can be converted to FAST headings. This is the Event facet.', '', 'OWL', 1, NULL, '2017-04-14T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/FAST-EVENT', '85c9c2e19d021f9f57b89e5be67592ede12f50520885c03e249de67e8b966f1f', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.5, 2.5, NULL, NULL, NULL, 193971, 16982, 691, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:24:21+00:00', '2026-09-23T23:25:10+00:00');
