INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'FASTO', 'HL7 FHIR and SSN ontology based Type 1 Diabetes Mellitus Ontology', 'FHIR And SSN based Type 1 diabetes Ontology (FASTO) is an OWL 2 ontology for real time management of insulin for diabetes patients especially type 1 diabetics. The ontology is based on BFO as the top-level ontology, SSN sensor ontology, and HL7 FHIR standard. This ontology can support the development of mobile health applications. It supports the interoperability between clinical decision support systems on a cloud environment, distributed electronic health records, mobile devices, and wireless body area networks.', '', 'OWL', 2, '2015-11-20', '2018-09-23T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/FASTO', '6d1d748bd78aad3d32ed9fe7637053bb822f0a85eefc31618b5b65c4b8c1327d', 'scored', NULL, 8.91, 0.16, 1.64, 'http://purl.obolibrary.org#Definition [detected_by_name (2343 uses)]; http://purl.obolibrary.org/obo/DDO.owl#DDO_0099998 [detected_by_name (1 uses)]', 0.44, 10.0, 4.8775, 5.2475, NULL, NULL, NULL, 90030, 10026, 9577, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T22:57:55+00:00', '2026-09-23T23:25:10+00:00');
