INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'FIRE', 'Fire Ontology', 'The ontology of Fire was created in order to represent the set of concepts about the fire occurring in natural vegetation, its characteristics, causes and effects, with focus on Cerrado vegetation domain. The fire plays a determinant role on the structure and composition of Cerrado physiognomies.', '', 'OWL', 7, '0.8', '2014-02-24T18:14:37.000-08:00', 'https://bioportal.bioontology.org/ontologies/FIRE', 'a339d0f703fad8f92bc1e317f2ed6934eb244ad069af0026b24f532822f45e3f', 'scored', NULL, 9.84, 5.58, 5.58, 'same_as_strict (1.0 result, not re-checked)', 1.49, 10.0, 6.7275, 6.7275, NULL, NULL, NULL, 475, 63, 54, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:30+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'FISH-AST', 'FISH Archaeological Sciences Thesaurus', 'Terminology used for recording the techniques, recovery methods and materials associated with archaeological sciences. Maintained by Historic England on behalf of the FISH Terminology Working Group.', '', 'SKOS', 1, NULL, '2013-07-17T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/FISH-AST', '2a0e3c936d52fad206270a418679c25632327dfcc130fc19811b13012b738cf5', 'scored', NULL, 9.92, 0.05, 0.05, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.4925, 2.4925, NULL, NULL, NULL, 1682, 128, 127, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:32+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'FISHO', 'Fish Ontology', 'This Fish Ontology is an ontology created as how the author views the fish structure following the book "The Diversity of Fishes: Biology, Evolution and Ecology" as the main reference, which covers one part of view on ichthyology, with an emphasis on diversity and adaptation. This ontology is created with the mindset of categorizing fish automatically based on the attributes and terms mined from the fish specimen.

Most of the basic organization from this ontology follows Nelson''s research due to its synthetic and broad approach, while recognizing that Nelson''s conclusions are one of many alternative interpretations of the literature, which is mostly agreed by our main references, and many fish and fisheries researchers.

Most of the classification used in this ontology is in no means completed and just following the recent classification provided by the books

For now our work focused more on two group of fish which is early jawless fish, and advanced jawed fishes. The classification from both of this group are structured following the reference.', 'Fish_Anatomy', 'OWL', 1, 'Version 1.0.3 (Possible addition)

-Considering to add more fish study related terms in the ontology such as fish immune sytem, and Fish Locomotion and Feeding Behavior.
-Also focused on completing other classification of fish, and adding more relationships between the classes.


Version 1.0.2

-Added a lot of annotations and metadata for fish terms, and added several more subclasses for the ontology. 


Version 1.0.1

-Change  the structure and the hierarchy of a lot of classes to follow the main references. Several classes are deleted and marked as "deprecated" or "In Review" in case they might be useful later.


Version 1.0.0

-The first version of the fish ontology is created.', '2017-08-28T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/FISHO', '93bed14ae3391932db7447585eb48f99c2067047d919f587eea6cd3af06932b6', 'scored', NULL, 9.97, 1.69, 1.69, 'same_as_strict (1.0 result, not re-checked)', 0.68, 10.0, 5.585, 5.585, NULL, NULL, NULL, 2835, 395, 387, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:24+00:00', '2026-09-23T23:25:10+00:00');
