INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'FLOPO', 'Flora Phenotype Ontology', 'The Flora Phenotype Ontology is an ontology of phenotypes reported in Floras. The original version was developed at the pro-iBiosphere Hackathon in Leiden. This is the pre-classified version of the ontology; the original OWL file is at https://github.com/flora-phenotype-ontology/flopoontology/blob/master/ontology/flopo.owl

The Flora Phenotype Ontology is generated from the Flora Malesiana, Flora Gabon, Flora of Central Africa, and a collection of Kew''s African Floras. Every class in the ontology has at least one taxon annotation. The (draft) taxon annotation are available at http://jagannath.pdn.cam.ac.uk/plant/flora/clean-rerun/, Traits and phenotypes of flowering plants occurring in digitized Floras.', 'Phenotype;Plant', 'OWL', 10, '2026-07-31', '2026-08-01T18:04:13.000-07:00', 'https://bioportal.bioontology.org/ontologies/FLOPO', '63b5cf1d8b8826c42af744844f906d45dc976ca812f619fbeaaaf5fbe489c2b0', 'scored', NULL, 10.0, 5.98, 5.98, 'same_as_strict (1.0 result, not re-checked)', 2.27, 10.0, 7.0625, 7.0625, NULL, NULL, NULL, 793565, 35582, 35580, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:44:39+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'FLU', 'Influenza Ontology', 'Starting in the fall of 2007, a collaborative group of influenza researchers have established an influenza ontology. The influenza ontology is an application ontology. 

Consolidated influenza sequence and surveillance terms from resources such as the BioHealthBase (BHB), a Bioinformatics Resource Center (BRC) for Biodefense and Emerging and Re-emerging Infectious Diseases, the Centers for Excellence in Influenza Research and Surveillance (CEIRS)', '', 'OWL', 27, '0.9.0', '2015-08-20T18:03:53.000-07:00', 'https://bioportal.bioontology.org/ontologies/FLU', '0c3b87e2dbfd3ce8300d3437eac4011ab28a4490aa071e4b43075449a21a64d1', 'scored', NULL, 9.98, 4.73, 4.73, 'same_as_strict (1.0 result, not re-checked)', 3.22, 9.0, 6.7325, 6.7325, NULL, NULL, NULL, 7996, 605, 585, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:27+00:00', '2026-09-23T23:25:10+00:00');
