INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'FOODON', 'The FoodOn Food Ontology', 'FoodOn is an ontology built to represent entities which bear a “food role” and is initially focused on categorizing and processing of food for humans. We aim to develop semantics for food safety, food security, the agricultural and animal husbandry practices linked to food production, culinary, nutritional and chemical ingredients and processes.  FoodOn belongs to the OBOFoundry.org family of ontologies., FoodOn is a consortium-driven project to build a comprehensive and easily accessible global farm-to-fork ontology about food, that accurately and consistently describes foods commonly known in cultures from around the world. See https://foodon.org for more details.', 'All_Organisms;Biomedical_Resources;Health;Plant;Vocabularies', 'OWL', 111, '2026-02-02', '2026-02-02T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/FOODON', '185d99e04a115ee8c54ccc20003ce42adab2913c4fe189a1e9e552031612be20', 'scored', NULL, 10.0, 5.14, 5.14, 'same_as_strict (1.0 result, not re-checked)', 3.18, 10.0, 7.08, 7.08, NULL, NULL, NULL, 456610, 40123, 40107, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:37:47+00:00', '2026-09-23T23:25:10+00:00');
