INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GALLONT', 'Plant Gall Ontology', 'Ontology of plant gall phenotypes. Plant galls are novel plant structures, generated by plants in response to biotic stressors. This ontology is used to annotate gall phenotypes (e.g., their colors, textures, sizes, locations on the plant) in a semantic way, in order to facilitate discoveries about the genetic and physiologic mechanisms responsible for such phenotypes. The ontology can also be used as a controlled vocabulary for natural language descriptions of plant galls.', 'Phenotype', 'OWL', 1, '2024-04-19', '2024-04-19T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/GALLONT', 'fc03bf99ad33794f4c33465f1dbe5917c8a4aceb2faeb21a82335652849b7111', 'scored', NULL, 9.98, 5.72, 5.72, 'same_as_strict (1.0 result, not re-checked)', 6.63, 9.0, 7.8325, 7.8325, NULL, NULL, NULL, 12078, 402, 396, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:40+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GAMUTS', 'Radiology Gamuts Ontology', 'In radiology, a "gamut" is the set of conditions that can cause a specified imaging finding.  The Radiology Gamuts Ontology (RGO) links more than 16,000 diseases and imaging findings.  The causal relation (may_cause; inverse, may_be_caused_by) connects findings and possible causes.

This work is made available under provisions of the Creative Commons Attribution-NonCommercial-NoDerivatives 4.0 International (CC BY-NC-ND 4.0) license.', 'Health;Human;Imaging', 'OWL', 25, '2.0', '2024-06-24T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/GAMUTS', '9c99a45765087f128e7949dc88b1c52820b3a1c6952c51f3dd75ac1cb37e1e2c', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 7.63, 10.0, 6.9075, 6.9075, NULL, NULL, NULL, 537796, 16877, 16877, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:33:52+00:00', '2026-09-23T23:25:10+00:00');
