INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GCDFO', 'DFO Salmon Ontology', 'OWL + SKOS ontology for DFO salmon data: stocks/CUs/MUs, survey events, escapement measurements, and GSI constructs; aligns to DwC via rdfs:subClassOf; hybrid approach with SKOS for methods and OWL for events.', 'Biological_Process;Fish_Anatomy;Other;Vocabularies', 'OWL', 7, '0.0.9', '2025-09-06T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/GCDFO', 'eccf787830ec528b332942bd7d75109c4d9d27d9f47e191a15d67f318bad3759', 'scored', NULL, 9.98, 6.03, 6.03, 'same_as_strict (1.0 result, not re-checked)', 0.46, 9.0, 6.3675, 6.3675, NULL, NULL, NULL, 4874, 412, 377, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:10+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GCO', 'Genome Component Ontology', 'The Genome Component Ontology is intended to define the abstract division of the total genetic information of an organism by its physical separation into different components, thereby providing a high level reference point to which more specific descriptions of the characteristics of these components can be linked.', 'Biomedical_Resources;Genomic_and_Proteomic', 'OWL', 4, '0.2', '2013-05-23T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/GCO', 'f87b128b9f5ba980c24e9a7969f7c0e47e1dc70f87e0a694ca57104c201ab1f9', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 4.0, 3.5, 3.5, NULL, NULL, NULL, 41, 5, 5, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:03:38+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GDCO', 'Data Collection Ontology', 'The Data Collection Ontology (DCO) is an ontology designed for data collection providing classes and relations on top of the Basic Formal Ontology (BFO) to facilitate data collection processes, subjects, and data anaylsis through the use of classifiers.

DCO is based on the notion of reasoning to validate incoming data through their definitions based on classifiers.', 'Development', 'OWL', 1, '1.0', '2017-08-09T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/GDCO', '69447f21a1446b80cb61345c1d606a4ae0da8658af7d9a6c7eacfc6579909331', 'scored', NULL, 9.86, 2.5, 2.5, 'same_as_strict (1.0 result, not re-checked)', 4.25, 9.0, 6.4025, 6.4025, NULL, NULL, NULL, 1332, 73, 73, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:21+00:00', '2026-09-23T23:25:10+00:00');
