INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GDOA', 'Graphic Descriptor Ontology Anatomy Extension', 'For the best browsing experience, see our illustrated browser at https://gdo.endlessforms.info that provides visual depictions of many classes and individuals. The GitHub repository is at https://github.com/endlessforms-info/GDO-GDOA. 
<br><br>
The version of the GDO/A here is the GDOA and the GDO merged. The version number applies to the merged variant. For separate GDOA and GDO artifacts, please visit the GitHub repo above. 
<br /><br />
The Graphic Descriptor Ontology (GDO) is intended for use in describing graphics that represent the form of objects. The Graphic Descriptor Ontology Anatomy extension (GDOA) extends the GDO to the domain of anatomical graphics by providing classes for anatomical views and anatomically-relevant region mark roles, such as representing a type of body tissue or body fluid., The Graphic Descriptor Ontology (GDO) is intended for use in describing graphics that represent the form of objects. It uses the language of visual communication, illustration, and technical drawing. The GDO is rooted in the Basic Formal Ontology (BFO) and uses several classes from the Information Entity Ontology of the Common Core Ontologies as a mid-level ontology., The Graphic Descriptor Ontology (GDO) is intended for use in describing graphics that represent the form of objects. The Graphic Descriptor Ontology Anatomy extension (GDOA) extends the GDO to the domain of anatomical graphics by providing classes for anatomical views and anatomically-relevant region mark roles', 'Anatomy;Gross_Anatomy', 'OWL', 10, '1.1.4', '2026-03-17T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/GDOA', '0428b6996c38cbcef053d012f583fdf836004b914645060828306581018ec94c', 'scored', NULL, 10.0, 6.38, 6.38, 'same_as_strict (1.0 result, not re-checked)', 0.82, 10.0, 6.8, 6.8, NULL, NULL, NULL, 2234, 282, 196, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:11+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GECCO', 'COVID-19 Common Datamodel', 'To ensure the interoperability and compatibility among COVID-19 datasets, we present here a Common Data
Model (CDM) which has been built from 11 different COVID-19 datasets from various geographical locations.
The current version of the CDM holds 4639 data variables related to COVID-19 such as basic patient
information (age, biological sex, and diagnosis) as well as disease-specific data variables, for example, Anosmia
and Dispnea. Each of the data variables in the data model is associated with specific data types, variable
mappings, value ranges, data units, and data encodings that could be used for standardizing any dataset.', 'Health;Human', 'OWL', 1, '1.0.0', '2022-08-19T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/GECCO', '177e95e23205234e69f0d5a92edf6b6a68aa6a4830e265e638004a0dc6c51125', 'scored', NULL, 10.0, 0.1, 0.1, 'same_as_strict', 6.12, 10.0, 6.555, 6.555, NULL, NULL, NULL, 121227, 5383, 5383, '0.10.0', 'core4-1.1', 'cuda', '2026-09-23T21:07:04+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GECKO', 'Genomics Cohorts Knowledge Ontology', 'An ontology to represent genomics cohort attributes.', 'Other', 'OWL', 11, NULL, '2021-01-20T18:04:24.000-08:00', 'https://bioportal.bioontology.org/ontologies/GECKO', '32c93ab11e84a8b1e5d0beed6af36e9044ed8e8f8b7cc9211be9eeb663cac5b5', 'scored', NULL, 9.94, 5.8, 5.8, 'same_as_strict (1.0 result, not re-checked)', 0.35, 10.0, 6.5225, 6.5225, NULL, NULL, NULL, 1506, 155, 155, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:35+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GENAI', 'Generative AI Ontology', 'The Generative AI Ontology - This is an OWL ontology that provides a comprehensive representation of concepts, relationships, and processes in generative AI. It covers various model types (e.g., LLMs, GANs, VAEs), architectural components (e.g., transformers, diffusion models), training techniques (e.g., RLHF, self-supervised learning), fine-tuning methods (e.g., LoRA, Prompt Tuning), tools, deployment strategies, and ethical considerations. This ontology serves as a resource for research and proof-of-concept development, allowing detailed exploration and understanding of generative AI systems.', 'Other', 'OWL', 1, '1.0', '2024-10-24T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/GENAI', '6aa71f885a184aa619319ba7151d98f5ed46e74d67c343b175449a5a7311dad6', 'scored', NULL, 0.63, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 8.0, 2.1575, 2.1575, NULL, NULL, NULL, 137, 63, 56, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:03:56+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GENDER', 'Gender Identity', 'This vocabulary makes up the different gender identities - Female, Male and Other.', 'Vocabularies', 'SKOS', 1, NULL, '2022-12-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/GENDER', 'eba86434b60f798be68e5d0f381b88044656e20d5f5bb21d44f6f41e7a30bfe7', 'scored', NULL, 8.75, 3.87, 3.87, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 3.155, 3.155, NULL, NULL, NULL, 65, 8, 7, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:03:38+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GENE-CDS', 'Genomic Clinical Decision Support Ontology', 'The Genomic CDS ontology aims to unify several functionalities in a single resource, being:
* A knowledge base for clinical pharmacogenomics/pharmacogenetics that can be used for question-answering (e.g., which SNPs are associated with this drug?)
* A rule base for clinical decision support (e.g., inferring that a patient with a specific set of SNPs requires a lowered dose of warfarin and generating a CDS message that can be viewed by clinicians)
* A tool for checking data consistency (e.g., highlighting which allele definitions in PharmGKB are overlapping, or which clinical decision support rules are matching the same group of patients)', 'Genomic_and_Proteomic;Health;Human', 'OWL', 1, '0.8.0', '2012-11-21T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/GENE-CDS', 'c31f5e7bb7bbf1d349ae1e0eff34202f77d2347c118b7bcc802ba9b51eec34ca', 'scored', NULL, 10.0, 0.03, 0.03, 'same_as_strict (1.0 result, not re-checked)', 4.87, 10.0, 6.225, 6.225, NULL, NULL, NULL, 50497, 2266, 2266, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:13:19+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GENEPIO', 'Genomic Epidemiology Application Ontology ', 'The Genomic Epidemiology Application Ontology describes the genomics, laboratory, clinical and epidemiological contextual information required to support data sharing and integration for foodborne infectious disease surveillance and outbreak investigations., The Genomic Epidemiology Ontology aims to provide a comprehensive controlled vocabulary for infectious disease surveillance and outbreak investigations. It is an application ontology that draws on many other ontologies including anatomy, taxonomy, disease, symptoms, environment and food types for foodborn pathogen metadata.', 'Health', 'OBO', 3, '2026-04-13', '2026-04-13T18:05:37.000-07:00', 'https://bioportal.bioontology.org/ontologies/GENEPIO', 'f8fb7f1f96f5bee60ba2be40a7cc01f7a81a3a88c6d00e2097512811d4df59b5', 'scored', NULL, 10.0, 4.77, 4.77, 'same_as_strict (1.0 result, not re-checked)', 0.74, 10.0, 6.3775, 6.3775, NULL, NULL, NULL, 86003, 9389, 9160, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:19:05+00:00', '2026-09-23T23:25:10+00:00');
