INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GENO', 'Genotype Ontology', 'An integrated ontology for representing the genetic variations described in genotypes, and their causal relationships to phenotype and diseases., GENO is an OWL model of genotypes, their more fundamental sequence components, and links to related biological and experimental entities.  At present many parts of the model are exploratory and set to undergo refactoring.  In addition, many classes and properties have GENO URIs but are place holders for classes that will be imported from an external ontology (e.g. SO, ChEBI, OBI, etc).  Furthermore, ongoing work will implement a model of genotype-to-phenotype associations. This will support description of asserted and inferred relationships between a genotypes, phenotypes, and environments, and the evidence/provenance behind these associations. 

Documentation is under development as well, and for now a slidedeck is available at http://www.slideshare.net/mhb120/brush-icbo-2013', '', 'OWL', 33, '2026-02-02', '2026-02-05T18:05:37.000-08:00', 'https://bioportal.bioontology.org/ontologies/GENO', '354ced230cf68c33ba1055fb84b181d4818c55eec8d13782b89ac9446999b7f1', 'scored', NULL, 10.0, 5.42, 5.42, 'same_as_strict (1.0 result, not re-checked)', 2.34, 9.0, 6.69, 6.69, NULL, NULL, NULL, 12940, 875, 590, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:29+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GEO', 'Geographical Entity Ontology', 'An ontology of geographical entities implemented in Web Ontology Language 2 (OWL2) and based on Basic Formal Ontology (BFO).', '', 'OWL', 3, 'production version 2018-02-23', '2019-02-17T18:05:19.000-08:00', 'https://bioportal.bioontology.org/ontologies/GEO', '51613065376bdb9e9ca3291547d72d61bd7bae829ae6919ca860be15f1c15b69', 'scored', NULL, 10.0, 0.04, 0.04, 'same_as_strict (1.0 result, not re-checked)', 8.16, 10.0, 7.05, 7.05, NULL, NULL, NULL, 308891, 54873, 328, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:34:32+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GEOSPARQL', 'GeoSPARQL', 'The OGC GeoSPARQL standard supports representing and querying geospatial data on the Semantic Web. GeoSPARQL defines a vocabulary for representing geospatial data in RDF, and it defines an extension to the SPARQL query language for processing geospatial data. In addition, GeoSPARQL is designed to accommodate systems based on qualitative spatial reasoning and systems based on quantitative spatial computations.', 'Other', 'OWL', 1, 'OGC GeoSPARQL 1.0', '2017-12-09T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/GEOSPARQL', '83f46870cdd10f1ff18c7824924fa7e7bb5d1e3426957a833fbe76eb374cfcd4', 'scored', NULL, 9.84, 0.71, 0.71, 'same_as_strict (1.0 result, not re-checked)', 0.25, 8.0, 4.7, 4.7, NULL, NULL, NULL, 1134, 62, 62, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:11+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GEOSPECIES', 'GeoSpecies Ontology', 'This ontology was designed to help integrate species concepts with species occurrences, gene sequences, images, references and geographical information. See also Taxonconcept.org', 'Other', 'OWL', 2, '2012-10-02', '2012-10-02T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/GEOSPECIES', '68de8f48b9e6979fffdb72eaed9b88bb72418b09a1469c82cccd19400fbcaa10', 'scored', NULL, 10.0, 0.31, 0.31, 'same_as_strict (1.0 result, not re-checked)', 1.99, 9.0, 5.325, 5.325, NULL, NULL, NULL, 2273, 290, 86, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:03+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GERO', 'Gerotranscendence Ontology', 'The Gerotranscendence Ontology contains terms for defining and classifying concepts related to gerotranscendence, including its dimensions, experiences, and outcomes. Its concepts and relations support the development of tools and resources to better understand gerotranscendence and enable integration and interoperability of data across studies.

The Gerotranscendence Ontology is developed as a subset of (http://purl.obolibrary.org/obo/phases.owl). , and outcomes. Its concepts and relations support the development of tools and resources to better understand gerotranscendence and enable integration and interoperability of data across studies.

The Gerotranscendence Ontology is developed as a subset of (http://purl.obolibrary.org/obo/phases.owl). Issues and term requests can be submitted at (https://github.com/Buffalo-Ontology-Group/phases/issues)', '', 'OWL', 2, '2026-02-25', '2026-02-26T18:06:02.000-08:00', 'https://bioportal.bioontology.org/ontologies/GERO', 'bd90be52a0f97ae11f22d6199062512a4bc133a43a72d98f1d72b4aa723ef24a', 'scored', NULL, 9.86, 6.03, 6.03, 'same_as_strict (1.0 result, not re-checked)', 4.52, 8.0, 7.1025, 7.1025, NULL, NULL, NULL, 1462, 73, 54, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:33+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GEXO', 'Gene Expression Ontology', 'An application ontology for the domain of gene expression. The ontology integrates fragments of GO and MI with data from GOA, IntAct, UniProt, NCBI, and orthology relations using ontological properties from RO and ISO.', 'Biological_Process', 'OWL', 2, '2015', '2015-12-16T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/GEXO', 'ada0c42f56fe40a82086cf8327093fb6840a024b684535316d3192a14bb5d86c', 'scored', NULL, 10.0, 6.63, 6.63, 'same_as_strict (1.0 result, not re-checked)', 8.09, 10.0, 8.68, 8.68, NULL, NULL, NULL, 2466411, 166255, 166255, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T07:36:36+00:00', '2026-09-23T23:25:10+00:00');
