INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GFO', 'General Formal Ontology', 'The General Formal Ontology (GFO) is a top-level ontology integrating objects and processes.', 'All_Organisms;Upper_Level_Ontology', 'OWL', 1, 'Version 1.0 ($Revision: 1.13 $)', '2006-01-07T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/GFO', '4625d1c4f959ee0bdb0928140d6ee8d5e42ad691cfffd52c0c3bf4d8ab86e9d2', 'scored', NULL, 10.0, 0.17, 0.17, 'same_as_strict (1.0 result, not re-checked)', 2.8, 9.0, 5.4925, 5.4925, NULL, NULL, NULL, 654, 45, 45, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:47+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GFO-BIO', 'General Formal Ontology for Biology', 'GFO-Bio is a biological core ontology built on the General Formal Ontology.', 'All_Organisms;Anatomy;Animal_Development;Animal_Gross_Anatomy;Biological_Process;Cell;Cellular_anatomy_;Chemical;Development;Gene_Product;Gross_Anatomy;Human;Human_Developmental_Anatomy;Molecule;Mouse_Anatomy;Phenotype;Plant;Plant_Anatomy;Plant_Development;Protein;Subcellular;Subcellular_anatomy', 'OWL', 1, '1.1', '2010-07-12T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/GFO-BIO', 'ce9fe39764d3ab84367ee033e9cf369ae149eb35fcfe67dfd5fc8c9e2e560072', 'scored', NULL, 4.73, 1.88, 1.88, 'same_as_strict (1.0 result, not re-checked)', 2.76, 9.0, 4.5925, 4.5925, NULL, NULL, NULL, 1277, 169, 168, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:25+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GFVO', 'Genomic Feature and Variation Ontology', 'The Genomic Feature and Variation Ontology (GFVO) is modeled to represent genomic data using the Resource Description Format (RDF) or Linked Data using JSON (JSON-LD). It is captures the contents of data files that adhere to the Generic Feature Format Version 3 (GFF3, http://www.sequenceontology.org/resources/gff3.html), the General Transfer Format (GTF, http://mblab.wustl.edu/GTF22.html), the Genome Variation Format Version 1 (GVF, http://www.sequenceontology.org/resources/gvf.html), and the Variant Call Format (VCF, http://vcftools.sourceforge.net/specs.html), as well as the FASTA format (http://en.wikipedia.org/wiki/FASTA_format). The creation of the ontology was inspired by previous work of Robert Hoehndorf on RDF2OWL (http://code.google.com/p/rdf2owl).

NOTE: GFVO in BioPortal is a simplified version without ontology imports and having class/property equivalences removed. The full ontology is available at: http://www.biointerchange.org/gfvo', 'Biological_Process;Biomedical_Resources;Gene_Product;Genomic_and_Proteomic;Human', 'OWL', 20, '1.0.6', '2015-07-14T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/GFVO', 'e4def9136e5c915cbdddd0f90cf01a035d5e66caa45dc1ea71b1012c3345018d', 'scored', NULL, 9.9, 6.76, 6.76, 'same_as_strict (1.0 result, not re-checked)', 3.74, 10.0, 7.6, 7.6, NULL, NULL, NULL, 1350, 103, 103, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:31+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GLYCO', 'Glycomics Ontology', 'The GlycO ontology provides an up-to-date knowledge base of experimentally verified glycan structures. Glycan (oligosaccharide or polysaccharide) structures are represented as trees of monosaccharide residues. Linkage to proteins and lipids is supported as well. Insertion of a new glycan is controlled by curation process that includes matching the new glycan against a canonical glyco-tree (a highly branched representation for a family of glycans).', 'Biomedical_Resources;Chemical;Molecule;Other;Protein', 'OWL', 1, '4.6.0.0', '2012-10-29T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/GLYCO', '9324992209ff3ae4de0b53dd1909070b66fd24688495a89f47a2eae5d1827ee5', 'scored', NULL, 10.0, 1.35, 1.35, 'same_as_strict (1.0 result, not re-checked)', 8.3, 10.0, 7.4125, 7.4125, NULL, NULL, NULL, 38795, 2014, 230, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:14:16+00:00', '2026-09-23T23:25:10+00:00');
