INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'GS1GDSN', 'GS1 Global Data Model', 'The GS1 Global Data Model (GDM) and Attribute Definitions for Business (ADB) standards enable greater data quality within the GS1 Global Data Synchronisation Network (GS1 GDSN). The GS1 Global Data Model standard defines a globally consistent set of foundational product attributes needed to list, order, store, move and sell products.

Implementing the GS1 Global Data Model standards within GS1 GDSN will improve data accuracy and completeness for consumers across their omnichannel purchasing journey, and increase operational efficiency for brand owners, retailers and data pools.

By providing a consistent business language and usage statements for these foundational attributes, the ADB standard clarifies sometimes difficult technical terminology, and helps data senders get their content right.', 'Taxonomic_Classification;Vocabularies', 'OWL', 1, '3.1.35', '2026-08-03T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/GS1GDSN', 'ad243f247d63a22fb585ef7ab80096640595cde2d7f630e6bdbc359a706c727e', 'scored', NULL, 10.0, 5.34, 5.34, 'same_as_strict (1.0 result, not re-checked)', 0.45, 8.0, 5.9475, 5.9475, NULL, NULL, NULL, 235257, 17475, 1489, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:26:01+00:00', '2026-09-23T23:25:10+00:00');
