INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HAMIDEHSGH', 'Inherited Retinal Dystrophy', 'Inherited retinal dystrophy (IRD) as one of the rare ocular diseases encompasses different types of hereditary retinal degenerations appearing by involvement of the different layers of the posterior ocular segment. In respect of the importance of the classification systems regarding the recorded history of biologic and natural sciences, there is no classification regarding the IRD diagnoses. Therefore, we aimed to present a novel classification in this regard.', 'Human', 'OWL', 1, NULL, '2019-07-10T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/HAMIDEHSGH', '30114daf35b25e792ccc6d63b1aa1b0836fc2a6b17db56cffc318448416e7558', 'scored', NULL, 9.98, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 2.82, 10.0, 5.7, 5.7, NULL, NULL, NULL, 3630, 408, 408, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:06:29+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HANCESTRO', 'Human Ancestry Ontology', 'The Human Ancestry Ontology (HANCESTRO) provides a systematic description of the ancestry concepts used in the NHGRI-EBI Catalog of published genome-wide association studies.

Please note that as of v2.0 (released July 2018), HANCESTRO (formerly ANCESTRO) has undergone some major changes including a revised namespace., Human ancestry ontology for the NHGRI GWAS Catalog', 'Experimental_Conditions;Human;Vocabularies', 'OWL', 21, '2025-10-14', '2025-10-14T18:05:25.000-07:00', 'https://bioportal.bioontology.org/ontologies/HANCESTRO', 'c2555d27f393f5124749589ee1d9190069b676cad7209f9439d050f6029ca367', 'scored', NULL, 10.0, 3.35, 3.35, 'same_as_strict (1.0 result, not re-checked)', 7.29, 10.0, 7.66, 7.66, NULL, NULL, NULL, 27599, 1329, 1310, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:10:51+00:00', '2026-09-23T23:25:10+00:00');
