INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HASCO', 'Human-Aware Science Ontology', 'The Human-Aware Science Ontology (HAScO) integrates a collection of well-established science-related ontologies, and aims to address issues related to data annotation for large data ecosystem, where data can come from diverse data sources including sensors, lab results, and questionnaires. The HAScO has been used to annotate data collections to facilitate data exploration and analysis for numerous scientific projects. Data files produced by scientific studies are processed to identify and annotate the objects (a gene, for instance) with the appropriate ontological terms. ', 'Upper_Level_Ontology', 'OWL', 8, '0.9', '2025-11-17T18:07:28.000-08:00', 'https://bioportal.bioontology.org/ontologies/HASCO', 'b024ebc5ca2de00e35728fe2df4f3288f015968e5fc25bce59e181876dcfb715', 'scored', NULL, 8.38, 4.13, 4.13, 'same_as_strict (1.0 result, not re-checked)', 2.32, 10.0, 6.2075, 6.2075, NULL, NULL, NULL, 28312, 3714, 2546, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:11:37+00:00', '2026-09-23T23:25:10+00:00');
