INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HCDR', 'Homelessness and Clinical Data Recording', 'This ontology utilizes the European Typology of Homelessness and Housing Exclusion (ETHOS), a respected conceptual framework used to define degrees of housing insecurity and homelessness internationally, to conceptualize, define, and link homelessness in SNOMED, Read CTV3, and Read 2 codes to clinical data extraction. The ontology uses the ETHOS as a general framework, leading to endpoints represented by codes from across the three databases. This is useful for researchers and medical professionals seeking to understand how homelessness is represented in clinical data, how homelessness is defined internationally, and what types of services are available for homeless individuals. ', 'Other', 'OWL', 1, '1', '2020-01-21T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/HCDR', 'efba3bee186bdc014f7f71b4b9e98e40bc1c3973455bd36243b564a9462b58b3', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.19, 9.0, 4.7975, 4.7975, NULL, NULL, NULL, 666, 120, 120, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:48+00:00', '2026-09-23T23:25:10+00:00');
