INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HDMPONTO', 'HierarchicalDMProcessOnto', 'A Hierarchical Data Mining Process Ontology, by combined OntoKDD and DMWF.', 'Taxonomic_Classification', 'OWL', 1, NULL, '2020-12-18T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/HDMPONTO', '5e67e62bd9b3592f0581bb3f5ba062d7ca0ecb5188a18157bf7abc7447fde892', 'scored', NULL, 9.74, 0.03, 0.03, 'same_as_strict (1.0 result, not re-checked)', 5.93, 10.0, 6.425, 6.425, NULL, NULL, NULL, 4341, 382, 378, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:53+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HDS', 'Humanitarian Data Space', 'The humanitarian data space vocabulary describes entities and relationships relevant for humanitarian applications, specifically focusing on events related to sexual violence, human trafficking and refugee protection. The aim of this vocabulary is to report on situations and incidents that are taking place on the ground into the humanitarian data space.', 'Human;Other;Vocabularies', 'OWL', 1, NULL, '2025-12-11T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/HDS', 'b744d10cb058ba63676cd30a9946f35342ca22a1d0dc87e308bde07019588394', 'scored', NULL, 6.6, 1.69, 1.69, 'same_as_strict (1.0 result, not re-checked)', 1.26, 5.0, 3.6375, 3.6375, NULL, NULL, NULL, 381, 50, 50, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:14+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HECON', 'HECON: Health Condition Evolution Ontology', 'Health Condition Evolution Ontology (HECON), is a formal model representation of the evolution of medical events over time.', 'Health;Other', 'OWL', 1, '0.1', '2022-04-22T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/HECON', 'e638b77d5113f596d4946a332f1ee2f6382f82b61d3220cbc0aa3844be85a798', 'scored', NULL, 7.11, 2.46, 2.46, 'same_as_strict (1.0 result, not re-checked)', 7.23, 7.0, 5.95, 5.95, NULL, NULL, NULL, 383, 38, 17, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:20+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HED', 'Hierarchical Event Descriptors', 'HED (Hierarchical Event Descriptors) is a standardized vocabulary for describing what happens during experiments and a framework for mapping these terms and other metadata onto the experimental timeline to enable analysis. HED is a subtag system organized by the top-level categories: Event, Agent, Action, Item, Property, and Relation. Users create HED annotations as comma-separated, parenthesized lists of terms. See https://www.hed-resource.org for documentation, tutorials and other resources.

Recently we have created an ontology representation of the HED vocabulary (HED schema) to provide a better mechanism for linking the HED terms to terms from other ontologies and to provide better provenance information. The HED tags as well as auxiliary information such as types of units and types of values are represented as classes. The HED schema attributes are represented either as DataProperty or ObjectProperty depending on their range. Some additional attributes that are not inherited are represented as AnnotationProperty. HED is the standard used for event annotation in BIDS (Brain Imaging Data Structure) a standard for storing neuroimaging repository and is used by datasets on several repositories such as openNeuro and Nemar.', 'Vocabularies', 'OWL', 1, 'releases/2024-06-10', '2024-07-03T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/HED', '367a1897da9ce84ed182631af7a2095eb316a377f134896c29392d08f0d58f69', 'scored', NULL, 10.0, 0.02, 0.02, 'same_as_strict (1.0 result, not re-checked)', 0.77, 10.0, 5.1975, 5.1975, NULL, NULL, NULL, 12506, 1358, 1358, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:43+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HEIO', 'Regional Healthcare System Interoperability and Information Exchange Measurement Ontology', 'The purpose of this ontology is to develop a model for regional healthcare system interoperability and information exchange quantification (measured by the electronic health information exchange (eHIE) indicator). The eHIE is hypothesized as a leading measure of regional healthcare system integration.
A publication associated with this ontology is currently under review. ', 'Other', 'OWL', 17, 'Version 1.15', '2015-04-09T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/HEIO', 'df5896c3e52a8eb6095cd36d8220b8439be935c2e6913cc0e586ad2ee81bc334', 'scored', NULL, 10.0, 2.24, 2.24, 'same_as_strict (1.0 result, not re-checked)', 7.45, 9.0, 7.1725, 7.1725, NULL, NULL, NULL, 17670, 1730, 125, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:12:08+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HELIFIT', 'HeLiFit-Ontology', 'This an ontology for healthcare.', 'Biomedical_Resources;Health', 'OWL', 1, '1.6.4', '2022-12-13T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/HELIFIT', '34c4c442922677307dfcae19146d2b9ee2b371e1cc96f7ef36b4b77350af2c4d', 'scored', NULL, 9.05, 3.5, 3.5, 'same_as_strict (1.0 result, not re-checked)', 0.13, 10.0, 5.67, 5.67, NULL, NULL, NULL, 3929, 652, 511, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:03+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HENECON', 'Head and Neck Cancer Ontology', 'HeNeCOn (Head and Neck Cancer Ontology) is the first ontology specifically focused on the Head and Neck Cancer (HNC) domain. It provides a clinically reliable data model for HNC processes during all phases of the disease: prognosis, treatment, and follow-up. The ontology is established based on an annotated dataset to provide formal reference descriptions, contains  170 clinical variables organized into a taxonomy, and is expanded and mapped to formalize and integrate multiple databases into the HeNeCOn ontology. The outcomes of this iterative process were reviewed and validated by clinicians and statisticians. HeNeCOn, with roughly 500 classes, is a very specific ontology which includes a taxonomy with a hierarchical structure, semantic definitions of 283 medical terms and detailed relations between them, which makes it a reference data model. ', 'Biomedical_Resources;Health;Vocabularies', 'OWL', 1, '2.0', '2020-04-14T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/HENECON', '56d13fd068572044648e582d71086be57b3dbc00a865c0c3feb14b02c6912665', 'scored', NULL, 9.99, 3.81, 3.81, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 5.95, 5.95, NULL, NULL, NULL, 10059, 1844, 1842, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:36+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HENEGEO', 'Head and Neck Cancer - Clinical and Gene Ontology', 'HeNeGeO (Head and Neck Cancer - Clinical and Gene Ontology) presents a data model that encompasses both clinical and genomic aspects of Head and Neck Cancer (HNC) across every stage of the disease, covering prognosis, treatment and follow-up. This ontology builds upon the foundation laid by HENECON (Head and Neck Cancer Ontology) and has been significantly expanded with a focus on information pertaining to cancer recurrence, alongside a comprehensive list of genes that offer valuable insights throughout the entire head and neck cancer progression. To enhance clarity, novel medical terms have been thoughtfully annotated with their respective semantic meanings. This comprehensive update includes the incorporation of 29,770 genes, featuring essential details such as NCBI GeneID (EntrezID), gene symbol, gene name, gene alias, and the HGNC ID. The development of this ontology underwent rigorous review and validation by experts in both clinical and genomic domains.', 'Biomedical_Resources;Genomic_and_Proteomic;Health;Vocabularies', 'OWL', 1, '1.0', '2023-10-23T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/HENEGEO', '75f99d5db5555838c67ad888e626add228ee4513f48b546264481f22a3e3d130', 'scored', NULL, 9.99, 0.01, 0.01, 'same_as_strict (1.0 result, not re-checked)', 0.0, 9.0, 4.75, 4.75, NULL, NULL, NULL, 295110, 29997, 29997, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:29:51+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HERO', 'Healthcare Monitoring and Emergency Response Ontology', 'This ontology is designed to support a healthcare monitoring system that leverages wearable devices and Semantic Web technologies to continuously monitor patient vital signs, assess their medical conditions, and provide timely alerts and interventions in case of abnormalities or emergencies. It aims to enhance patient care, safety, and decision-making by integrating ontology-based reasoning, SWRL rules, and real-time data from various sources.

Main Features:
- Integration of Diverse Data Sources: The ontology integrates different data models like FHIR (for electronic health records and medical data), SOSA (for sensor data and vital signs), and FOAF (for patient profile management). This integration allows for a comprehensive representation of both static and dynamic patient data, supporting more accurate monitoring and decision-making.

- Vital Sign Monitoring: It includes classes and properties for representing vital signs such as Temperature, Blood Pressure, Heart Rate, Respiratory Rate, and Oxygen Saturation. Each vital sign is associated with corresponding observations and results, following the SOSA ontology pattern.

- Health Condition Assessment: The ontology defines multiple classes to represent different health conditions:
  1- Normal Situation: Represents a state where all monitored vital signs fall within their normal ranges.
   2- Abnormal Situation: Represents a state where one or more vital signs fall outside their normal range, but there is no indication of device 
       malfunction.
  3- Wrong Situation: Represents a condition where at least one vital sign is classified as "wrong," indicating a possible malfunction of the wearable 
      device. This triggers alerts to the patient to check or repair the device.
- Emergency and Critical Emergency Handling: In abnormal situations, SWRL rules are used to infer whether the situation is an emergency or a critical emergency:
  Emergency Situation: Requires additional evaluation by healthcar', 'Health', 'OWL', 1, 'FHIR W5 categorization (Preliminary)', '2024-09-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/HERO', NULL, 'not_downloadable', '{"errors":["License restrictions on download for HERO"],"status":403}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HFO', 'Heart Failure Ontology', 'Heart failure ontology is an attempt to define heart-failure-relevant information including the causes and risk factors, signs and symptoms, diagnostic tests and results, and treatment. ', 'Ethology;Health;Human;Phenotype;Vocabularies', 'OWL', 1, 'version 1.0', '2015-12-08T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/HFO', '5554e3563c1e69758799312d93611f3bfbc68bcb57fdcbe97c3d91f2af27f844', 'scored', NULL, 9.99, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 4.9975, 4.9975, NULL, NULL, NULL, 10592, 1653, 1653, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:08:36+00:00', '2026-09-23T23:25:10+00:00');
