INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HHEAR', 'Human Health Exposure Analysis Resource', 'The Human Health Exposure Analysis Resource (HHEAR) Ontology was developed as an application ontology to represent data collected within the HHEAR program and support data pooling efforts across studies in the environmental health sciences. If you are interested in using the HHEAR ontology for a source of standard terminology, please view the HHEAR Value Sets available on BioPortal.', 'Health', 'OWL', 20, '1.13.1', '2026-03-09T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/HHEAR', '4206834814852a2b69ff6c618085213180185d96799998e53a585523ecc02447', 'scored', NULL, 9.29, 5.56, 5.56, 'same_as_strict (1.0 result, not re-checked)', 1.34, 10.0, 6.5475, 6.5475, NULL, NULL, NULL, 37553, 4574, 3691, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:13:06+00:00', '2026-09-23T23:25:10+00:00');
