INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HINO', 'Human Interaction Network Ontology', 'The Human Interaction Network Ontology (HINO) is an INO extension for the domain of human interaction networks. It has currently incoporated Reactome reactions and pathways. Like INO, HINO aligns with BFO. HINO is developed by following the OBO Foundry principles. ', '', 'OWL', 6, 'Vision Release: 1.0.69', '2014-06-27T12:32:47.000-07:00', 'https://bioportal.bioontology.org/ontologies/HINO', '8b2d2eb92a799412025af5fefbe1dfc0da330c5b6ea52eccaff046f3b755fc04', 'scored', NULL, 10.0, 3.4, 3.4, 'same_as_strict (1.0 result, not re-checked)', 8.34, 10.0, 7.935, 7.935, NULL, NULL, NULL, 799186, 37631, 37631, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:48:19+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HIO', 'Hearing Impairment Ontology', 'The Hearing Impairment Ontology (HIO) is a common controlled hearing impairment (HI) vocabulary, which is expected to enhance collaborative research. This ontology is currently the most comprehensive and standardized human- and machine-readable resource that unambiguously defines HI concepts and terminology for researchers, patients and clinicians in order to help process, reuse and re-apply existing HI knowledge in biomedical research and health-care systems. In the context of big data analytics, this ontology may facilitate a retrospective data harmonization and contribute to mapping HI datasets to functional knowledge to enable the subsequent HI research translation into clinical applications and policy guidelines. The HIO will allow researchers, clinicians and patients to readily access standardized HI-related knowledge in a single location and promote HI data integration, interoperability and sharing, including epidemiological, socio-environmental, biomedical, genetic and phenotypic datasets.', 'Dysfunction', 'OWL', 3, '1', '2019-10-31T18:10:08.000-07:00', 'https://bioportal.bioontology.org/ontologies/HIO', 'fcd96b8c0cdb720aa98c96cba62b34cc22bba0f02b47ab36f5786b2bc84619a3', 'scored', NULL, 10.0, 0.25, 5.38, 'http://purl.org/dc/elements/1.1/description [bioportal_definitionProperty]', 1.15, 10.0, 5.35, 6.6325, NULL, NULL, NULL, 6090, 496, 496, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T22:57:09+00:00', '2026-09-23T23:25:10+00:00');
