INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HIVO004', 'HIVOntologymain.owl', '
A Project of Biomedical Ontology for Systems Biomedicine. The Project includes, so far, a main ontology (HIVOnt0**.owl) which is imported by several other sub ontologies AIDSClinic0**.owl, etc. The goals of the Project include: (1). To pilot the novel researches on AIDS and HIV or other diseases by viruses, by means of the ontology and other biomedical informatics technologies, connecting the insights of the Biomedical Knowledge Integration (BMKI), systems biomedicine, complexity sciences etc. (2). To Carry out the methodology explorations for the goals above.', 'Biological_Process;Biomedical_Resources;Dysfunction;Health;Immunology;Molecule;Protein;Subcellular;Taxonomic_Classification', 'OWL', 29, '020', '2020-10-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/HIVO004', '14c32dbe4c56990eb063174ad1657c1af0ca639136d85ca41b983d82fca2f0e2', 'scored', NULL, 9.99, 0.47, 0.47, 'same_as_strict (1.0 result, not re-checked)', 1.22, 10.0, 5.42, 5.42, NULL, NULL, NULL, 11699, 2207, 2114, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:52+00:00', '2026-09-23T23:25:10+00:00');
