INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HNS', 'HNS_Ontolgoy', 'The purpose of this research is to develop an ontology with subsequent testing and evaluation, for identifying utility and value. The domain that has been chosen is human nervous system (HNS) disorders. It is hypothesized here that an ontology-based patient records management system is more effective in meeting and addressing complex information needs of health-care personnel. Therefore, this study has been based on the premise that developing an ontology and using it as a component of the search interface in hospital records management systems will lead to more efficient and effective management of health-care. It is proposed here to develop an ontology of the domain of HNS disorders using a standard vocabulary such as MeSH or SNOMED CT. The principal classes of an ontology include facet analysis for arranging concepts based on their common characteristics to build mutually exclusive classes. We combine faceted theory with description logic, which helps us to better query and retrieve data by implementing an ontological model. Protégé 5.2.0 was used as ontology editor. The use of ontologies for domain modelling will be of acute help to doctors for searching patient records. In this paper we show how the faceted approach helps us to build a flexible model and retrieve better information. We use the medical domain as a case study to show examples and implementation.', 'Health;Human;Neurologic_Disease', 'OWL', 1, '4.0', '2020-05-05T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/HNS', '3435784c02c92bb42bf0b2f5329ac29ed6849a0c657ba56d48c67dace2847dff', 'scored', NULL, 8.07, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.5, 10.0, 4.6425, 4.6425, NULL, NULL, NULL, 2187, 684, 547, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:06:20+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'HO', 'Histological Ontology', 'A Histological Ontology of the Human Cardiovascular System v. 1.1', 'Biomedical_Resources', 'OWL', 78, '1.1', '2017-10-06T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/HO', 'ecda78fb875173e2177a6d2dd31608c55e27223f897f0203379fead92ca6f6d2', 'scored', NULL, 9.91, 5.99, 5.99, 'same_as_strict (1.0 result, not re-checked)', 4.56, 9.0, 7.365, 7.365, NULL, NULL, NULL, 2222, 215, 214, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:53+00:00', '2026-09-23T23:25:10+00:00');
