INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'IAO', 'Information Artifact Ontology', 'The Information Artifact Ontology (IAO) is an  ontology of information entities, originally driven by work by the OBI consortium.<p>

<p><b>To import</b><p>

Latest released version: <a href="http://purl.obolibrary.org/obo/iao.owl">http://purl.obolibrary.org/obo/iao.owl</a><p>

<b>Other versions</b><p>

Developer (live) version: <a href="http://purl.obolibrary.org/obo/iao/dev/iao.owl">http://purl.obolibrary.org/obo/iao/dev/iao.owl</a><p>

Ontology metadata properties and classes only: <a href="http://purl.obolibrary.org/obo/iao/dev/ontology-metadata.owl">http://purl.obolibrary.org/obo/iao/dev/iao.owl</a><p>

<b>Dated versions</b>
<ul>
<li><a href="http://purl.obolibrary.org/obo/iao/2009-11-06/iao.owl">http://purl.obolibrary.org/obo/iao/2009-11-06/iao.owl</a>
<li><a href="http://purl.obolibrary.org/obo/iao/2010-09-14/iao.owl">http://purl.obolibrary.org/obo/iao/2010-09-14/iao.owl</a>
<li><a href="http://purl.obolibrary.org/obo/iao/2010-10-26/iao.owl">http://purl.obolibrary.org/obo/iao/2010-10-26/iao.owl</a>
<li><a href="http://purl.obolibrary.org/obo/iao/2011-05-09/iao.owl">http://purl.obolibrary.org/obo/iao/2011-05-09/iao.owl</a>
<li><a href="http://purl.obolibrary.org/obo/iao/2015-02-23/iao.owl">http://purl.obolibrary.org/obo/iao/2015-02-23/iao.owl</a>
</ul><p>

<p>Please note: The ontology metrics displayed by BioPortal do not distinguish IAO-developed terms from terms imported from other ontologies.

<p><b>Tracker</b>: <a href="http://purl.obolibrary.org/obo/iao/tracker">http://purl.obolibrary.org/obo/iao/tracker</a><br>
<b>Discussion group</b>: <a href="http://groups.google.com/group/information-ontology">http://groups.google.com/group/information-ontology</a>, The Information Artifact Ontology (IAO) is an ontology of information entities, originally driven by work by the OBI digital entity and realizable information entity branch.', 'Biomedical_Resources;Imaging;Other', 'OWL', 11, '2026-03-30', '2026-04-10T18:06:30.000-07:00', 'https://bioportal.bioontology.org/ontologies/IAO', '9dd592388d6221e5ffbb834fe1125c49ae85d850cba8c147c59f3b573d60e2a3', 'scored', NULL, 10.0, 5.61, 5.61, 'same_as_strict (1.0 result, not re-checked)', 4.08, 10.0, 7.4225, 7.4225, NULL, NULL, NULL, 5547, 286, 267, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:35+00:00', '2026-09-23T23:25:10+00:00');
