INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ICECI', 'International Classification of  External Causes of Injuries', 'The International Classification of External Causes of Injury (ICECI) is a system of classifications to enable systematic description of how injuries occur. It is designed especially to assist injury prevention. 

The ICECI was originally designed for use in settings in which information is recorded in a way that allows statistical reporting--for example, injury surveillance based on collection of information about cases attending a sample of hospital emergency departments. It has also been found useful for other purposes. For example, it has been used as a reference classification during revision of another classification, to record risk-factor exposure of children in a cohort study, as the basis for special-purpose classifications and in a growing number of other ways.', '', 'OWL', 6, 'Original Source: 1.2; OWL version 1.02', '2004-07-01T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/ICECI', '69bc384ffa123d5ab4923f05ae2f0ad12f58c52a1b9a09123e994bb443205d6e', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.86, 10.0, 5.215, 5.215, NULL, NULL, NULL, 22555, 2232, 2232, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:11:20+00:00', '2026-09-23T23:25:10+00:00');
