INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ICF', 'International Classification of Functioning, Disability and Health', 'The International Classification of Functioning, Disability and Health, known more commonly as ICF, is a classification of health and health-related domains. These domains are classified from body, individual and societal perspectives by means of two lists: a list of body functions and structure, and a list of domains of activity and participation. Since an individual''s functioning and disability occurs in a context, the ICF also includes a list of environmental factors.
<br><br>
Source: <a href="http://www.who.int/classifications/icf/en/">http://www.who.int/classifications/icf/en/</a>', 'Health;Human;Vocabularies', 'OWL', 3, '1.0.2', '2012-05-08T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/ICF', 'e5545b146e86b8cd1d144840a13ab8f315bb9bfbf5bf85a84dd0bbf54deaf943', 'scored', NULL, 9.26, 0.0, 0.0, 'http://who.int/icd#definition [bioportal_definitionProperty]', 7.8, 10.0, 6.765, 6.765, NULL, NULL, NULL, 33390, 4851, 1596, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T22:57:27+00:00', '2026-09-23T23:25:10+00:00');
