INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ICW', 'International Classification of Wellness', 'The International Classification of Wellness (ICW) is Wellness taxonomy. ICW provides a scheme for classifying Wellness events (activities) in which persons (users) can participate. ICW furthers the goals of preventative medicine and population health by supporting goal setting, quantifying user engagement in wellness activities, and correlating user engagement in wellness activities with health outcomes.', 'Health;Taxonomic_Classification', 'OWL', 5, '1.3', '2025-08-29T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ICW', 'fbea349589384c1252ad44065015b8a6f843f9bb900af8c02bb873543c20319c', 'scored', NULL, 10.0, 0.04, 0.04, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 5.01, 5.01, NULL, NULL, NULL, 561, 104, 104, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:27+00:00', '2026-09-23T23:25:10+00:00');
