INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'IDEM', 'IDEM: wInD Energy Models Taxonomy', 'Controlled vocabularies such as taxonomies allow an accurate and controlled approach in describing datasets. One of such controlled vocabulary is Wind Energy Taxonomy of Models. This taxonomy is the result of EERA JP WIND IRPWind Open Data initiative that took place in 2017 in which wind energy experts generated the first version of the taxonomy as an input for defining and structuring wind energy metadata.

The report of this work is available at Zenodo: https://www.zenodo.org/record/1199489#.XSD6haeQ3RY

In 2018, the taxonomy of topics was improved during the internal project of DTU Wind Energy titled ''FAIR Digitalization'': https://www.zenodo.org/record/1493874#.XSD7TaeQ3RY

In 2021, the taxonomy was converted into FAIR machine-actionable controlled vocabulary using sheet2rdf. The controlled vocabulary is served to humans and machines using an instace of OntoStack hosted by DTU Wind Energy. sheet2rdf and OntoStack are developed by FAIR Data Collective.

Additionally, in 2021, the persistent URL purl.org/idem has been registered for the taxonomy. This allows us to:

If there is a needed to move the taxonomy to another domain (currently under data.windenergy.dtu.dk) URLs will be still resolvable and unchanged
Use short URls as PIDs for the taxonomy terms and properties.', '', 'SKOS', 2, 'v0.1.0', '2021-10-05T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/IDEM', '923130c7a2fe7531aae75173e2011321eb6995b499241b274662eecdd090a5c3', 'scored', NULL, 9.76, 0.14, 0.14, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.475, 2.475, NULL, NULL, NULL, 256, 41, 41, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:02+00:00', '2026-09-23T23:25:10+00:00');
