INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'IDO', 'Infectious Disease Ontology', 'The IDO ontologies are designed as a set of interoperable ontologies that will together provide coverage of the infectious disease domain. At the core of the set is a general Infectious Disease Ontology (IDO-Core) of entities relevant to both biomedical and clinical aspects of most infectious diseases. Sub-domain specific extensions of IDO-Core complete the set providing ontology coverage of entities relevant to specific pathogens or diseases. 

<br><br>
To import,<br>
Latest version: <a href="http://purl.obolibrary.org/obo/ido.owl">http://purl.obolibrary.org/obo/ido.owl</a><br>
This version (2010-12-02): <a href="http://purl.obolibrary.org/obo/ido/2010-12-02/ido.owl">http://purl.obolibrary.org/obo/ido/2010-12-02/ido.owl</a><br>
Previous  versions:<br>
2010-05-26 <a href="http://purl.obolibrary.org/obo/ido/2010-05-26/ido.owl">http://purl.obolibrary.org/obo/ido/2010-05-26/ido.owl</a><br>
2009-08-14 <a href="http://purl.obolibrary.org/obo/ido/2009-08-14/ido.owl">http://purl.obolibrary.org/obo/ido/2009-08-14/ido.owl</a><br>
<br>
<br>
Latest release notes at <a href="http://infectiousdiseaseontology.org/page/Download">http://infectiousdiseaseontology.org/page/Download</a><br>

Please note: The ontology metrics displayed by BioPortal do not distinguish IDO-developed terms from terms imported from other ontologies.', 'All_Organisms;Health', 'OWL', 13, '8-3-20', '2017-11-03T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/IDO', 'e372e7ef13e02edd915af4d8501916274a05fd0a847378d008576124d5a5f3fc', 'scored', NULL, 10.0, 6.05, 6.05, 'same_as_strict (1.0 result, not re-checked)', 3.14, 10.0, 7.2975, 7.2975, NULL, NULL, NULL, 6761, 364, 362, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:35+00:00', '2026-09-23T23:25:10+00:00');
