INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'IFAR', 'Fanconi Anemia Ontology', 'An application ontology devoted to the standardized recording of data related to Fanconi Anemia (FA). This ontology was created using an OWL file provided by Dr. Ada Hamish (and Francois Schiettecatte) at the Centers for Mendelian Genetics, with their permission. Their original ontology can be found at: http://phenodb.net/help/features. Modifications were made using HPO, OMIM, NCI, and SNOMED. Novel classes pertaining to FA were added and defined as appropriate. ', 'Other', 'OWL', 5, '3', '2013-06-26T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/IFAR', 'f56f921e53f1fa53391ada2159f9cf02840030763c627345542d5fc03da0e6f9', 'scored', NULL, 10.0, 6.43, 6.43, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 6.6075, 6.6075, NULL, NULL, NULL, 24082, 4531, 4531, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:12:27+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ILLNESSINJURY', 'Illness and Injury', 'This list of Illness and Injury (Morbidity and Mortality) classifications is an abbreviated version of the World Health Organization''s (WHO) Startup Mortality List (ICD-10-SMoL).  ICD-10-SMoL is the WHO''s application of ICD-10 for low-resource settings initial cause of death collection.

ICD-10-SMoL was chosen because it is a simplified version of the ICD-10.
ICD (International Classification of Diseases) "is the foundation for the identification of health trends and statistics globally, and the international standard for reporting diseases and health conditions. It is the diagnostic classification standard for all clinical and research purposes. ICD defines the universe of diseases, disorders, injuries and other related health conditions" [http://www.who.int/classifications/icd/en/].

Version 1.0 of this ontology was compiled for the Canadian Writing Research Collaboratory (CWRC) ontology project and reflects the need to have causes of death and health issues organized in a way to allow for analysis of cultural data.  A simplified list was deemed sufficient since the domain under study (cultural documents) will not have detailed medical information with regards to cause of death or health issues.  But instead of accepting a list of general usage terms for causes of death or health issues that appear in some sources (e.g. Wikipedia, Wikidatak, etc.), a standardized, medical classification was selected so that it could be of use for future analysis regarding questions involving the intersection of health and culture.

ICD-10-SMoL was chosen since it was the latest version of this list (June, 2018).  A stable version of ICD-11 was to be available in June 2018 but there was no ICD-11-SMoL available at this time.

To obtain the ICD10-SMoL:
http://www.who.int/healthinfo/civil_registration/ICD_10_SMoL.pdf?ua=1', 'Health;Human;Taxonomic_Classification', 'OWL', 1, '1.0.2', '2018-07-22T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ILLNESSINJURY', '7fc0a4c81100f119eecdc5edfe9a350801fa23f4fdf1b66a0826145d831551e8', 'scored', NULL, 2.91, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 7.0, 2.4775, 2.4775, NULL, NULL, NULL, 653, 148, 22, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:55+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'IMGT-ONTOLOGY', 'Immunogenetics Ontology', 'IMGT-ONTOLOGY is the first ontology for immunogenetics and immunoinformatics. It provides a semantic specification of the terms to be used in immunogenetics and immunoinformatics and manages the related knowledge, thus allowing the standardization for immunogenetics data from genome, proteome, genetics, two-dimensional (2D) and three-dimensional (3D) structures.  
IMGT-ONTOLOGY manages the knowledge through diverse facets relying on seven axioms, "IDENTIFICATION", "CLASSIFICATION", "DESCRIPTION", "NUMEROTATION", "LOCALIZATION", "ORIENTATION" and "OBTENTION". These axioms postulate that any object, any process and any relation can be identified, classified, described, numbered, localized and orientated, and the way it is obtained can be characterized. The axioms constitute the Formal IMGT-ONTOLOGY, also designated as IMGT-Kaleidoscope. As the same axioms can be used to generate concepts for multi-scale level approaches, the Formal IMGT-ONTOLOGY represents a paradigm for system biology ontologies, which need to identify, to classify, to describe, to number, to localize and to orientate objects, processes and relations at the molecule, cell, tissue, organ, organism or population levels.
IMGT®, the international ImMunoGeneTics information system®, has been built on IMGT-ONTOLOGY.

The version 1.0.3 of IMGT-ONTOLOGY includes the concepts of IDENTIFICATION and an update of the concepts of CLASSIFICATION.', 'Immunology', 'OWL', 5, '1.0.3', '2019-07-22T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/IMGT-ONTOLOGY', '9d5bb0de996fcccdcf38eaeed57322ba9f3b7844f7ce72deb191f8b8006a41ac', 'scored', NULL, 10.0, 7.12, 7.12, 'same_as_strict (1.0 result, not re-checked)', 4.06, 10.0, 7.795, 7.795, NULL, NULL, NULL, 30867, 1429, 1429, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:12:47+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'IMOBO', 'Intelligent Medicine oriented Biobank Ontology', 'Intelligent Medicine oriented Biobank Ontology (IMOBO) is an ontology developed to facilitate the annotation and modeling of biobank repositories, metadata, and biobanking administration, supporting the paradigm shift towards AI in medicine. IMOBO focuses on AI modeling in both clinical applications and healthcare, with a specific emphasis on engaging clinical doctors and patients in data collection. Its goal is to structure knowledge for the future patient-centered medical paradigm. As measurement technologies and medical artificial intelligence continue to evolve, IMOBO will continually enhance its content and structure.', 'Biomedical_Resources;Human', 'OWL', 1, '0.1', '2024-06-04T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/IMOBO', '33e766724a382cf4c03bebb34a4a860a1f5c9f66feaf5371c55ae2f74516cf34', 'scored', NULL, 9.9, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 9.0, 4.725, 4.725, NULL, NULL, NULL, 307, 103, 103, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:10+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'INBANCIDO', 'Assessment of Indian Economy During Covid-19 ', 'InBan-CIDO ontology is an extension of the CIDO ontology to show the impact of Covid-19 on the Indian economy sector.', '', 'OWL', 1, '1.0.214', '2021-07-05T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/INBANCIDO', 'a43dad7046a97de38764273325fa27fb05ac986f7673f4d0b16c603340ec14af', 'scored', NULL, 10.0, 3.37, 3.37, 'same_as_strict (1.0 result, not re-checked)', 8.25, 10.0, 7.905, 7.905, NULL, NULL, NULL, 150874, 7866, 7834, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:22:53+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'INBIO', 'Invasion Biology Ontology', 'The Invasion Biology Ontology (INBIO) contains terms and concepts relevant in the field of invasion biology, which is a research area dealing with the translocation, establishment, spread, impact and management of species outside of their native ranges, where they are called non-native or alien species. This first version of the ontology covers terms and concepts needed to describe twelve major invasion hypotheses building the hierarchical hypothesis network (see also Jeschke JM, Heger T (Eds) (2018) Invasion Biology: Hypotheses and Evidence. CABI, Wallingford, UK).', '', 'OWL', 3, '1.2', '2025-02-14T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/INBIO', 'd114683beb01a8a173bb2b4ccd937db25fdca20ce769a7d6660b0db3f24674cd', 'scored', NULL, 10.0, 4.96, 4.96, 'same_as_strict (1.0 result, not re-checked)', 3.17, 9.0, 6.7825, 6.7825, NULL, NULL, NULL, 8140, 495, 495, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:50+00:00', '2026-09-23T23:25:10+00:00');
