INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'INO', 'Interaction Network Ontology', 'The Interaction Network Ontology (INO) is an ontology in the domain of interactions and interaction networks. INO represents general and species-neutral types of interactions and interaction networks, and their related elements and relations. INO is a community-driven ontology, aligns with BFO, and is developed by following the OBO Foundry principles.', 'All_Organisms;Biological_Process', 'OWL', 34, '1.1.13', '2022-03-27T18:06:10.000-07:00', 'https://bioportal.bioontology.org/ontologies/INO', 'd730aec4a8e64baf134292fdd1fb9afe1b8bb832050c20d5926511e8ecedd592', 'scored', NULL, 9.97, 5.76, 5.76, 'same_as_strict (1.0 result, not re-checked)', 0.71, 10.0, 6.61, 6.61, NULL, NULL, NULL, 4360, 329, 329, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:06+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'INSECTH', 'insectH', 'NeuroMorpho.Org insect brain regions ontology is compiled to create data annotation standard for depositing insect data. Currently at v6.2, NeuroMorpho.Org hosts over 17k neuronal reconstructions mostly from the fly. The insect ontology follows the standard nomenclature of the insect brain (Ito et al., 2013) and the virtualfly.org.  ', 'Anatomy', 'OWL', 7, '0.1', '2019-11-22T18:07:08.000-08:00', 'https://bioportal.bioontology.org/ontologies/INSECTH', '959e4ac2cb1380f96335d2d913c1cb39d13f00ed2bf789785d992d7d88a89059', 'scored', NULL, 8.2, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 4.55, 4.55, NULL, NULL, NULL, 1018, 334, 163, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:05:15+00:00', '2026-09-23T23:25:10+00:00');
