INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'IOBC', 'Interlinking Ontology for Biological Concepts', 'Interlinking Ontology for Biological Concepts (IOBC) contains approximately 80,000 biological concepts such as biological phenomena, diseases, molecular functions, gene products, chemicals, and medical cares, and approximately 20,000 related concepts such as earth science and environmental science.  The concepts are structured by thirty-five relations such as has function, has role, has quality, and precedes. Each concept has both of English and Japanese labels. For further information including the developmental method, see papers in the PUBLICATIONS PAGE.

The license for this ontology is specified in the Creative Commons Attribution-NonCommercial 4.0 International. If you use data from this ontology, please be sure attribute this ontology as follows: "Interlinking Ontology for Biological Concepts © National Bioscience Database Center licensed under CC Attribution-NonCommercial 4.0 International".', '', 'OWL', 25, 'version 1.6.0', '2021-09-25T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/IOBC', '8ec6b9c5f8fb13d0d7d3145c4734a04b5c327d8f7e920f04d74fa0333514c93e', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 4.22, 10.0, 6.055, 6.055, NULL, NULL, NULL, 1962483, 126847, 126847, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T07:13:09+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'IPD', 'injury process description ontology', 'IPD-Onto divides product injury  into five unified classes (host, vector, agent, environment, and consequences) and constructs the accident process through the object properties (lead to, touch, accident, etc.)IPD-Onto is used to realise the transformation and reorganisation from product injury to injury information, to reproduce the process of accident occurrence, and realise human-computer interactions to meet the needs of data query.', '', 'OWL', 2, '1.0', '2023-01-22T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/IPD', '9aaf6995cc821a114f4e0d36a065ec71add810510ac56c066051c8aab22588c8', 'scored', NULL, 8.57, 3.17, 3.17, 'same_as_strict (1.0 result, not re-checked)', 3.2, 8.0, 5.735, 5.735, NULL, NULL, NULL, 294, 14, 9, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:14+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'IRAEO', 'Immune-Related Adverse Event Ontology', 'irAEO (Immune-Related Adverse Event Ontology)
irAEO is a biomedical ontology that standardizes the representation of immune-related adverse events (irAEs) following cancer immunotherapy, especially immune checkpoint inhibitor (ICI) treatment. It defines core concepts for irAE phenotypes, organ involvement, severity grading, immune mechanisms, and clinical management.', 'Biomedical_Resources', 'OWL', 1, NULL, '2026-05-04T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/IRAEO', 'f5425ff761e0961214c51fdcfdaa5b864830005144a98f100ac0f1111f9417e9', 'scored', NULL, 9.99, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 4.12, 10.0, 6.0275, 6.0275, NULL, NULL, NULL, 14789, 863, 863, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:09:14+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'IRD', 'Inherited Retinal Dystrophies', 'Inherited retinal dystrophy (IRD) as one of the rare ocular diseases encompasses different types of hereditary retinal degenerations appearing by involvement of the different layers of the posterior ocular segment. In respect of the importance of the classification systems regarding the recorded history of biologic and natural sciences, there is no classification regarding the IRD diagnoses. Therefore, a novel classification for this type of hereditary ocular disease was developed and presented.  ', '', 'OWL', 1, NULL, '2019-10-21T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/IRD', '6bdf034be00c1e3c6e132a32b8626f43a57eb72078892cbdec72c5d2543e557b', 'scored', NULL, 9.94, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 4.985, 4.985, NULL, NULL, NULL, 4333, 542, 542, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:06:25+00:00', '2026-09-23T23:25:10+00:00');
