INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ISO-FOOD', 'A formal representation of the knowledge within the domain of Isotopes for Food Science', 'To link and harmonize different knowledge repositories with respect to isotopic data, we propose an ISO-FOOD ontology as a domain ontology for describing isotopic data within Food Science. The ISO-FOOD ontology consists of metadata and provenance data that needs to be stored together with data elements in order to describe isotopic measurements with all necessary information required for future analysis. The new domain has been linked with existing ontologies, such as Units of Measurements Ontology, Food, Nutrient and the Bibliographic Ontology. So linked ontology consists of several superclasses, and for each of these the relevant subclasses, object properties and data properties are defined. To show how such an ontology can be used in practice, it was populated with 20 isotopic measurements of Slovenian food samples. Describing data in this way offers a powerful technique for organizing and sharing stable isotope data across Food Science. ', 'Chemical', 'OWL', 1, NULL, '2018-10-22T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ISO-FOOD', 'f6f4698c1b1542a06cdb0c7b586b522eb109811ac8fff9de3870663e902c696d', 'scored', NULL, 9.24, 1.86, 1.86, 'same_as_strict (1.0 result, not re-checked)', 2.45, 10.0, 5.8875, 5.8875, NULL, NULL, NULL, 10678, 1445, 1323, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:09+00:00', '2026-09-23T23:25:10+00:00');
