INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ISO639-1', 'ISO 639-1: Codes for the Representation of Names of Languages - Part 1: Two-letter codes for languages', 'Language codes from ISO 639-1, as expressed in https://www.w3schools.com/tags/ref_language_codes.asp and converted to SKOS using http://labs.sparna.fr/skos-play/convert. ', 'Vocabularies', 'SKOS', 1, '1.0.0', '2020-10-19T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ISO639-1', '655bd6147ac502baf45ce73518a85cb36b12fd3c91f31c77614ccf87f68b9123', 'scored', NULL, 9.95, 5.8, 5.8, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 3.9375, 3.9375, NULL, NULL, NULL, 1356, 193, 192, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:20+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ISO639-2', 'ISO 639-2: Codes for the Representation of Names of Languages', 'ISO 639-2 is part of the ISO 639 language code family, which provides also a two-character code set (ISO 639-1) for the representation of names of languages. ISO 639-2 contains codes for all languages contained in ISO 639-1 and several hundred additional languages. The ISO 639-2 (Bibliographic) codes were devised for use in bibliographic metadata, e.g., for libraries, information services, and publishers, and ISO 639-2 (Terminology) targets terminology, lexicography, and linguistic applications. The lists are the same except for 20 languages that have different Bibliographic and Terminology codes. The list contains over 500 discrete codes.', 'Other', 'OWL', 3, NULL, '2017-12-01T19:04:52.000-08:00', 'https://bioportal.bioontology.org/ontologies/ISO639-2', '6d8c14fa20c0ffc270768193c1ba525d07de51e82ac01f7987b50769107425d5', 'scored', NULL, 0.01, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 9.06, 8.0, 4.2675, 4.2675, NULL, NULL, NULL, 113137, 15537, 11, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:20:54+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ISPO', 'Integrated Ontology for Symptom Phenotype Terminologies', 'ISPO delivers an integrated controlled vocabulary for symptom phenotypes, with both clinical and biomedical literature synonyms in Chinese and English languages, it would enhance the semantic interoperability among heterogeneous medical data sources and clinical decision support systems. Furthermore, symptom ontology would propose a standard vocabulary for teasing the symptom-gene associations and thus become a vital requirement for symptom science and TCM biological discovery.', 'Health', 'OWL', 1, '2023V1', '2023-01-10T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ISPO', '1fde37f3a5aa0d379f0ea9c34cb8e904e934564a979ab7617daaf1769b660a49', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 5.0, 5.0, NULL, NULL, NULL, 43948, 3149, 3149, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:13:03+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ISSVA', 'International Society for the Study of Vascular Anomalies (ISSVA) Ontology', 'The International Society for the Study of Vascular Anomalies (ISSVA) is a multidisciplinary international society of physicians, scientists, and health care providers united by an interest in vascular anomalies. The Society aims to promote the highest standards of care for patients with vascular anomalies by advancing clinical and scientific knowledge concerning causes, diagnosis and treatment, and by education of physicians, health care providers, patients and the community. The Society encourages the free flow of information between its members and interested groups, through workshop meetings and teaching programs, and by the dissemination of a classification scheme and pertinent scientific data.

The updated classification was approved at the May, 2018 General Assembly in Amsterdam, the Netherlands and can be found at https://www.issva.org/classification.

What is the ISSVA Ontology?

The ISSVA ontology has been created to represent a sharable semantic data model of the ISSVA classification. This ontological representation of the ISSVA classification is machine-readable and facilitates interoperability between systems that capture data about vascular anomalies. It is structured hierarchically and contains all concepts of the ISSVA classification and the relationships between them. The ontology is available in the Web Ontology Language (OWL) format, and can be browsed and downloaded online: https://bioportal.bioontology.org/ontologies/ISSVA

How to Use the ISSVA Ontology?

The ISSVA ontology does not substitute the ISSVA classification, instead, it should be used as an additional component to facilitate interoperability. Every concept in the ISSVA ontology has a unique code that should be attached to the corresponding data element. In the context of databases, the ISSVA ontology codes could be added as an extra column to the existing data. 

Mappings to Other Ontologies?

The ISSVA ontology contains machine-readable mappings to equivalent concepts i', 'Health', 'OWL', 5, '1.1.3', '2021-02-19T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ISSVA', '59a8d488df7dcb3486cf53f43445b258bd4c6bc99ad9e02a45886700d5352c7c', 'scored', NULL, 10.0, 0.85, 0.85, 'same_as_strict (1.0 result, not re-checked)', 1.14, 10.0, 5.4975, 5.4975, NULL, NULL, NULL, 1513, 199, 194, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:30+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ITEMAS', 'Medical Technology Innovation in healthcare centers', 'The defined ontology is focused on  addressing medical innovation technology in public healthcare institutions. This ontology is currently only in Spanish language. It has been developed the Platform for Innovation Medical and Health Technology (ITEMAS) a network composed by 67 Spanish healthcare organizations (including hospitals, healthcare centers, Ministry of Health, Social Services and Equality and more than 100 organizations focused on medical technology innovation. The ITEMAS Platform  has been by Carlos III National Health Institute (PT13/0006/0036), both co-funded by FEDER from European Regional Development Funds (European Union).', 'Other', 'OWL', 1, '3.0', '2017-11-16T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ITEMAS', '6c5e34bc22209ce6fff7f31fdf8304834ed6b331c3e2d54e8eda21634aa12717', 'scored', NULL, 9.5, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 6.97, 10.0, 6.6175, 6.6175, NULL, NULL, NULL, 2178, 141, 134, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:06:01+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ITO', 'Intelligence Task Ontology', 'The Intelligence Task Ontology and Knowledge Graph (ITO) provides a comprehensive, curated model of artificial intelligence tasks, benchmarks and benchmark results, including the biomedical domain.

NOTE: The version uploaded to BioPortal has all instances and benchmark data removed because of performance issues with the BioPortal class browser. Please refer to https://github.com/OpenBioLink/ITO/ for downloading the full version of the ontology and dataset.', 'Other', 'OWL', 17, '1.12 (PWC export dated 2022-07-30) - internal, just a minor fix', '2022-09-09T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ITO', '32afdae331ce2e861c3789ac49a36b5f47dd67f6560c4b1464f68174c80e55a4', 'scored', NULL, 10.0, 0.45, 0.45, 'same_as_strict (1.0 result, not re-checked)', 0.07, 10.0, 5.13, 5.13, NULL, NULL, NULL, 464792, 53528, 16283, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:41:03+00:00', '2026-09-23T23:25:10+00:00');
