INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'JERM', 'Just Enough Results Model Ontology', 'The JERM ontology is an application ontology that describes the relationships between the data, models and other research assets that can be shared through the FAIRDOM platform, for sharing Systems and Synthetic Biology experiments. JERM 2 includes a new model for describing Biosamples, developed during the ELIXIR-lead Biosamples club', 'Biological_Process;Biomedical_Resources;Experimental_Conditions;Other', 'OWL', 15, '2', '2017-09-26T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/JERM', 'f7d042e1b8e6b0ab5ca6a706bbb196d75c0a9798af0710ae3b9742ef6cc0852a', 'scored', NULL, 10.0, 0.32, 1.6, 'http://purl.org/dc/elements/1.1/description [bioportal_definitionProperty]', 0.97, 10.0, 5.3225, 5.6425, NULL, NULL, NULL, 2059, 295, 295, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T22:57:06+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'JFO', 'Japanese Food Ontology', 'JFO v0.57 - FoodAtlasEntity moved under BFO:0000020 (not top-level), The Japanese Food Ontology (JFO) is a comprehensive ontology of Japanese foods that integrates FGNHNS (National Health and Nutrition Survey) food groups, the Standard Tables of Food Composition in Japan (foodcomp), FoodOn cross-references, MeSH/OMOP medical terminologies, allergen data, microbiome literature, and UECFOOD256 image dataset categories. Version 0.60 adds WorldCuisine branch for non-Japanese foods., allergen data (including hasExposure, hasAllergyEvidence, allergyMechanism, allergySite, cross-reactivity mapping with PFAS/latex/LTP), microbiome literature (Prevotella, etc.), and UECFOOD256 image dataset categories. Version 0.70 adds 29 specific allergen individuals with exposure routes, mechanism/site annotations, literature evidence (PMID), and cross-reactivity relationships (pollen-food, latex-fruit, LTP, α-Gal).', 'Development;Health', 'OWL', 71, '0.90', '2026-07-06T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/JFO', 'a14d749d4770a88d31a465d3a55739f54cc10cae590ae86759a9d684218186cc', 'scored', NULL, 10.0, 0.02, 0.02, 'same_as_strict', 2.96, 10.0, 5.745, 5.745, NULL, NULL, NULL, 309086, 6662, 6583, '0.10.0', 'core4-1.1', 'cuda', '2026-09-23T22:00:13+00:00', '2026-09-23T23:25:10+00:00');
