INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'KISAO', 'Kinetic Simulation Algorithm Ontology', 'The Kinetic Simulation Algorithm Ontology (KiSAO) is an ontology of algorithms for simulating and analyzing biological models, as well as the characteristics of these algorithms, their input parameters, and their outputs. In addition, KiSAO captures relationships among algorithms, their parameters, and their outputs.', 'Other', 'OWL', 64, '2.34', '2026-06-02T18:09:29.000-07:00', 'https://bioportal.bioontology.org/ontologies/KISAO', '2f6cb5aebac414af2edce7c1f539d168392da5dc7c41add33da4b62e3a8d1cbb', 'scored', NULL, 10.0, 6.16, 6.16, 'same_as_strict (1.0 result, not re-checked)', 6.75, 10.0, 8.2275, 8.2275, NULL, NULL, NULL, 12030, 526, 526, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:53+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'KOIO', 'Knowledge Object Implementation Ontology', 'KOIO is a domain ontology that tells us what a Knowledge Object is as an artifact. It describes Knowledge Objects and their parts as they are implemented. For this reason, KOIO generally serves as an evolving formal and explicit model of Knowledge Objects. It can be used to describe the parts of many computable biomedical knowledge (CBK) artifacts found in the wild. In addition, KOIO functions as a formal specification for linked metadata relevant for describing, annotating, packaging, and handling CBK artifacts.

KOIO is a smaller, more readily usable ontology originally derived from the Knowledge Objects Reference Ontology, KORO.', 'Other;Upper_Level_Ontology;Vocabularies', 'OWL', 1, '2.1', '2025-02-19T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/KOIO', '9d36f77c34e3a66d481d0cd3a91b9b13b591840e927a2ae0c328dc5dcd397c12', 'scored', NULL, 10.0, 5.44, 5.44, 'same_as_strict (1.0 result, not re-checked)', 3.39, 10.0, 7.2075, 7.2075, NULL, NULL, NULL, 39694, 2653, 2191, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:12:55+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'KORO', 'Knowledge Object Reference Ontology', 'An ontology to define the parts of a Knowledge Object and their relations built using the Basic Formal Ontology and Information Artifact Ontology', 'Biomedical_Resources', 'OWL', 6, '1.3', '2018-02-12T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/KORO', '9d275b6975946035f62946552539d39e4916564b241b652587ead18b527a26df', 'scored', NULL, 10.0, 6.01, 6.01, 'same_as_strict (1.0 result, not re-checked)', 2.75, 9.0, 6.94, 6.94, NULL, NULL, NULL, 1210, 124, 110, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:26+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'KTAO', 'Kidney Tissue Atlas Ontology', 'The Kidney Tissue Atlas Ontology (KTAO) is an ontology that integrates kidney-related cell types, cell states, locations, gene markers, disease, etc., and their relations. KTAO is 
developed to support the NIH-NIDDK-funed Kidney Precision Medicine Project (KPMP). ', 'Anatomy;Biological_Process;Biomedical_Resources;Cell;Cellular_anatomy_;Development;Dysfunction;Gene_Product;Genomic_and_Proteomic;Health;Human;Human_Developmental_Anatomy;Molecule;Phenotype;Subcellular;Subcellular_anatomy', 'OWL', 20, 'Vision Release: 1.0.121', '2024-03-16T18:07:22.000-07:00', 'https://bioportal.bioontology.org/ontologies/KTAO', 'e79331ce5046a16d5e6c49d14b5f7fa07c6b0df3e34c76c9ab3ab9fe548e3fce', 'scored', NULL, 10.0, 4.42, 4.42, 'same_as_strict (1.0 result, not re-checked)', 8.33, 10.0, 8.1875, 8.1875, NULL, NULL, NULL, 251823, 11235, 11211, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:27:59+00:00', '2026-09-23T23:25:10+00:00');
