INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'LCDGT', 'Library of Congress Demographic Group Terms', 'The Library of Congress Demographic Group Terms (LCDGT) is designed to describe the characteristics of the intended audiences of resources, and also the creators of, and contributors to, those resources.', '', 'SKOS', 2, NULL, '2018-01-01T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/LCDGT', '708bc2318a012ed972ed9a9581c23b0170c5b336ac6cdca0b1d75222c4d9e87b', 'scored', NULL, 9.0, 0.71, 0.71, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.4275, 2.4275, NULL, NULL, NULL, 62, 10, 5, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:03:38+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'LCGFT', 'Library of Congress Genre/Form Thesaurus for Library and Archival Materials', 'The Library of Congress Genre/Form Terms for Library and Archival Materials (LCGFT) is a thesaurus that describes what a work is versus what it is about. For instance, the subject heading Horror films, with appropriate subdivisions, would be assigned to a book about horror films. A cataloger assigning headings to the movie The Texas Chainsaw Massacre would also use Horror films, but it would be a genre/form term since the movie is a horror film, not a movie about horror films. The thesaurus combines both genres and forms. Form is defined as a characteristic of works with a particular format and/or purpose. A "short" is a particular form, for example, as is "animation." Genre refers to categories of works that are characterized by similar plots, themes, settings, situations, and characters. Examples of genres are westerns and thrillers. In the term Horror films"horror" is the genre and "films" is the form.', 'Other', 'SKOS', 3, '2017-09-05', '2017-09-05T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/LCGFT', 'c278cdb30d4719556f96c38ac5509a34da552bdded37012b0baacc99010ecbf1', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.5, 2.5, NULL, NULL, NULL, 609717, 39927, 13, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:43:17+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'LDA', 'Ontology of Language Disorder in Autism', 'We present the short review of language terms used in the domain of autism and populate them into ontology available for consultation and sharing. The language terms were obtained via text mining and automatic retrieval of terms from the corpus of PubMed abstracts.', 'Health', 'OWL', 1, '12-15-2008', '2008-12-15T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/LDA', 'a811cdbd71ee0b18dbeff47c53dba7a330bdb2c0f7dab9bed0ad8a262e96b58c', 'scored', NULL, 9.73, 6.66, 6.66, 'same_as_strict (1.0 result, not re-checked)', 0.0, 8.0, 6.0975, 6.0975, NULL, NULL, NULL, 299, 37, 37, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:47+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'LDBASE', 'LDbase', 'LDbase is an NIH-funded behavioral research data repository. The LDbase taxonomy includes project descriptors for projects in the fields of educational and developmental sciences. Developed as a collaboration between researchers and librarians, this first-of-its-kind project-oriented data repository contains decades of knowledge and includes data on individuals across the full range of abilities. The LDbase ontology is used to describe research projects in the developmental sciences. ', 'Development;Human;Other', 'SKOS', 2, '0.0.1', '2024-02-27T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/LDBASE', '438c76bee0c3e4eed91b0c494a966dfa1ffc682f46cc049b049225c8758c0e9d', 'scored', NULL, 9.98, 0.02, 0.02, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.5, 2.5, NULL, NULL, NULL, 4497, 639, 638, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:35+00:00', '2026-09-23T23:25:10+00:00');
