INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'LEO', 'Living Environment Ontology', 'The Living Environment Ontology (LEO) is a structured framework designed to classify and standardize concepts related to human living conditions. It integrates keywords and concepts from diverse sources, such as questionnaires, references, and abstracts, to create a comprehensive ontology for assessing human living environments.', 'Health;Human', 'OWL', 1, '1.0', '2024-12-05T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/LEO', 'accf9ccd4ce0b86dfef66ba5bd4c5fca4ccf675d5c77aeb7310f5a821a535619', 'scored', NULL, 9.91, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 4.9775, 4.9775, NULL, NULL, NULL, 1660, 235, 235, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:05:33+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'LEPAO', 'Lepidoptera Anatomy Ontology', 'The Lepidoptera Anatomy Ontology contains terms used for describing the anatomy and phenotype of moths and butterflies in biodiversity research. LEPAO is developed in part by BIOfid (The Specialised Information Service Biodiversity Research).', 'Other', 'OWL', 2, '2023-02-18', '2023-02-19T18:09:34.000-08:00', 'https://bioportal.bioontology.org/ontologies/LEPAO', '233806cd544d4dadce46abb393bc7c6e27eb6fa008803cb0874a4040bf4675af', 'scored', NULL, 9.99, 5.24, 5.24, 'same_as_strict (1.0 result, not re-checked)', 7.94, 10.0, 8.2925, 8.2925, NULL, NULL, NULL, 34692, 823, 823, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:11:42+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'LHN', 'Loggerhead Nesting Ontology', 'A demonstration of ontology construction as a general technique for coding ethograms and other descriptions of behavior into machine understandable forms. An ontology for Loggerhead sea turtle (<i>Caretta caretta</i>) nesting behavior, based on the published ethogram of Hailman and Elowson.', '', 'OWL', 4, NULL, '2013-05-10T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/LHN', '1fed4404e197d0d516147946e45bc74d6353f0fecdf78810a68750b53bffa4b4', 'scored', NULL, 9.97, 4.4, 4.4, 'same_as_strict (1.0 result, not re-checked)', 5.38, 9.0, 7.1875, 7.1875, NULL, NULL, NULL, 3343, 309, 309, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:33+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'LHO', 'LivestockHealthOntology', 'The Livestock Health Ontology (LHO) extends the DECIDE ontology specifically designed for salmon usecase. LHO contains information on the health and well-being of livestock animal species such as cattle, pigs, and poultry. Furthermore, it represents the explicit structured and standardized framework for specific domain knowledge and data integration of livestock species. During the development process, knowledge can be retrieved from domain experts, and after the retrieving process, the prototype is designed for reasoning and planning of data related to cattle, pigs, and poultry. Moreover, LHO contains information regarding farms Identifications, their samples, geolocation, breed, diagnostic tests, Pathogen identifications, and Pathogen results for specific bacteria such as Histophilus Somni (HS), Mannheimia Haemolytica (MH), Pasteurella Multocida (PM), Bovine Coronavirus (BCV) bacterial mycoplasma and aerobic culture results for the respiratory diseases in cattle. This information is represented as concepts of classes, subclasses, and their relationship in the form of object and data properties.
For pigs, it includes FarmType, age, weight, and pathogens like PRRS, SwineInfluenza, and M_Hyponemoniea. In poultry, LHO incorporates FarmType, with specific pathogen names such as Infectious Bronchitis (IB), providing a concise overview of health aspects across livestock species.
), Salmon case study demonstrates the semantic modeling and integration of aquaculture-specific attributes such as hasMortality, hasActualBiomass, hasWaterType, and hasLocalAuthority. The data supports epidemiological analysis of fish health by mapping samples and measurements to environmental and production factors.', 'All_Organisms;Animal_Development;Biomedical_Resources;Health;Taxonomic_Classification;Vocabularies', 'OWL', 9, 'V1.4', '2025-12-19T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/LHO', '64241de89c667e6004ffafd7a1abddbeedf0a55894f0f87c7f1a7d0a10ea8455', 'scored', NULL, 9.96, 6.14, 6.14, 'same_as_strict (1.0 result, not re-checked)', 4.91, 9.0, 7.5025, 7.5025, NULL, NULL, NULL, 1647, 234, 105, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:41+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'LIB', 'MWS-WSM', NULL, '', NULL, -1, NULL, NULL, 'https://bioportal.bioontology.org/ontologies/LIB', NULL, 'no_submission', 'latest_submission http=200 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-23T23:25:10+00:00');
