INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'LICO', 'Liver Case Ontology (LiCO)', 'Liver Case Ontology (LiCO) is a case-centric ontology for liver patient cases called lico (Liver Case Ontology) that integrates several ontologies and lexicons developed for sub-disciplines of medicine such as RadLex (Radiology Lexicon), SNOMED CT (Systematized Nomenclature of Medicine, Clinical Terms), LOINC (The Logical Observation Identifier Names and Codes). It is an extension of ONLIRA (Ontology of the Liver for Radiology) that represents the liver and lesions from a radiological perspective.', 'Health', 'OWL', 2, 'changes
* Segments and Regions are modelling as Classes in order to identify which patient (liver) they belong to.
* Redundant restrictions are removed
', '2018-08-31T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/LICO', '39992976222a1d38ee494fa961d76b5a7808da651e1e948110eaafb7502a71df', 'scored', NULL, 9.89, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 2.05, 10.0, 5.485, 5.485, NULL, NULL, NULL, 2036, 93, 93, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:05:56+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'LIFO', 'Life Ontology', 'The Life Ontology (LifO) is an ontology of the life of organism. LifO represents the life processes of organisms and related entities and relations. LifO is a general purpose ontology that covers the common features associated with different organisms such as unicellular prokaryotes (e.g., E. coli) and multicellular organisms (e.g., human).', 'All_Organisms', 'OWL', 1, 'Vision Release: 1.0.17', '2018-03-11T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/LIFO', 'b4756e47e534cd62ac834bb2f079d21cb15a7936a39491ab19e1ad0580111e45', 'scored', NULL, 10.0, 5.71, 5.71, 'same_as_strict (1.0 result, not re-checked)', 2.38, 9.0, 6.7725, 6.7725, NULL, NULL, NULL, 4621, 224, 215, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T03:26:21+00:00', '2026-09-23T23:25:10+00:00');
