INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'LIPRO', 'Lipid Ontology', 'Lipid research is increasingly integrated within systems level biology such as lipidomics where lipid classification is required before appropriate annotation of chemical functions can be applied. The ontology describes the LIPIDMAPS nomenclature classification explicitly using description logics (OWL-DL). Lipid classes are organized hierarchically with the super-classes restricted by generic necessary conditions. More specific necessary conditions are used to define membership requirements for sub classes of lipid according to appropriate functional groups.', '', 'OWL', 4, 'See Remote Site', '2014-02-11T20:34:46.000-08:00', 'https://bioportal.bioontology.org/ontologies/LIPRO', '346311ada0d2c21674eefcc467c840a5562f639aecfb427315f520704f7ab8e8', 'scored', NULL, 9.96, 0.02, 0.02, 'same_as_strict (1.0 result, not re-checked)', 0.14, 5.0, 3.78, 3.78, NULL, NULL, NULL, 901, 277, 277, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:06+00:00', '2026-09-23T23:25:10+00:00');
