INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MADS-RDF', 'Metadata Authority Description Schema in RDF', 'MADS/RDF (Metadata Authority Description Schema in RDF) is a knowledge organization system (KOS) designed for use with controlled values for names (personal, corporate, geographic, etc.), thesauri, taxonomies, subject heading systems, and other controlled value lists. It is closely related to SKOS, the Simple Knowledge Organization System and a widely supported and adopted RDF vocabulary. MADS/RDF has been fully mapped to SKOS. It is presented as an OWL ontology. The MADS/RDF is designed as a data model for authority and vocabulary data used within the library and information science (LIS) community, which is inclusive of museums, archives, and other cultural institutions. For example, MADS/RDF provides a means to record data from the Machine Readable Cataloging (MARC) Authorities format in RDF for use in semantic applications and Linked Data projects.', 'Other', 'OWL', 5, '1.0', '2018-05-09T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MADS-RDF', 'eccc7b746f35915e0a7651d2c8409477037d62d06e585377a53476110c970ad4', 'scored', NULL, 9.26, 3.9, 3.9, 'same_as_strict (1.0 result, not re-checked)', 1.16, 9.0, 5.83, 5.83, NULL, NULL, NULL, 844, 68, 67, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:58+00:00', '2026-09-23T23:25:10+00:00');
