INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MARC-LANGUAGES', 'MARC List for Languages', 'MARC List for Languages provides three-character lowercase alphabetic strings that serve as the identifiers of languages and language groups. The codes are usually based on the first three letters of the English form or, in some cases, vernacular form of the corresponding language name. The codes are varied where necessary to resolve conflicts and are not intended to be abbreviations of a language name. When the name of a language is changed in the list, the original code is generally retained. The codes in this list are equivalent to those of ISO 639-2 (Bibliographic) codes and some codes from ISO 639-5, although the language name labels may differ. They are linked to the equivalent codes in ISO 639-2 and ISO 639-5 and the corresponding two-character codes in ISO 639-1.', '', 'SKOS', 271, NULL, '2022-04-25T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MARC-LANGUAGES', 'f697e4b957c7a5075e33e5b5f30f13594b1874ecddff33258ed1efc6ae129393', 'scored', NULL, 9.99, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.4975, 2.4975, NULL, NULL, NULL, 9848, 1482, 488, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:08:37+00:00', '2026-09-23T23:25:10+00:00');
