INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MAXO', 'Medical Action Ontology', 'The Medical Action Ontology (MAxO) provides a structured vocabulary for medical procedures, interventions, therapies, and treatments for disease with an emphasis on rare disease (RD). It is often difficult to find relevant clinical literature about strategies to manage RD patients. Responding to this need, MAxO provides a vocabulary to annotate diseases and phenotypes with recommended treatments and interventions., An ontology to represent medically relevant actions, procedures, and recommendations.', '', 'OWL', 57, '2026-01-15', '2026-01-15T18:08:38.000-08:00', 'https://bioportal.bioontology.org/ontologies/MAXO', '54cc40fdfed30507d0eb1f91bb9a4dde5af97fe0ab6aad573cdd586783adb58c', 'scored', NULL, 10.0, 5.89, 5.89, 'same_as_strict (1.0 result, not re-checked)', 7.22, 10.0, 8.2775, 8.2775, NULL, NULL, NULL, 210802, 7121, 7121, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:23:57+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MCBCC', 'Breast Tissue Cell Lines Ontology', 'Contains a comprehensive list of cell lines derived from breast tissue, both normal and pathological. The ontology in built in OWL with cross relation to classes- genetic variation, pathological condition, genes, chemicals and drugs. The relations built enable semantic query across different classes', 'Cell', 'OWL', 2, '2', '2010-07-30T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/MCBCC', '1ccc9b4154e57beeebb5611634727424109fb4186d428a1786dfad27e6ec71e7', 'scored', NULL, 9.59, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 6.75, 10.0, 6.585, 6.585, NULL, NULL, NULL, 15668, 386, 386, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:09:12+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MCCL', 'Cell Line Ontology [by Mahadevan]', 'Ontologies provide a common platform of controlled vocabulary for researchers who need to share information across a particular domain, inclusive of machine-interpretable definitions of basic concepts in the domain and relations among them. The need for ontologies that provide a systematic arrangement of available data and allow cross talk across various related domains is gaining momentum. In this backdrop, we have developed a comprehensive ontology on primary and established cell lines-both normal and pathologic. It covers around 400 cell lines. This ontology has been built to include the major domains in the field of biology like anatomy, bio-molecules, chemicals and drugs, pathological conditions and genetic variations around the cell lines. An extensive network of relations has been built across these concepts to enable different combinations of queries. The ontology covers all cell lines from major sources like ATCC, DSMZ, ECACC, ICLC etc. and is built in OWL format.', 'Anatomy;Cell;Health;Protein', 'OWL', 2, '2', '2014-08-05T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MCCL', 'd98256dd2a1e06edc53dfdfefe9dd519f7fd28fb35d0404b7d55d70831aacede', 'scored', NULL, 9.81, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 6.47, 10.0, 6.57, 6.57, NULL, NULL, NULL, 62620, 5475, 5475, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:16:47+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MCCV', 'Microbial Culture Collection Vocabulary', 'Structured controlled vocabulary for describing meta information of microbial calture collection maintained in biological research centers', 'Other', 'OWL', 11, 'Version 0.99 beta', '2015-04-08T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MCCV', 'ff817656751ab1e7f0df2c417462ed18e75049f32c752de77ce6f7031dd9955a', 'scored', NULL, 8.08, 2.63, 2.63, 'same_as_strict (1.0 result, not re-checked)', 1.55, 7.0, 4.815, 4.815, NULL, NULL, NULL, 929, 26, 23, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:51+00:00', '2026-09-23T23:25:10+00:00');
