INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MCO', 'Microbial Conditions Ontology', 'Microbial Conditions Ontology contains terms to describe growth conditions in microbiological experiments. The first version is based on gene regulation experiments in Escherichia coli K-12. It is being used in RegulonDB to link growth conditions to gene regulation data.', 'Experimental_Conditions', 'OWL', 1, NULL, '2019-05-15T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MCO', '920ae4d962ceac1cb9ded3fddfdb0eef4629f6563fddd0c08dab0fe509220779', 'scored', NULL, 10.0, 3.5, 3.5, 'same_as_strict (1.0 result, not re-checked)', 7.08, 10.0, 7.645, 7.645, NULL, NULL, NULL, 177099, 3384, 3384, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:23:45+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MCO4HKE', 'Multiplex Classification Ontology for the HyperKvasir Experiment', 'Ontology used for one of the experiments from the Multiplex Classification Framework (paper under review). This ontology is based on the set of classes from the HyperKvasir dataset. The HyperKvasir dataset is a manually annotated, multi-class image and video dataset for gastrointestinal endoscopy (Borgli et al., 2020). For the Multiplex experiment, only pathological finding labels were used (such as “Esophagitis grade A,” “Esophagitis grade B-D,” and “Hemorrhoids").

Data Article: Borgli et al. (2020). HyperKvasir, a comprehensive multi-class image and video dataset for gastrointestinal endoscopy. Scientific Data, 7(1), 283. https://doi.org/10.1038/s41597-020-00622-y', 'Health;Imaging', 'OWL', 2, NULL, '2024-09-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MCO4HKE', '445598fe3d0e6b3e0736efd48f930492eb8df51bbdaf561852f3b61689d3ed21', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 6.96, 9.0, 6.49, 6.49, NULL, NULL, NULL, 213, 19, 19, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:05+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MCO4MCRE', 'Multiplex Classification Ontology for the MultiCaRe Experiment', 'Ontology used for one of the experiments from the Multiplex Classification Framework (paper under review). This ontology is based on the set of classes from the MultiCaRe dataset. The MultiCaRe dataset is a multimodal case report dataset containing medical images that were programmatically labeled based on the content of their captions (Nievas Offidani & Delrieux, 2024). Images may have more than one label, making this a multi-label classification task. For this experiment, we selected a subset of 31 classes, including “endoscopy”, “colonoscopy”, and “mri”. The original ontology is flat, and it does not contain any logical constraints among the classes. Data Article: Nievas Offidani, M. A., & Delrieux, C. A. (2024). Dataset of clinical cases, images, image labels and captions from open access case reports from PubMed Central (1990–2023). Data in Brief, 52, 110008. https://doi.org/10.1016/j.dib.2023.110008', 'Health;Imaging', 'OWL', 1, NULL, '2024-09-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MCO4MCRE', '211be9175733250fb5e2a36d494d078ea8fdf72b23dd3715d1dcb0d61c009d81', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 7.4, 9.0, 6.6, 6.6, NULL, NULL, NULL, 414, 36, 36, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:21+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MCRO', 'Model Card Report Ontology', 'An ontology representing the structure of model card reports - reports that describe basic characteristics of machine learning models for the public and consumers., An ontology representing the model card structure', 'Other', 'OWL', 3, '2023-03-07', '2025-12-02T18:15:19.000-08:00', 'https://bioportal.bioontology.org/ontologies/MCRO', 'fdee1c3f1b77c54a3fe336ae170614102cb7b5ce84a6172d44e7c439454fd3d3', 'scored', NULL, 10.0, 4.31, 4.31, 'same_as_strict (1.0 result, not re-checked)', 2.6, 10.0, 6.7275, 6.7275, NULL, NULL, NULL, 13381, 956, 938, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:28+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MCR_TX', 'MultiCaRe Taxonomy', 'The MultiCaRe Taxonomy contains the class structure used for medical image classification in the MultiCaRe dataset (v2).', 'Anatomy;Biomedical_Resources;Health;Human;Imaging', 'OWL', 2, '1.0', '2024-11-18T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MCR_TX', '70b5fc93d0f8962f43533114940cc6d7609606315aa2d96d7278cae5f37b3090', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 7.69, 10.0, 6.9225, 6.9225, NULL, NULL, NULL, 2519, 163, 163, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:06:07+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MDDB', 'Master Drug Data Base Clinical Drugs', 'Master Drug Data Base provides pricing and descriptive drug information on name brand, generic, prescription and OTC medications, and herbal products. It includes industry standard identifiers for all brand and generic drugs on the market including National Drug Code (NDC), Universal Product Code (UPC) and Health Related Item (HRI) numbers.
', 'Health', 'UMLS', 10, 'MDDB_2017_02_08', '2017-02-06T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MDDB', NULL, 'not_downloadable', '{"errors":["License restrictions on download for MDDB"],"status":403}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MDM', 'Mapping of Drug Names and MeSH 2022', 'The Mapping of Drug Names and MeSH 2022 (MDM) provides owl:sameAs relationships as well as owl:equivalentClass of similar concepts for Drug Names from the DrugBank vocabulary (released 2022-01-03 under version 5.1.9: https://go.drugbank.com/releases/latest#open-data) and the Medical Subject Headings (2022 version: http://id.nlm.nih.gov/mesh/). Two concepts are considered similar if they share the same concept name or a common synonym. Additional synonyms are generated using the Snowball stemming algorithm. The software implementation is available on github within the Maven project SNoKE in the module snoke.ontology: https://github.com/bernd-mueller/snoke/tree/master/snoke.ontology', 'All_Organisms;Anatomy;Biological_Process;Biomedical_Resources;Chemical;Health;Human;Immunology;Molecule;Neurologic_Disease;Neurological_Disorder;Physicochemical;Taxonomic_Classification', 'OWL', 5, '0.330', '2022-03-30T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MDM', '39df90c5f966c639b2aff04c935f7503e0d1443d3fdb459d235e2fb7a3f92f3d', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 4.0, 3.5, 3.5, NULL, NULL, NULL, 856988, 44790, 44790, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:42:49+00:00', '2026-09-23T23:25:10+00:00');
