INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MEDRED', 'MedRed ontology: clinical data acquisition model', 'This ontology aims to model generic Medical Data Acquisition Instruments, which can be interoperable across different clinical data management systems. The ontology is developed in the context of the MedRed project (https://www.hevs.ch/en/rad-institutes/institute-of-information-systems/projects/medical-research-data-acquisition-platform-14092), Esta ontología has sido diseñada para representar Instrumentos de captura de datos clínicos, dentro del contexto del proyecto MedRed (https://www.hevs.ch/en/rad-institutes/institute-of-information-systems/projects/medical-research-data-acquisition-platform-14092), Cette ontologie a été conçue pour representer des Instruments pour l''aquisition de données cliniques, dans le contexte du projet MedRed project (https://www.hevs.ch/en/rad-institutes/institute-of-information-systems/projects/medical-research-data-acquisition-platform-14092)', '', 'OWL', 1, '0.0.1', '2017-04-01T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MEDRED', '7b63abdd7fcb783932190c8f48562d57bc801ae99e6295dca962f229bc1387ef', 'scored', NULL, 7.48, 3.9, 3.9, 'same_as_strict (1.0 result, not re-checked)', 3.91, 9.0, 6.0725, 6.0725, NULL, NULL, NULL, 1703, 159, 75, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:36+00:00', '2026-09-23T23:25:10+00:00');
