INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MEPO', 'Mapping of Epilepsy Ontologies', 'The Mapping of Epilepsy Ontologies (MEPO) provides owl:sameAs relationships of similar concepts for the ontologies EpSO, ESSO, EPILONT, EPISEM, and FENICS. Two concepts are considered similar if they share the same concept name or the same synonym. Additional synonyms for each of the concepts are generated using the Snowball stemming algorithm. The software implementation is available on github within the Maven project snoke in the module snoke.ontology: https://github.com/bernd-mueller/snoke/tree/master/snoke.ontology', 'Biological_Process;Biomedical_Resources;Development;Gene_Product;Health;Human;Neurologic_Disease;Neurological_Disorder;Protein;Vocabularies', 'OWL', 6, '0.6', '2021-01-15T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MEPO', 'c3a50ae6eeec8127da15ebc464e3ab7ad7fd2a279f8b4e2975e0fd35444fa072', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.5, 2.5, NULL, NULL, NULL, 46578, 5687, 5687, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:15:30+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MERA', 'Medical Educational Resource Aggregator', 'The educational resource ontology is designed in order to provide structure to resources aggregated by the educational resource aggregator.
The aim of the educational resource aggregator is to harvest educational resources from 3rd party repositories, present these to the medical expert for annotation and rating, and output the results of the annotation (together with resource metadata) to the CARRE public RDF repository.
The main parts of this aggregator are: the Resource Retriever, the Resource Rating, the Resource Metadata Processing, and the User Application.
The educational metadata involve the Resource Metadata processing module.This module is a combination of 3 services that collect data per article, making multiple SPARQL requests to enrich the data and finally store it as a unique identified resource into the local datastore. Then data is transformed into RDF triples in order to be inserted to CARRE educational repository.
The ontology is developed using the Protégé v5.0 , a free, open-source ontology editor from the Stanford University. The ontology is available on CARRE rdf repository among the other ontologies. CARRE url : http://carre.kmi.open.ac.uk/ontology/educational.owl', 'Vocabularies', 'OWL', 1, '0.0.1', '2015-04-26T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MERA', '213474093b0fa2c72d11848602dbff0b820c1ba2d5a126a455d47fa4bd2fa48d', 'scored', NULL, 1.67, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 0.4175, 0.4175, NULL, NULL, NULL, 130, 6, 6, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:03:53+00:00', '2026-09-23T23:25:10+00:00');
