INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'METABUS', 'metaBUS controlled vocabulary for organizational and applied psychology research', 'The metaBUS hierarchical taxonomy of ~5,000 constructs studied in applied psychology, organizational behavior, and human resource management.', 'Human;Other;Taxonomic_Classification;Vocabularies', 'OWL', 18, '0.1', '2024-01-31T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/METABUS', '6a2149e193e38c43b90d89025e9e9ccee837ffd5f66f1ed5cf831325f27e685c', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 5.0, 5.0, NULL, NULL, NULL, 20739, 5185, 5185, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:10:09+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'METAMESH', 'Meta Mesh Ontology', 'The Meta Mesh Ontology (MMO) is a universal framework designed to integrate diverse knowledge bases across all domains of inquiry. It provides a coherent, philosophically grounded foundation that enables the unification of medical, psychological, social, technological, ecological, and cultural knowledge systems. While developed and applied initially in the context of psychiatry and interoperability (e.g., smart cities, robotics, clinical research), the MMO is structured to encompass and interlink every form of knowledge into a single, coherent, and interoperable framework., 
            The Meta Mesh Ontology (MMO) is a universal framework designed to integrate diverse knowledge bases 
            across all domains of inquiry. It provides a coherent, philosophically grounded foundation 
