INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MHC', 'Major Histocompatibility Complex Ontology', 'The MaHCO contains terms necessary for describing and categorizing concepts related to MHC, in general, and for a number of model species, and also for humans. ', 'Genomic_and_Proteomic', 'OWL', 4, '1.0.1', '2009-04-15T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/MHC', 'e04587fa5d0847e13133a559f4467ed464bdf0b1870acc9f301afa0bb358c82f', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 3.26, 10.0, 5.815, 5.815, NULL, NULL, NULL, 48019, 7929, 7929, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:13:41+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MHCRO', 'MHC Restriction Ontology', 'The MHC Restriction Ontology (MRO) is an application ontology capturing how Major Histocompatibility Complex (MHC) restriction is defined in experiments, spanning exact protein complexes, individual protein chains, serotypes, haplotypes and mutant molecules, as well as evidence for MHC restrictions., The MHC Restriction Ontology is an application ontology capturing how Major Histocompatibility Complex (MHC) restriction is defined in experiments', '', 'OWL', 50, '2026-09-15', '2026-09-15T18:08:32.000-07:00', 'https://bioportal.bioontology.org/ontologies/MHCRO', '2bc24cafdc2344909aecb88b8f44c202260e880c04c1664fd8fb000f876bdb15', 'scored', NULL, 10.0, 0.01, 0.01, 'same_as_strict (1.0 result, not re-checked)', 8.06, 10.0, 7.0175, 7.0175, NULL, NULL, NULL, 1117384, 51446, 51446, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:52:03+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MHIO', 'Mental Health Interface Ontology', 'Digital mental health tools have expanded quickly, but many still struggle to understand the way people actually talk about their emotions online. Clinical vocabularies like SNOMED CT, ICD-10, DSM-5, and the Mental Functioning Ontology were created for medical settings, so they often miss the casual phrases and slang people use on platforms such as Reddit. Someone might say, “I feel burnt out,” “I’m mentally cooked,” or “I disappeared for a week.” These expressions rarely match any formal clinical term, even though they describe real emotional experiences. In MHIO, we extract slang terms as concepts from social-media language using graph clustering and map them to a clinical equivalent.', 'Health;Human;Neurologic_Disease;Neurological_Disorder;Taxonomic_Classification;Upper_Level_Ontology', 'OBO', 1, NULL, '2026-05-31T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MHIO', 'bd59a49eebddb7f0de15b00807e5e285792ea7c2f1fb2b9582c98424254caa81', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 5.0, 5.0, NULL, NULL, NULL, 1470, 369, 369, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:05:14+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MHMO', 'Mental Health Management Ontology', 'This ontology can assist in the management of mental healthcare networks. It allows the integration and semantic interoperability between independent health databases, promotes the ability to infer knowledge in this domain, enables the generation of relevant indicators for mental health to improve decision-making, and increases mental health management and planning efficiency and effectiveness. This is a non-profit, open-source project.', 'Health', 'OWL', 9, '3.2', '2019-03-18T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MHMO', 'bc6379b681c00dc72f7cab46bdc062e4c864c505a23b01feb309b290ede42655', 'scored', NULL, 8.56, 0.2, 0.2, 'same_as_strict (1.0 result, not re-checked)', 1.84, 10.0, 5.15, 5.15, NULL, NULL, NULL, 2883, 437, 373, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:43+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MI', 'Molecular Interactions', 'A structured controlled vocabulary for the annotation of experiments concerned with protein-protein interactions. Developed by the HUPO Proteomics Standards Initiative.', '', 'OBO', 77, NULL, '2026-09-11T18:09:13.000-07:00', 'https://bioportal.bioontology.org/ontologies/MI', 'df46c8a2cb10d349b8d5d3f30f448e196eb4abd53a543e99bfee0d11dfca156d', 'scored', NULL, 9.99, 6.74, 6.74, 'same_as_strict (1.0 result, not re-checked)', 7.62, 10.0, 8.5875, 8.5875, NULL, NULL, NULL, 36701, 1658, 1658, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T03:26:26+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MIAPA', 'MIAPA Ontology', 'An application ontology to formalize annotation of phylogenetic data according to the emerging Minimum Information About a Phylogenetic Analysis (MIAPA) metadata reporting standard.', '', 'OWL', 1, NULL, '2017-05-08T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MIAPA', '60bf131304493393d54ab48db089d1c20f585bf4277c358e5d3d9648960f07f1', 'scored', NULL, 10.0, 2.1, 2.1, 'same_as_strict (1.0 result, not re-checked)', 2.67, 10.0, 6.1925, 6.1925, NULL, NULL, NULL, 3733, 269, 232, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:36+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MICRONT', 'microntology', 'microntology encompasses (in v1.0) a controlled vocabulary of 148 crosslinked terms that fall into five broad habitat categories (terrestrial, aquatic, aerial, host-associated and anthropogenic environments) and additional categories that describe broad physicochemical properties, morphology, human host properties, animal host captivity status, and miscellaneous informative features such as (chemical) contamination or ancient (paleontological) sample provenance. MICRONT is designed as a pragmatic lightweight complement to existing detailed ontologies like ENVO, UBERON or GOLD; MICRONT terms are crosslinked to these where appropriate. Its purpose is a fast, automatable annotation of (meta)genomic microbial samples with browsable informative tags.', 'All_Organisms;Other;Vocabularies', 'OWL', 2, 'v1.0.1', '2026-04-28T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MICRONT', '23940a8eb078576524c68582baa5432a2bb304a939a72f5c711af45ab43254d3', 'scored', NULL, 10.0, 6.87, 6.87, 'same_as_strict', 3.42, 10.0, 7.5725, 7.5725, NULL, NULL, NULL, 1439, 160, 160, '0.10.0', 'core4-1.1', 'cuda', '2026-09-23T21:59:05+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MIDO', 'Medical Imaging and Diagnostic Ontology', 'MIDO is an OWL 2 ontology for creating a standardized format for modeling data in medical imaging tasks such as Disease Classification/ Diagnosis as well as Disease localization/segmentation
', 'Anatomy;Biological_Process;Biomedical_Resources;Health;Human;Imaging', 'OWL', 1, '2015-11-20', '2022-04-25T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MIDO', '3e98566d84fbb60d3ab205c870536960207132d61d89b1893772634e49e64002', 'scored', NULL, 10.0, 0.51, 0.51, 'same_as_strict (1.0 result, not re-checked)', 4.89, 10.0, 6.35, 6.35, NULL, NULL, NULL, 936565, 51882, 51838, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:49:04+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MIFD', 'Minimum Information for Fermentation Devices', 'MIFD is an ontology schema for modeling fermentation devices, their components and all the intricate hierarchical dependencies involved in such equipment configurations. The concept of device refers to the top layer of the cultivation equipment abstraction. Devices can host single fermentation vessels or have slots that can host multiple ones. The concept of vessel reflects individual fermentation units that can be of any type (e.g. bioreactor, microwell, flask etc). The component category describes sensors and actuators that are typically attached to fermentation vessels.', '', 'OWL', 5, NULL, '2026-02-26T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MIFD', '7dacb2d48bf3f31d48f603efa879734bd8ce3c87302d202be85f6ff0d2c9a835', 'scored', NULL, 10.0, 1.07, 1.07, 'same_as_strict (1.0 result, not re-checked)', 2.08, 6.0, 4.7875, 4.7875, NULL, NULL, NULL, 696, 13, 13, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:38+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MIFE', 'Minimum information for fermentation experiments', 'Minimum Information for Fermentation Experiments (MIFE) was designed to thoroughly describe industrial biotechnology fermentation experiments. It extends Investigation Study Assay (ISA) metadata structure to also include the concepts of observation units and samples that correspond to fermentation runs and samples taken from a fermentation vessel. The hierarchical nature of the extended ISA structure behind MIFE is capable of supporting the management of entire projects by enabling the thorough recording of key information related to fermentation experiments.', '', 'OWL', 3, NULL, '2026-02-26T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MIFE', 'e3034f8943344962072dea21c6eb370fc4f90145e01d821203a32499127a2ef2', 'scored', NULL, 10.0, 3.95, 3.95, 'same_as_strict (1.0 result, not re-checked)', 4.59, 4.0, 5.635, 5.635, NULL, NULL, NULL, 2188, 7, 7, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:44+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'MIM', 'Molecular Interaction Map', 'The Molecular Interaction Map (MIM) notation seeks to provide a standardized method to draw diagrams for bioregulatory networks with features similar to technical diagrams in other fields.

This vocabulary uses the term hierarchy from the Formal MIM Notation Specification. Where possible, Systems Biology Ontology (SBO) and Biological Pathway Exchange (BioPAX) terms and IRIs are used. If no SBO or BioPAX term is available, a new term and IRI are created.

This is currently only a partial implementation. Many elements still need to be added to cover the full the specification.', 'Biological_Process;Vocabularies', 'OWL', 3, '10:30:2014 16:04', '2014-10-30T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/MIM', '4416379f8270c6a667780411300e432280ca710563ed96da48ac39e6d20fbd7c', 'scored', NULL, 9.55, 6.41, 6.41, 'same_as_strict (1.0 result, not re-checked)', 3.73, 10.0, 7.4225, 7.4225, NULL, NULL, NULL, 1555, 88, 88, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:57+00:00', '2026-09-23T23:25:10+00:00');
