INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NAMO', 'New Approach Methodology Ontology', 'The New Approach Methodology Ontology and Schema (NAMO) is a comprehensive data framework designed to standardize and integrate information about alternative methods to animal testing in biomedical research. Built on LinkML, NAMO provides a common vocabulary and data structure for describing diverse model systems, from cellular cultures and organ-on-chip devices to computational models and digital twins.', 'Biomedical_Resources;Chemical;Experimental_Conditions;Health;Phenotype;Physicochemical', 'OWL', 2, NULL, '2026-08-01T18:07:50.000-07:00', 'https://bioportal.bioontology.org/ontologies/NAMO', 'e0a1021e72d46eadcf4326444ad346c87f60b6c6025b2eab1a39a72f51477bd6', 'scored', NULL, 10.0, 5.29, 5.29, 'same_as_strict (1.0 result, not re-checked)', 6.24, 10.0, 7.8825, 7.8825, NULL, NULL, NULL, 5479, 263, 263, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:15+00:00', '2026-09-23T23:25:10+00:00');
