INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NBO', 'Neuro Behavior Ontology', 'The Neurobehavior Ontology (NBO) consists of two main components, an ontology of behavioral processes and an ontology of behavioral phenotypes. The behavioral process branch of NBO contains a classification of behavior processes complementing and extending GO’s process ontology. The behavior phenotype branch of NBO consists of a classification of both normal and abnormal behavioral characteristics of organisms.', '', 'OWL', 38, '2023-07-04', '2023-07-04T18:11:51.000-07:00', 'https://bioportal.bioontology.org/ontologies/NBO', 'aadc585e5f6abe0b79ade89e005633384e680ed446349afe3018b03a2dbeb741', 'scored', NULL, 10.0, 1.86, 1.86, 'same_as_strict (1.0 result, not re-checked)', 6.36, 10.0, 7.055, 7.055, NULL, NULL, NULL, 82168, 4548, 4548, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:17:00+00:00', '2026-09-23T23:25:10+00:00');
