INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NCCNEHR', 'NCCN EHR Oncology Categories', 'The NCCN EHR Oncology Advisory Group was formed to address the high variance in oncology history documentation within EHR systems. Specifically, there is a lack of standardization in the names of oncology history categories across institutions. Moreover, no synonym list or mapping currently exists between the varied category names. Furthermore, oncology history documentation is often inconsistent, incomplete, and not updated appropriately. The NCCN EHR Oncology Advisory Group has established best practices and is working with EHR vendors to implement and enhance tools for documentation of oncology history. This ontology is a result of the work of the group, and provides users with a list of oncology history categories and synonyms. It is our sincere hope that this work can form the basis of improving standardization and interoperability of oncology history documentation within EHR systems.', 'Biomedical_Resources;Health', 'OWL', 1, '1.0.0', '2017-10-11T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/NCCNEHR', '8104193fb4ae10e8e9b637d38350aaa90e449d7c8b623b5606d3850828223be8', 'scored', NULL, 8.0, 5.08, 5.08, 'same_as_strict (1.0 result, not re-checked)', 7.18, 0.0, 5.065, 5.065, NULL, NULL, NULL, 83, 15, 15, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:03:46+00:00', '2026-09-23T23:25:10+00:00');
