INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NEMO', 'Neural ElectroMagnetic Ontology', 'Neural ElectroMagnetic Ontology (NEMO) describes classes of event-related brain potentials (ERP) and their properties, including spatial, temporal, and functional (cognitive/behavioral) attributes, and data-level attributes (acquisition and analysis parameters). Working (unstable), Release (stable), and Old (archival) versions of NEMO can be found on sourceforge: http://sourceforge.net/projects/nemoontologies/.', 'Anatomy;Biological_Process;Experimental_Conditions;Human;Imaging', 'OWL', 24, 'v3.10', '2013-10-21T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/NEMO', 'b04a82ef5fadfda27721d752287ef9c8fc13d02953bf3834de8483ebdd9c6fa3', 'scored', NULL, 9.99, 0.21, 6.12, 'http://purl.bioontology.org/NEMO/ontology/NEMO_annotation_properties.owl#definition [bioportal_definitionProperty + detected_by_name]', 2.01, 10.0, 5.5525, 7.03, NULL, NULL, NULL, 42131, 1926, 1848, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T22:57:40+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NEO', 'Neurologic Examination Ontology', 'An ontology to capture findings from the neurological examination.  The ontology is based on concepts from UMLS Metathesaurus and SNOMED CT.  Only abnormal findings are included.  The purpose of the ontology is to act as a limited vocabulary for coding the neurological examination for big data projects or machine learning.

Hier DB, Brint SU. A Neuro-ontology for the neurological examination. BMC Med Inform Decis Mak. 2020;20(1):47. Published 2020 Mar 4. doi:10.1186/s12911-020-1066-7', 'Health;Neurologic_Disease;Neurological_Disorder;Taxonomic_Classification', 'OWL', 90, '49.0', '2022-07-05T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/NEO', '63778f05ab0288345620406c2a5f1ab4a90a3f3c27c807844a404e9248e78869', 'scored', NULL, 9.98, 0.0, 0.0, 'same_as_strict', 0.0, 10.0, 4.995, 4.995, NULL, NULL, NULL, 12052, 1614, 1611, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T22:57:15+00:00', '2026-09-23T23:25:10+00:00');
