INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NERO', 'Named Entity Recognition Ontology ', 'Named Entity Recognition Ontology (NERO) developed specifically for describing textual entities in biomedical texts, which accounts for diverse levels of ambiguity, bridging the scientific sublanguages of molecular biology, genetics, biochemistry, and medicine. The annotation of natural science texts is more challenging than in other domains. Biomedical language is replete with ambiguity distinct from that observed in news articles or informal text online. In biomedical texts, alternative meanings are not always clearly separated.

For example, in some biomedical contexts, the words for a named entity may refer to a gene or a protein with nearly equal probability; for example, “a mutant hemoglobin α_2” can refer to either a gene or a protein. If the author meant gene-or-protein A, and we force an annotator to choose either interpretation gene A or protein A, the resulting annotation is of limited utility because the choice between gene and protein is random if the meanings are equally likely based on context. NERO attempts to minimize unwarranted, arbitrary annotative semantic label assignments for textual entities. 

NERO defines ambiguous concepts, such as GeneOrProtein, which subsumes both Gene and Protein using the following axiom: EquivalentTo: ‘Gene’ or ‘Protein.’ There are no biological entities that are either a gene or a protein, but there are lexical entities that can correspond to either or both of these entities.
', 'Biomedical_Resources', 'OWL', 1, 'The main developer of NERO is Prof. Robert Stevens, the University of Manchester', '2021-04-28T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/NERO', '4a3a3188f093768de48f78f8f936d8239726a691475a579e8d7638cbcadafc5e', 'scored', NULL, 9.84, 1.52, 1.52, 'same_as_strict (1.0 result, not re-checked)', 2.79, 10.0, 6.0375, 6.0375, NULL, NULL, NULL, 508, 64, 64, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:35+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NEUDIGS', 'Neuroscience Domain Insight Graph', 'Neuroscience Domain Insight Graphs provide a framework for expressing linked open data about neuronal populations expressed as statements about (A) distributions of subcellular components, (B) measurable physiological changes under various experimental conditions. The goal of this representation is to provide a computable language for reasoning over experimental neuroscientific findings.   ', 'Anatomy;Cell;Cellular_anatomy_', 'OWL', 1, '0.0.1', '2017-02-23T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/NEUDIGS', '1e8aa0eedc0b6a3d5832cf45a5ebdaca00cec4eaca2a8c87d3bfa636c8ec813e', 'scored', NULL, 9.58, 4.53, 4.53, 'same_as_strict (1.0 result, not re-checked)', 0.0, 7.0, 5.2775, 5.2775, NULL, NULL, NULL, 189, 24, 24, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:03+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NEUMORE', 'Neural Motor Recovery Ontology', 'Neural Functional Motor Recovery Ontology', '', 'OWL', 1, '0.1', '2010-07-28T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/NEUMORE', '748e1f70cb5f1ce41176447160a5feda927f6f2c60341621f6d9adef31973713', 'scored', NULL, 9.71, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 7.0, 4.1775, 4.1775, NULL, NULL, NULL, 101, 34, 34, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:03:50+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NEUROBRG', 'NeuroBridge Ontology', 'NeuroBridge ontology is being developed as part of the NeuroBridge project to implement FAIR principles for neuroimaging and neurophysiology data using computable provenance metadata. The NeuroBridge ontology extends the W3C PROV ontology and the ProvCaRe ontology with terms from the SchizConnect and Data Bridge ontology aligned and merged into the original class structure of the ProvCaRe ontology. ', 'Biomedical_Resources;Experimental_Conditions;Imaging;Neurologic_Disease', 'OWL', 2, '1.0 (Release 2023)', '2023-06-21T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/NEUROBRG', 'da30c68a95e211d28055dbaa005f2e5b594be26deefa2baffeb6cc04e427134a', 'scored', NULL, 10.0, 0.82, 0.82, 'same_as_strict (1.0 result, not re-checked)', 0.35, 10.0, 5.2925, 5.2925, NULL, NULL, NULL, 4023, 667, 667, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:06+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NEXUS', 'NEXUS: An Integrated Semantic Framework and Ontology for Neurodegenerative Disease Knowledge - Linking Clinical, Cognitive, Biological, and Artificial Intelligence Domains', 'NEXUS (An Integrated Semantic Framework and Ontology for Neurodegenerative Disease Knowledge: Linking Clinical, Cognitive, Biological, and Artificial Intelligence Domains) is an OWL 2 ontology developed to provide a structured and semantically interoperable representation of knowledge related to neurodegenerative diseases. The ontology integrates clinical, cognitive, biological, anatomical, imaging, diagnostic, therapeutic, disease-progression, artificial intelligence, explainability, clinical decision-support, and patient-safety concepts within a unified semantic framework.

NEXUS represents relationships among neurodegenerative diseases, clinical manifestations, symptoms, cognitive and behavioral functions, brain anatomy, molecular and genetic biomarkers, neuroimaging concepts, clinical assessments, diagnostic concepts, disease stages, disease progression, therapeutic interventions, and clinical outcomes. The ontology includes representations of Alzheimer disease, Parkinson disease, frontotemporal dementia, Lewy body dementia, and Huntington disease, together with relevant biomarkers such as amyloid beta, tau protein, phosphorylated tau, alpha-synuclein, neurofilament light, and selected genetic biomarkers including APOE, LRRK2, GBA, and MAPT.

The ontology also provides a semantic representation of artificial intelligence and computational concepts relevant to neurodegenerative disease research, including machine learning, deep learning, knowledge graphs, semantic reasoning, predictive and classification models, disease and progression prediction, risk prediction, model inputs and outputs, confidence information, feature importance, clinical decision-support systems, clinical recommendations, human oversight, safety constraints, clinical risk, adverse events, near misses, audit trails, evidence, and provenance.

NEXUS is designed to support semantic knowledge integration, ontology-based querying, representation and linkage of heterogeneous clinical and biom', 'Biomedical_Resources;Genomic_and_Proteomic;Neurologic_Disease;Neurological_Disorder', 'OWL', 1, '1.0.0', '2026-09-20T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/NEXUS', '7a85f9b632ce2304289ef3af6253311c221b9d47189a4f37de0c870e61ae4b62', 'scored', NULL, 9.95, 0.03, 0.03, 'same_as_strict (1.0 result, not re-checked)', 2.12, 10.0, 5.525, 5.525, NULL, NULL, NULL, 1960, 216, 215, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:46+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NGBO', 'Next Generation Biobanking Ontology', 'The Next Generation Biobanking Ontology (NGBO) is an open application ontology representing contextual data about omics digital assets in biobank. The ontology focuses on capturing the information about three main activities: wet bench analysis used to generate omics data, bioinformatics analysis used to analyze and interpret data, and data management.', 'Biomedical_Resources', 'OWL', 4, '2024-08-27', '2024-09-04T18:16:17.000-07:00', 'https://bioportal.bioontology.org/ontologies/NGBO', 'e1bfe69a956628aeaf27c19ae4f2a443b9014d019cd1773a71765c1cac2fae0a', 'scored', NULL, 10.0, 4.9, 4.9, 'same_as_strict (1.0 result, not re-checked)', 0.68, 10.0, 6.395, 6.395, NULL, NULL, NULL, 14594, 1516, 1516, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:47+00:00', '2026-09-23T23:25:10+00:00');
