INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NIDM-RESULTS', 'NIDM-Results', 'NIDM-Results is a data model that enable sharing neuroimaging results using a common descriptive standard across neuroimaging software. NIDM-Results focuses on mass-univariate studies and is mostly targeted at fMRI but is also suitable for anatomical MRI (with Voxel-Based Morphometry), and Positron Emission Tomography (PET). 

NIDM-Results packs provide a lightweight solution to share maps generated by neuroimaging studies along with their metadata. Export to NIDM-Results is natively implemented in SPM, NeuroVault and CBRAIN and a Python library is ready for  integration in FSL. NeuroVault additionally can import NIDM-Results packs.', 'Imaging;Other', 'OWL', 2, 'Recommendation version 2013-04-30', '2016-06-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/NIDM-RESULTS', 'b64c6c3e23afa76ee17988769046f4d4d74273f8015b62ef69b127a945afbe29', 'scored', NULL, 9.69, 5.81, 5.81, 'same_as_strict (1.0 result, not re-checked)', 0.74, 10.0, 6.56, 6.56, NULL, NULL, NULL, 3444, 191, 161, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:35+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NIFCELL', 'Neuroscience Information Framework (NIF) Cell Ontology', 'Cell types from NIFSTD', '', 'OWL', 15, 'v.1.10 - July 17, 2013', '2017-10-10T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/NIFCELL', '132b9183d6e9e66f0de2f3f315e0c2100a7e621f37d0ef96fa41e862db7d98e9', 'scored', NULL, 9.97, 3.66, 3.66, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 5.9075, 5.9075, NULL, NULL, NULL, 3932, 375, 375, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:37+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NIFDYS', 'Neuroscience Information Framework (NIF) Dysfunction Ontlogy', 'This ontology contains the former BIRNLex-Disease, version 1.3.2. -- The BIRN Project lexicon will provide entities for data and database annotation for the BIRN project, covering anatomy, disease, data collection, project management and experimental design.  It is built using the organizational framework provided by the foundational Basic Formal Ontology (BFO).  It uses an abstract biomedical layer on top of that - OBO-UBO which has been constructed  as a proposal to the OBO Foundry.  This is meant to support creating a sharable view of core biomedical objects such as biomaterial_entity, and organismal_entity that all biomedical ontologies are likely to need and want to use with the same intended meaning.  The BIRNLex biomaterial entities have already been factored to separately maintained ontology - BIRNLexBiomaterialEntity.owl which this BIRNLex-Main.owl file imports.  The Ontology of Biomedical Investigation (OBI) is also imported and forms the foundation for the formal description of all experiment-related artifacts.  The BIRNLex will serve as the basis for construction of a formal ontology for the multiscale investigation of neurological disease.', '', 'OWL', 16, '1.5 (December, 2012)', '2018-04-11T18:08:58.000-07:00', 'https://bioportal.bioontology.org/ontologies/NIFDYS', '3ddf81b12c56d276fa3e25215f929b22949cea67943177d95527773174066d52', 'scored', NULL, 9.93, 5.56, 5.56, 'same_as_strict (1.0 result, not re-checked)', 7.23, 10.0, 8.18, 8.18, NULL, NULL, NULL, 422197, 11466, 11256, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:34:15+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NIFSTD', 'Neuroscience Information Framework (NIF) Standard Ontology', 'NIF Standard ontology (NIFSTD) is a core component of Neuroscience Information Framework (NIF) project (http://neuinfo.org), a semantically enhanced portal for accessing and integrating neuroscience data, tools and information. NIFSTD includes a set of modular ontologies that provide a comprehensive collection of terminologies to describe neuroscience data and resources.', 'All_Organisms;Anatomy;Biological_Process;Cell;Cellular_anatomy_;Dysfunction;Molecule;Neurologic_Disease;Neurological_Disorder;Other;Subcellular;Subcellular_anatomy', 'OWL', 27, '3.1 - January 15, 2018', '2018-02-10T18:06:57.000-08:00', 'https://bioportal.bioontology.org/ontologies/NIFSTD', '029caa9a960d4a5bdf10ab705da5c1d2090afb6c8b48620636fd524926a22409', 'scored', NULL, 9.98, 4.2, 4.2, 'same_as_strict (1.0 result, not re-checked)', 6.22, 10.0, 7.6, 7.6, NULL, NULL, NULL, 4407575, 178494, 177974, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T08:11:11+00:00', '2026-09-23T23:25:10+00:00');
