INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NIGO', 'Neural-Immune Gene Ontology', 'The Neural-Immune Gene Ontology (NIGO) is a subset of GO directed for neurological and immunological systems. NIGO was created by clipping those GO terms that are not associated to any gene in human, rat and mouse, and by clipping terms not found to be relevant to the neural and/or immune domains.', 'Biological_Process;Human;Other', 'OBO', 2, 'v1', '2010-09-12T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/NIGO', 'bf90161d89f79b5e8b60876d815ea241be46e56be3a4350c65b522adbeb30c70', 'scored', NULL, 10.0, 6.58, 6.58, 'same_as_strict (1.0 result, not re-checked)', 7.89, 10.0, 8.6175, 8.6175, NULL, NULL, NULL, 99033, 4843, 4843, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:21:02+00:00', '2026-09-23T23:25:10+00:00');
