INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NRO', 'NeuralReprogrammingOntology', 'The neural reprogramming ontology encompasses the domain of neural regenerative cell reprogramming knowledge. As research progresses, researchers and specialists in the field of reprogramming could continue to expand the bounds of this foundation, so adding to its depth.', 'Biomedical_Resources;Cell;Neurologic_Disease;Phenotype', 'OWL', 1, '1.0.0', '2022-10-10T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/NRO', 'f7eb6ce4408ddfcc7c92fa4f26bd0d814bd78422f3130ea860e06c89b913541d', 'scored', NULL, 9.89, 0.02, 0.02, 'same_as_strict (1.0 result, not re-checked)', 4.88, 10.0, 6.1975, 6.1975, NULL, NULL, NULL, 2961, 564, 564, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:42+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'NUCLEON', 'Nuclide and Element Ontology', 'NUCLEON models chemical elements, nuclides, and decay pathways. 

Elements and nuclides are modeled as classes and punned as individuals. Elements, nuclides and decay branches are named by chemical symbol: an element''s IRI and rdfs:label are its symbol (:H, ''H''), a nuclide''s are its symbol and mass number (:H-1, :Al-26m for an isomer), and a decay branch appends _b1, _b2, _b3 to its parent nuclide (:Co-60_b1). Element names in Englist, German, Spanish, French, Italian, Russian and Chinese (simplified and traditional) are carried as language-tagged skos:altLabel values. Mapped to Ontology of Chemical Elements (OCE/  ChEBI), SNOMED CT, and DICOM.', 'Chemical;Imaging;Molecule;Other;Physicochemical;Vocabularies', 'OWL', 3, '0.9', '2026-08-30T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/NUCLEON', '0cd28108bdc4e93f048ca753a8f4233d8363d2f30b0991c78c06b7e525b41416', 'scored', NULL, 10.0, 0.13, 0.13, 'same_as_strict (1.0 result, not re-checked)', 8.66, 7.0, 6.4475, 6.4475, NULL, NULL, NULL, 111849, 9161, 4228, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:21:08+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'O-REXTECH', 'OSIRIS-REx Analytical Technique', 'second draft, M4M workshop, testing SKOS-Play and workflows. Add top concepts and more hierarchy.', 'Vocabularies', 'SKOS', 2, '0.0.2', '2022-09-08T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/O-REXTECH', 'cb03447c4a7d2e07875f5df708d09cb1f56f8770d3b3046cd2240a945a23fe31', 'scored', NULL, 9.84, 0.6, 0.6, 'same_as_strict (1.0 result, not re-checked)', 8.69, 4.0, 5.7825, 5.7825, NULL, NULL, NULL, 782, 62, 61, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:49+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'O3', 'Operational Ontology for Oncology ', 'The Operational Ontology for Oncology is formalized, machine-readable knowledge representation that defines and standardizes the concepts, terms, value sets and relationships used in cancer care. O3 is an operational ontology, meaning that its format and content is optimized for clinical process implementation with current clinical data systems. It is formed through multi-professional society based, multi-institutional consensus formation with  physicians, physicists, informaticists and other domain experts in the context of the American Association of Physicists in Medicine (AAPM). It is formed in collaboration with and has been endorse by multiple professional societies including American Society of Radiation Oncology (ASTRO), Canadian Association for Radiation Oncology (CARO) and the European Society for Therapeutic Radiation Oncology (ESTRO).    Its primary purpose is to ensure semantic interoperability of comprehensive data sets from disparate sources like electronic health records (EHRs), lab systems, and research databases to be accurately aggregated and understood by different systems. This is particularly crucial for a complex and data-rich field like oncology.  

O3 was first published in the article, Operational Ontology for Oncology (O3): A Professional Society-Based, Multistakeholder, Consensus-Driven Informatics Standard Supporting Clinical and Research Use of Real-World Data From Patients Treated for Cancer. Int J Radiat Oncol Biol Phys. 2023 Nov 1;117(3):533-550. doi: 10.1016/j.ijrobp.2023.05.033. Epub 2023 May 26. PMID: 37244628; PMCID: PMC10741247.

The home web site is at o3standard.net. The site is used as the main mechanism for gathering public comments and accessing future, current and prior versions of the ontology in json format.', '', 'OWL', 5, '2.0', '2026-06-15T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/O3', '650fb27e1f2588cd0e721015aff3b87b7a59f3d7a8e68922bdf97af58edbadeb', 'scored', NULL, 10.0, 2.11, 2.11, 'same_as_strict (1.0 result, not re-checked)', 7.09, 10.0, 7.3, 7.3, NULL, NULL, NULL, 29810, 2108, 2108, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:12:43+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OA', 'Web Annotation Ontology', 'The Web Annotation Data Model specification describes a structured model and format to enable annotations to be shared and reused across different hardware and software platforms. Annotations are typically used to convey information about a resource or associations between resources. Simple examples include a comment or tag on a single web page or image, or a blog post about a news article.', 'Upper_Level_Ontology', 'OWL', 4, '2016-11-12T21:28:11Z', '2017-07-17T18:07:10.000-07:00', 'https://bioportal.bioontology.org/ontologies/OA', 'dd5294968d5170cffd1e135c9a921e70cd1c3df50f08bdc50109b0f2507f64ac', 'scored', NULL, 9.35, 5.15, 5.15, 'same_as_strict (1.0 result, not re-checked)', 0.0, 6.0, 5.125, 5.125, NULL, NULL, NULL, 392, 46, 26, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:22+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OAE', 'Ontology of Adverse Events', 'The Ontology of Adverse Events (OAE) is a community-based biomedical ontology in the domain of adverse events. OAE is developed to standardize adverse event annotation, integrate various adverse event data, and support computer-assisted reasoning. Its development follows the OBO Foundry principles. , The Ontology of Adverse Eventsy (OAE) is a biomedical ontology in the domain of adverse events. OAE aims to standardize adverse event annotation, and support computer-assisted reasoning.  OAE is a community-based ontology. Its development follows the OBO Foundry principles. Vaccine adverse events have been used as an initial testing use case. OAE also studies adverse events associated with the administration of drug and nutritional products, the operation of surgeries, and the usage of medical devices, etc.', 'Health', 'OWL', 172, '1.2.54', '2026-04-07T18:11:14.000-07:00', 'https://bioportal.bioontology.org/ontologies/OAE', 'ffc2608f41b59550cf3a87418bb6447ded35db60395fffb6f9adda8343798e4a', 'scored', NULL, 10.0, 6.31, 6.31, 'same_as_strict (1.0 result, not re-checked)', 2.59, 10.0, 7.225, 7.225, NULL, NULL, NULL, 149819, 10590, 10590, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:22:25+00:00', '2026-09-23T23:25:10+00:00');
