INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OBA', 'Ontology of Biological Attributes', 'A collection of biological attributes (traits) covering all kingdoms of life. Interoperable with VT (vertebrate trait ontology) and TO (plant trait ontology). Extends PATO.', 'Phenotype', 'OWL', 29, '2026-07-14', '2026-07-14T18:14:24.000-07:00', 'https://bioportal.bioontology.org/ontologies/OBA', 'c0a626679b994a126a9e98e9ee0f0bc85ff41b695f50e0c8b4cb6d7384bc01de', 'scored', NULL, 10.0, 4.3, 4.3, 'same_as_strict (1.0 result, not re-checked)', 7.1, 10.0, 7.85, 7.85, NULL, NULL, NULL, 2472131, 83751, 83516, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T07:22:28+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OBCS', 'Ontology of Biological and Clinical Statistics', 'The Ontology of Biological and Clinical Statistics (OBCS) is a biomedical ontology in the domain of biological and clinical statistics. OBCS is primarily targeted for statistical representation in the fields in biological, biomedical, and clinical domains.

OBCS uses the Basic Formal Ontology (BFO) as the upper level ontology. OBCS imports all biostatistics related terms in the Ontology for Biomedical Investigations (OBI) including all logical axioms.', 'Other', 'OWL', 15, '2023-12-08', '2023-12-21T18:12:19.000-08:00', 'https://bioportal.bioontology.org/ontologies/OBCS', 'a81400ca926e638585fbbf61178d2b9be4b116acbd38e32bdfbf1278d4a82d44', 'scored', NULL, 10.0, 6.21, 6.21, 'same_as_strict (1.0 result, not re-checked)', 3.1, 10.0, 7.3275, 7.3275, NULL, NULL, NULL, 20749, 1234, 1211, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:10:31+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OBEST', 'Ontology of Bioethics and Ethics of Science & Technology', 'The Ontology of Bioethics and Ethics of Science & Technology (OBEST) is an ontology that examines moral and ethical norms, basic ethical principles and their application in biological research, and scientific and technological practices. This constitutes a significant research area within the field of Dialectics of Nature.', 'Biomedical_Resources;Development;Health;Human;Other', 'OWL', 2, '1.0.1', '2025-11-05T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OBEST', 'eb9dd84c2f165db019d927a33081ca9b0266d9634bda60639a0043713a7775cd', 'scored', NULL, 10.0, 6.08, 6.08, 'same_as_strict (1.0 result, not re-checked)', 1.76, 10.0, 6.96, 6.96, NULL, NULL, NULL, 21599, 1403, 1386, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:10:38+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OBI', 'Ontology for Biomedical Investigations', 'OBI is an ontology of investigations, the protocols and instrumentation used, the material used, the data generated and the types of analysis performed on it. <br><br>
To import,<br>
Latest version: <a href="http://purl.obolibrary.org/obo/obi.owl">http://purl.obolibrary.org/obo/obi.owl</a><br>
<br>
Latest release notes at <a href="http://purl.obolibrary.org/obo/obi/release-notes.html">http://purl.obolibrary.org/obo/obi/release-notes.html</a><br>
<br>
Note: BFO 2.0 pre-Graz release (not official release version) was used in this release., An ontology for representing biomedical investigations, including study designs, the collection and preparation of the targets of investigation, assays, instrumentation and reagents used, as well as the data generated and the types of analysis performed on the data to reach conclusions, and their documentation.', 'Experimental_Conditions', 'OWL', 66, '2026-07-27', '2026-08-07T18:08:15.000-07:00', 'https://bioportal.bioontology.org/ontologies/OBI', 'd760b9b6a040197874d11890262a4b976f5d141bafb4ed182ca555894b7486fd', 'scored', NULL, 10.0, 6.38, 6.38, 'same_as_strict (1.0 result, not re-checked)', 3.07, 10.0, 7.3625, 7.3625, NULL, NULL, NULL, 125014, 5541, 5240, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:20:12+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OBIB', 'Ontology for Biobanking', 'The ontology for Biobanking (OBIB) is an ontology built for annotation and modeling of biobank repository and biobanking administration. It is developed based on subset of Ontology for Biomedical Investigations (OBI) using Basic Formal Ontology (BFO) as top ontology and following OBO Foundry principles. The first version of the ontology is merged of two existing biobank related ontologies, OMIABIS and biobank ontology.', 'Health', 'OWL', 14, '2023-04-05', '2023-05-12T18:11:27.000-07:00', 'https://bioportal.bioontology.org/ontologies/OBIB', 'd8c29d6e13cc1e7f3d671f1c277b234ca2c40a0d04df193cb062e5429627d35c', 'scored', NULL, 10.0, 5.63, 5.63, 'same_as_strict (1.0 result, not re-checked)', 1.32, 10.0, 6.7375, 6.7375, NULL, NULL, NULL, 27953, 2029, 1804, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:11:33+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OBIWS', 'Bioinformatics Web Service Ontology', 'The Bioinformatics Web Services ontology (OBIws) is an ontology that extends the Ontology for Biomedical Investigations (OBI) to build an Ontology that supports consistent annotation of Bioinformatics Web services. ', 'Other', 'OWL', 2, 'Release v1.1', '2012-12-18T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/OBIWS', '8e04cf8ca45c5c08167c4b21748da5ef1bad4accb351e8a416e9d6a5358f5968', 'scored', NULL, 10.0, 5.29, 5.29, 'same_as_strict (1.0 result, not re-checked)', 3.51, 9.0, 6.95, 6.95, NULL, NULL, NULL, 3653, 262, 228, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:29+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OBI_BCGO', 'Beta Cell Genomics Ontology', 'Beta Cell Genomics Ontology (BCGO) is an application ontology built for the Beta Cell Genomics database (http://genomics.betacell.org/gbco/) aiming to support database annotation, complicated semantic queries, and automated cell type classification. The ontology is developed using Basic Formal Ontology (BFO) as upper ontology, Ontology for Biomedical Investigations (OBI) as ontology framework and integrated subsets of multiple OBO Foundry (candidate) ontologies. Current the BCGO contains 2383 classes including terms referencing to 24 various OBO Foundry ontologies including CL, CLO, UBERON, GO, PRO, UO, etc.', '', 'OWL', 14, '2015-07-08', '2015-08-20T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OBI_BCGO', '3e1ffaf658b807e8b61d04238144abddf70c8543bcb29aaf074d8fc099ab3446', 'scored', NULL, 10.0, 6.16, 6.16, 'same_as_strict (1.0 result, not re-checked)', 2.99, 10.0, 7.2875, 7.2875, NULL, NULL, NULL, 33000, 2314, 2270, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:12:50+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OBI_IEE', 'The Ontology for Biomedical Investigation based Inner Ear Electrophysiology ', 'Inner Ear Electrophysiology (IEE) is an application ontology created to describe electrophysiology and biophysical data collections of the anatomical entities and cells (e.g., outer hair cells) of the inner ear.  The ontology is developed with The Ontology for Biomedical Investigations (OBI) and integrated subsets of multiple OBO ontologies, especially, PATO, FMA, CHEBI, and OBA.', '', 'OWL', 1, '2018-05-23', '2019-08-31T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OBI_IEE', 'b6e16d0aa630458d09128104df795572ffc9d026550452b790166b5ef6aa38ad', 'scored', NULL, 10.0, 6.44, 6.44, 'same_as_strict (1.0 result, not re-checked)', 3.24, 10.0, 7.42, 7.42, NULL, NULL, NULL, 66582, 3803, 3507, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:17:16+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OBOE', 'The Extensible Observation Ontology', 'The Extensible Observation Ontology (OBOE) is a formal ontology for capturing the semantics of scientific observation and measurement. The ontology supports researchers to add detailed semantic annotations to scientific data, thereby clarifying the inherent meaning of scientific observations. The main concepts in OBOE include:

- Observation: an event in which one or more measurements are taken
- Measurement: the measured value of a property for a specific object or phenomenon (e.g., 3.2)
- Entity: an object or phenomenon on which measurements are made (e.g., Quercus rubrum)
- Characteristic: the property being measured (e.g., VolumetricDensity)
- Standard: units and controlled vocabularies for interpreting measured values (e.g., g/cm^3)
- Protocol: the procedures followed to obtain measurements (e.g., DensityProtocol2014)

OBOE can characterize the context of an observation (e.g., space and time), as well as dependencies such as nested experimental observations. It includes an extensive set of unit definitions (e.g., grams of carbon per liter of seawater), and can facilitate automatic unit conversions (e.g., pounds to kilograms). OBOE can be easily extended to create Entities and Characteristics for specific research domains, making it both broadly applicable and highly customizable.

OBOE is being used to improve data interpretation, facilitate reuse, and create precise and effective systems for data search and discovery.', '', 'OWL', 4, 'Version 1.2', '2019-09-17T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OBOE', '699bbafdddca1f95683b55b3ef6ee677917a30b0905415594bd4061b35933709', 'scored', NULL, 10.0, 1.18, 1.18, 'same_as_strict', 6.1, 10.0, 6.82, 6.82, NULL, NULL, NULL, 5395, 292, 292, '0.10.0', 'core4-1.1', 'cuda', '2026-09-23T21:59:09+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OBOE-SBC', 'Santa Barbara Coastal Observation Ontology', 'Extensible Observation Ontology for the Santa Barbara Coastal Long Term Ecological Research project (SBC-LTER).
OBOE SBC extends core concepts defined in the OBOE suite that are particular to the Santa Barbara Coastal Long Term Ecological Research project''s data collection activities. These include specific measurement protocols, sites, etc. This is mean as a case study ontology for the Semtools project.', 'Other', 'OWL', 1, 'Version 1.0', '2010-08-12T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/OBOE-SBC', '4d477031fc89acafe0ec671827a0a15c8edc4dd5a1dcc65cfe2000ae4c7d9d08', 'scored', NULL, 10.0, 1.08, 1.08, 'same_as_strict (1.0 result, not re-checked)', 2.88, 10.0, 5.99, 5.99, NULL, NULL, NULL, 7144, 631, 631, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:53+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OBOREL', 'Relations Ontology', 'A collection of relations intended primarily for standardization across ontologies in the OBO Foundry and wider OBO library. It incorporates ROCore upper-level relations such as part of as well as biology-specific relationship types such as develops from., The OBO Relations Ontology (RO) is a collection of OWL relations (ObjectProperties) intended for use across a wide variety of biological ontologies.', '', 'OWL', 46, '2026-09-04', '2026-09-07T18:08:33.000-07:00', 'https://bioportal.bioontology.org/ontologies/OBOREL', '4866f7ff148ec8c3d0f1fae5357dde68bec3bccd1c719f62db9596ccb9f513fa', 'scored', NULL, 9.84, 5.15, 5.15, 'same_as_strict (1.0 result, not re-checked)', 5.67, 8.0, 7.165, 7.165, NULL, NULL, NULL, 11776, 62, 60, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:59+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OBS', 'OntoBioStat', 'Application ontology for covariate selection support. ', '', 'OWL', 5, NULL, '2022-12-19T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OBS', '77deec7a93f1ef4ca75c5db33e214719d892b7ea57fd14c91af1d59ee217f29c', 'scored', NULL, 6.48, 0.76, 0.76, 'same_as_strict (1.0 result, not re-checked)', 6.25, 10.0, 5.8725, 5.8725, NULL, NULL, NULL, 2662, 88, 58, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:32+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OCCO', 'Occupation Ontology', 'This Occupaton Ontology (OccO) is an ontology in the domain of human occupations. Current OccO version is developed based on the US Bureau of Labor Statistics Standard Occupation Classification (SOC) and the related O*Net System. The OccO development follows the principles of the Open Biological and Biomedical (OBO) Foundry.', 'Human;Other', 'OWL', 5, '2023-08-20', '2023-09-01T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OCCO', '9309b7be5a8247aa48954eb074153b31c8e95eb6ca1fd532d42a893702269f4b', 'scored', NULL, 10.0, 4.55, 4.55, 'same_as_strict (1.0 result, not re-checked)', 4.32, 10.0, 7.2175, 7.2175, NULL, NULL, NULL, 76415, 1787, 1769, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:16:13+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OCD', 'Obsessive-Compulsive Disorder Ontology', 'A comprehensive ontology for Obsessive-Compulsive Disorder (OCD) developed at Cardiff University. The ontology defines 80 OCD-specific concepts with formal Description Logic definitions, integrates eleven existing biomedical ontologies through five documented reuse strategies, and provides systematic lexical enrichment of both concepts and object properties using the OntoLex-Lemon model. Developed using a two-stage human–machine methodology combining expert clinical validation with large language model benchmarking., and provides systematic lexical enrichment of both concepts and object properties using the OntoLex-Lemon model. Developed using a two-stage human-machine methodology combining expert clinical validation with large language model benchmarking., Generated by combining 458 base triples, 3020 lexical enrichment triples, and 9387 external mapping triples.', 'Biomedical_Resources;Health;Taxonomic_Classification', 'OWL', 11, '1.2', '2025-07-29T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OCD', 'e6f77d3e88524158a68f2e6bdd161f779d36a9f05c7bd3f2a1526045ff710b3b', 'scored', NULL, 10.0, 0.19, 0.19, 'same_as_strict (1.0 result, not re-checked)', 0.1, 10.0, 5.0725, 5.0725, NULL, NULL, NULL, 14321, 2447, 105, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:10:44+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OCDM', 'Ontology of Craniofacial Development and Malformation', 'The Ontology of Craniofacial Development and Malformation (OCDM) is a mechanism for representing knowledge about craniofacial development and malformation, and for using that knowledge to facilitate integrating craniofacial data obtained via multiple techniques from multiple labs and at multiple levels of granularity. The OCDM is a project of the NIDCR-sponsored FaceBase Consortium, whose goal is to promote and enable research into the genetic and epigenetic causes of specific craniofacial abnormalities through the provision of publicly accessible, integrated craniofacial data. ', 'Anatomy;Development', 'OWL', 8, '1.10.0', '2023-11-08T18:10:42.000-08:00', 'https://bioportal.bioontology.org/ontologies/OCDM', 'b8137167c67c7d3898382476615de1924f3161069177815ef3964b3bc5b3b80a', 'empty', NULL, 0.0, 0.0, 0.0, 'same_as_strict', 0.0, 0.0, 0.0, 0.0, NULL, NULL, NULL, 14, 0, 0, '0.10.0', 'core4-1.1', NULL, '2026-09-23T21:58:04+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OCE', 'Ontology of Chemical Elements', 'The Ontology of Chemical Elements (OCE) is a community-based ontology in the domain of chemical elements. OCE systematically represents and annotates the known 118 chemical elements and their charactistics and relations with other entities. OCE imports the basic chemical element information from ChEBI and adds more classes, annotations, and axioms. OCE specifically focuses on adding all the related information from the Periodic Table of Chemical Elements. ', 'Physicochemical', 'OWL', 2, 'Vision Release: 1.0.29', '2020-02-28T18:11:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/OCE', 'c3857faace189a0aabd48369c42582ae27ca7026109358e8120a33334f260be5', 'scored', NULL, 9.96, 3.18, 3.18, 'same_as_strict (1.0 result, not re-checked)', 3.14, 10.0, 6.57, 6.57, NULL, NULL, NULL, 6179, 250, 250, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:30+00:00', '2026-09-23T23:25:10+00:00');
