INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OCIMIDO', 'Ocular Immune-Mediated Inflammatory Diseases Ontology', 'Application ontology for Ocular Immune-mediated Inflammatory Diseases, built from domain experts in ophthalmology, clinical guidelines, and enhanced with patient-preferred terms.', 'Phenotype', 'OWL', 2, '1.2', '2020-07-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OCIMIDO', '4a08d65b3e2e5c80772cf49919882390a9d736c35f5e032447d7f9de6d30d633', 'scored', NULL, 9.98, 2.91, 2.91, 'same_as_strict (1.0 result, not re-checked)', 7.7, 10.0, 7.6475, 7.6475, NULL, NULL, NULL, 8142, 662, 662, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:08+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OCMR', 'Ontology of Chinese Medicine for Rheumatism', 'OCMR is a biomedical ontology that represents anti-rheumatism traditional Chinese medicines and related information.', 'Health;Human', 'OWL', 3, 'Vision Release; 1.0.11', '2017-04-20T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OCMR', '4fd13bee0180ff2096be9040ec566c42fbbde66c090e90b93196b1797d04e488', 'scored', NULL, 10.0, 5.57, 5.57, 'same_as_strict (1.0 result, not re-checked)', 5.9, 10.0, 7.8675, 7.8675, NULL, NULL, NULL, 90161, 3369, 3360, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:19:28+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OCO', 'OpenCareOntology ', 'Open healthCare Ontology (OpenCare) is an integrated metadata vocabulary expressed as an ontological data model, to facilitate the effective reasoning of patient-specific electronic health record (EHR) data. The OpenCare model identifies the concepts and semantic types in the EHR data with the aim of enabling the representation of clinical data in a way that is accessible and usable by researchers and healthcare facility users. The development of OpenCare and its components is formalized using the Ontology Web Language (OWL). This framework aims to enhance the accessibility and user-friendliness of EHR clinical data.', 'Biomedical_Resources;Health;Vocabularies', 'OWL', 2, '1.1', '2023-05-05T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OCO', 'afb86db09b38accfde8e04780c4f97e222512c0461cc0fb28a30728e8fbb5209', 'scored', NULL, 5.04, 2.7, 2.7, 'same_as_strict (1.0 result, not re-checked)', 2.94, 10.0, 5.17, 5.17, NULL, NULL, NULL, 3171, 389, 196, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:46+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OCRE', 'Ontology of Clinical Research', 'OCRe is an ontology designed to support systematic description of, and interoperable queries on, human studies and study elements.', 'Biomedical_Resources', 'OWL', 23, 'Revision 315', '2013-06-21T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/OCRE', 'f1ab8937f15c30fa1d4edcb56f3b54cf90943e2512f2a17d1b9c6a1bd7c53815', 'scored', NULL, 10.0, 5.15, 5.15, 'same_as_strict (1.0 result, not re-checked)', 2.77, 10.0, 6.98, 6.98, NULL, NULL, NULL, 5901, 428, 389, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:38+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OCS', 'A Foundational Ontology for Computational Sociology', 'OCS (Ontology for Computational Sociology) is the first formal ontology covering the general domain of sociology. Built on BFO 2020, it comprises 701 classes (665 domain + 36 BFO), 254 object properties with explicit inverses, 78 data properties, and 201 n-ary causal relations modelling complex multi-factorial sociological causation through a systematic reification pattern. The ontology spans social structures, institutions, processes, stratification, deviance, cultural systems, and research methodology. A web-based browser, full Java development pipeline (DBFOschemafy), and all source materials are freely available. ', 'Other;Upper_Level_Ontology', 'OWL', 4, NULL, '2025-10-14T18:11:29.000-07:00', 'https://bioportal.bioontology.org/ontologies/OCS', 'd59678d05e8d0bd87968240f821f3baccfa9d45c2b2c38cda7f7c1e339fef1ce', 'scored', NULL, 9.98, 6.91, 6.91, 'same_as_strict (1.0 result, not re-checked)', 7.91, 10.0, 8.7, 8.7, NULL, NULL, NULL, 10530, 1640, 702, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:11:27+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OCVDAE', 'Ontology of Cardiovascular Drug Adverse Events', 'OCVDAE is a biomedical ontology of cardiovascular disease drug-associated adverse events', '', 'OWL', 2, 'Vision Release; 1.0.4', '2016-12-29T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OCVDAE', 'efab28b7eb51933a336249e8a6dc2f35f6f8eeec9af3cf8b45f4ca22b36a0302', 'scored', NULL, 10.0, 3.86, 3.86, 'same_as_strict (1.0 result, not re-checked)', 5.09, 10.0, 7.2375, 7.2375, NULL, NULL, NULL, 96299, 2949, 2949, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:18:57+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OC_E', 'OntoCaimer_Examples', 'This version of ontocaimer contains instantiated examples of patients, sensors, and actuators.
OntoCaimer is an ontology that aims to support the development of systems that support and facilitate the care of Alzheimer''s patients. This ontology offers a platform that contains concepts related to the support and management of the symptoms suffered by Alzheimer''s patients in each of stage of disease, also encompasses knowledge about sensors, observations and actuators. With these knoledge covered, the proposed system can be used as a knowledge base or as a basis for creating artifacts that can interact with the real world.
', '', 'OWL', 1, NULL, '2025-09-25T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OC_E', '64544d3fbb9580ae3e7bf17259bde475f4e6f12892b4f2cf5e4d9c5410dfbda8', 'scored', NULL, 2.13, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 7.84, 7.0, 4.2425, 4.2425, NULL, NULL, NULL, 2316, 211, 46, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:06:06+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ODAE', 'Ontology of Drug Adverse Events', 'The Ontology of Drug Adverse Events (ODAE) is a biomedical ontology in the area of drug adverse events, developed by following OBO Foundry principles (e.g., openness, collaboration). ', 'Health', 'OWL', 1, 'Vision Release: 1.0.08', '2019-01-12T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ODAE', 'c87dbdd2164d41b5393b792812d9c8568e0409983751a4ffe3c09c971eb99ee2', 'scored', NULL, 10.0, 2.52, 2.52, 'same_as_strict (1.0 result, not re-checked)', 2.98, 10.0, 6.375, 6.375, NULL, NULL, NULL, 179592, 3673, 3673, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T03:26:35+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ODENTIFYHUMAN', 'Ontology for Forensic Human Identification by Dental Evidence and Source Conclusions', 'The ODentifyHuman ontology provides a comprehensive semantic representation for forensic human identification by dental evidence. It formalizes the terminology, data elements, and relationships used in ante-mortem and post-mortem dental records and forms, including dental status, anatomical variations, treatments, prostheses and appliances, imaging findings, and other individualizing features.

The ontology supports ante-mortem and post-mortem comparison, the assessment of concordant features, discrepancies and exclusions, the reconciliation process, and the formulation and reporting of source conclusions. By organizing these concepts into machine-readable hierarchies and semantic relationships, ODentifyHuman promotes semantic interoperability, structured data exchange, transparent assessment processes, and consistent reporting in forensic odontology and disaster victim identification.

ODentifyHuman is a work in progress designed to support terminology harmonization within the subject domain addressed by ISO/PRF 21611, Dentistry — Vocabulary for Source Conclusion for Human Identification by Dental Evidence, and related forensic odontology standards and practices.', 'Biomedical_Resources;Health;Human;Imaging;Vocabularies', 'OWL', 1, NULL, '2026-08-25T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ODENTIFYHUMAN', NULL, 'not_downloadable', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ODFA', 'Ontology of Dental Care-Related Fear and Anxiety', 'The Ontology of Dental care-related Fear, Anxiety, and/or Phobia (ODFA) contains terms for defining and classifying dental-care related fear, anxiety, and/or phobia (DFA). The ODFA’s concepts and relations facilitate the development of tools and resources capable of enhancing our understanding of the impacts of DFA, and when applied to study data, the ODFA enables the integration and interoperability of data from multiple studies.

The ODFA is developed as a subset of the Oral Health and Disease Ontology (http://purl.obolibrary.org/obo/ohd.owl). Issues and new term requests can be submitted at https://github.com/oral-health-and-disease-ontologies/ohd-ontology/issues., the ODFA enables the integration and interoperability of data from multiple studies.

The ODFA is developed as a subset of the Oral Health and Disease Ontology (http://purl.obolibrary.org/obo/ohd.owl). Issues and new term requests can be submitted at https://github.com/oral-health-and-disease-ontologies/ohd-ontology/issues.', 'Health', 'OWL', 6, '2026-04-03', '2026-04-09T18:16:30.000-07:00', 'https://bioportal.bioontology.org/ontologies/ODFA', 'eede2b2a66fd3b0124d4c249009b976e10ba49c01dedd371416ae4f75b84e1c1', 'scored', NULL, 9.96, 6.61, 6.61, 'same_as_strict (1.0 result, not re-checked)', 5.68, 9.0, 7.8125, 7.8125, NULL, NULL, NULL, 5013, 238, 238, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:59+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ODHT', 'Digital Health Technologies', 'This is an ontology of digital health technologies (DHTs) with a specific focus on DHT use in clinical trials. It was created as part of a collaborative project between Prism.Bio and Janssen Clinical Innovation on digital sustainability for the clinical trials enterprise.', 'Health', 'OWL', 2, '0.2', '2022-08-30T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ODHT', 'a10a1fe417c786b6b5f560c35378fd4a773ba6ec76a19a3a2a4898fefc68a050', 'scored', NULL, 9.99, 0.31, 0.31, 'same_as_strict (1.0 result, not re-checked)', 7.72, 8.0, 6.505, 6.505, NULL, NULL, NULL, 4870, 813, 40, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:09+00:00', '2026-09-23T23:25:10+00:00');
