INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OF', 'OntoFood', 'This is an ontology with SWRL rules of nutrition for diabetic patient. We can import the value of Blood Sugar and Weight by .xls and use that like instance for generate the rules with rule engine Jess.', 'Biological_Process;Health', 'OWL', 1, '1.0', '2015-12-26T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OF', '63c9180ab6f154531fe70d4c5d08fff45c1efa9e362f95348c0d9a9b938a1a1d', 'scored', NULL, 5.67, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 1.33, 10.0, 4.25, 4.25, NULL, NULL, NULL, 7564, 522, 293, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:08:29+00:00', '2026-09-23T23:25:10+00:00');
