INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OGCO', 'OriGinal Chemical Ontology', 'The Original Chemical Ontology was developed by Michael Ashburner & Pankaj Jaiswal in 2002, before development shifted to CHEBI. It was revived by Chris Mungall for purposes of comparison with the current CHEBI and CHEMESSENCE', 'Chemical', 'OWL', 1, NULL, '2025-01-09T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OGCO', 'c2d33239e01f88baa8859b30fa9a1d20297fdc7d9c1368f873e03082712b37f4', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 5.0, 5.0, NULL, NULL, NULL, 56180, 8777, 8777, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:13:59+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OGDI', 'Ontology for Genetic Disease Investigations', 'It is the ontology used to model the scientific investigation, especially  Genome-Wide Association Study (GWAS),  to find out  genetic susceptibility factor to disease, such as Diabetes. It models the genetic varaints, polymorphisms, statistical measurement, populations and other elements that are essential to determine a genetic susceptibility factor in GWAS study. It must be used with other two ontologies, in the case of Diabetes, :Ontology of Geographical Region (OGR) and Ontology of Glucose Metabolism Disorder (OGMD) .', 'Experimental_Conditions', 'OWL', 3, '1.0', '2013-01-30T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/OGDI', '6c42185c8ba2bd9cf7658e194d705b141157a67303933859f7330c74561c1ff1', 'scored', NULL, 5.45, 1.0, 1.0, 'same_as_strict (1.0 result, not re-checked)', 5.23, 10.0, 5.42, 5.42, NULL, NULL, NULL, 4131, 751, 386, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:02+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OGG', 'Ontology of Genes and Genomes', 'OGG is a biological ontology in the area of genes and genomes. OGG uses the Basic Formal Ontology (BFO) as its upper level ontology. This OGG document contains the genes and genomes of a list of selected organisms, including human, two viruses (HIV and influenza virus), and bacteria (B. melitensis strain 16M, E. coli strain K-12 substrain MG1655, M. tuberculosis strain H37Rv, and P. aeruginosa strain PAO1). More OGG information for other organisms (e.g., mouse, zebrafish, fruit fly, yeast, etc.) may be found in other OGG subsets.', 'Gene_Product;Genomic_and_Proteomic;Human', 'OWL', 3, 'Vision Release: 1.0.59', '2016-12-02T18:08:15.000-08:00', 'https://bioportal.bioontology.org/ontologies/OGG', '16dd5e54b68b222561e79e21b90ae4a954b794df3e52906bb7c5345f38ab21b0', 'scored', NULL, 10.0, 2.08, 2.08, 'same_as_strict (1.0 result, not re-checked)', 0.02, 10.0, 5.525, 5.525, NULL, NULL, NULL, 1280798, 69690, 69690, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T07:11:30+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OGG-MM', 'Ontology of Genes and Genomes - Mouse', 'OGG-Mm is the OGG Mus musculus (mouse) subset. The OGG (Ontology of Genes and Genomes) is a formal ontology of genes and genomes of biological organisms. OGG is developed by following OBO Foundry principles and aligning with the BFO top ontology. ', 'Biomedical_Resources;Genomic_and_Proteomic;Molecule', 'OWL', 5, 'Vision Release: 1.0.66', '2018-03-23T18:09:51.000-07:00', 'https://bioportal.bioontology.org/ontologies/OGG-MM', '87d20df8946eaeb83cdbb653e635946440fce4ecfe5a5c5a76dcefdcfde59dde', 'scored', NULL, 10.0, 2.18, 2.18, 'same_as_strict (1.0 result, not re-checked)', 0.01, 10.0, 5.5475, 5.5475, NULL, NULL, NULL, 1299105, 69434, 69434, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T03:29:41+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OGI', 'Ontology for Genetic Interval', 'Using BFO as its framwork, OGI formalized the genomic element by defining an upper class ''genetic interval''.

The definition of ''genetic interval'' is "the spatial continuous physical entity which contains ordered genomic sets(DNA, RNA, Allele, Marker,etc.) between and including two points (Nucleic_Acid_Base_Residue) on a chromosome or RNA molecule which must have a liner primary sequence sturcture.', 'Genomic_and_Proteomic', 'OWL', 18, '2.0', '2015-08-20T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OGI', '9b8d1e490d465a4e99c4f5ac8f8d0635347dc0f5f5f8c14fff622cde443fe4f2', 'scored', NULL, 8.96, 1.59, 1.59, 'same_as_strict (1.0 result, not re-checked)', 4.43, 9.0, 5.995, 5.995, NULL, NULL, NULL, 2661, 202, 184, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:15+00:00', '2026-09-23T23:25:10+00:00');
