INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ONTODM-CORE', 'Ontology of Core Data Mining Entities', 'OntoDM is a generic ontology for the domain of data mining. The ontology includes the information processing processes that occur in the domain of data mining, participants in the processes and their specifications. OntoDM is highly transferable and extendable due to its adherence to accepted standards, and compliance with existing ontology resources. The generality in scope allows wide number of applications of the ontology, such as semantic annotation of data mining scenarios, ontology based support for QSARs, etc.', '', 'OWL', 9, '2.0', '2024-03-04T18:12:37.000-08:00', 'https://bioportal.bioontology.org/ontologies/ONTODM-CORE', '6ae2d3f0fde51129562f7dab11ec8b879da52b530d40d940f28a3a2b9469fbda', 'scored', NULL, 10.0, 2.04, 2.04, 'same_as_strict (1.0 result, not re-checked)', 5.82, 9.0, 6.715, 6.715, NULL, NULL, NULL, 21719, 1751, 1729, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:10:36+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ONTODM-KDD', 'Ontology of Data Mining Investigations', 'OntoDM-KDD is an ontology for representing data mining investigations. Its goal is to allow the representation of knowledge discovery processes and be general enough to represent the data mining investigations. The ontology is based on the CRISP-DM process methodology.', '', 'OWL', 1, '0.1', '2012-06-06T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/ONTODM-KDD', '19e79162c135c778282410d6ba8f96d10b9a521ca6ce6f1181dd56ee90a1c230', 'scored', NULL, 9.92, 1.55, 1.55, 'same_as_strict (1.0 result, not re-checked)', 7.14, 9.0, 6.9025, 6.9025, NULL, NULL, NULL, 3210, 264, 264, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:20+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ONTODT', 'Ontology of Datatypes', 'This ontology contains entities such as: datatype, datatype generator, datatype qualiy and others giving the possibility to represent arbitrary complex datatypes. This is an important fact for a general data mining ontology that wants to represent and query over modelling algorithms for mining structured data. 

The ontology was first developed under the OntoDM (Ontology of Data Mining is available at http://kt.ijs.si/panovp/OntoDM) ontology, but for generality and reuse purpose it was decided to export it as a separate ontology. Additionaly, the OntoDT ontology is based on and ISO/IEC 11404 (http://www.iso.org/iso/catalogue_detail.htm?csnumber=39479) standard and can be reused used independently by any domain ontology that requires representation and reasoning about general purpose datatypes.', '', 'OWL', 9, '2.0', '2024-03-04T18:12:44.000-08:00', 'https://bioportal.bioontology.org/ontologies/ONTODT', '867d1e3d6e3e15e9610ad05df350884ff1954f17abb8a11d50643d9d9fe50e32', 'scored', NULL, 10.0, 0.87, 0.87, 'same_as_strict (1.0 result, not re-checked)', 4.9, 9.0, 6.1925, 6.1925, NULL, NULL, NULL, 4310, 377, 377, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:27+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ONTOKBCF', 'Ontological Knowledge Base Model for Cystic Fibrosis', 'OntoKBCF is an ontological knowledge base model for cystic fibrosis. There are molecular genetic information (i.e. gene mutations) and health information included in OntoKBCF. The purposes of OntoKBCF include management of molecular genetic information and health information and embedding OntoKBCF into EHR settings.', 'Biomedical_Resources;Gene_Product;Health;Phenotype', 'OWL', 3, '1301', '2013-01-14T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/ONTOKBCF', '54ac8ab9a2bcecf945739597c93494a3f4b6acb1fa1b84b5fbd9dbfa46b94ca0', 'scored', NULL, 9.98, 4.07, 4.07, 'same_as_strict (1.0 result, not re-checked)', 2.2, 9.0, 6.3125, 6.3125, NULL, NULL, NULL, 3366, 409, 409, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:38+00:00', '2026-09-23T23:25:10+00:00');
