INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ONTRISCAL', 'Ontology of Risk Stratification in Mental Health', 'This ontology organizes concepts and properties of risk stratification in mental health. Stratification aims to determine the patient''s risk level by scoring signs and symptoms. Psychotherapeutic treatments aim to minimize patient risk by producing qualitative data reported in therapeutic sessions. Thus, the ONTRISCAL is applied in projects that organize the knowledge about quali-quanti data produced by risk stratification and mental health treatments. Quali-quanti data, semantically annotated by ONTRISCAL, can be ingested into knowledge graphs. Domain specialists can use knowledge graphs to navigate the ONTRISCAL concepts, analyze psychotherapeutic treatments, and control risks in mental health. This is a non-profit and open-source project.', 'Biomedical_Resources;Health;Human;Neurological_Disorder', 'OWL', 1, '1.0', '2023-12-27T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ONTRISCAL', 'd49d383d84f8ed969a1495903aefba266191db53044be49466b73c04e1f10c10', 'scored', NULL, 9.97, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 5.57, 10.0, 6.385, 6.385, NULL, NULL, NULL, 1926, 333, 333, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:05:33+00:00', '2026-09-23T23:25:10+00:00');
