INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OOEVV', 'Ontology of Experimental Variables and Values', 'The ontology of experimental variables and values provides a lightweight representation of (a) the variables used to measure experimental properties and (b) the measurement scales that form the complex data types supporting that data. Many different variables measure the same thing, here we use a lightweight representation driven by a small number of classes and a large number of variables to focus only on providing a vocabulary of variables that may be extended for consolidation to standardized variables for specific things and functions to map between values from different measurements scales. We use the base ontology description to provide a very lightweight representation of the basic elements of an experimental design and we use views to instantiate it for specific domains. ', 'Vocabularies', 'OWL', 4, '0.0.4', '2012-04-29T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/OOEVV', '3e195dab4e6b97dab17eb8021590eae1c713ba614f3523b3f9623972e23745cb', 'scored', NULL, 9.89, 4.96, 4.96, 'same_as_strict (1.0 result, not re-checked)', 3.23, 10.0, 7.02, 7.02, NULL, NULL, NULL, 1214, 87, 69, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:16+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OOSTT', 'Ontology of Organizational Structures of Trauma centers and Trauma systems', 'The Ontology of Organizational Structures of Trauma centers and Trauma systems (OOSTT) is a representation of the components of trauma centers and trauma systems coded in Web Ontology Language (OWL2). It is developed collaboratively by domain and ontology experts in the NIH-funded CAFE (Comparative Assessment Framework for Environments of trauma care) project (1R01GM111324-01A1). It will be used as the ontology backbone of a graphical user interface comparing graphical representations of organizational structures., The Ontology of Organizational Structures of Trauma centers and Trauma systems (OOSTT) is a representation of the components of trauma centers and trauma systems coded in Web Ontology Language (OWL2).', 'Health', 'OWL', 15, 'release version - 2026-09-10', '2026-09-10T18:11:24.000-07:00', 'https://bioportal.bioontology.org/ontologies/OOSTT', '99ab9cff2cd5d3076cefa4ea280eb4939911790ed08c6dc57b3f9a3fba846df7', 'scored', NULL, 10.0, 4.39, 4.39, 'same_as_strict (1.0 result, not re-checked)', 2.53, 10.0, 6.73, 6.73, NULL, NULL, NULL, 24210, 1661, 1220, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:10:59+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OPB', 'Ontology of Physics for Biology', 'The OPB is a reference ontology of classical physics and thermodynamics as applied to the dynamics of biological systems. It is designed to encompass the multiple structural scales (atoms to organisms) and multiple physical domains (fluid dynamics, chemical kinetics, particle diffusion, etc.) that are encountered in the study and analysis of biological organisms.', 'Biological_Process;Biomedical_Resources;Chemical;Phenotype;Physicochemical', 'OWL', 18, '1.2', '2023-01-09T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OPB', '1f4b949a25e8a8efc3807e834887941f1c51dbe52ec0e4d76b9d0d1702dca2db', 'scored', NULL, 10.0, 4.19, 4.19, 'same_as_strict (1.0 result, not re-checked)', 2.53, 10.0, 6.68, 6.68, NULL, NULL, NULL, 6115, 858, 858, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:41+00:00', '2026-09-23T23:25:10+00:00');
