INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OPE', 'Ontology of Physical Exercises', 'The Ontology of Physical Exercises (OPE) provides a reference for describing an exercise in terms of functional movements, engaged musculoskeletal system parts, related equipment or monitoring devices, intended health outcomes, as well as target ailments for which the exercise might be employed as a treatment or preventative measure. ', 'Anatomy;Health;Human;Other', 'OWL', 6, '0.0.1', '2013-03-13T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/OPE', '60bdd8a0cc6d6385dafef1c298a8601e3350f45dc288d15b16fc390ebea8e72a', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.14, 10.0, 5.035, 5.035, NULL, NULL, NULL, 4023, 634, 634, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:07:13+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OPL', 'Ontology for Parasite LifeCycle', 'The Ontology for Parasite LifeCycle (OPL) models the life cycle stage details of various parasites, including Trypanosoma sp., Leishmania major, and Plasmodium sp., etc. In addition to life cycle stages, the ontology also models necessary contextual details, such as host information, vector information, and anatomical location. OPL is based on the Basic Formal Ontology (BFO) and follows the rules set by the OBO Foundry consortium.', 'Development;Phenotype;Vocabularies', 'OWL', 11, '2023-08-28', '2023-08-31T18:14:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/OPL', 'df1e14a38be31d9087b6745fa5f88f8b8cf0cf174dfc1c97d4c8023a36f62a5a', 'scored', NULL, 10.0, 5.45, 5.45, 'same_as_strict (1.0 result, not re-checked)', 6.91, 10.0, 8.09, 8.09, NULL, NULL, NULL, 11761, 580, 561, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:36+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OPMI', 'Ontology of Precision Medicine and Investigation', 'The Ontology of Precision Medicine and Investigation (OPMI) is an application ontology to support precision medicine and its related investigations. OPMI is community-driven and developed by following the OBO Foundry ontology development principles. OPMI reuses, aligns, and integrates related terms from existing OBO ontologies.  ', 'Health', 'OWL', 27, 'Vision Release: 1.0.166', '2024-03-16T18:11:42.000-07:00', 'https://bioportal.bioontology.org/ontologies/OPMI', 'c73283bb0f5c144d566ce0189f8f920b73da8486e261eb11f9bba4d76cffe334', 'scored', NULL, 10.0, 2.8, 2.8, 'same_as_strict (1.0 result, not re-checked)', 7.98, 10.0, 7.695, 7.695, NULL, NULL, NULL, 45225, 3175, 3153, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:14:19+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OPTIMAL', 'OPTImAL: An ontology for patient adherence modeling in physical activity domain', 'OPTImAL is a reusable formal model of factors affecting CVD patient adherence to physical activity and exercise. The basis for this model relies on the analysis of data/evidence published in the scientific literature and enables identification of adherence based on the patient profile. In the model, the patient profile is seen from the perspective of 60 multidimensional aspects (320 factors). Each factor is associated with defined adherence to a particular patient activity behavior.', 'Health;Taxonomic_Classification', 'OWL', 1, '1', '2019-03-28T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OPTIMAL', 'a1405ac4da65e3d0e1dd3e55b0f8edfdcaf5455709a7e383f167e6b20f269c06', 'scored', NULL, 0.19, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 7.26, 9.0, 4.1125, 4.1125, NULL, NULL, NULL, 21219, 513, 142, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:10:08+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OPTION-ONTOLOGY', 'Optimization Algorithm Benchmarking Ontology', 'OPTImization Algorithm Benchmarking ONtology', 'Other', 'OWL', 3, '1.0.0', '2021-04-12T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OPTION-ONTOLOGY', 'e2149712e64e7b7a6700f5b97281dd4df91f92e4a2b1abf58b0a16e7681a3769', 'scored', NULL, 9.78, 5.39, 5.39, 'same_as_strict (1.0 result, not re-checked)', 3.73, 10.0, 7.225, 7.225, NULL, NULL, NULL, 5626, 370, 347, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:38+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ORCS', 'Ontology for Representing CDM Semantics', 'The Ontology for Representing CDM Semantics (ORCS) is an application ontology that was developed to transform common-data-model-based data into ontologically-based data such as RDF, RDF*, OWL2, or Referent Tracking tuples.  Although initially developed for such transformations of PCORnet Common Data Model (CDM) based data, ongoing and future work involves other CDMs such as OMOP.', 'Health', 'OWL', 1, '2021-11-13', '2021-11-18T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ORCS', '26d1d931475534815dd442c92887915b7be2baf11e8eb3708bff94b0b5d0bf70', 'scored', NULL, 10.0, 5.05, 5.05, 'same_as_strict (1.0 result, not re-checked)', 2.94, 10.0, 6.9975, 6.9975, NULL, NULL, NULL, 20272, 914, 861, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:10:43+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ORDO', 'Orphanet Rare Disease Ontology', 'The Orphanet Rare Disease ontology (ORDO) is jointly developed by Orphanet and the EBI to provide a structured vocabulary for rare diseases capturing relationships between diseases, genes and other relevant features which will form a useful resource for the computational analysis of rare diseases. 

It derived from the Orphanet database (www.orpha.net <http://www.orpha.net>) , a multilingual database dedicated to rare diseases populated from literature and validated by international experts. It integrates a nosology (classification of rare diseases), relationships (gene-disease relations, epiemological data) and connections with other terminologies (MeSH, SNOMED CT, UMLS, MedDRA),databases (OMIM, UniProtKB, HGNC, ensembl, Reactome, IUPHAR, Geantlas) or classifications (ICD10). 

The ontology will be maintained by Orphanet and further populated with new data. Orphanet classifications can be browsed in the OLS view.

The Orphanet Rare Disease Ontology is updated twice a year and follows the OBO guidelines on deprecation of terms. It constitutes the official ontology of rare diseases produced and maintained by Orphanet (INSERM, US14). ', 'Biomedical_Resources;Health;Human;Phenotype;Vocabularies', 'OWL', 33, '4.9', '2013-06-20T12:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ORDO', '6b3b83b990c6f5102fd4785e10ff7b1c5bac259f0d88cf8e23ac2671bcc57109', 'scored', NULL, 10.0, 0.0, 3.02, 'http://www.ebi.ac.uk/efo/definition [bioportal_definitionProperty + detected_by_name]', 8.08, 10.0, 7.02, 7.775, NULL, NULL, NULL, 677217, 16297, 16297, '0.10.0', 'core4-1.1.1', NULL, '2026-09-23T22:58:38+00:00', '2026-09-23T23:25:10+00:00');
