INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ORNASEQ', 'Ontology of RNA Sequencing', 'This is an application ontology used to annotate next-generation sequencing experiments performed on RNA (RNAseq). It uses terms from BFO, CHEBI, CL, GENEPIO, GO, IAO, NCBITaxon, NCIT, OBI, OBIws, OGMS, OMIABIS, SO, TAXRANK, and UBERON as well as EFO.', 'Experimental_Conditions', 'OWL', 1, NULL, '2019-07-08T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ORNASEQ', 'adce02c0170a928e2ddfa6408849af516e5bd66a2b13eb8a135fa0dc2ddca716', 'scored', NULL, 10.0, 5.47, 5.47, 'same_as_strict (1.0 result, not re-checked)', 0.43, 9.0, 6.225, 6.225, NULL, NULL, NULL, 1415, 164, 164, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:37+00:00', '2026-09-23T23:25:10+00:00');
