INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OSDI', 'Ontology for the Simulation of Diseases', 'OSDi is an ontology designed to help the health technology assessment (HTA) community automate multiple stages in the development of economic evaluations. OSDi includes concepts and relationships that model the HTA domain, from characterizing diseases or affected populations to assessing interventions. OSDi serves as a supporting framework for the structured extraction of knowledge from literature and the automated generation of computational models using decision trees or discrete-event simulation., Ontología diseñada para recopilar e inferir los parámetros necesarios para crear una evaluación de tecnología sanitaria basada en simulación, Ontology designed for collecting and inferring the parameters required to create a simulation-based Health Technology Assesment', 'Health', 'OWL', 2, '1.0', '2026-01-16T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OSDI', 'ac0fcf4dae6ba5387fbfa9fadccdbfce52fa8b77929f0a40428bfac64e3593ac', 'scored', NULL, 8.95, 3.48, 3.48, 'same_as_strict (1.0 result, not re-checked)', 4.71, 10.0, 6.785, 6.785, NULL, NULL, NULL, 3010, 124, 83, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:07+00:00', '2026-09-23T23:25:10+00:00');
