INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OVAE', 'Ontology of Vaccine Adverse Events', 'The Ontology of Vaccine Adverse Events (OVAE) is a biomedical ontology in the area of vaccine adverse events. OVAE is an extension of the Ontology of Adverse Events (OAE) and the Vaccine Ontology (VO). OVAE is aimed to represent and analyze various vaccine-specific adverse events. ', 'Health;Human;Immunology;Phenotype', 'OWL', 10, 'Vision Release: 1.0.34', '2016-05-14T18:11:28.000-07:00', 'https://bioportal.bioontology.org/ontologies/OVAE', 'e35c780a64330ea33fdc197088966e4fae599270e859750e55d7b39ea87306a1', 'scored', NULL, 9.99, 5.62, 5.62, 'same_as_strict (1.0 result, not re-checked)', 6.94, 10.0, 8.1375, 8.1375, NULL, NULL, NULL, 50280, 1574, 1556, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:14:46+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'OntoVIP', 'Medical image simulation', 'The OntoVIP ontology was developed in the context of the Virtual Imaging Platform project (VIP), a french project supported by ANR (ANR-09-COSI-03 grant) aiming at sharing medical image simulation resources. 
This ontology describes the content of the models used in medical image simulation. This ontology can be used to annotate such models in order to highlight the different entities that are present in the 3D scene to be imaged, i.e. anatomical structures, pathological structures, foreign bodies, contrast agents etc. The model allows also to associate to these entities information about their physical qualities, which are used in the medical image simulation process (to mimick physical phenomena involved in CT, MR, US and PET imaging). This ontology partly relies on the OntoNeuroLOG ontology (ONL-DP ONL-MR-DA), as well as PATO, RadLex, FMA and ChEBI.', 'Imaging', 'OWL', 1, 'v1', '2013-07-12T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/OntoVIP', '848c34f788481dced295194ccace2ae72405f29a4ed70015de1d12b5c43b9764', 'scored', NULL, 9.44, 2.55, 2.55, 'same_as_strict (1.0 result, not re-checked)', 4.6, 10.0, 6.6475, 6.6475, NULL, NULL, NULL, 6154, 744, 702, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:21+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PACO', 'Physical Activity Ontology', 'Physical Activity Concept Ontology (PACO) contains various concepts that are required to describe one''s physical activity. ', 'Health;Human;Other', 'OWL', 2, '0.2', '2019-02-14T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PACO', '9f2ebcc8269bcc49f8f98f22b6f751b2a4656dd9921be5a4fa44ce2aeb39c4a0', 'scored', NULL, 7.94, 0.18, 0.18, 'same_as_strict (1.0 result, not re-checked)', 4.88, 10.0, 5.75, 5.75, NULL, NULL, NULL, 2622, 282, 225, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:14+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PAE', 'Plant Anatomy', 'REPLACED BY: Plant Ontology (PO). A controlled vocabulary of plant morphological and anatomical structures representing organs, tissues, cell types, and their biological relationships based on spatial and developmental organization. Note that this has been subsumed into the PO. This file is created by filtering plant_ontology_assert.obo to contain only terms from the plant anatomical entity branch of the PO. For more information, please see: http://palea.cgrb.oregonstate.edu/viewsvn/Poc/tags/live/', 'Plant;Plant_Anatomy', 'OBO', 13, 'Release #20', '2013-08-20T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PAE', 'e1a1450f62835c4d1cde6654b096f443d960f49fc931536e8abdaeb1b420c63e', 'scored', NULL, 9.99, 5.81, 5.81, 'same_as_strict (1.0 result, not re-checked)', 7.31, 10.0, 8.2775, 8.2775, NULL, NULL, NULL, 51618, 1549, 1549, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:15:22+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PAIN', 'The Pain Ontology', 'The Pain Ontology contains terms for representing pain as defined by the International Association For the Study of Pain (IASP), meaning that pain is both an unpleasant physical sensation and unpleasant emotional experience. It includes terms and axioms to represent the multidimensional aspect of pain, such as temporality (e.g, acute, chronic), qualitative (e.g., sharp, throbbing), extent (e.g., local, widespread), biological mechanism (e.g., nociceptive, neuropathic), and specific anatomical locations (e.g., back, knee)., such as temporality (e.g.', 'Biological_Process;Biomedical_Resources;Dysfunction;Health', 'OWL', 9, '2026-08-13', '2022-08-23T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PAIN', 'f2eccfd101e2425920034917fc4d4ff2c7e7c00043862d9bb36b5b7d4a4ec933', 'scored', NULL, 10.0, 6.16, 6.16, 'same_as_strict (1.0 result, not re-checked)', 7.14, 9.0, 8.075, 8.075, NULL, NULL, NULL, 9919, 289, 289, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:23+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PANDA', 'Probabilistic Knowledge Assembly Ontology', 'Probabilistic Knowledge Assembly (PANDA) Ontology has been developed in the context of the DARPA''s Big Mechanism research program. It provides a semantic interface for capturing information on molecular interactions extracted from scientific texts.', '', 'OWL', 2, '0.9', '2017-01-01T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PANDA', '75c59b2f490b07ccdef05646d133edebf98e091d3730e12fb143c80802b3d3d3', 'scored', NULL, 10.0, 1.55, 1.55, 'same_as_strict (1.0 result, not re-checked)', 0.64, 10.0, 5.5475, 5.5475, NULL, NULL, NULL, 558, 75, 75, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:40+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PANET', 'PaN Experimental technique', 'The PaNET ontology provides a taxonomy and thesaurus of photon and neutron (PaN) experimental techniques, based mainly on accelerator-based light sources and neutron facilities. The primary use of the ontology is to enhance the FAIRness of PaN data catalogues services. The ontology defines specific techniques in terms of more general technique classes and provides synonyms and references.', 'Other', 'OWL', 27, '1.3.0', '2025-10-21T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PANET', 'a352f3e383ead4f0e9ec0adc2a0d83595e414a40c397f3728e07cd3bce1749dd', 'scored', NULL, 9.98, 0.33, 0.33, 'same_as_strict (1.0 result, not re-checked)', 2.62, 10.0, 5.7325, 5.7325, NULL, NULL, NULL, 4384, 518, 508, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:28+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PARTUMDO', 'postpartum depression ontology', 'This ontology is for use in extracting postpartum depression condition codes, and also comorbidities and diseases often mistaken for postpartum depression. The ontology describes not only the codes but also the relationships between these various diseases/risk factors for use in automatically extracting relevant patient populations from Electronic Health Records', 'Human;Neurologic_Disease;Neurological_Disorder;Phenotype;Vocabularies', 'OWL', 1, NULL, '2021-07-08T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PARTUMDO', '76ece8931a1f824a523f608c796a4f15cc8d3056c23176b6ff31334c936828e8', 'scored', NULL, 8.72, 5.94, 5.94, 'same_as_strict (1.0 result, not re-checked)', 7.1, 10.0, 7.94, 7.94, NULL, NULL, NULL, 32567, 5578, 734, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:14:14+00:00', '2026-09-23T23:25:10+00:00');
