INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PATGV', 'Placental Genetic Variance', 'Includes variations of DNA sequence, chromosomal structure and copy number, as well as RNA and translational variation. The Genetic Variation ontology expands on work done for Variation Ontology (VariO) and Sequence Types and Features Ontology (SO) which can be found on NCBO. This ontology was further developed by PAT External Scientific Panel Members and contributions from other subject matter experts.', 'Genomic_and_Proteomic', 'OWL', 1, '1.0', '2020-01-13T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PATGV', 'b00b6e7463e1affdddb340661565cd40a12c48e6372e81f31cc5a6180d4e8e76', 'scored', NULL, 10.0, 5.25, 5.25, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 6.3125, 6.3125, NULL, NULL, NULL, 2093, 73, 73, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:25+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PATHLEX', 'Anatomic Pathology Lexicon', 'PathLex, a comprehensive lexicon—a unified language of anatomic pathology terms—for standardized indexing and retrieval of anatomic pathology information resources. ', 'Anatomy;Health;Taxonomic_Classification;Vocabularies', 'OWL', 5, '1.2', '2013-01-22T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/PATHLEX', 'cdcbcc7cbce3fbe17ebcba30b6e040d5431da000ff151d0e049479a0092e8931', 'scored', NULL, 10.0, 7.32, 7.32, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 6.83, 6.83, NULL, NULL, NULL, 7182, 1786, 1786, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:44+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PATIT', 'Placental Investigative Technique', 'Experimental methods and observation types used in placental research. The PAT Investigative Techniques ontology builds on work done for a handful of existing ontologies, including the Ontology for Biomedical Investigations (OBI) and NCI Thesaurus (NCIT), and was further developed by PAT External Scientific Panel Members and contributions from other subject matter experts.', 'Other', 'OWL', 1, '1.0', '2020-01-13T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PATIT', 'f8df5cfb635dbbd2b670766af1eff5ab5fe88919a3a6a85fd2e61006be174cca', 'scored', NULL, 10.0, 4.21, 4.21, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 6.0525, 6.0525, NULL, NULL, NULL, 2731, 139, 139, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:52+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PATMHC', 'Placental Maternal Health Conditions', 'Physical and psychological disorders in the mother that occur during pregnancy, childbirth, and the postpartum period. These include both pre-existing and gestational maternal health conditions that may result in adverse pregnancy outcomes. The Maternal Conditions Ontology builds on the work done for a handful of existing ontologies, including the Human Phenotype Ontology (HPO) and NCI Thesaurus (NCIT), and was further developed by PAT External Scientific Panel Members and contributions from other subject matter experts.', 'Health', 'OWL', 1, '1.0', '2020-01-13T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PATMHC', '1a9e32f07386c27297be14526f6fafee63fc2e1374ca4ae7034f1c2fbd7762d7', 'scored', NULL, 10.0, 6.48, 6.48, 'same_as_strict (1.0 result, not re-checked)', 0.0, 9.0, 6.37, 6.37, NULL, NULL, NULL, 6143, 228, 228, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:34+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PATO', 'Phenotypic Quality Ontology', 'Phenotypic qualities (properties). This ontology can be used in conjunction with other ontologies such as GO or anatomical ontologies to refer to phenotypes. Examples of qualities are red, ectopic, high temperature, fused, small, edematous and arrested.', 'Phenotype', 'OWL', 207, '2025-05-14', '2025-05-14T18:10:56.000-07:00', 'https://bioportal.bioontology.org/ontologies/PATO', 'e78aa2b6d290c5f02547c04f48f8760956f503a932fde37f75dcf0aa5a4fddaa', 'scored', NULL, 10.0, 5.59, 5.59, 'same_as_strict (1.0 result, not re-checked)', 7.42, 10.0, 8.2525, 8.2525, NULL, NULL, NULL, 281535, 8626, 8626, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:26:58+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PAV', 'PAV Provenance, Authoring and Versioning', 'PAV is a lightweight ontology for tracking Provenance, Authoring and Versioning. PAV specializes the W3C provenance ontology PROV-O in order to describe authorship, curation and digital creation of online resources.

This ontology describes the defined PAV properties and their usage. Note that PAV does not define any explicit classes or domain/ranges, as every property is meant to be used directly on the described online resource.', 'Other;Vocabularies', 'OWL', 3, '2.3.1', '2017-01-19T18:12:41.000-08:00', 'https://bioportal.bioontology.org/ontologies/PAV', '67a4eadaea2e5ddf49bac05f6f7062d0c865b7e62090a5db33a39a0db3c7ed49', 'scored', NULL, 8.89, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.2225, 2.2225, NULL, NULL, NULL, 352, 9, 3, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:40+00:00', '2026-09-23T23:25:10+00:00');
