INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PAYOR', 'Payor', 'This class refers to the entity that made the payment on behalf of the interviewee.', 'Other', 'SKOS', 1, NULL, '2022-12-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PAYOR', '26daa219bce58c7cc54ce7a1b18445e4ea6201a115494c2138edaa85d8131fa2', 'scored', NULL, 8.89, 4.14, 4.14, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 3.2575, 3.2575, NULL, NULL, NULL, 73, 9, 8, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:03:38+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PBO', 'Plant Breeding Ontology', 'Plant Breeding Ontology (PBO): an ontology for the plant breeding community which captures more than 2200 entries where 80 represent the core terms. PBO has translations in 8 different languages: English (main language), Spanish, French, Dutch, German, Japanese, Catalan and Thai, as well as their definitions, synonyms, derived terms and samples of their usage. PBO has been built partially manually and semi automatically.', 'All_Organisms;Phenotype;Plant', 'OWL', 4, NULL, '2024-08-30T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PBO', '53e81aa04076dec4f015a52e44bdebe43f9eaada35566edb3de5b3a6f16d88d5', 'scored', NULL, 10.0, 0.23, 0.23, 'same_as_strict', 0.0, 7.0, 4.3075, 4.3075, NULL, NULL, NULL, 12098, 2273, 2273, '0.10.0', 'core4-1.1', 'cuda', '2026-09-23T21:59:16+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PBPKO', 'Physiologically-Based Pharmacokinetic ontology', 'PBPKO is used for annotation of kinetic model in SBML description format., Physiologically Based Pharmacokinetic Models (PBPK) are widely used in both pharmaceutical and environmental domain by experts to assess the kinetics of xenobiotics. Thousands of papers have been published over years but the major drawback being utilization of inconsistent vocabulary which reduce the potential for automation. Machine-readable semantic technology like ontology can be used to improve the reporting of PBPK models. Currently there are multiple ontologies related to life science domain on portals like Bioportal, still there is no dedicated ontology for describing PBPK. The objective of this work is to develop a dedicated ontology for PBPK named PBPKO which can be used in future by wider kinetic community. PBPKO has covered possible mechanisms, existing kinetic terms in multiple databases and commonly utilized terminology by experts. This is freely available ontology with first version (V1.0) being published following FAIR guidelines using ROBOT tool and published at OBO foundry (crispae.github.io/pbpko/ (github.com)). It will be further enriched by including multiple species and much more kinetic terms with the help of experts. PBPKO annotates both physiological and biochemical parameters related to PBPK modeling. This ontology can be further used for text mining of PBPK parameters and model output., Physiologically Based Pharmacokinetic Models ontology for describing PBPK models, parameters, and processes., The PBPK (Physiologically Based Pharmacokinetic) Ontology (PBPKO) describes PBPK models, compartments, and pharmacokinetic processes for pharmaceutical and environmental life-science applications. It is aligned with Basic Formal Ontology (BFO) and the Relation Ontology (RO), and integrates terms from OBO Foundry ontologies including GO, OBI, and IAO.', 'Biological_Process', 'OWL', 6, '2026-07-15', '2024-08-11T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PBPKO', 'c923f3b65d7153599d77fff497f34cd6b3b71533c561702fa6842c7571a871ef', 'scored', NULL, 9.99, 5.47, 5.47, 'same_as_strict (1.0 result, not re-checked)', 3.07, 10.0, 7.1325, 7.1325, NULL, NULL, NULL, 30009, 1312, 1025, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:11:08+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PCALION', 'Prostate Cancer Lifestyle Ontology', 'PCLiON:Prostate Cancer Lifestyle Ontology', 'Health;Human', 'OWL', 6, '3.0', '2020-10-28T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PCALION', 'cdeb0738146c4465d9bbc5d1082cc9aaac97ffa4652cff6ed38594d9c33a2a8e', 'scored', NULL, 9.54, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 1.21, 10.0, 5.1875, 5.1875, NULL, NULL, NULL, 3962, 416, 398, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:06:58+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PCAO', 'Prostate Cancer Ontology', 'Here, we introduce the Prostate cancer ontology (PCaO) as a comprehensive semantic framework covering the whole breadth of the PCa’s knowledge domain. This ontology with a subclass-based taxonomic hierarchy not only covers the broad spectrum of major biomedical concepts from molecular to clinical features of the disease, but also the different views on disease features held by molecular biologists, clinicians and drug developers.  PCaO organized under three biological viewpoints, i.e., epidemiology, diagnosis, and treatment.
Note: The prostate cancer ontology version 1.0 (PCAO 1.0) was published by Hua Min in 2009 (PMID: 19497389).', 'Health;Human', 'OWL', 2, '2.0', '2023-06-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PCAO', 'a14627e633dc5a735e280dcef8268197bb139cd6683b31977e6028310fd7ee6b', 'scored', NULL, 9.98, 6.53, 6.53, 'same_as_strict (1.0 result, not re-checked)', 0.32, 10.0, 6.7075, 6.7075, NULL, NULL, NULL, 6780, 634, 634, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:15+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PCL', 'Provisional Cell Ontology', 'Cell types that are provisionally defined by experimental techniques such as single cell or single nucleus transcriptomics rather than a straightforward & coherent set of properties., Cell types that are provisionally defined by experimental techniques such as single cell transcriptomics rather than a straightforward & coherent set of properties.', 'Cell', 'OWL', 25, '2025-07-07', '2025-09-09T09:25:04.000-07:00', 'https://bioportal.bioontology.org/ontologies/PCL', '8318adda8d7624d4ea75037bba8cf31076479462ad996f2655b623edbcd838ee', 'scored', NULL, 10.0, 2.76, 2.76, 'same_as_strict (1.0 result, not re-checked)', 7.3, 10.0, 7.515, 7.515, NULL, NULL, NULL, 1737412, 46406, 37211, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T07:14:36+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PCMO', 'Pediatric Consultation and Monitoring Ontology ', 'Pediatric Consultation and Monitoring Ontology consists of 10 main classes, 10 sub-classes, 39 properties (object-type and sub-object-type properties,  data type), numerous OWL individuals and almost 90 SWRL rules (medical cases based on ARTI based diseases for pediatric patients).
Almost all the rules of the knowledge base consider:
-Body temperature
-Currently observed number of the local, major, and minor symptoms
-Medications used and time of use in recent period (has drug and has drug time properties)
-Presence of medical cold treatment applied in recent period ⇒ only one of medical case will be inferencing result.
Project Funding: “This research project was funded in 2014 by the National Science Foundation- The Scientific and Technological Research Council of Turkey (TUBITAK) under 1501 type funding program with the ‘3140417’ grant number. The titled “Mobile Pediatric Consultation and Monitoring System” project was successfully completed by the end of 2015. The project was completed by collaboration of the Acıbadem Hospitals Group, Istanbul Aydin University and Semantica Internet and Software Services Trd. Ltd. Company in Turkey”. ', 'Health', 'OWL', 2, 'v.4.0', '2015-12-25T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PCMO', '6fa78bf5d2b944082668f5f295e5a16dafa6229fc0187f0f7070b1fb2864902d', 'scored', NULL, 1.77, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 5.65, 5.0, 3.105, 3.105, NULL, NULL, NULL, 14566, 220, 21, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:12:15+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PCO', 'Population and Community Ontology', 'The Population and Community Ontology (PCO) models material entities, qualities, and processes related to collections of interacting organisms such as populations and communities. It is taxon neutral, and can be used for any species, including humans. The classes in the PCO are useful for describing evolutionary processes, organismal interactions, and ecological experiments. Practical applications of the PCO include community health care, plant pathology, behavioral studies, sociology, and ecology.

The PCO is complient with the Basic Formal Ontology (BFO) and is designed to be compatible with other OBO Foundry ontologies. ', 'All_Organisms;Other', 'OWL', 17, '2013-10-03', '2021-05-03T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PCO', 'fe757f0e46614899abc0a3dae2a0d8ae39fb23c3e26f6d78b18e50486ee1e217', 'scored', NULL, 9.96, 4.34, 4.34, 'same_as_strict (1.0 result, not re-checked)', 4.26, 9.0, 6.89, 6.89, NULL, NULL, NULL, 5543, 239, 222, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:28+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PDO', 'Pathogenic Disease Ontology', 'An ontology for describing both human infectious diseases caused by microbes and the diseases that is related to microbial infection. ', 'Health', 'OWL', 6, 'Version 0.7', '2016-03-31T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PDO', '60141756312b0257e50d06cfa84495b854c38640872d481b573cc7b9d66a977f', 'scored', NULL, 9.97, 6.28, 6.28, 'same_as_strict (1.0 result, not re-checked)', 7.67, 10.0, 8.48, 8.48, NULL, NULL, NULL, 5430, 389, 389, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:29+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PDON', 'Parkinson''s Disease Ontology', 'Here, we introduce the Parkinson’s disease ontology (PDO) as a comprehensive semantic framework covering the whole breadth of the Parkinson’s knowledge domain. This ontology with a subclass-based taxonomic hierarchy not only covers the broad spectrum of major biomedical concepts from molecular to clinical features of the disease, but also the different views on disease features held by molecular biologists, clinicians and drug developers. This resource has been created for use in the IMI-funded AETIONOMY project (www.aetionomy.org).  ', '', 'OWL', 1, '1.0', '2015-06-17T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PDON', 'd49599bd5c08a70acdc9bdf7e97979e61367b69cea4c2b98a0d4020ea61282df', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 5.0, 5.0, NULL, NULL, NULL, 6542, 632, 632, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:08:18+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PDO_CAS', 'Plant Diversity Ontology', 'Plant Diversity Ontology (PDO) is the outcome of the construction tasks of domain ontology of science in the project of Scientific & Technological Knowledge Organization Systems (STKOS). The structure of PDO centers on species, including micro level of molecular, cell and tissue, medium level of plant organs, species and population, and macro level of ecosystem. The classes of PDO also capture the habitat, environmental conditions and expand the general characteristics of plants, completing the instances richness for plant species, geographical, classification and morphology. Furthermore, PDO builds the relationships among species, region, morphology, plant organs, developmental stage, revealing the list of species in an area, the morphology and life form of plants, and development process of species. In sum, PDO shows a growth process or development stage of a species and its structure characteristics in particular space and time scale, realizing the description of species diversity, ecosystem diversity and genetic diversity. At present, PDO has been applied to the platform of Go to Selected Open Access Journals (GoOA) developed by National Science Library of Chinese Academy of Sciences, supporting concept retrieval and concept extension for GoOA.', 'Plant', 'OWL', 1, NULL, '2015-04-30T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PDO_CAS', '68479bd131f102edb1aeb9606e993a5a8d2fa8f0d6a49dafbc6fbaf0fccb6ad6', 'scored', NULL, 0.65, 0.15, 0.16, 'http://www.stkos-ontology/domain/plantbiodiversity#definition [bioportal_definitionProperty + detected_by_name]', 5.51, 10.0, 4.0775, 4.08, NULL, NULL, NULL, 48703, 12532, 380, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T22:57:37+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PDQ', 'Physician Data Query', 'Physician Data Query (PDQ) Terminology is part of NCI''s comprehensive cancer information database, which contains expert summaries on a wide range of cancer topics, a listing of some 30,000 cancer clinical trials from around the world, a directory of genetics services professionals, the NCI Dictionary of Cancer Terms, and the NCI Drug Dictionary.', 'Health', 'UMLS', 16, 'PDQ_2018_10_27', '2019-05-06T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PDQ', '4ac9f5dc8322f6f8432aa00d8f07dd0a3495c8b053157aeb937736369a18a56c', 'scored', NULL, 10.0, 3.46, 3.46, 'same_as_strict (1.0 result, not re-checked)', 8.16, 10.0, 7.905, 7.905, NULL, NULL, NULL, 217670, 13453, 13453, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:25:08+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PDRO', 'The Prescription of Drugs Ontology', 'PDRO is a realist ontology that aims to represent the domain of drug prescriptions. Such an ontology is currently missing in the OBOFoundry and is highly relevant to the domains of existing ontologies like DRON, OMRSE and OAE. PDRO’s central focus is the structure of a drug prescription, which is represented as a mereology of informational entities. Our current use cases are (1) refining this structure (e.g., adding closure axioms, cardinality, datatype bindings, etc) for prospectively standardizing local electronic prescriptions and (2) annotating prescription data of differing EHRs for detecting inappropriate prescriptions using a central semantic framework. Future ontological work will include aligning PDRO more closely with the Document Acts Ontology.', 'Health', 'OWL', 11, '2026-06-09', '2026-06-09T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PDRO', '3727713d109b1f257ee67f8a06fc07755c5e4eaa248f511ca76d62f22192b78c', 'scored', NULL, 10.0, 5.74, 5.74, 'same_as_strict (1.0 result, not re-checked)', 4.71, 9.0, 7.3625, 7.3625, NULL, NULL, NULL, 7640, 321, 321, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:12+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PDUMDV', 'Platynereis Developmental Stages', 'Life cycle stages for Platynereis dumerilii.', '', 'OWL', 175, NULL, '2024-04-03T18:12:12.000+00:00', 'https://bioportal.bioontology.org/ontologies/PDUMDV', 'fcc313e01fa11a6427ff0176013738e50cdd0036cb30b61e993270c89970cecc', 'scored', NULL, 9.55, 6.77, 6.77, 'same_as_strict (1.0 result, not re-checked)', 8.11, 8.0, 8.1075, 8.1075, NULL, NULL, NULL, 542, 22, 22, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:46+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PE', 'Pulmonary Embolism Ontology', 'A controlled vocabulary of PE-relevant information. Currently, only treatment information is available. ', 'Biomedical_Resources;Health;Human;Vocabularies', 'OWL', 1, 'version 1.0', '2015-12-08T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PE', '455509ada476e46edf17e5f8fabe7768a8c5511d7cd9de1c71187c10032f1e79', 'scored', NULL, 9.9, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 4.975, 4.975, NULL, NULL, NULL, 651, 98, 98, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:36+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PE-O', 'Pre-eclampsia Ontology', 'The PEO incorporates a wide range of key concepts and terms of PE from clinical and biomedical research in structuring the knowledge base that is specific to PE.', 'Health;Human', 'OWL', 3, 'v15
Heneka comments / shifs / modifications integrated', '2016-08-30T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PE-O', 'f6977c724bae5b05a7954eb328fcf881df1144114ca8e9184d0d78547bb3ae77', 'scored', NULL, 10.0, 0.79, 0.79, 'same_as_strict (1.0 result, not re-checked)', 0.94, 10.0, 5.4325, 5.4325, NULL, NULL, NULL, 9228, 1251, 1251, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:25+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PEAO', 'Plant Experimental Assay Ontology', 'The Plant domain has been the subject of several attempts to structure and formally define terms and corresponding relations, such as their anatomical features, developmental stages, and the application of particular experimental procedures to a biological problem. However, a focus on experimental assays in order to describe the whole experimental procedure, to the best of our knowledge, has only been attempted in the context of a very general description based on classical views of the scientific method. In this study, we focus on the development and proposal of an ontology dedicated to the description of these experimental procedures, regardless of the scientific questions that prompted the assays. This ontology includes entities from three distinct realms (biological, physical and data), which include both experimental products, their relations and the protocols describing their manipulation. The final outcome is a useful and comprehensive ontology in the plant domain, to be used as a log book by experimentalists, providing a formal relation between entities.', '', 'OWL', 4, NULL, '2019-02-08T18:09:31.000-08:00', 'https://bioportal.bioontology.org/ontologies/PEAO', '65c9d18aa35a9c56967d1e39382745929fc6d73f0d2d801455150a1c025ce29a', 'scored', NULL, 9.98, 0.22, 0.22, 'same_as_strict (1.0 result, not re-checked)', 0.27, 10.0, 5.1175, 5.1175, NULL, NULL, NULL, 12990, 2298, 2298, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:33+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PECO', 'Plant Experimental Conditions Ontology', 'The Plant Experimental Conditions Ontology describes the treatments, growing conditions, and/or study types used in plant biology experiments. The subjects of the studies may also include in vitro plant structures (PO:0000004). A plant treatment is the most specific,and may be a component of a plant growing condition, and the plant study type. The broadest classes are the plant study types where the terms can be used to identify the growth study facility. Each growth facility such as field study, growth chamber, green house etc is a environment on its own and it may also involve instances of biotic and abiotic treatments and different growing conditions.', 'Experimental_Conditions;Phenotype;Plant', 'OBO', 33, 'v2025-12-02', '2025-12-05T18:16:42.000-08:00', 'https://bioportal.bioontology.org/ontologies/PECO', 'ed32ca77580f4095cfa099ac97c98b02babe223586a53d5c073814a23755f4cf', 'scored', NULL, 10.0, 3.95, 3.95, 'same_as_strict (1.0 result, not re-checked)', 6.1, 9.0, 7.2625, 7.2625, NULL, NULL, NULL, 89021, 3171, 3171, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:17:55+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PEDTERM', 'Pediatric Terminology', 'Terms associated with pediatrics, representing information related to child health and development from pre-birth through 21 years of age; contributed by the National Institute of Child Health and Human Development.', 'Health;Human', 'OWL', 5, 'Version 2.0', '2013-01-25T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/PEDTERM', '7b36b67abfbaa3aed609d861cdd7c5c122a2180bff52feb88252e2d3ff4a5020', 'scored', NULL, 9.99, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 4.9975, 4.9975, NULL, NULL, NULL, 17686, 1772, 1772, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:10:53+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PEO', 'Parasite Experiment Ontology', 'The Parasite Experiment Ontology (PEO) models provenance metadata associated with experiment protocols used in parasite research. The PEO extends the upper-level Provenir ontology (http://knoesis.wright.edu/provenir/provenir.owl) to represent parasite domain-specific provenance terms.

The PEO (v 1.0) includes Proteome, Microarray, Gene Knockout, and Strain Creation experiment terms along with other terms that are used in pathway.', '', 'OWL', 5, '1', '2011-06-20T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/PEO', 'fc987e4f22c3ffb40c595b9b4d4e384924e64d87f9fc46cf8e10d6d583a658b2', 'scored', NULL, 8.46, 5.03, 5.03, 'same_as_strict (1.0 result, not re-checked)', 1.68, 10.0, 6.2925, 6.2925, NULL, NULL, NULL, 1063, 169, 143, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:13+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PEO_ONTOLOGY', 'Prompt Engineering Ontology', 'The PEO ontology is a modern ontology that covers state-of-art prompt engineering techniques and large language models. The ontology is designed to support students, researchers and developers who want to know more about prompt engineering, applying prompting techniques in solving tasks.', '', 'OWL', 3, '1.0', '2025-03-12T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PEO_ONTOLOGY', '7470f077366817d2dc1bd1be490a008f5e54ff7ead68bd5979cfb2e187aebad3', 'parse_failed', 'unsupported format (tried xml, auto, turtle, n3, nt, trig, trix, owlready2:rdfxml). Last error: RDF/XML parsing error in file C:\owl4_run\downloads\PEO_ONTOLOGY\3\PEO_ONTOLOGY_3_original-submission.rdf, line 1241, column 135.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-23T21:58:28+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PESONT', 'Preposition_enabled Spatial Ontology', 'Preposition-enabled Spatial Ontology (PeSONT) is a model that describes health service with related concepts, sub-concepts, attributes, and relations among concepts. Inferences of new knowledge are possible using queries. PeSONT classifies linguistic place terms using (Bennett and Agarwal, 2007) and uses prepositions of English language for location identification. Its implementation is to further the application of the PeNLP parser on human related problems by classifying place-like terms in natural language and for extracting geolocations.
', '', 'OWL', 1, NULL, '2021-09-24T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PESONT', '7a7c5ae3f8b8f24bedacd100157c63adc63e790a06a0bfd5ab8b7a8d3c8361fc', 'scored', NULL, 0.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 9.0, 2.25, 2.25, NULL, NULL, NULL, 834, 211, 161, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:05:09+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PGHD-BP', 'PGHD Auxillary - BP', 'Ontology containing terms describing the ancillary information surrounding the collection of Blood Pressure data and the communication via Interactive Voice Response in the context of the VODAN-Africa project.', 'Health;Other', 'SKOS', 2, '1.1', '2024-05-10T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PGHD-BP', '54e1b11524a083523a0a355f99deae7d92701bc238030d386d6d582399514898', 'scored', NULL, 9.44, 5.02, 5.02, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 3.615, 3.615, NULL, NULL, NULL, 160, 18, 17, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:03:56+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PGHDPROV', 'PGHDProvo: Context and Provenance Based Standardized Patient Generated Health Data Shared with an Electronic Health Record', 'This ontology seeks to capture the provenance and data quality associated with PGHD shared with an EHR. The objective is to have an ontological formal representation of the provenance and contextual data related to PGHD shared with EHR, in order to offer clinicians a means to use PGHD data for decision making and treatment support., Patient Generated Health Data (PGHD) refer to health data collected by patient or their relatives. This ontology seeks to capture information about the data, the provenance and data quality associated with PGHD shared with an EHR.', 'Health', 'OWL', 4, '1.0', '2021-05-24T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PGHDPROV', '5a3688529e3164638bdd92ee390e569b6b1b7675d9d2b647b455f1712d43f5a1', 'scored', NULL, 6.22, 3.89, 3.89, 'same_as_strict (1.0 result, not re-checked)', 5.91, 9.0, 6.255, 6.255, NULL, NULL, NULL, 882, 37, 23, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:50+00:00', '2026-09-23T23:25:10+00:00');
