INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PGXO', 'PGxO', 'PGxO: a lite Pharmacogenomic Ontology.
A lightweight and simple ontology to reconcile and trace knowledge in pharmacogenomics (PGx). 
PGxO is also available on http://ns.inria.fr/pgxo/. 
A full description of the motivation, implementation and instantiation of PGxO is available in 
Monnin, P., Legrand, J., Husson, G., Ringot, P., Tchechmedjiev, A.,
Jonquet, C., Napoli, A., & Coulet, A.
PGxO and PGxLOD: a reconciliation of pharmacogenomic knowledge of various provenances, enabling further comparison. BMC Bioinformatics 20-S(4): 139:1-139:16 (2019). (https://doi.org/10.1186/s12859-019-2693-9)
', 'Biomedical_Resources;Genomic_and_Proteomic;Phenotype', 'OWL', 5, 'v0.6.1', '2026-07-28T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PGXO', 'a987bc5b27669ae9ff9a7a9f7ac76a05c0c06b569983666c716f99f52f6ad94f', 'scored', NULL, 9.23, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 6.0, 3.8075, 3.8075, NULL, NULL, NULL, 207, 13, 13, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:02+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PHAGE', 'Phylogenetics Ontology', 'This ontology represents the seven steps of phylogenetic analyses. Each root concept step is composed from a set of resource annotations (to represent the data-flow) and programs (to represent the control flow). Object properties serve to represent relations to annotate data (e.g. has_RetrievedInDatabase, has_ModeledBy, etc.) and reorder the sequence of programs (e.g. has_InputOutput).This ontology has been collected in a semi-automated way from well-known databases such as NCBI, GeneOntology, UniProtKB and Felsenstein’s Web site through Web crawling and mapping techniques.', 'Upper_Level_Ontology', 'OWL', 5, '5.0', '2016-05-02T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PHAGE', 'c25750cd13b1a3508bbc11ed379cce048404305906fc584ab32ec739e75d5a56', 'scored', NULL, 10.0, 6.28, 6.28, 'same_as_strict (1.0 result, not re-checked)', 7.55, 10.0, 8.4575, 8.4575, NULL, NULL, NULL, 1510395, 51495, 51495, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T07:00:31+00:00', '2026-09-23T23:25:10+00:00');
