INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PHIPO', 'Pathogen Host Interaction Phenotype Ontology', 'PHIPO is a formal ontology of species-neutral phenotypes observed in pathogen-host interactions. PHIPO is being developed to support the comprehensive and detailed representation of phenotypes in PHI-base, the multi-species Pathogen-Host Interactions database available online at http://www.phi-base.org. PHIPO is pre-composed and logically defined., Ontology of species-neutral phenotypes observed in pathogen-host interactions.', 'Phenotype', 'OWL', 34, '2026-08-06', '2026-08-06T18:09:59.000-07:00', 'https://bioportal.bioontology.org/ontologies/PHIPO', '76f066a5e5f7b78a399457975a59dc3a8fa32993276ad69cfd9523075c24fb1d', 'scored', NULL, 10.0, 6.03, 6.03, 'same_as_strict (1.0 result, not re-checked)', 7.79, 10.0, 8.455, 8.455, NULL, NULL, NULL, 410629, 10924, 10729, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:31:50+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PHMAMMADO', 'Phallusia mammillata Anatomy and Development Ontology', 'The first ontology describing the anatomy and the development of Phallusia mammillata. ', 'Anatomy;Animal_Development', 'OBO', 2, NULL, '2015-08-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PHMAMMADO', '394bee5fcab3d65db17340170769010b6819d524255bcac3d5595bfdbe034501', 'scored', NULL, 9.99, 6.82, 6.82, 'same_as_strict (1.0 result, not re-checked)', 9.71, 10.0, 9.13, 9.13, NULL, NULL, NULL, 33396, 881, 881, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:12:02+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PHY', 'physiotherapy', 'This ontology contains structured data for five physiotherapy exercises tailored for lower limb rehabilitation. Each exercise is aimed at supporting patients post-surgery, with a particular focus on preventing complications like deep vein thrombosis (DVT) and improving strength, mobility, and blood circulation in the legs.

Included Exercises:
Ankle Pump Exercise: Enhances blood flow in the lower limbs by flexing and extending the ankle, helping to prevent DVT.
Quad Set Exercise: Strengthens the quadriceps by engaging the knee in gentle extension, aiding recovery and muscle endurance.
Heel Slide Exercise: Improves knee mobility by sliding the heel toward the buttocks, promoting flexibility.
Straight Leg Raise Exercise: Strengthens hip flexors and quadriceps by lifting a straight leg, enhancing lower limb stability.
Glute Bridge Exercise: Activates the glutes and stabilizes the hips through lifting movements, improving strength and control.
Each exercise entry includes details such as targeted body parts, primary muscles, joint movements, instructions, precautions, progression criteria, and patient response metrics. The file leverages biomedical ontologies like OBI, ICF, and SNOMED CT for interoperability, making it suitable for integration into healthcare or rehabilitation applications.', 'Anatomy;Vocabularies', 'OWL', 2, '0.0.2', '2024-11-12T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PHY', 'f4e2fd25ec7554d14540b5d508ac245e643d6ba08af75f002768fbe527879ba6', 'scored', NULL, 8.33, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.0825, 2.0825, NULL, NULL, NULL, 188, 6, 6, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:02+00:00', '2026-09-23T23:25:10+00:00');
