INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PICO', 'Pathogen-related Informed Consent Ontology', 'PICO is an application ontology designed for the standardization of pathogen-related informed consent data and taxonomic logic relationship classification. The current development priority focuses on constructing its morbidity data representation framework in a manner that ensures consistent structural mapping with medical questionnaire architectures, thereby enabling interoperable data schema across epidemiological research systems.', 'Health', 'OWL', 3, '1.0.0', '2025-03-23T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PICO', 'b304d606bfddb5be1564265606048305fc4e1e43a21522181aa17c8abc7bbb1c', 'scored', NULL, 10.0, 5.31, 5.31, 'same_as_strict (1.0 result, not re-checked)', 1.46, 8.0, 6.1925, 6.1925, NULL, NULL, NULL, 4188, 234, 225, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:57+00:00', '2026-09-23T23:25:10+00:00');
