INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PLOSTHES', 'PLOS Thesaurus', 'The PLOS Thesaurus includes over 10,000 Subject Area terms covering the wide range of research topics included the PLOS journals.  It was initially built for PLOS in 2012 by Access Innovations (http://www.accessinn.com/). The entire corpus of PLOS articles was analysed to ensure that the thesaurus covers relevant research domains comprehensively. Updates are released several times a year.', '', 'SKOS', 10, 'plosthes.2017-1', '2017-09-14T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PLOSTHES', '7df8f9687c39eb3ecb9932591dfae3553adedb9a9f579c072f3c82e7184508e1', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 4.26, 0.0, 3.565, 3.565, NULL, NULL, NULL, 113483, 10717, 10715, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:20:19+00:00', '2026-09-23T23:25:10+00:00');
