INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PMAPP-PMO', 'PMO Precision Medicine Ontology', 'The Precision Medicine Ontology (PMO) has been developed as a standardized ontology for human precision medicine with consistent, reusable and sustainable descriptions of human disease terms, genomic molecular, phenotype characteristics and related medical vocabulary disease concepts through collaborative efforts of researchers at Institute of Medical Information, Chinese Academy of Medical Sciences. The Precision Medicine Ontology focuses on the development of a high level patients-centric ontology for the academic research, thus, it systematically integrates biomedicine vocabularies from GO, NCBI Gene, DrugBank, HPO, MeSH, SNOMED CT, etc. This work is supported by the National Key Research and Development Program of China (Precision Medicine Knowledge Base, Grant No. 2016YFC0901901).', 'Biomedical_Resources', 'OWL', 1, '4.0', '2020-12-16T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PMAPP-PMO', '4f80cd7feefbdf07ae30a435d696cc02a0ca4d07a64d84236c683349475dde7a', 'scored', NULL, 10.0, 0.0, 5.18, 'http://www.phoc.org.cn/pmo/class/Definition [bioportal_definitionProperty + detected_by_name]', 0.68, 10.0, 5.17, 6.465, NULL, NULL, NULL, 2458057, 76155, 76155, '0.10.0', 'core4-1.1.1', NULL, '2026-09-23T23:08:56+00:00', '2026-09-23T23:25:10+00:00');
