INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PMDO', 'Parkinson and Movement Disorder Ontology', 'The Parkinson Movement Disorder Ontology (PMDO) uses a systematic analysis of movement disorder instruments, extensive review of literature led by movement disorder specialists, and the AMP PD knowledge portal with an iterative ontology engineering process. The current version of PMDO is focused on parkinsonian disorders with classes representing three broad categories of: (1) neurological findings, (2) treatment plans, and (3) instruments used to evaluate various traits of PD. 

Release notes (v1.0):
This version models the MDS Clinical Diagnostic Criteria for Parkinson’s Disease (2015), including:
1. Essential criteria (1)
2. Supportive criteria (4)
3. Absolute exclusion criteria (9)
4. Red flags (10)', 'Human;Neurologic_Disease;Neurological_Disorder;Phenotype', 'OWL', 4, '1.1', '2023-12-12T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PMDO', '6c79e1682d54959ac8b4e5a657fc043930f700bfcb883a6556abb80352fee3aa', 'scored', NULL, 7.46, 0.47, 0.47, 'same_as_strict (1.0 result, not re-checked)', 1.46, 10.0, 4.8475, 4.8475, NULL, NULL, NULL, 2615, 629, 629, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:09+00:00', '2026-09-23T23:25:10+00:00');
