INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PO', 'Plant Ontology', 'The Plant Ontology is a structured vocabulary and database resource that links plant anatomy, morphology and growth and development to plant genomics data. The PO is under active development to expand to encompass terms and annotations from all plants., An ontology that describes plant anatomy, morphology, and growth and development in plants.', 'Plant;Plant_Anatomy;Plant_Development', 'OBO', 30, 'releases/2024-04-17', '2026-01-14T18:14:35.000-08:00', 'https://bioportal.bioontology.org/ontologies/PO', '42894aa57a4982165772fcacba5241a64b97ab9291388eaa37bb55563402f61e', 'scored', NULL, 10.0, 6.03, 6.03, 'same_as_strict (1.0 result, not re-checked)', 7.42, 10.0, 8.3625, 8.3625, NULL, NULL, NULL, 69622, 2031, 2029, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:18:00+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'POEM', 'Psychometric Ontology of Experiences and Measures', 'POEM supports the usage of psychometric instruments, particularly questionnaires, representing their structure, measured constructs, intended contexts, and provenance.', 'Human', 'OWL', 8, '1.0', '2025-01-07T18:13:42.000-08:00', 'https://bioportal.bioontology.org/ontologies/POEM', '74b138c75536c7e93a0e019735a11b0276c2262e8d0a7f06fa4cade635f348e4', 'scored', NULL, 9.99, 5.58, 5.58, 'same_as_strict (1.0 result, not re-checked)', 2.33, 10.0, 6.975, 6.975, NULL, NULL, NULL, 17880, 1637, 1637, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:10:07+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PORO', 'Porifera Ontology', 'An ontology covering the anatomy of Porifera (sponges)', 'Anatomy;Phenotype', 'OWL', 9, 'unknown', '2021-11-08T18:11:03.000-08:00', 'https://bioportal.bioontology.org/ontologies/PORO', '3f1d03c48e7caea5c418bde9af9ef172ce5ce88bed5837474f4c7c8692bfdaae', 'scored', NULL, 10.0, 5.56, 5.56, 'same_as_strict (1.0 result, not re-checked)', 6.08, 10.0, 7.91, 7.91, NULL, NULL, NULL, 11130, 896, 896, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:02+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PP', 'Pipeline Patterns Ontology', 'To answer the need for a workflow representing a sequence of data transformations, a high-level process ontology was defined, denoted Pipeline Patterns (PP) ontology. 

Every concept is generically a Data (class from EDAM), which can be further specified as an Entry (P:00002) or an Exit (P:00009). All Entries can be subjected to an Operation (class from EDAM) producing an Intermediate (P:00010). An Intermediate has a TemporalEntity associated to represent its time of creation. Some Entries are specifically of the type Exit, meaning that they will represent concepts that exit the current category and be passed to the next one on the workflow. Additionally, in order to permit the treatment of a set of objects as a single entity, this high-level ontology considers the concept of List (P:00004) and more specifically an Aggregate (P:00005), containing a set of Data or Entry, respectively.
The concept Intermediate is an Entry, allowing for the successive application of an operation to an Element. This is particularly useful in the case of the application of sequential set of operations.', 'Upper_Level_Ontology', 'OWL', 1, '1.0', '2014-12-17T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PP', '25dedaa3b901e6ac0d0d215bb46b0fdf35bc24d35d19760370436d655fb9cddf', 'scored', NULL, 8.0, 3.25, 3.25, 'same_as_strict (1.0 result, not re-checked)', 2.1, 6.0, 4.8375, 4.8375, NULL, NULL, NULL, 90, 15, 15, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:03:48+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PPLC', 'Placental Pathology Lesion Classification', 'Placental pathology: current terminology with definitions, short descriptions, and representative images pertaining to the cause, origin and nature of placental disease. The Placental Pathology Lesion Classification was developed by a PAT External Scientific Panel Member, placental pathologist Dr. Raymond Redline. This terminology is a continuation of the effort of the Amsterdam Placental Lesion Consensus Group.', 'Health', 'OWL', 1, '1.0', '2020-01-13T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PPLC', '77919c6c3841d7201a9a00cd0a6c6476d7da445cdc6fd675c551e4a913d97397', 'parse_failed', 'unsupported format (tried owlready2:owlxml). Last error: OWL/XML parsing error in file C:\owl4_run\downloads\PPLC\1\PPLC_1_original.owl, line 7, column 56.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-23T21:06:58+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PPO', 'Plant Phenology Ontology', 'An ontology for describing the phenology of individual plants and populations of plants, and for integrating plant phenological data across sources and scales., An ontology that defines plant phenological classes and is used to run the plantphenology.org data portal. Reuses terms from PO and PATO where possible.', '', 'OWL', 13, '2026-05-06', '2026-05-06T18:10:55.000-07:00', 'https://bioportal.bioontology.org/ontologies/PPO', '43022f3d730db0fde33febf92a5b49bac9855c84c7e8b3e206bf33329ff14d0d', 'scored', NULL, 9.98, 6.62, 6.62, 'same_as_strict (1.0 result, not re-checked)', 5.94, 10.0, 8.135, 8.135, NULL, NULL, NULL, 17300, 577, 577, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:31+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PR', 'Protein Ontology', 'The PRotein Ontology (PRO) represents taxon-specific and taxon-neutral protein-related entities in three major areas: proteins related by evolution (including orthologous proteoforms); proteins produced from a given gene (including specific modified forms) and protein-containing complexes., The PRotein Ontology (PRO) formally defines taxon-specific and taxon-neutral protein-related entities in three major areas: proteins related by evolution; proteins produced from a given gene; and protein-containing complexes.', 'All_Organisms;Gene_Product;Molecule;Protein', 'OWL', 94, '73.0', '2026-09-15T18:13:15.000-07:00', 'https://bioportal.bioontology.org/ontologies/PR', 'b9dc8168e08a24a660f2821a1319aabefb89c80c329a631ff35a688522a63679', 'scored', 'stream failed: ChunkedEncodingError: (''Connection broken: IncompleteRead(1074913280 bytes read, 204501390 more expected)'', IncompleteRead(1074913280 bytes read, 204501390 more expected))', 10.0, 6.76, 6.76, 'same_as_strict', 8.51, 10.0, 8.8175, 8.8175, NULL, NULL, NULL, 12599978, 332990, 332990, '0.10.0', 'core4-1.1', 'cuda', '2026-09-23T22:43:55+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PREFER', 'Precision Fermentation Ontology', 'PREFER is an ontology designed to integrate high-throughput bioprocess data, covering operational, environmental and process parameters across different scales of a precision fermentation process, to accelerate the development and scaling of biosustainable production processes., An ontology for PREcision FERmentation.', '', 'OWL', 7, '2026-08-24', '2026-08-25T18:11:09.000-07:00', 'https://bioportal.bioontology.org/ontologies/PREFER', 'a05dfa000fa1594a8d386a04409c1aa659ca850804fec8c1fdf3ea29bee69693', 'scored', NULL, 10.0, 6.1, 6.1, 'same_as_strict (1.0 result, not re-checked)', 8.32, 10.0, 8.605, 8.605, NULL, NULL, NULL, 278654, 7189, 6952, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:26:27+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PREGONTO', 'Pregnancy Ontology', 'The pregnancy ontology is a biomedical ontology used for identifying pregnancies in routine health databases. The ontology was primarily developed for conducting surveillance of vaccine uptake in pregnant women in the UK.', 'Biological_Process', 'OWL', 1, NULL, '2018-10-31T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PREGONTO', 'd4742e52dbfcc52dbb1e30fb76da4b2f3429c0ff99b406747fc008af073fac63', 'scored', NULL, 9.75, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 8.0, 4.4375, 4.4375, NULL, NULL, NULL, 175, 40, 40, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:03:57+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PREMEDONTO', 'Precision Medicine Ontology', 'Precision MedicinePreMedOnto is an application ontology built for the precision medicine domain on top of gold standard biomedical ontologies. The ontology learning process involves mining the PubMed repository to extract domain specific texts, abstracts and vocabulary as sources of data. The information gathered is clustered and outlined to determine main modules. It reuses terms and concepts from NCIT, MESH and IOBC to construct the ontology hierarchy.', 'Health', 'OWL', 1, NULL, '2018-11-24T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PREMEDONTO', '1d52cedd74a10f0b5ac9404aeedcf288745f97d724ab5e95c14d17963f1719d8', 'scored', NULL, 10.0, 6.03, 6.03, 'same_as_strict (1.0 result, not re-checked)', 0.34, 10.0, 6.5925, 6.5925, NULL, NULL, NULL, 9309, 543, 543, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:51+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PREO', 'Presence Ontology', 'The Presence Ontology is a systematic vocabulary of terms with defined relationships that models the encounters taking place every day among providers, patients, and family members or friends in environments such as hospitals and clinics. The Presence Ontology provides a conceptual model for the human experience in medicine. This is a preliminary approach, but further use of methods we have developed here may aid in providing clarity and consensus to topics in healthcare. The ontology is also a model for interdisciplinary collaboration, as it was developed in conjunction with experts from bioinformatics, medicine, anthropology, business, and communication sciences through multiple iterative stages.', 'Biomedical_Resources;Health;Human', 'OWL', 1, '1.0.0', '2019-07-27T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PREO', '8d9b581839fc290399ba57d3915c21297e6713519ffb726e8a82770efbfd3d1c', 'scored', NULL, 9.96, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 2.25, 10.0, 5.5525, 5.5525, NULL, NULL, NULL, 1267, 277, 277, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:05:18+00:00', '2026-09-23T23:25:10+00:00');
