INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PROCO', 'Process Chemistry Ontology', 'PROCO covers process chemistry, the chemical field concerned with scaling up laboratory syntheses to commercially viable processes.', 'Other', 'OWL', 1, 'PROCO release 20220414', '2022-04-14T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PROCO', '5dcc6e21d1d7ab7a95ed41cbc4fed3f68a17f552920626ca3dcaceab832d94cb', 'scored', NULL, 10.0, 6.03, 6.03, 'same_as_strict (1.0 result, not re-checked)', 2.43, 9.0, 6.865, 6.865, NULL, NULL, NULL, 13231, 936, 922, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:38+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PROJ', 'Project ontology', 'The PROJECT ontology is a profile of PROV-O which is designed to enable publication of information describing projects, including research projects. It is not designed to support project management, though sub-activities are included. As far as possible PROJECT is intended to be domain-neutral, and it is expected that domains and applications will specialize or extend this ontology for more specific purposes.

The ontology gives terms to support the representation of:

project planning, funding, goals
project stakeholders and relationships
project activities and timeline

Primary documentation is at http://linked.data.gov.au/def/project', 'Other', 'OWL', 2, '2020', '2020-04-24T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PROJ', '1ec180adf9ffb7283975b6b33dd6741dead726b7b6da99dac9d26e928501b9f6', 'scored', NULL, 9.73, 3.66, 3.66, 'same_as_strict (1.0 result, not re-checked)', 1.63, 8.0, 5.755, 5.755, NULL, NULL, NULL, 3156, 113, 90, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:32+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PROMOT', 'PROMOT Ontology', 'The PROMOT ontology was built in the context of the "Performing a Rare Disease-Oriented Master Observational Trial" initiative (PROMOT initiative).
 
PROMOT ontology represents three groups of neuromuscular diseases related to the 13 genes the PROMOT Master Observational Trial focuses on:
 
- Oculopharyngeal Muscular Dystrophy (PABPN1)
- Congenital Myasthenic Syndromes (CHRNE, DOK7, COLQ, RAPSN, GFPT1, GMPPB)
- Congenital Myopathies (RYR1, TTN, NEB, MTM1, ACTA1, SELENON).
 
This ontology aims to be the conceptual schema for the common data model the PROMOT initiative will use to collect patient data scattered between the different sites involved in PROMOT initiative.
 
PROMOT initiative has received funding from the Canadian Institutes of Health Research (CIHR), and in partnership with L’Agence Nationale de la Recherche (France), Health Research Board (Dublin, Ireland), Instituto de Salud Carloss III (Spain), IRSC–IG, Swedish Research Council (Sweden), and Swiss National Science Foundation (Switzerland), partners of the European Joint Programme on Rare Diseases (EJP RD).
 
More about PROMOT initiative can be found at https://www.promotinitiative.com/project
 
This ontology is published under the following licence: https://creativecommons.org/licenses/by-nc-sa/4.0/

Ontology Github and documentation will be available soon., The PROMOT ontology was built in the context of the "Performing a Rare Disease-Oriented Master Observational Trial" initiative (PROMOT initiative).

PROMOT ontology represents three groups of neuromuscular diseases related to the 13 genes the PROMOT Master Observational Trial focuses on:
 
- Oculopharyngeal Muscular Dystrophy (PABPN1)
- Congenital Myasthenic Syndromes (CHRNE, SELENON)

This ontology aims to be the conceptual schema for the common data model the PROMOT initiative will use to collect patient data scattered between the different sites involved in the project.
 
PROMOT initiative has received funding from the ', 'Dysfunction;Health;Human;Neurologic_Disease;Neurological_Disorder;Phenotype', 'OWL', 2, 'V1.02', '2026-09-14T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PROMOT', '8492ad5fb1a35bf721e8448ebcc595b602f61b1e4b4997dc9776e2af339ed32f', 'scored', NULL, 9.99, 5.13, 5.13, 'same_as_strict (1.0 result, not re-checked)', 8.08, 10.0, 8.3, 8.3, NULL, NULL, NULL, 41822, 1016, 1016, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:13:11+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PROPREO', 'Proteomics Data and Process Provenance Ontology', 'A comprehensive proteomics data and process provenance ontology.', '', 'OWL', 2, '1.1', '2015-08-21T18:05:51.000-07:00', 'https://bioportal.bioontology.org/ontologies/PROPREO', 'e4c848f4e7aa50fe2a300c00e2dae3769757e71baba3263cc0dae3b6c7552b26', 'scored', NULL, 9.82, 6.22, 6.22, 'same_as_strict (1.0 result, not re-checked)', 2.31, 10.0, 7.0875, 7.0875, NULL, NULL, NULL, 2885, 447, 401, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:41+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PROVO', 'Provenance Ontology', 'The PROV Ontology (PROV-O) expresses the PROV Data Model using the OWL2 Web Ontology Language (OWL2). It provides a set of classes, properties, and restrictions that can be used to represent and interchange provenance information generated in different systems and under different contexts. It can also be specialized to create new classes and properties to model provenance information for different applications and domains.', '', 'OWL', 124, 'Recommendation version 2013-04-30', '2013-07-04T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/PROVO', '96cfeeb583d78a43c9e974445e3e02442c9ac1b351c71661f3673b7c3d4bd64f', 'scored', NULL, 10.0, 4.61, 4.61, 'same_as_strict (1.0 result, not re-checked)', 2.54, 9.0, 6.5375, 6.5375, NULL, NULL, NULL, 1172, 31, 31, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:06+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PSDO', 'Performance Summary Display Ontology', 'The Performance Summary Display Ontology (PSDO) is a lightweight application ontology used to reproducibly study visualizations of clinical performance and their associated outcomes in healthcare quality improvement settings. PSDO extends boundaries of visual representation artifacts by the IAO in the domain of distributed representations. PSDO describes dimensional representations of relational information displays that can be used to study the influence of feedback interventions on clinical practice., Performance Summary Display Ontology (PSDO) is an application ontology about motivating information in performance summaries and the visual and textual entities that are used to communicate about performance. Motivating information includes performance comparisons and changes that motivate improvement or sustainment, such as improvement towards a goal, loss of high performer status, or the presence of a performance gap. Visual and textual entities include charts, tables, and graphs that display performance information. PSDO''s domain focus is healthcare organizations that use clinical quality dashboards and feedback interventions for healthcare professionals and teams. Performance information is commonly about the quality of care and health outcomes that have been derived from clinical data using performance measures (aka metrics, process indicators, quality measures, etc). PSDO uses Basic Formal Ontology as its upper level ontology. This work is supported by the NIH, National Library of Medicine (1K01LM012528-01, 1R01LM013894-01).

Landis-Lewis Z, Stansbury C, Rincón J, Gross C. Performance Summary Display Ontology: Feedback intervention content, delivery, and interpreted information. International Conference on Biomedical Ontology 2022 (ICBO 2022). https://icbo-conference.github.io/icbo2022/papers/ICBO-2022_paper_2172.pdf', 'Other', 'OWL', 9, '1.0.1', '2026-02-10T18:15:51.000-08:00', 'https://bioportal.bioontology.org/ontologies/PSDO', '7fe67a9e83f422ebba47ae46f4f85b5454fdd63ddeb3aae26bd96d5beb0d3f7a', 'scored', NULL, 10.0, 6.33, 6.33, 'same_as_strict (1.0 result, not re-checked)', 4.95, 10.0, 7.82, 7.82, NULL, NULL, NULL, 26430, 1271, 1252, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:11:22+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PSDS', 'Plant Structure Development Stage', 'REPLACED BY: Plant Ontology (PO).  A controlled vocabulary of growth and developmental stages in various plants. Note that this has been subsumed into the Plant Ontology (PO).
This file is created by filtering plant_ontology_assert.obo to contain only terms from the plant structure development stage branch of the PO. For more information, please see: http://palea.cgrb.oregonstate.edu/viewsvn/Poc/tags/live/', 'Development;Plant;Plant_Development', 'OBO', 6, 'Release #20', '2013-08-21T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PSDS', '9f24664d587a3055ac02aac9a9a089ca62053e2f3737f0f4fa83da715f993e49', 'scored', NULL, 9.97, 6.53, 6.53, 'same_as_strict (1.0 result, not re-checked)', 7.64, 10.0, 8.535, 8.535, NULL, NULL, NULL, 11220, 346, 346, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:12+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PSIMOD', 'Protein Modification Ontology', 'PSI-MOD is an ontology consisting of terms that describe protein chemical modifications, logically linked by an is_a relationship in such a way as to form a direct acyclic graph (DAG). The PSI-MOD ontology has more than 45 top-level nodes, and provides alternative hierarchical paths for classifying protein modifications either by the molecular structure of the modification, or by the amino acid residue that is modified.', '', 'OBO', 35, '1.031.6', '2026-09-18T18:11:56.000-07:00', 'https://bioportal.bioontology.org/ontologies/PSIMOD', 'b6da12f9665c231c2498eabcc4385d87842d03ce05790430ecb90a42b7c8a1b8', 'scored', NULL, 10.0, 6.92, 6.92, 'same_as_strict (1.0 result, not re-checked)', 8.38, 10.0, 8.825, 8.825, NULL, NULL, NULL, 187978, 2117, 2117, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:24:41+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PSO', 'PatientSafetyOntology', 'It is the ontology embedding PRIME (Prospective Risk Analysis in Medical Environments) in related issues of patient safety research and activities. It classifies terms and express relations between them.
The ontology building in an ongoing process. Any comments are welcome.', 'Health;Vocabularies', 'OWL', 2, '008:2017-08-04: Einarbeitung der Zustände', '2017-06-25T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PSO', '1c03df3ea235edfc5c7b8fa9e9149e934fdcb20431b03b5f52aa7aeee05f9812', 'scored', NULL, 9.68, 0.51, 0.51, 'same_as_strict (1.0 result, not re-checked)', 1.8, 10.0, 5.4975, 5.4975, NULL, NULL, NULL, 2771, 568, 568, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:48+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PSO_2', 'PatientSafetyOntologyRevisted', 'This is a revised version of the Patient Safety Ontology', 'Health', 'OWL', 3, '005', '2020-06-26T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PSO_2', 'ecba5c6c9099ac45155ff303427ef5d03f16833bbf2210daec17903543783a69', 'scored', NULL, 9.97, 0.0, 0.0, 'same_as_strict', 0.96, 10.0, 5.2325, 5.2325, NULL, NULL, NULL, 1337, 292, 292, '0.10.0', 'core4-1.1', NULL, '2026-09-23T21:59:05+00:00', '2026-09-23T23:25:10+00:00');
