INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PTRANS', 'Pathogen Transmission Ontology', 'The Pathogen Transmission Ontology describes the transmission methods of human disease pathogens from one host, reservoir, or source to another host. The pathogen transmission may occur either directly or indirectly and may involve animate vectors or inanimate vehicles., The Pathogen Transmission Ontology describes the transmission methods of human disease pathogens describing how a pathogen is transmitted from one host', 'Health;Vocabularies', 'OWL', 20, '2026-03-13', '2026-03-14T13:48:52.000-07:00', 'https://bioportal.bioontology.org/ontologies/PTRANS', '59e2a5b7d6cb3cc5594c4cefe0de749df6500493bfa142f08b66afb74438b507', 'scored', NULL, 9.72, 6.05, 6.05, 'same_as_strict (1.0 result, not re-checked)', 6.83, 9.0, 7.9, 7.9, NULL, NULL, NULL, 452, 36, 36, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:29+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PTRO', 'Preclinical Trials in Radiation Oncology Ontology', 'PTRO focuses on preclinical data standardized according to SEND, with emphasis on radiation oncology studies. It is not intended to replace clinical trial ontologies or general-purpose biomedical ontologies but to complement them by addressing the specific needs of preclinical research data representation.', '', 'OWL', 2, '0.1 alpha', '2026-04-27T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/PTRO', '6a09e1fb93113deca188e2505e718aa262f1432e69ca863407151c92ce248c87', 'scored', NULL, 10.0, 6.49, 6.49, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 6.6225, 6.6225, NULL, NULL, NULL, 1091, 43, 43, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:04+00:00', '2026-09-23T23:25:10+00:00');
