INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PVONTO', 'Pharmacovigilance Ontology', 'A pharmacovigilance ontology to connect known facts on drugs, disease, ADEs, and their molecular mechanisms.', '', 'OWL', 1, '0.1', '2011-01-17T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/PVONTO', '748e1f70cb5f1ce41176447160a5feda927f6f2c60341621f6d9adef31973713', 'scored', NULL, 9.71, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 7.0, 4.1775, 4.1775, NULL, NULL, NULL, 101, 34, 34, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:03:51+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'PW', 'Pathway Ontology', 'The goal of the Pathway Ontology is to cover all types of biological pathways, including altered and disease pathways, and to capture the relationships between them within the hierarchical structure of a Directed Acyclic Graph (DAG). The five nodes of the ontology are: classic metabolic, regulatory, signaling, drug and disease pathways. An extensive survey of the review literature along with searches of existing pathway databases have been used to choose terms and their position within the tree. The ontology is continually expanding along with the development of Pathway and Disease Portals at RGD. Mapping of pathways in other databases to terms in PW as synonyms further increased the content of the ontology. It also provided the means to bring in annotations made by these databases and link to their sites via automatic pipelines built at RGD. The ontology allows for the standardized annotation of rat as well as human and mouse genes to pathway terms. It also serves as a vehicle to connect between genes and ontology reports, between reports and interactive pathway diagrams, between pathways that directly connect to one another within a diagram or between pathways that in some fashion are globally related in pathway suites and suite networks. Metabolic, regulatory or signaling pathway terms have associated terms for the altered version of the pathway and the level at which the alteration(s) may occur. Proteins with mutations known to affect a particular pathway can be annotated to the normal and altered version(s) of the pathway and to a disease pathway, if known. Both the provision of terms for the altered versions of pathways and the representation of disease pathway diagrams as a collection of altered pathways are unique to the PW ontology and RGD''s pathway data.
The Pathway ontology is distributed under the terms of the Creative Commons Attribution license version 3.0 Unported (CC BY 3.0), see
http://creativecommons.org/licenses/by/3.0 for details. ', 'Biological_Process', 'OBO', 130, '2026-05-16', '2026-05-18T18:13:06.000-07:00', 'https://bioportal.bioontology.org/ontologies/PW', '6848d34e98e62dc96c4f2e500f4983a2c08c0b4ef7e985843e1cd70a95154b7a', 'scored', NULL, 10.0, 6.21, 6.21, 'same_as_strict (1.0 result, not re-checked)', 6.95, 10.0, 8.29, 8.29, NULL, NULL, NULL, 44913, 2761, 2761, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:15:55+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'QUANTUM-MIND', 'Quantum Mind Framework', 'Formal architecture for modeling state-field transitions in human behavioral systems using sigmoid-based activation. Operationalizes the interaction between Directed Focus (f), Raw Perceptual Imprint (alpha), and Perceived Meaning (beta) to calculate the formal observation variable Psi. Foundational for Behavioral and Cognitive Ontology (BCO), providing machine-readable logic for AI ingestion and predictive psychological modeling.', 'Health;Human;Other', 'OWL', 4, NULL, '2026-02-11T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/QUANTUM-MIND', 'd0914cd4856d23fb03202b4af47f53fc5835388f9a14e66566a8b4c060c27d90', 'scored', NULL, 9.27, 5.22, 5.22, 'same_as_strict (1.0 result, not re-checked)', 2.32, 10.0, 6.7025, 6.7025, NULL, NULL, NULL, 4749, 440, 395, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:40+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'QUDT', 'Quantities, Units, Dimensions, and Types Ontology', 'The QUDT, or ''Quantity, Unit, Dimension and Type'' collection of ontologies define the base classes properties, and restrictions used for modeling physical quantities, units of measure, and their dimensions in various measurement systems. The goal of the QUDT ontology is to provide a unified model of, measurable quantities, units for measuring different kinds of quantities, the numerical values of quantities in different units of measure and the data structures and data types used to store and manipulate these objects in software. This OWL schema is a foundation for a basic treatment of units.', 'Other', 'OWL', 46, NULL, '2026-09-22T18:14:31.000-07:00', 'https://bioportal.bioontology.org/ontologies/QUDT', '6e92ad1f2add84e0893912ba31514320d41db1f46e61b0c9f7e42906e82084d5', 'scored', NULL, 10.0, 3.99, 3.99, 'http://purl.org/dc/elements/1.1/description [bioportal_definitionProperty]', 3.01, 10.0, 6.75, 6.75, NULL, NULL, NULL, 3347, 128, 105, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T22:57:07+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'QUDT2', 'Quantities, Units, Dimensions and Types (QUDT) Schema - Version 2.0', 'The QUDT, or "Quantity, Unit, Dimension and Type" schema defines the base classes properties, and restrictions used for modeling physical quantities, units of measure, and their dimensions in various measurement systems. The goal of the QUDT ontology is to provide a unified model of, measurable quantities, units for measuring different kinds of quantities, the numerical values of quantities in different units of measure and the data structures and data types used to store and manipulate these objects in software.

Except for unit prefixes, all units are specified in separate vocabularies. 

This is version 2.0 of QUDT. A more recent version is elsewhere on BioPortal.', 'Upper_Level_Ontology', 'OWL', 1, '2.0', '2016-10-09T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/QUDT2', '0140165ee34be9b9458215d08be0d84a2cefc91e41b0cb3b556a86d59ae70a88', 'scored', NULL, 9.49, 1.47, 1.47, 'same_as_strict (1.0 result, not re-checked)', 2.96, 9.0, 5.73, 5.73, NULL, NULL, NULL, 3325, 156, 114, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:39+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'QUDT2-1', 'Quantities, Units, Dimensions and Types (QUDT Version 2.1)', 'QUDT presents a unified architecture for the conceptual representation of quantities, quantity kinds, units, dimensions, and data types, which lie at the core of all scientific and engineering inquiry. But the QUDT specification is more than a core architecture and a list of these concepts, because it implements international standards and thus provides the foundation for system interoperability. In order to provide for interoperability and data exchange between information systems, the specification needs to be available in a machine processable form, with no ambiguities. For these reasons, the QUDT approach to specifying these concepts is to use precise semantically grounded specifications in an ontology model with translation into machine-processable representations.', '', 'OWL', 2, '2.1', '2020-01-30T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/QUDT2-1', 'd1a4c9b8eeb600f5879e13a7907bfc0fb7048b3088677606766d15cf1eed04bb', 'scored', NULL, 9.12, 3.47, 3.47, 'same_as_strict (1.0 result, not re-checked)', 2.25, 10.0, 6.21, 6.21, NULL, NULL, NULL, 2292, 114, 89, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:09+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'RADLEX', 'Radiology Lexicon', 'RadLex OWL, as downloaded from BioPortal, includes a set of puns in order to facilitate browsing and display.  For the base RadLex ontology alone, without puns,  and release notes for the latest version, please see http://radlex.org/', '', 'OWL', 43, '4.3', '2025-12-01T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/RADLEX', 'c4cfb59b64b06635f5111109c1e5ccb79a0e1723614a3c09e909b1f9cce8bb7d', 'scored', NULL, 10.0, 0.0, 0.55, 'http://www.radlex.org/RID/Definition [bioportal_definitionProperty + detected_by_name]', 4.67, 10.0, 6.1675, 6.305, NULL, NULL, NULL, 818708, 46901, 46901, '0.10.0', 'core4-1.1.1', NULL, '2026-09-23T22:59:20+00:00', '2026-09-23T23:25:10+00:00');
