INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'RADXTT-MVREASONS', 'RADx Tiger Team Missing Value Reasons', 'These concepts define the different reasons values might be missing from the RADx data record. The concepts have been approved by the RADx Executive Committee to fill in fields that do not have a value in them. 

