INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'RDAO', 'Rare Diseases Awareness Ontology', 'The Rare Diseases Awareness Ontology was developed using the Basic Formal Ontology (BFO) framework to support education and awareness processes about rare diseases. It is a semantic data structure that organizes and categorizes specific information about these processes, facilitating access and understanding of the data. This ontology includes key concepts from this domain. Furthermore, it incorporates information to train health professionals, family members, and patients, promoting awareness and more comprehensive education.
Through data modeling and relationships between these concepts, the ontology allows the creation of interactive and personalized educational resources, in addition to facilitating interoperability between health information systems. With accessible language and visual tools, the system supports disseminating knowledge about rare diseases.
This study is supported by the São Paulo Research Foundation (FAPESP) as part of the Public Policy Research Program (grant number 2023/10203-8, managed by Domingos Alves). Diego Yamada is also supported by FAPESP (grant number 2024/06751-2).', 'Health', 'OWL', 5, '3.2', '2024-10-31T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/RDAO', 'a195f81b9b1e4875d31347ccd4a322ae55d8c31fb64b316c6b8d118188503990', 'scored', NULL, 3.44, 1.24, 1.24, 'same_as_strict (1.0 result, not re-checked)', 1.05, 10.0, 3.9325, 3.9325, NULL, NULL, NULL, 2021, 259, 259, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:08+00:00', '2026-09-23T23:25:10+00:00');
