INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'REPRODUCE-ME', 'REPRODUCE-ME', 'The REPRODUCE-ME ontology is an extension of the PROV-O and the P-Plan ontology to describe a complete path of a scientific experiment. It expresses the REPRODUCE-ME Data Model using the OWL2 Web Ontology Language (OWL2). It provides a set of classes and properties to represent a scientific experiment including its computational and non-computational steps to track the provenance of results. It describes an experiment and its data, agents, activities, plans, steps, variables, instruments, materials and settings required for its reproducibility. ', '', 'OWL', 7, '1.1', '2019-01-14T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/REPRODUCE-ME', '1a2c16679459a4db5b946b306ec489177fc110f3fa44008ccf10386c5f7db289', 'scored', NULL, 9.97, 2.91, 3.07, 'https://www.w3.org/TR/rdf-schema/#ch_comment [bioportal_definitionProperty]; http://www.w3.org/ns/prov#definition [detected_by_name (51 uses)]', 0.13, 10.0, 5.7525, 5.7925, NULL, NULL, NULL, 3879, 598, 347, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T22:57:08+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'RETO', 'Regulation of Transcription Ontology', 'An application ontology for the domain of gene transcription regulation. The ontology integrates fragments of GO and MI with data from GOA, IntAct, UniProt, NCBI and orthological properties  from RO and SIO.', 'Biological_Process', 'OWL', 8, '2015', '2015-12-16T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/RETO', '7bef3172ce07d4813ffe29dab7cba639307cd91231636179e2cfcd6b707cffe2', 'scored', NULL, 10.0, 6.65, 6.65, 'same_as_strict (1.0 result, not re-checked)', 8.06, 10.0, 8.6775, 8.6775, NULL, NULL, NULL, 2213766, 147739, 147739, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T07:25:02+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'REX', 'Physico-Chemical Process', 'REX is an ontology of physico-chemical processes, i.e. physico-chemical changes occurring in course of time. REX includes both microscopic processes (involving molecular entities or subatomic particles) and macroscopic processes. Some biochemical processes from Gene Ontology (GO Biological process) can be described as instances of REX.', 'Physicochemical', 'OBO', 7, '1.13', '2011-02-15T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/REX', '13186217c9564e79a54e13ba1dddfde192dc2eb3b0e10aabf908e251be95f7c6', 'scored', NULL, 9.98, 4.16, 4.16, 'same_as_strict (1.0 result, not re-checked)', 5.21, 9.0, 7.0875, 7.0875, NULL, NULL, NULL, 7008, 553, 553, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:06+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'REXO', 'Regulation of Gene Expression Ontolology', 'An application ontology for the domain of gene expression regulation. The ontology integrates fragments of GO and MI with data from GOA, IntAct, UniProt, NCBI,  and orthology relations using ontological properties from RO and ISO.', '', 'OWL', 6, '2015', '2015-12-16T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/REXO', '9926cc8e76ce87143ae27f63575f7ee7cbc66f9c00b2977d3c16e35402d5db85', 'scored', NULL, 10.0, 6.64, 6.64, 'same_as_strict (1.0 result, not re-checked)', 8.07, 10.0, 8.6775, 8.6775, NULL, NULL, NULL, 2350444, 158240, 158240, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T07:31:26+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'RGD', 'RRB Group D', NULL, 'Biological_Process', NULL, -1, NULL, NULL, 'https://bioportal.bioontology.org/ontologies/RGD', NULL, 'no_submission', 'latest_submission http=200 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'RH-MESH', 'Robert Hoehndorf Version of MeSH', 'Medical Subjects Headings Thesaurus 2014, Modified version.

This is an OWL representation of MeSH so that it can be integrated with other ontologies represented in OWL. It contains all terms that are in MeSH and in the MeSH concept tree, including the pharmacological actions (represented as subclass relations).

Concepts in the MeSH concept tree are merged with MeSH term ids.

<p><p>
--------------------------
<p>

Note that, while this ontology is composed of MeSH terms, it does not correspond directly to UMLS MeSH. In particular, a single term in UMLS MeSH often results in multiple classes in this ontology.


For example, in MeSH there is a single term with the label "Heart". The internal code (unique identifier) for this term is A07.541. In 
this ontology there are two entirely different terms, both of which have the label "Heart". The codes for these terms are A07.541 
and D006321. 
', 'Dysfunction;Health;Human;Phenotype;Vocabularies', 'OWL', 3, '2014', '2014-04-21T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/RH-MESH', '6e58e9617ef6b2e1372eb196bed92b9d093d7375533416c24bf1d8cfa3b0f3d7', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.06, 10.0, 5.015, 5.015, NULL, NULL, NULL, 1972712, 305350, 305350, '0.10.0', 'core4-1.0', NULL, '2026-09-23T07:40:40+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'RNAO', 'RNA Ontology', 'The central aim of the RNA Ontology Consortium (ROC) is to develop an ontology to capture all aspects of RNA - from primary sequence to alignments, secondary and tertiary structure from base pairing and base stacking to sophisticated motifs.', 'All_Organisms', 'OBO', 4, 'r113', '2015-08-21T18:06:31.000-07:00', 'https://bioportal.bioontology.org/ontologies/RNAO', '7d48655ea89d33b869c274552e83e9053619bde5fd0e8715a7ad18c640a35aee', 'scored', NULL, 9.99, 0.7, 0.7, 'http://purl.org/dc/elements/1.1/description [bioportal_definitionProperty]', 5.9, 10.0, 6.6475, 6.6475, NULL, NULL, NULL, 7848, 693, 693, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T22:57:11+00:00', '2026-09-23T23:25:10+00:00');
