INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'RNRMU', 'RNRMU', 'The terms of RNRMU', 'Development', 'OWL', 1, '0.1', '2014-09-30T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/RNRMU', '8e133c79e63186ca781a2b6ca5dc52863ce61c8b8ddb48394b8e7b9e9774d03f', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 9.0, 4.75, 4.75, NULL, NULL, NULL, 6962, 2311, 2311, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:08:13+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'RO', 'Radiomics Ontology', 'The Radiomics Ontology aims to cover the radiomics feature domain with a strong focus on first order, shape, textural radiomics features. In addition, in the original version. it includes classes about segmentation algorithms and imaging filters.
Due to a recent collaboration with the IBSI (International Biomarkers Standardization Initiative), the ontology has been expanded (v 1.6) and it includes all the entities presented in the IBSI document. Therefore, a broad coverage of not only radiomics features, but also every entity (e.g. software properties, filter properties, features extraction parameters) involved into radiomics computation has been added. In the latest version (v2.0), the ontology URIs have been updated to reflect the codes avaialble in the IBSI latest manual', 'Biomedical_Resources;Imaging', 'OWL', 6, '2.1', '2017-08-29T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/RO', 'cf99b64a7b2ed1d732ee74485458aed9ed179c63c6659b5bcda10a044defc34b', 'scored', NULL, 9.96, 5.09, 5.09, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 6.2625, 6.2625, NULL, NULL, NULL, 2578, 486, 459, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:04+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ROADMAP', 'Radiology Ontology of AI Datasets, Models and Projects', 'ROADMAP provides a controlled terminology for the metadata that describe AI models and datasets. It builds on "model cards" and "datasheets for datasets" with imaging-specific descriptors. It includes a comprehensive set of metrics to assess the performance of AI models that work with images, text, and/or discrete data. ', 'Biomedical_Resources;Imaging;Vocabularies', 'OWL', 7, NULL, '2026-05-21T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ROADMAP', '82f5941681759e509cff907ce727be87f5340786d573e3fa324eed030721a651', 'scored', NULL, 10.0, 6.64, 6.64, 'same_as_strict (1.0 result, not re-checked)', 3.16, 10.0, 7.45, 7.45, NULL, NULL, NULL, 8302, 651, 647, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:13+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ROCKNROLLTEST', 'ROCK-N-ROLL-TEST', 'This Vocabulary describes some few terms of high level geologic concept hierarchy. This vocabulary is not complete and half randomly made up, but based on the USGS North American Geological Map Data Model. It is a test before the M4M workshop.
', '', 'SKOS', 2, NULL, '2021-03-30T18:20:43.000-07:00', 'https://bioportal.bioontology.org/ontologies/ROCKNROLLTEST', 'c37f2ca1a245ddecad2a94c3c4075fe4c8b5e564d54c8bf2cd3cfcdf6d4c60e5', 'scored', NULL, 6.67, 2.34, 2.34, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.2525, 2.2525, NULL, NULL, NULL, 23, 3, 2, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:03:35+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ROLEO', 'Role Ontology', 'The Role Ontology (RoleO) is an ontology in the domain of role classification. RoleO aims to standardize role classification and support computer-assisted reasoning.  RoleO development follows the OBO Foundry principles. RoleO has represented  all the occupations defined in the Standard Occupational Classification (SOC) System from the USA Bureau of Labor Statistics. ', '', 'OWL', 3, 'Vision Release: 1.0.16', '2018-03-24T18:13:32.000-07:00', 'https://bioportal.bioontology.org/ontologies/ROLEO', '560d33ae2b5aef99790b1c1535fde126371df0cfba8daa15654c0efcdbfcb88e', 'scored', NULL, 10.0, 0.38, 0.38, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 5.095, 5.095, NULL, NULL, NULL, 14475, 2126, 2126, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:05+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ROO', 'Radiation Oncology Ontology', 'The Radiation Oncology Ontology aims to cover the radiation oncology domain with a strong focus on re-using existing ontologies.

From release 0.5 forward the ROO has changed its naming scheme from all entities starting with numbers to all entities starting with C(lasses) or P(redicates). This change was needed for better compatibility to web standards. Releases 0.4.1-0.4.3. include the necessary axioms to go from the original naming scheme to the new naming scheme.
 <br />
 <br />0.4.1: Added new entities with equivalence to the old entities
 <br />0.4.2: Added deprecated property to the old entities
 <br />0.4.3: Removed axioms with the old entities except annotations
 <br />0.5: Removed all old entities, the new base', 'Development;Health;Human;Imaging;Vocabularies', 'OWL', 8, '0.5', '2018-06-19T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ROO', 'a40655b0f16b1c9e10555bdd8a4eac6c54829a90c0265920374888a86ae3aed9', 'scored', NULL, 10.0, 5.17, 5.17, 'same_as_strict (1.0 result, not re-checked)', 0.19, 10.0, 6.34, 6.34, NULL, NULL, NULL, 12091, 1307, 1307, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:55+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ROR', 'Research Organization Registry', 'ROR (Research Organization Registry) is a global, community-led registry of open persistent identifiers for research organizations. ROR is jointly operated by California Digital Library, Crossref, and Datacite.

This artifact is produced by PyOBO in the https://github.com/biopragmatics/obo-db-ingest repository., community-led registry
of open persistent identifiers for research organizations. ROR is jointly
operated by California Digital Library, and Datacite.', '', 'OWL', 1, '2.0', '2026-01-23T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ROR', '77edac29ae9f2d49fcb3fb2ad654f8fe54d636800a6285f0f51a456ed38fe589', 'scored', NULL, 10.0, 4.94, 4.94, 'same_as_strict (1.0 result, not re-checked)', 8.14, 7.0, 7.52, 7.52, NULL, NULL, NULL, 1546347, 137753, 10, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T07:05:54+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'ROS', 'Radiation Oncology Structures Ontology', 'This ontology describes commonly contoured (anatomical and treatment planning) structures for radiation treatment planning. 22000 structures labels (created over a 16 years period in our radiation department) were extracted, classified and categorized to produce this ontology. Lymph nodes delineation international guidelines are provided.

This ontology was created to ease and standardize the integration of radiation oncology data into clinical datawarehouses for multicentric studies. The high granularity of this ontology will allow precise dosimetric evaluations.', 'Anatomy;Human;Imaging', 'OWL', 6, '1.2.2', '2017-07-27T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/ROS', '2e9929ce3f2bbafd1b4062629e930ecdedc1f4c5ffdcd18301c4cb8d0b64fb20', 'scored', NULL, 10.0, 1.47, 1.47, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 5.3675, 5.3675, NULL, NULL, NULL, 2134, 416, 416, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:02+00:00', '2026-09-23T23:25:10+00:00');
