INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SALMON', 'Salmon Ontology', 'An ontology representing knowledge about salmon, features of their habitats, salmon stakeholders, and related entities. This ontology is considered to be in the early stages of development, though it is based upon considerable previous work. Contributions of all kinds are welcome and encouraged, including alignments, updates to existing terms, and new terms.', 'Fish_Anatomy;Other;Taxonomic_Classification', 'OWL', 4, '0.4.0', '2024-09-04T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SALMON', '09fc7b0860c140f74725c899c66c3ca2d3f4a844c0f1523508d1a9484b7d367a', 'scored', NULL, 9.99, 5.6, 5.6, 'same_as_strict (1.0 result, not re-checked)', 5.58, 10.0, 7.7925, 7.7925, NULL, NULL, NULL, 20594, 1161, 1122, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:10:57+00:00', '2026-09-23T23:25:10+00:00');
