INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SARSMUTONTO', 'Ontology for SARS-CoV-2  lineages and mutations', 'The SARSMutOnto ontology provides a list of all SARS-CoV-2 Pango lineages while maintaining their hierarchy (lineage/sublineage) describing in detail all lineage mutations', 'Gene_Product;Genomic_and_Proteomic', 'OWL', 7, '1.1', '2023-02-01T18:22:36.000-08:00', 'https://bioportal.bioontology.org/ontologies/SARSMUTONTO', '4ca138f76e85fdbeef01c1d1838831e94e06431db075c4fdf3f08f62a45a360c', 'scored', NULL, 4.35, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 1.49, 10.0, 3.96, 3.96, NULL, NULL, NULL, 25699, 5488, 2388, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:13:01+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SASAP', 'The State of Alaska''s Salmon and People Ontology', 'An ontology which represents information about the State of Alaska''s Salmon and People (SASAP) project, as well as knowledge about salmon, features of their habitats, salmon stakeholders, and related entities.', 'Other', 'OWL', 2, '0.3.1', '2022-07-22T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SASAP', '0bd16faefffc28d414d091e9388874d15197f1b910b6b173d48716e57799c2bf', 'scored', NULL, 9.8, 1.78, 1.78, 'same_as_strict (1.0 result, not re-checked)', 7.77, 9.0, 7.0875, 7.0875, NULL, NULL, NULL, 2498, 252, 31, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:19+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SATO', 'SATO (IDEAS expAnded wiTh BCIO): workflow for designers of patient-centered mobile health behaviour change intervention applications', 'Designing effective theory-driven digital behaviour change interventions (DBCI) is a challenging task. To ease the design process, and assist with knowledge sharing and evaluation of the DBCI, we propose the SATO (IDEASexpAnded wiTh BCIO) design workflow based on the IDEAS (Integrate, Design, Assess, and Share) framework and aligned with the Behaviour Change Intervention Ontology (BCIO). BCIO is a structural representation of the knowledge in behaviour change domain supporting evaluation of behaviour change interventions (BCIs) but it is not straightforward to utilise it during DBCI design. IDEAS (Integrate, Design, Assess, and Share) framework guides multi-disciplinary teams through the mobile health (mHealth) application development life-cycle but it is not aligned with BCIO entities. SATO couples BCIO entities with workflow steps and extends IDEAS Integrate stage with consideration of customisation and personalisation.
The SATO ontology provides the extensions of BCIO along with examples of a BCI Scenario of Fatigue Reduction.', 'Health', 'OWL', 2, 'v2', '2022-11-17T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SATO', '49431b908c431e110daedbb108e0b15ab982f72e3b0ae26d54f40d573b3c92e5', 'scored', NULL, 9.99, 6.56, 6.56, 'same_as_strict (1.0 result, not re-checked)', 0.43, 10.0, 6.745, 6.745, NULL, NULL, NULL, 10176, 1265, 1264, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:46+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SATUSEHATTHESIS', 'SatuSehatThesis', 'This is only the beginning', 'Biomedical_Resources', 'SKOS', 1, NULL, '2024-11-11T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SATUSEHATTHESIS', 'a16a7032ef1001a6817048d10b4d84b548d1690365d0a287dadb6e724b737081', 'scored', NULL, 8.6, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.15, 2.15, NULL, NULL, NULL, 1911, 599, 13, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:06:05+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SBO', 'Systems Biology Ontology', 'The Systems Biology Ontology is a set of controlled, relational vocabularies of terms commonly used in Systems Biology, and in particular in computational modeling. The ontology consists of six orthogonal vocabularies defining: the roles of reaction participants (eg. "substrate"), quantitative parameters (eg. "Michaelis constant"), a precise classification of mathematical expressions that describe the system (eg. "mass action rate law"), the modeling framework used (eg. "logical framework"), and a branch each to describe entity (eg. "macromolecule") and interaction (eg. "process") types, and a branch to define the different types of metadata that may be present within a model.

SBO terms can be used to introduce a layer of semantic information into the standard description of a model, or to annotate the results of biochemical experiments in order to facilitate their efficient reuse. SBO is an Open Biomedical Ontologies (OBO) candidate ontology, and is free for use. More information about SBO can be found from the project FAQ, at http://www.ebi.ac.uk/sbo/

SBO is a project of the BioModels.net effort and is developed through community collaboration.', 'Vocabularies', 'OWL', 663, '28:08:2021 03:13', '2023-05-16T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SBO', '1b6518e28abf62b952eb78e7ed6a07d2004925327a9068fcced3b1c603ce743f', 'scored', NULL, 9.99, 6.52, 6.52, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 6.6275, 6.6275, NULL, NULL, NULL, 3689, 696, 696, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:08+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SBOL', 'Synthetic Biology Open Language Visual Ontology', 'Synthetic Biology Open Language Visual (SBOLv) is an ontology to represent standardized graphical notation for synthetic biology.', 'Other', 'OBO', 2, 'unknown', '2013-04-26T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/SBOL', '99cbc94e365b79d7337781cc0120eb1b8d74ab3c7f0e6bc121b29d2bea64d98c', 'scored', NULL, 9.76, 6.08, 6.08, 'same_as_strict (1.0 result, not re-checked)', 4.58, 9.0, 7.355, 7.355, NULL, NULL, NULL, 703, 42, 42, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:50+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SCDO', 'Sickle Cell Disease Ontology', 'The Sickle Cell Disease Ontology (SCDO) project is a collaboration between H3ABioNet (Pan African Bioinformatics Network) and SPAN (Sickle Cell Disease Pan African Network). The SCDO is currently under development and its purpose is to:

1) establish community standardized SCD terms and descriptions,
2) establish canonical and hierarchical representation of knowledge on SCD,
3) links to other ontologies and bodies of work such as DO, PhenX, MeSH, ICD, NCI’s thesaurus, SNOMED and OMIM.

Once complete, we anticipate that the ontology will:

1) be the most comprehensive collection of knowledge on SCD,
2) facilitate exploration of new scientific questions and ideas,
3) facilitate seamless data sharing and collaborations including meta-analysis within the SCD community,
4) support the building of databasing and clinical informatics in SCD.', 'Biomedical_Resources', 'OWL', 21, '2021-04-15', '2021-05-06T18:30:09.000-07:00', 'https://bioportal.bioontology.org/ontologies/SCDO', 'b0f4ba561ce6e619d9044482b05b49253bd17c8e5699739adfe7d27bc09e00a5', 'scored', NULL, 10.0, 6.44, 6.44, 'same_as_strict (1.0 result, not re-checked)', 4.49, 10.0, 7.7325, 7.7325, NULL, NULL, NULL, 42240, 2072, 2072, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:13:25+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SCHEMA', 'Schema.org core and all extension vocabularies', 'A collection of schemas that webmasters can use to markup HTML pages in ways recognized by major search providers, and that can also be used for structured data interoperability (e.g. in JSON). This representation includes all layers, as presented in the experimental OWL file at https://schema.org/docs/schemaorg.owl.', 'Vocabularies', 'OWL', 6, '30.1', '2026-09-15T18:20:04.000-07:00', 'https://bioportal.bioontology.org/ontologies/SCHEMA', '31827ea0ea7b10eb534461492bff7284394eba298235c4018b736cc11f02c95f', 'scored', NULL, 9.99, 6.23, 6.23, 'same_as_strict', 8.13, 10.0, 8.5875, 8.5875, NULL, NULL, NULL, 37596, 950, 950, '0.10.0', 'core4-1.1.1', 'cuda', '2026-09-23T22:57:21+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SCIO', 'Spinal Cord Injury Ontology', 'Representation of pre-clinical studies in the domain of spinal cord injury therapies', 'Biomedical_Resources;Experimental_Conditions;Neurologic_Disease;Neurological_Disorder', 'OWL', 2, '1', '2017-09-19T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SCIO', '6ed5b6138346e2d9c2a13cdd5b012d4045e407a1b01b710f0fbd59b5803eae9d', 'scored', NULL, 9.23, 0.67, 0.67, 'same_as_strict (1.0 result, not re-checked)', 0.78, 10.0, 5.17, 5.17, NULL, NULL, NULL, 4304, 532, 320, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:01+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SCO', 'Study Cohort Ontology', 'The Study Cohort Ontology (SCO) is developed to model overall structure and patterns of cohort variables and control/intervention groups defined within the structured population descriptions (commonly referred to as Table1''s or Cohort Summary Tables)of observational case studies and clinical trials. We maintain only domain agnostic and commonly occuring subject variables and interventions in SCO, and we have a suite of ontologies (Diseases, Medications, LabResults etc) to encode Diabetes related terminology. We have adopted a bottom-up approach to modeling and we have revised the structure of SCO upon investigation of a few research studies (11 to be precise) from the Pharmacological Interventions (Chapter 8) and Cardiovascular Complications (Chapter 9) of the American Diabetes Association (ADA)’s Standards of Medical Care 2018 CPG. We enable deep drive visualizations driven off queries to knowledge graphs modeled on SCO, to help assist physician visualize the similarity of a patient to a study group, at a quick glance. We welcome contributions and suggestions to extend SCO to represent cohort descriptions of publications targeted to other diseases, and we plan to release set of tools to make this process seamless.', 'Biomedical_Resources;Health', 'OWL', 5, '1.1.0', '2019-04-18T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SCO', 'af6bd515e617230bc400695f57075da28653af18716f3b3c56667fc3c13f5c3b', 'scored', NULL, 8.32, 4.12, 4.12, 'same_as_strict (1.0 result, not re-checked)', 6.24, 10.0, 7.17, 7.17, NULL, NULL, NULL, 30382, 3917, 2712, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:12:10+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SCO-U', 'Sustainability Core Ontology - Segment U', 'SCO is a middle-level ontology, representing the major theoretical challenges to sustainability:
1) The polysemy of the term sustainability.
2) The relationship between sustainability and sustainable development.
3) The complexity underlying sustainability.
SCO aims to play a pivotal role in harmonizing and integrating top-level and domain ontologies regarding sustainability., SCO V1.1.0 aligns with two Top-Level Ontologies (TLOs), Basic Formal Ontology (BFO) and Unified Foundational Ontology (UFO). SCO V1.1.0 is comprised of two segments: SCO-B (B for BFO) and SCO-U (U for UFO). SCO-B aligns the SCO vocabulary with BFO (as SCO V1.0.0). SCO-U aligns the SCO vocabulary with gUFO (UFO implementation in the Web Ontology Language (OWL)). This file provides SCO-U segment.

References – TLOs:  
https://github.com/BFO-ontology/BFO-2020 
https://ontouml.readthedocs.io/en/latest/intro/ufo.html 
https://nemo-ufes.github.io/gufo/', 'Other', 'OWL', 5, 'Version 1.1.0. ; segment U.', '2025-10-17T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SCO-U', '4613e1b4a3b2bbcd637e882a019fd99c7e32786565b692f7a378492134cba9d2', 'scored', NULL, 10.0, 6.99, 6.99, 'same_as_strict (1.0 result, not re-checked)', 5.4, 9.0, 7.8475, 7.8475, NULL, NULL, NULL, 6501, 116, 113, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:31+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SCO_V1', 'Sustainability Core Ontology', 'The Sustainability Core Ontology (SCO) is a middle-level ontology, covering the terminology related to the three major theoretical challenges of sustainability: 1) The polysemy of the term sustainability. 2) The relationship between sustainability and sustainable development. 3) The complexity underlying sustainability. SCO is designed to be the pivotal resource upon which to harmonize and integrate ontologies regarding sustainability. The ultimate goal is to establish a family of interoperable sustainability ontologies. Currently, SCO employs Basic Formal Ontology (BFO) and Unified Foundational Ontology (UFO) as the upper-level ontologies. SCO V1.1.0 is the current release and is comprised of two segments: SCO-B (B for BFO) and SCO-U (U for UFO). SCO-B aligns the SCO vocabulary with BFO. SCO-U aligns the SCO vocabulary with gUFO (UFO implementation in the Web Ontology Language (OWL)). SCO V1.1.0. conforms to OBO-Foundry principles. The most recent version of SCO-B segment can always be found at https://w3id.org/sco. The most recent version of SCO-U segment can always be found at https://w3id.org/sco/sco-u.
This file provides SCO-B segment. References – TLOs: https://github.com/BFO-ontology/BFO-2020 https://ontouml.readthedocs.io/en/latest/intro/ufo.html https://nemo-ufes.github.io/gufo/
', 'Other', 'OWL', 5, 'Version 1.1.0. ; segment B.', '2025-10-11T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SCO_V1', '49e27b24c1e0f6e490c469d6e7ce52f9c1f1da9d177c0e6df492f5a309e73f88', 'scored', NULL, 9.88, 6.95, 6.95, 'same_as_strict (1.0 result, not re-checked)', 5.5, 9.0, 7.8325, 7.8325, NULL, NULL, NULL, 6396, 83, 81, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:08:19+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SD3', 'Simulation Delivery and Documentation Deviations', 'The taxonomy will facilitate quality assurance in scenario delivery, permit standardized descriptors of simulation delivery deviations, and enable researchers to quantify the impact that scenario delivery and documentation deviations have upon participant performance. Though created specifically for high-fidelity mannequin-based simulation, the taxonomy can be applied to other simulation modalities.', 'Other', 'OWL', 1, '1.0', '2015-04-27T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SD3', 'd5faea286313f6667aebed50a6b36491db060f926283c26363b179b7def724a2', 'scored', NULL, 10.0, 4.39, 4.39, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 6.0975, 6.0975, NULL, NULL, NULL, 293, 57, 57, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:30+00:00', '2026-09-23T23:25:10+00:00');
