', 'Health;Human;Neurologic_Disease;Neurological_Disorder;Phenotype', 'OWL', 4, 'Last modification: Feb. 11, 2013 Sivaram Arabandi', '2015-06-23T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SDO', '6f3427fb120893b25cc20703c02d9fec8d591d8b4d7bd1daddacf6bf5e2654d1', 'scored', NULL, 9.94, 3.48, 3.48, 'same_as_strict (1.0 result, not re-checked)', 4.05, 9.0, 6.6175, 6.6175, NULL, NULL, NULL, 14372, 1436, 1382, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:26+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SDOED', 'Social Determinants of Education Ontology', 'Social Determinants of Education Ontology (SDoE) arise from the growing recognition that various factors influence educational outcomes.
Educational success or failure is not solely determined by in-school factors but external factors including social, economic, and environmental influences effect the edcational outcome.
e.g. family income, access to resources, neighborhood, health, and more
', '', 'OWL', 1, 'V1', '2024-10-13T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SDOED', '1628d97bb39851067bfbf7e89302a437a7ac625bc17ebe1251a9b2385ad72c91', 'scored', NULL, 0.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 6.99, 10.0, 4.2475, 4.2475, NULL, NULL, NULL, 955, 232, 232, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:57+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SDOHO', 'social determinants of health ontology-TaoLab', 'SDoHO aims to represent fundamental SDoH factors and their relationships in a standardized and measurable way. It has well-designed hierarchies, practical objective properties, and versatile functionalities, and the comprehensive semantic and coverage evaluation achieved promising performance compared to the existing ontologies relevant to SDoH.', 'Health', 'OWL', 2, 'SDoHO_1216', '2024-02-22T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SDOHO', 'c5dd607751bca7d9c3f2370eb646a757ee9b9d5457a9819ac1ad415a82687182', 'scored', NULL, 9.69, 2.44, 2.44, 'same_as_strict (1.0 result, not re-checked)', 1.91, 10.0, 6.01, 6.01, NULL, NULL, NULL, 2655, 421, 386, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:21+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SEDI', 'Semantic DICOM Ontology', 'An ontology for DICOM as used in the SeDI project.', '', 'OWL', 6, '0.6 alpha', '2015-06-10T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SEDI', 'dfe257d55e44e084c516fd2fd840c47ef7c5c077d450952fed548f0f6ffd7705', 'scored', NULL, 9.99, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 4.58, 9.0, 5.8925, 5.8925, NULL, NULL, NULL, 61649, 1424, 1424, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:14:25+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SENSO', 'Sensitive Data Ontology', 'The SENSO ontology is designed to provide classification terms for labeling sensitive data for data archival and sharing.', 'Other;Vocabularies', 'OWL', 1, 'Version 0.1.0', '2021-10-13T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SENSO', '81ac925db6293cb94386c53fe10607767f7a65cc49cc4ae35cb1d2c6a61a60b0', 'scored', NULL, 8.0, 5.29, 5.29, 'same_as_strict (1.0 result, not re-checked)', 0.0, 7.0, 5.0725, 5.0725, NULL, NULL, NULL, 72, 5, 5, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:03:41+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SEP', 'Sample Processing and Separation Techniques Ontology', 'A structured controlled vocabulary for the annotation of sample processing and separation techniques in scientific experiments, such as, and including, gel electrophoresis, column chromatography, capillary electrophoresis, centrifugation and so on. Developed jointly by the HUPO Proteomics Standards Initiative and The Metabolomics Standards Initiative.', '', 'OBO', 5, '1.070708', '2015-08-21T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SEP', '020f2ce388cc53d3ad5cf5c9da80716ee7e36581b94923ddbeccb4197e70fcd4', 'scored', NULL, 9.96, 6.2, 6.2, 'same_as_strict (1.0 result, not re-checked)', 7.7, 10.0, 8.465, 8.465, NULL, NULL, NULL, 3126, 224, 224, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:38+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SEPIO', 'Scientific Evidence and Provenance Information Ontology', 'The Scientific Evidence and Provenance Information Ontology (SEPIO) was developed to support description of evidence and provenance information for scientific claims. The core model represents the relationships between claims, their evidence lines, the information items that comprise these lines of evidence, and the methods, tools, and agents involved in the creation of these entities. Use cases driving SEPIO development include integration of scientific claims and their associated evidence/provenance metadata, and support for the discovery, analysis, and evaluation of claims based on this metadata.', 'Other', 'OWL', 7, '2023-06-13', '2023-06-29T18:29:17.000-07:00', 'https://bioportal.bioontology.org/ontologies/SEPIO', 'a2be178ac0ecb0a83349950b4e5828e0b1f6980c9ee4b37fef7a6746127e8e01', 'scored', NULL, 10.0, 4.81, 4.81, 'same_as_strict (1.0 result, not re-checked)', 3.94, 9.0, 6.9375, 6.9375, NULL, NULL, NULL, 4922, 148, 127, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:21+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SEPON', 'Sepsis Ontology', 'The Sepsis Ontology (SEPON) is a disease-specific ontology that defines the concepts and relationships between concepts in the field of sepsis and related diseases, contributing to data standardization and providing precise and personalized diagnosis, treatment and prognosis recommandations for sepsis.', 'Health;Human', 'OWL', 2, 'V1.0.0', '2024-05-14T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SEPON', '1be1c9728e223502a19aa83fa40909af1c163729f89e8d933672c92fe0445f10', 'scored', NULL, 9.99, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.01, 10.0, 5.0, 5.0, NULL, NULL, NULL, 14241, 1909, 1909, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:10:25+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SHEDDING-HUB', 'Pathogen and Biomarker Shedding', 'The Shedding Hub Vocabulary (SHV) is a SKOS-based controlled vocabulary designed to standardize terminology for studies involving pathogen and biomarker shedding., A controlled vocabulary for studies with pathogen and biomarker shedding information.', 'Biomedical_Resources;Human', 'SKOS', 3, '0.2.0', '2025-05-20T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SHEDDING-HUB', '313ccb2c6a325386f783db5542a816bc2e7a0ae678e6ac92cf247f7791396567', 'scored', NULL, 9.92, 0.88, 0.88, 'same_as_strict (1.0 result, not re-checked)', 8.56, 4.0, 5.84, 5.84, NULL, NULL, NULL, 1186, 118, 117, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:06+00:00', '2026-09-23T23:25:10+00:00');
