INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SIMM', 'In Silico Methodologies Ontology for MAATrica metric', 'MAATrica is a novel metric for assessing the coherence of methodologies in research papers within the fields of medicinal and nutraceutical chemistry. MAATrica employs user-controlled and customizable ontologies (in silico, in vitro and in vivo), enabling personalized analysis of research papers in the fields of medicinal and nutraceutical chemistry.', 'Chemical;Molecule;Protein;Vocabularies', 'OBO', 1, NULL, '2024-04-21T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SIMM', 'ead97d7bae6d5afb98cca58adf828ce9f0671bca4d44b8dc585e75abf1aad445', 'scored', NULL, 9.97, 0.07, 0.07, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 5.01, 5.01, NULL, NULL, NULL, 1941, 305, 305, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:53+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SIMON', 'Simple Measurement Ontology', 'The SImple Measurement ONtology (SIMON) is a small vocabulary (3 top level classes: PunnedClass, Measurement, and Unit) to represent measurements and units. It uses the pattern to represent N-ary relations and a recursive structure to make the representation of various measurements and units (e.g., "5 kilograms", "4 miles per hour", "5 meters per second per second"  straight forward and obvious. It utilizes the Semantic Web Rule Language (SWRL) to automatically order measurements of the same type (e.g., Speed) regardles of units. E.g., that 5 kilometers per hour is greater than 5 meters per hour. It does this by transforming all measures of a specific type (e.g., distance, mass, speed, acceleration) to canonical units. The canonical units can be modified by changing a few rules. I also include on the github page some SPARQL transformations that generate the rdfs:label for each measurement instance so the developer doesn''t have to take the effort and potential error prone risk of doing this manually.  The version included here is the version after the SWRL rules have run and with the inferences exported and also after the SPARQL transforms have generated all the rdfs:label values. Although there are other vocabularies that address this problem they are either much more complex (addressing many additional issues besides units and measures) and/or do not automatically order measures of different units. ', 'Vocabularies', 'OWL', 1, '1.0', '2021-05-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SIMON', '5b0a89c2d59021326ecb7d6228278f28b92931124cbfe9739ef4bb2163f13639', 'parse_failed', 'unsupported format (tried xml, auto, turtle, n3, nt, trig, trix, owlready2:rdfxml). Last error: RDF/XML parsing error in file C:\owl4_run\downloads\SIMON\1\SIMON_1_original-submission.owl, line 33, column 210.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-23T21:58:37+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SIO', 'Semanticscience Integrated Ontology', 'The semanticscience integrated ontology (SIO) provides a simple, integrated upper level ontology (types, relations) for consistent knowledge representation across physical, processual and informational entities. It provides vocabulary for the Bio2RDF (http://bio2rdf.org) and SADI (http://sadiframework.org) projects., integrated ontology (types, relations) for objects, processes and their attributes.

This project provides foundational support for the Bio2RDF (http://bio2rdf.org) and SADI (http://sadiframework.org) projects. 

website: http://semanticscience.org
email: sio-ontology@googlegroups.com
mailing list: http://groups.google.com/group/sio-ontology
', 'All_Organisms;Biological_Process;Biomedical_Resources;Cell;Cellular_anatomy_;Chemical;Gene_Product;Genomic_and_Proteomic;Molecule;Phenotype;Physicochemical;Protein;Subcellular;Subcellular_anatomy;Taxonomic_Classification;Vocabularies;Yeast', 'OWL', 95, '1.61', '2010-03-29T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SIO', '4aef5ad383f7083ba998a32daa769aa42a5171784dd1e1dcd4a2c70224041161', 'scored', NULL, 9.99, 5.71, 5.71, 'same_as_strict (1.0 result, not re-checked)', 2.21, 10.0, 6.9775, 6.9775, NULL, NULL, NULL, 16269, 1586, 1586, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:44+00:00', '2026-09-23T23:25:10+00:00');
