INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SLEEP', 'SLEEP ontology', 'The SLEEP ontology aims to facilitate the collection of PGHD related to sleep patterns and behaviors. It was created by organizing sleep-related terms gathered from sleep questionnaires and specialized literature.', 'Health;Human', 'OWL', 1, '1.0', '2024-12-04T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SLEEP', '240137b04a038e2cbd27e3ea868e83e0358d583677967ef549bd7f5bd1010536', 'scored', NULL, 9.9, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 4.975, 4.975, NULL, NULL, NULL, 632, 105, 105, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:49+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SLSO', 'Space Life Sciences Ontology', 'The Space Life Sciences Ontology is an application ontology and is intended to support the operation of NASA''s Life Sciences Data Archive (located at https://nlsp.nasa.gov) and other systems that contain space life science research data. Many kinds of scientific research in space involve specialized equipment, experimental procedures, specimens and specimen collection apparatus, supporting operational structures, and references to specific space environments and their characteristics. Often such research is extremely costly compared with planetary/terrestrial investigations, and the community supporting space life sciences is accustomed to the use of various specialized concepts and terminologies when dealing with this kind of research and data. However, the underlying conceptual models (and especially the specific labeled relationships in these models) have never been made explicit. The SLSO attempts to provide definition and organization of these models for the space research community.
The SLSO was developed ab inicio using the Ontology Development Kit and imports an extends many concepts from the Basic Formal Ontology (BFO), the Ontology of Biomedical Investigations (OBI), the Environmental Ontology (ENVO), and other OBO Foundry ontologies. Projects at NASA such as the Open Science Data Repository (https://osdr.nasa.gov/) are already using many OBO ontologies, including the Radiation Biology Ontology (https://github.com/Radiobiology-Informatics-Consortium/RBO) and OBI, to index space biology investigation data. With the development of the SLSO, this practice can be extended to include all life science research in space or addressing space effects. Furthermore, the SLSO has a component that imports concepts from the Science Data Discovery Ontology, which was developed to support NASA''s Science Discovery Engine (https://sciencediscoveryengine.nasa.gov). These links in the imported SDDO to concepts underlying a broad spectrum of space research (astrophysics, helio', 'Biological_Process;Experimental_Conditions;Health;Human', 'OWL', 16, '2025-12-11', '2025-12-11T18:19:05.000-08:00', 'https://bioportal.bioontology.org/ontologies/SLSO', '7fd20a554d767e665ecce7dacfb5912f87621b038e3b73a91c6c77e6f682f037', 'scored', NULL, 10.0, 5.36, 5.36, 'same_as_strict (1.0 result, not re-checked)', 2.96, 10.0, 7.08, 7.08, NULL, NULL, NULL, 66597, 4680, 3979, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:16:40+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SL_DIS', 'Sleep Disorders ', NULL, '', 'OWL', 2, '2.0', '2025-08-25T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SL_DIS', 'e1d133780509268db4ad2a4c9be6765b787fbd690a86f923b0b9da7f73ce5f28', 'scored', NULL, 4.47, 2.25, 2.25, 'same_as_strict (1.0 result, not re-checked)', 6.48, 10.0, 5.8, 5.8, NULL, NULL, NULL, 3147, 340, 177, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:16+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SMASH', 'SMASH Ontology', 'The SMASH (Semantic Mining of Activity, Social, and Health data) system ontology describes concepts used in describing the semantic features of healthcare data and social networks. The SMASH system primarily addresses the research topic of sustained weight loss with continued intervention with frequent social contacts.', 'Health', 'OWL', 6, NULL, '2015-06-02T18:14:47.000-07:00', 'https://bioportal.bioontology.org/ontologies/SMASH', '0eca9b951714e6c4e951a1e1186ce5a4b9b61bb5163bd932e1b8746610e7582b', 'scored', NULL, 2.29, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.41, 10.0, 3.175, 3.175, NULL, NULL, NULL, 1209, 231, 190, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:05:39+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SNMI', 'Systematized Nomenclature of Medicine, International Version', 'SNOMED International concepts are organized into 12 axes. The 12 axes are:

Chemicals, Drugs and Biological Products,
Diseases/Diagnoses,
Function,
General Linkage/Modifiers,
List of Pharmaceutical Companies,
Living Organisms,
Morphology,
Occupations,
Physical Agents, Forces, and Activities,
Procedures,
Social Context, and
Topography.

SNOMED International has been superseded by the Systematized Nomenclature of Medicine – Reference Terminology (SNOMED RT®). SNOMED RT has been merged with Clinical Terms Version 3 (CTV3), also known as Read Codes, resulting in the creation of SNOMED Clinical Terms (SNOMED CT®). For more information about SNOMED CT in the Metathesaurus, see the SNOMED CT source synopsis.

Cote, Roger A., editor. Systematized Nomenclature of Human and Veterinary Medicine: SNOMED International. Northfield (IL): College of American Pathologists; Schaumburg (IL): American Veterinary Medical Association, Version 3.5, 1998.', '', 'UMLS', 24, '2024AA', '2024-05-06T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SNMI', 'b575d38624eb196e0ec39d82acd127dbc1e93d6cbb2e48039225f18a7fad9bbd', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 8.01, 10.0, 7.0025, 7.0025, NULL, NULL, NULL, 1107694, 109156, 109156, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T07:01:34+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SNOMEDCT', 'SNOMED CT, US Edition', '<p>The US Edition of SNOMED CT combines the International Release of SNOMED CT and the US Extension of SNOMED CT</p>

<p>SNOMED CT provides the core general terminology for the electronic health record (EHR). The concepts have unique meanings and formal logic-based definitions organized into hierarchies. Each International Release includes the core of the terminology (concepts, descriptions, and relationships), together with works to support the implementation and use of SNOMED CT, including subsets, cross maps to existing classifications and coding schemes, and an extensive set of guidelines.</p>

<p>The US Extension to SNOMED CT included the concepts, descriptions, and relationships accepted by NLM as a formal extension to the SNOMED CT International Release. NLM no longer releases the standalone US Extension.</p>

The US Edition of SNOMED CT includes more than 300,000 unique concepts. There are over 1,000,000 descriptions in SNOMED CT, including synonyms that can be used to refer to a concept. In addition, there are approximately 903,000 links or semantic relationships between the SNOMED CT concepts.</p>', 'Health', 'UMLS', 32, '2025_09_01', '2025-11-03T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SNOMEDCT', NULL, 'not_downloadable', '{"errors":["License restrictions on download for SNOMEDCT"],"status":403}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SNPO', 'Single-Nucleotide Polymorphism (SNP) Ontology', 'SNP-Ontology is a domain ontology that provides a formal representation (OWL-DL) of genomic variations. Despite its name, SNP-Ontology, is not limited to the representation of SNPs but it encompasses genomic variations in a broader meaning. SNP-Ontology is general enough to enable the representation of variations observed in genome of various species. Latest versions of SNP-Ontology include the representation of haplotype and of CNV. The unambiguous representation of genomic variations provided by SNP-Ontology enables to integrate heterogeneous data related to genomic variations. To achieve this goal SNP-Ontology enables (1) to represent one variation in accordance with various ways that exist for describing it, (2) to represent the equivalence between two distinct descriptions of one variation, and (3) to represent correspondence between a genomic variation and its outcome at the transcriptome and proteome levels.', 'Genomic_and_Proteomic', 'OWL', 4, 'version: full 1.6
release: 14/03/2017', '2017-03-14T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SNPO', 'e380baef67d04cad78a3732db60ad277eacd399ea1426cd58493aba5204ceb7e', 'scored', NULL, 10.0, 4.36, 4.36, 'same_as_strict (1.0 result, not re-checked)', 1.67, 10.0, 6.5075, 6.5075, NULL, NULL, NULL, 1035, 90, 90, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:19+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SO', 'Sequence Types and Features Ontology', 'SO is a collaborative ontology project for the definition of sequence features used in biological sequence annotation. SO was initially developed by the Gene Ontology Consortium. Contributors to SO include the GMOD community, model organism database groups such as WormBase, FlyBase, Mouse Genome Informatics group, and institutes such as the Sanger Institute and the EBI. Input to SO is welcomed from the sequence annotation community. The OBO revision is available here: http://sourceforge.net/p/song/svn/HEAD/tree/', 'Genomic_and_Proteomic', 'OWL', 315, 'unknown', '2026-08-07T18:12:58.000-07:00', 'https://bioportal.bioontology.org/ontologies/SO', 'd5beb212d4adca459eccf6c7f74abdca534f25074a36b78ef2271b4b2e538907', 'scored', NULL, 10.0, 6.08, 6.08, 'same_as_strict (1.0 result, not re-checked)', 6.74, 10.0, 8.205, 8.205, NULL, NULL, NULL, 49262, 2753, 2753, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:13:36+00:00', '2026-09-23T23:25:10+00:00');
