INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SP_ONTOLOGY', 'SmartPITeS Proyect Ontology for Complex Chronic Patients', 'The ontology developed for the SmartPITeS project contains decision rules established in clinical practice on which a software developed for clinical decision support for the pharmacological prescription and de-prescription of complex chronic patients is based. Specifically patients with atrial fibrillation under treatment with anticoagulants. ', 'Health', 'OWL', 1, NULL, '2023-03-27T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SP_ONTOLOGY', 'b0a321831792868edec1a458b556f4ceb14722d29061e1a070ee94b3d5ba0d7a', 'scored', NULL, 9.97, 2.8, 2.8, 'same_as_strict (1.0 result, not re-checked)', 2.43, 10.0, 6.3, 6.3, NULL, NULL, NULL, 4176, 335, 335, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:55+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SSBD', 'SSBD Ontology', 'SSBD Ontology is a two-tier model for FAIR metadata of bioimaging.
The repository layer captures the minimum information required for rapid, DOI-based release of image datasets, while the added-value layer enriches the same instances with detailed biological context (organism, strain, cell/cell-line, anatomy, GO terms) and imaging provenance (imaging method, instrument, OME-Zarr links).
SSBD Ontology re-uses and aligns with OBO Foundry ontologies— ChEBI, CL, CLO, UBERON, GO, FBbi, OBI, IAO—so that multi scale data information can be integrated uniformly.
The ontology is distributed under CC-BY 4.0., The SSBD Ontology is an ontology of SSBD (https://ssbd.riken.jp).
SSBD is a platform for sharing and reusing bioimaging data. SSBD:database is an added-value database for bioimages and biological dynamics data. It provides a rich set of open resources for analyzing microscopy images and qunatitative data of biological objects, such as single-molecule, cell, tissue, individual, etc., and software tools for analysis. Microscopy images and quantitative biological data are collected from a variety of species, sources, and methods. These include data obtained from both experiments and computational simulations.', 'Imaging', 'OWL', 4, '2025-05-12', '2025-07-23T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SSBD', '81484fed6a9da404d3dc7d24d9f82036f8a21191dfe2d727ee1d6bc2fbb62ede', 'scored', NULL, 10.0, 2.44, 2.44, 'same_as_strict (1.0 result, not re-checked)', 2.46, 10.0, 6.225, 6.225, NULL, NULL, NULL, 21787, 1925, 1478, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:11:13+00:00', '2026-09-23T23:25:10+00:00');
