INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SSN', 'Semantic Sensor Network Ontology', 'This ontology describes sensors, actuators and observations, and related concepts. It does not describe domain concepts, time, locations, etc. these are intended to be included from other ontologies via OWL imports.', 'Other', 'OWL', 2, 'New modular version of the SSN ontology. 

This ontology was originally developed in 2009-2011 by the W3C Semantic Sensor Networks Incubator Group (SSN-XG). For more information on the group''s activities see: http://www.w3.org/2005/Incubator/ssn/. The ontology was revised and modularized in 2015-2017 by the W3C/OGC Spatial Data on the Web Working Group, see: https://www.w3.org/2015/spatial/wiki/Semantic_Sensor_Network_Ontology. 

In particular, (a) the scope is extended to include actuation and sampling; (b) the core concepts and properties are factored out into the SOSA ontology. The SSN ontology imports SOSA and adds formal axiomatization consistent with the text definitions in SOSA, and adds classes and properties to accommodate the scope of the original SSN ontology. ', '2017-04-17T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SSN', '0a72d5510b9aacb566586c57bfaaf9898953a780598318fddb5f3f0cf4e868e4', 'scored', NULL, 10.0, 4.67, 4.67, 'same_as_strict (1.0 result, not re-checked)', 5.04, 10.0, 7.4275, 7.4275, NULL, NULL, NULL, 838, 29, 23, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:53+00:00', '2026-09-23T23:25:10+00:00');
