INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'SSTIM', 'Sensory Stimulation Ontology', 'An OWL 2 ontology with a multilingual SKOS vocabulary (frequency bands, modalities, mechanisms, techniques, evidence tiers) for parameter-specified delivery of structured sensory input — techniques, protocols, implementations, exposure conditions, observations, safety metadata, and evidence-qualified claims across auditory, visual, and tactile modalities., An OWL 2 ontology for describing parameter-specified delivery of structured sensory input, including techniques, and evidence-qualified claims., The stimulus-description half of the SSTIM Core Profile: engine-independent specifications, channels, regime, duration, and optional stimulation target., The ADR 0034–0037 neuromodulation, neurostimulation, self-regulation, neural-facet, and neuroplasticity extension., Reusable technique, framework, protocol, and implementation semantics, independent of neuromodulation and evidence claims., Reusable SSTIM module for the sensory-stimulation ecosystem: a neutral agent umbrella, qualified relationship and membership records, implementation responsibility, a retractable approved public projection, append-only private operational activities, and controlled relationship, purpose, and outcome vocabularies. Carries no personal data; named agents are curated implementation data., Reusable SSTIM module for separating physical delivery medium, perceived modality, device capability, body placement, comfort boundary, experiment context, effect claims, and knowledge status., Planned stimulation interventions, session specifications and executions, configuration overrides, and consent-governed self-reports., Optional shared descriptors used across SSTIM concerns: bands, temporal structure, delivery approach, cautions, and calibrated channel quantities., Optional range axioms connecting generic evidence scope and basis relations to exposure profiles and experiment contexts., Optional outcome relations connecting generic evidence concepts with neuromodulation access-route, target-site, sy', 'Biomedical_Resources;Experimental_Conditions;Health;Vocabularies', 'OWL', 31, '0.17.0', '2026-04-12T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/SSTIM', 'a8e23c6a651b7d70b83a907457bfe80e890faee776554628e4fbd22954a9f19d', 'scored', NULL, 9.99, 6.71, 6.71, 'same_as_strict (1.0 result, not re-checked)', 2.47, 10.0, 7.2925, 7.2925, NULL, NULL, NULL, 12523, 809, 733, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:19+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'STATO', 'Statistics Ontology', 'STATO is a general-purpose STATistics Ontology. Its aim is to provide coverage for processes such as statistical tests, their conditions of applications, and information needed or resulting from statistical methods, such as probability distributions, variable, spread and variation metrics. STATO also covers aspects of experimental design and description of plots and graphical representations commonly used to provide visual cues of data distribution or layout and to assist review of the results., STATO is the statistical methods ontology. It contains concepts and properties related to statistical methods, probability distributions and other concepts related to statistical analysis, including relationships to study designs and plots.', 'Biomedical_Resources;Experimental_Conditions', 'OWL', 19, '2026-04-20', '2026-04-20T18:14:48.000-07:00', 'https://bioportal.bioontology.org/ontologies/STATO', '9cf1c851fe52e7c427ab067a1446346d377ba6e5a2156d245bbd31941ba3bea8', 'scored', NULL, 10.0, 6.5, 6.5, 'same_as_strict (1.0 result, not re-checked)', 5.25, 10.0, 7.9375, 7.9375, NULL, NULL, NULL, 23713, 1063, 1054, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:10:49+00:00', '2026-09-23T23:25:10+00:00');
