INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TARA', 'TARA Acupoints Ontology', 'The TARA Acupoints Ontology is an ontology developed as part of the Topological Atlas and Repository for Acupoint Research (TARA) project funded by the National Institute of Health (NIH). The goal of TARA is to establish a new comprehensive resource for the acupuncture research and clinician community. The ontology will be used to support semantic search and annotations for clinical trial studies, anatomical maps, and datasets relevant to the TARA project.
- About TARA Research Project: https://www.acupunctureresearch.org/tara
- TARA Ontology GitHub Repository: https://purl.org/tara/ontology/repo
- TARA Ontology Files & Updates: https://purl.org/tara/ontology/updates, and datasets relevant to the TARA project.', 'Anatomy;Biomedical_Resources;Vocabularies', 'OWL', 8, '1.7.2 - Inferred Ontology', '2026-09-09T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/TARA', 'a1581f9d5a13c4a2595c6fabdb765952aa495b1d61e90d3ca76b050007ce350d', 'scored', NULL, 9.99, 4.67, 4.67, 'same_as_strict (1.0 result, not re-checked)', 7.24, 10.0, 7.975, 7.975, NULL, NULL, NULL, 58713, 1961, 1961, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:17:20+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TAXRANK', 'Taxonomic Rank Vocabulary', 'A vocabulary of taxonomic ranks intended to replace the sets of rank terms found in the Teleost Taxonomy Ontology, the OBO translation of the NCBI taxonomy and similar OBO taxonomy ontologies.  It provides terms for taxonomic ranks drawn from both the NCBI taxonomy database and from a rank vocabulary developed for the TDWG biodiversity information standards group.  Cross references to appearances of each term in each source are provided.  Consistent with its intended use as a vocabulary of labels, there is no relation specifying an ordering of the rank terms.', '', 'OBO', 12, 'unknown', '2025-09-24T18:17:10.000-07:00', 'https://bioportal.bioontology.org/ontologies/TAXRANK', 'c5c0fcbea49756b52d3bd716b7e170c1c477e7aa87b3fc951f4885ffae05ee32', 'scored', NULL, 9.87, 0.24, 0.24, 'same_as_strict (1.0 result, not re-checked)', 0.0, 7.0, 4.2775, 4.2775, NULL, NULL, NULL, 691, 78, 78, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:35+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TCDO', 'Traditional Chinese Drug Ontology', 'More than 400 popular TCD decoction pieces (TCD-DP) were selected from authoritative textbooks, standards and terminologies, as well as their crudes, Chinese medicinal material (CMM). The TCD-DP entities are categorized in 23 upper level terms by their clinical effects. Their properties like nature, flavor, toxicity and meridian entries are also defined formally by logical relations. CMM’s species is mapped to the NCBITaxon taxonomy ontology, which establishes a link between traditional medicine and modern biomedical science. TCDO contains over 1,500 terms, including terms drawn from existing ontologies and more than 1,000 TCD-specific terms, labeled in both Chinese and English., TCDO is an open source, community-based biomedical ontology in the area of traditional Chinese medicine drugs.', '', 'OWL', 3, '0.05', '2021-05-30T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/TCDO', '1cf41cb9ef3be4056658a9c79bc8e49b7dff76dfec54d005c1940faf72cf6861', 'scored', NULL, 9.99, 0.36, 0.36, 'same_as_strict (1.0 result, not re-checked)', 4.08, 10.0, 6.1075, 6.1075, NULL, NULL, NULL, 32302, 1989, 1989, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:12:04+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TCO', 'Thyroid Cancer Ontology', 'Thyroid cancer ontology (TCO) contains 578 concepts organized under 6 biological viewpoints, i.e., Anatomy and Histoembryology, Basic Information of Patient, Cellular or Molecular Interactions, Clinical Aspects, Etiology, Pathology', 'Health;Human', 'OWL', 2, '1.0', '2020-07-02T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/TCO', '857d5a2d95beb610628f68aedd27b92e915fcd4ef24dda137067fa5021940396', 'scored', NULL, 9.98, 0.0, 6.5, 'http://www.semanticweb.org/hx-jta/ontologies/thyroid_cancer_ontology#Definition [bioportal_definitionProperty + detected_by_name]', 0.0, 10.0, 4.995, 6.62, NULL, NULL, NULL, 7432, 579, 579, '0.10.0', 'core4-1.1.1', NULL, '2026-09-23T22:57:12+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TDWGSPEC', 'TDWG Specimen LSID Ontology', 'Biodiversity Information Standards (TDWG) is an international not-for-profit group that develops standards and protocols for sharing biodiversity data. They have a detailed collection of vocabularies and ontologies for studies of biological organisms.', 'Taxonomic_Classification', 'OWL', 1, '0.3', '2015-07-01T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/TDWGSPEC', '548bc999ee4bf211be970c50a091ab65727312a91cc1acf91a1ffd2c8fce3b68', 'scored', NULL, 6.47, 0.68, 0.68, 'same_as_strict (1.0 result, not re-checked)', 0.0, 4.0, 2.7875, 2.7875, NULL, NULL, NULL, 307, 17, 10, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:19+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TEDDY', 'Terminology for the Description of Dynamics', 'The TErminology for the Description of DYnamics (TEDDY) project aims to provide an ontology for dynamical behaviours, observable dynamical phenomena, and control elements of bio-models and biological systems in Systems Biology and Synthetic Biology.', 'Other', 'OWL', 11, 'rel-2014-04-24 (inferred)', '2014-04-25T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/TEDDY', '1f5d306b5f09af2cfb72ddd37876e6dc06cf467540c2cb03a7cf70821f49673b', 'scored', NULL, 9.94, 6.75, 6.75, 'same_as_strict (1.0 result, not re-checked)', 6.71, 10.0, 8.35, 8.35, NULL, NULL, NULL, 15557, 168, 168, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:16+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TEMPO', 'TempO', 'TempO is a lightweight ontology for describing temporal validity and efficacy according to a tritemporal data model., In a typical (uni)temporal data model every resource''s appearance (and disappearance) is being tracked.
Numerous systems accomplish unitemporal tracking, either externally by e.g. using git to record the insertion or deletion of a resource, or internally by e.g. using prov:generatedAtTime and prov:invalidatedAtTime.
This axis of time is known as *system time*, and none of TempO''s concern because for one there is readily available support, and moreover because unitemporal tracking is used for principally true statements, i.e. those that have always been (considered) true or will always be (considered) true.

TempO addresses bitemporal and tritemporal setups: Resources which are (known or believed to be) valid and efficacious for some time.
A second time axis orthogonal to system time is introduced, that is a resource can be valid even though it is currently not in the system, or, conversely, can be already or still invalid by the time it enters the system.

Efficacy, sometimes called decision time, is yet another concept orthogonal to validity, i.e. a resource that is no longer or not yet valid can be efficacious.
The converse, a valid but inefficacious resource in the system, is *usually* not encountered but TempO does not impose restrictions on the shape of the time area.

In general the necessity for tracking both validity and efficacy arises in areas where concepts are assigned a code or label that is subject to reuse following invalidation.
Tracking efficacy and validity concurrently then allows for fine-grained control over how much future knowledge or how much past knowledge we tolerate in a datset.

Example:
--------
Czechoslovakia was founded in 1918 but became part of Germany, Hungary and Poland in 1938.
It was reestablished in 1945 but split into two sovereign states in 1993.
The ISO 3166 country code for Czechoslovakia used to be ''CS'', ass', 'Other', 'OWL', 4, '0.2', '2022-05-26T05:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/TEMPO', 'fa36561691d92d922e02b81844b39120595a2fcb300efc5ff6ae27277082e71e', 'scored', NULL, 5.0, 3.64, 3.64, 'same_as_strict (1.0 result, not re-checked)', 0.0, 0.0, 2.16, 2.16, NULL, NULL, NULL, 71, 2, 2, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:09+00:00', '2026-09-23T23:25:10+00:00');
