INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'THREE-ST', '3-Step Theory of suicide', 'This ontology contains classes, sub-classes, and relationships that map onto the 3-Step Theory of suicide (3ST). The classes represent the four factors that make up the central tenets of the theory: 1) psychological pain, 2) hopelessness, 3) connectedness, and 4) capacity for suicide. The instances of each subclass are terms that were found in VA clinical notes and indicate presence or absence of the associated 3ST factor. The terms are intended to be used in an NLP pipeline to extract 3ST information from clinical progress notes.
Psychological pain, hopelessness, and capacity for suicide are major risk factors for suicide, whereas connectedness is a protective factor. In brief, the theory holds that suicide only occurs if pain and hopelessness outweigh connectedness and only then if the capacity for suicide is present.', 'Health;Human', 'OWL', 4, '1.0.1', '2023-07-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/THREE-ST', '892be685d01bc6b2e5e836f4d5d92cc3638cc9df32c0788149d3c0784c1ed161', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 9.0, 4.75, 4.75, NULL, NULL, NULL, 73096, 8533, 49, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:19:12+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TIME', 'OWL-Time', 'OWL-Time is an OWL-2 DL ontology of temporal concepts, for describing the temporal properties of resources in the world or described in Web pages. The ontology provides a vocabulary for expressing facts about topological (ordering) relations among instants and intervals, together with information about durations, and about temporal position including date-time information. Time positions and durations may be expressed using either the conventional (Gregorian) calendar and clock, or using another temporal reference system such as Unix-time, geologic time, or different calendars.', 'Other', 'OWL', 4, '2017', '2020-04-17T18:13:50.000-07:00', 'https://bioportal.bioontology.org/ontologies/TIME', '51c80c4e9a7fd933784a5bc72250399bf92423d782a981d9c8b8c2d746a5db8a', 'scored', NULL, 10.0, 3.92, 3.92, 'same_as_strict (1.0 result, not re-checked)', 2.53, 7.0, 5.8625, 5.8625, NULL, NULL, NULL, 1336, 35, 21, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:29+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TIMEBANK', 'Timebank Ontology', 'The Timebank Ontology is used to describe Timebank systems for Peer-to-Peer Service Exchange. A Timebank allows user to store virtual money, often called a Time Dollar, into a bank account. This virtual currency can be earned by helping fellow Timebank users and spent by requesting help from others. The main goal of the ontology is to facilitate the matching between helpers and requesters of help.', 'Human;Other', 'OWL', 2, '0.3', '2020-08-05T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/TIMEBANK', 'fba1bd3d237b1feadaa71b4e196cf7ff49ea100205d832f51b5e15fc27a02617', 'scored', NULL, 9.64, 5.74, 5.74, 'same_as_strict (1.0 result, not re-checked)', 5.39, 10.0, 7.6925, 7.6925, NULL, NULL, NULL, 1559, 140, 133, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:19+00:00', '2026-09-23T23:25:10+00:00');
