INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TMA', 'Tissue Microarray Ontology', 'Tissue microarrays (TMA) are enormously useful tools for translational research, but incompatibilities in database systems between various researchers and institutions prevent the efficient sharing of data that could help realize their full potential.  The Resource Description Framework (RDF) provides a flexible method to represent knowledge in triples, which take the form Subject-Predicate-Object.  All data resources are described using Uniform Resource Identifiers (URI), which are global in scope.  We present an OWL (Web Ontology Language) schema that expands upon the TMA data exchange specification to address this issue and assist in data sharing and integration.', 'Biomedical_Resources;Experimental_Conditions;Other', 'OWL', 1, '1.0.0', '2010-05-07T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/TMA', 'a2662328cd6eef69f05d157782b7d7e4dd6363e001d78ea46570cb08e5b73972', 'scored', NULL, 8.75, 2.33, 2.33, 'same_as_strict (1.0 result, not re-checked)', 0.0, 6.0, 4.27, 4.27, NULL, NULL, NULL, 163, 8, 8, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:03:55+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TML', 'trasformative machine learning metadata', 'a set of metadata to record transformative machine learning experiments with LINCS dataset', 'Other;Vocabularies', 'OWL', 1, '0.1', '2020-07-21T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/TML', '7eadfd63ac1da42b989f7562533903004eec9cae026bc0174529b4f31cea9094', 'scored', NULL, 8.12, 4.04, 4.04, 'same_as_strict (1.0 result, not re-checked)', 0.0, 4.0, 4.04, 4.04, NULL, NULL, NULL, 67, 16, 13, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:03:43+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TMO', 'Translational Medicine Ontology', 'This project focuses on the development of a high level patient-centric ontology for the pharmaceutical industry. The ontology should enable silos in discovery research, hypothesis management, experimental studies, compounds, formulation, drug development, market size, competitive data, population data, etc. to be brought together. This would enable scientists to answer new questions, and to answer existing scientific questions more quickly. This will help pharmaceutical companies to model patient-centric information, which is essential for the tailoring of drugs, and for early detection of compounds that may have sub-optimal safety profiles. The ontology should link to existing publicly available domain ontologies.', 'All_Organisms;Health', 'OWL', 13, '1.0.2', '2016-05-16T18:27:01.000-07:00', 'https://bioportal.bioontology.org/ontologies/TMO', 'b0f384cd370fddb16e3422085a4719700cf046539a357144e7c62e753806d22a', 'scored', NULL, 9.96, 0.16, 0.16, 'same_as_strict (1.0 result, not re-checked)', 0.72, 9.0, 4.96, 4.96, NULL, NULL, NULL, 1599, 241, 226, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:05:38+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TOK', 'Terminological and Ontological Knowledge Resources Ontology', 'An Ontology describing Resources having different formats. This Ontology can be used to annotate and describe Terminological, Ontological Knowledge resources.', 'Taxonomic_Classification', 'OWL', 3, '0.2.1', '2010-01-01T00:00:00.000-08:00', 'https://bioportal.bioontology.org/ontologies/TOK', 'e51a3048c237dac48f3a60d318b2b445d7f04d3dc29bf9862e84632a23f9daa9', 'scored', NULL, 10.0, 0.84, 0.84, 'same_as_strict (1.0 result, not re-checked)', 8.27, 10.0, 7.2775, 7.2775, NULL, NULL, NULL, 4660, 218, 193, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:06:42+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TOP-MENELAS', 'Menelas Project Top-Level Ontology', 'The two main goals MENELAS contributes to are to (i) Provide better account of and better access to medical information through natural languages in order to help physicians in their daily practice, and to (ii) Enhance European cooperation by multilingual access to standardised medical nomenclatures. The major achievements of MENELAS are the realisation of its two functional systems: (i) The Document Indexing System encodes free text PDSs into both an internal representation (a set of Conceptual Graphs) and international nomenclature codes (ICD-9-CM). Instances of the Document Indexing System have been realised for French, English and Dutch ; (ii) The Consultation System allows users to access the information contained in PDSs previously indexed by the Document Indexing System. The test domain for the project was coronary diseases. The existing prototype shows promising results for information retrieval from natural language PDSs and for automatically encoding PDSs into an existing classification such as ICD-9-CM. A set of components, tools, knowledge bases and methods has also been produced by the project. These include language-independent ontology and models for the domain of coronary diseases; conceptual description of the relevant ICD-9-CM codes.
This ontology includes a top-ontology, a top-domain ontology and a domain ontology (Coronay diseases surgery). The menelas-top ontology here is the part of the whole ontology without any reference to medical domain.
', '', 'OWL', 8, '1.0', '2018-01-26T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/TOP-MENELAS', '3e3ac0372cd0660a9a398381322a8d992174574c0e8c06c541241803866a411f', 'scored', NULL, 9.98, 2.81, 2.81, 'same_as_strict (1.0 result, not re-checked)', 0.0, 10.0, 5.6975, 5.6975, NULL, NULL, NULL, 5506, 459, 459, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:07:28+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TP4', 'Oualid', 'relation familiales ', 'Other', 'OWL', 1, NULL, '2023-07-02T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/TP4', '88b0f2fc2ffd3fb1ce0bc67972ec5f0aad337580d2e4c79ae1d3dcfdbab8e849', 'scored', NULL, 3.75, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 5.96, 6.0, 3.9275, 3.9275, NULL, NULL, NULL, 505, 24, 10, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:04:31+00:00', '2026-09-23T23:25:10+00:00');
