INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TRAK', 'Taxonomy for Rehabilitation of Knee Conditions', 'TRAK (Taxonomy for RehAbilitation of Knee conditions) is an ontology that formally models information relevant for the rehabilitation of knee conditions. TRAK provides the framework that can be used to collect coded data in sufficient detail to support epidemiologic studies so that the most effective treatment components can be identified, new interventions developed and the quality of future randomized control trials improved to incorporate a control intervention that is well defined and reflects clinical practice. ', 'Biomedical_Resources', 'OBO', 5, 'unknown', '2015-09-14T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/TRAK', '31f5e71a8a83f740ff5f1613af92139c9afb958ecfe2de16f7143762b4029949', 'scored', NULL, 9.99, 4.05, 4.05, 'same_as_strict (1.0 result, not re-checked)', 4.79, 10.0, 7.2075, 7.2075, NULL, NULL, NULL, 21802, 1620, 1620, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:11:02+00:00', '2026-09-23T23:25:10+00:00');
