INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TTO', 'Teleost Taxonomy Ontology', 'The Teleost taxonomy ontology is being used to facilitate annotation of phenotypes, particularly for taxa that are not covered by NCBI because no submissions of molecular data have been made. Taxonomy ontologies can also be valuable in annotating legacy data, where authors make phenotype or ecological assertions (e.g., host-parasite associations) that refer to groups that are reorganized or no longer recognized. The taxonomy ontology serves as the source of taxa for our project''s use for identifying evolutionary changes that match the phenotype of a zebrafish mutant.', 'Taxonomic_Classification', 'OWL', 44, 'unknown', '2012-07-19T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/TTO', 'a14d67ede2f935796b9851074d61b384e62a09369d4eca87f8fdb9f8f9b68f0b', 'scored', NULL, 10.0, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 5.12, 10.0, 6.28, 6.28, NULL, NULL, NULL, 689046, 38706, 38706, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T03:27:26+00:00', '2026-09-23T23:25:10+00:00');
