Application system TOXPILOT:
https://toxpilot.nibiohn.go.jp', 'Biological_Process;Dysfunction', 'OWL', 31, '2022/12/07', '2022-12-07T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/TXPO', 'de2870cb042008b10ffc796da944ed0d6dd4762f209964d9f82bcd30cd0aaaa4', 'scored', NULL, 10.0, 4.4, 4.4, 'same_as_strict (1.0 result, not re-checked)', 5.81, 10.0, 7.5525, 7.5525, NULL, NULL, NULL, 171438, 9407, 9407, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:25:33+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'TYPON', 'Microbial Typing Ontology', 'TyPon provides a comprehensive description of the existing microbial typing methods for the identification of bacterial Isolates and their classification. Such a description constitutes an universal format for the exchange of information on the microbial typing field, providing a vehicle for the integration of the numerous disparate online databases. In its current version, TyPon describes most used microbial typing methods but it is, and always will be, a work in progress given the constant advances in the microbial typing field.', '', 'OWL', 11, '20140929', '2014-09-29T14:45:25.000-07:00', 'https://bioportal.bioontology.org/ontologies/TYPON', '198060f1bee1aeae1426873f3c291aecbdbc0073745157040802e26392de9af3', 'scored', NULL, 9.78, 3.87, 3.87, 'same_as_strict (1.0 result, not re-checked)', 3.19, 8.0, 6.21, 6.21, NULL, NULL, NULL, 745, 45, 45, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:04:46+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'UBERON', 'Uber Anatomy Ontology', 'Uberon is an integrated cross-species anatomy ontology representing a variety of entities classified according to traditional anatomical criteria such as structure, function and developmental lineage. The ontology includes comprehensive relationships to taxon-specific anatomical ontologies, allowing integration of functional, phenotype and expression data.', 'Anatomy;Gross_Anatomy', 'OWL', 355, '2023-07-25', '2026-06-23T18:13:23.000-07:00', 'https://bioportal.bioontology.org/ontologies/UBERON', '1b6aa15c0eb6dcf0f30d1306d7251b4d62f921d36aaa71c150e1796f0e003941', 'scored', NULL, 10.0, 5.5, 5.5, 'same_as_strict (1.0 result, not re-checked)', 8.56, 10.0, 8.515, 8.515, NULL, NULL, NULL, 1252826, 26674, 26625, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:56:07+00:00', '2026-09-23T23:25:10+00:00');
