INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'UPA', 'Unipathway', 'UniPathway (http://www.unipathway.org) is a fully manually curated resource for the representation and annotation of metabolic pathways. UniPathway provides explicit representations of enzyme-catalyzed and spontaneous chemical reactions, as well as a hierarchical representation of metabolic pathways. This hierarchy uses linear subpathways as the basic building block for the assembly of larger and more complex pathways, including species-specific pathway variants. All of the pathway data in UniPathway has been extensively cross-linked to existing pathway resources such as KEGG and MetaCyc, as well as sequence resources such as the UniProt KnowledgeBase (UniProtKB), for which UniPathway provides a controlled vocabulary for pathway annotation. We introduce here the basic concepts underlying the UniPathway resource, with the aim of allowing users to fully exploit the information provided by UniPathway.', '', 'OWL', 2, 'UniPathway Release 2015_03', '2024-03-07T18:15:34.000-08:00', 'https://bioportal.bioontology.org/ontologies/UPA', '32f6f41cea2363b10e5860ebc54f99bca53ebe1c071a7419edfee5fe14e5fd53', 'scored', NULL, 10.0, 3.23, 3.23, 'same_as_strict (1.0 result, not re-checked)', 9.12, 10.0, 8.0875, 8.0875, NULL, NULL, NULL, 265324, 4673, 4673, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:25:46+00:00', '2026-09-23T23:25:10+00:00');
