INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'VHOG', 'Vertebrate Homologous Organ Group Ontology', 'vHOG is a multi-species anatomical ontology for the vertebrate lineage, developed as part of the Bgee project.
The mapping to species-specific anatomical ontologies is provided as a separated file:
http://bgee.unil.ch/download/organ_association_vHOG.txt
This mapping represents homology-strict relationships, in the sense of HOM:0000007 "historical homology". Each mapping has been manually reviewed, and we provide confidence codes and references when available.', 'Anatomy;Animal_Development;Animal_Gross_Anatomy;Fish_Anatomy;Gross_Anatomy;Human;Human_Developmental_Anatomy;Mouse_Anatomy', 'OBO', 13, 'unknown', '2023-11-21T18:26:04.000-08:00', 'https://bioportal.bioontology.org/ontologies/VHOG', 'b3f163e58d635a04ffc63041a0d036ce8c9c652f5675e61c27d91d01582fd9ae', 'scored', NULL, 9.99, 2.92, 2.92, 'same_as_strict (1.0 result, not re-checked)', 7.26, 10.0, 7.5425, 7.5425, NULL, NULL, NULL, 18509, 1186, 1186, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:10:14+00:00', '2026-09-23T23:25:10+00:00');
