INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'VSO', 'Vital Sign Ontology', 'The Vital Sign Ontology (VSO) is an extension of the Ontology for General Medical Science (OGMS). VSO covers the four consensus human vital signs: blood pressure, body temperature, respiration rate, pulse rate. 
VSO provides also a controlled structured vocabulary for describing vital signs measurement data, the various processes of measuring vital signs, and the various devices and anatomical entities participating in such measurements. ', 'Health', 'OWL', 1, '2012-04-25', '2012-04-25T00:00:00.000-07:00', 'https://bioportal.bioontology.org/ontologies/VSO', '8182218aa800a9117f6544ae3350aa3a2345761a0ca9686a5abf2bbe722648e0', 'scored', NULL, 10.0, 3.2, 3.2, 'same_as_strict (1.0 result, not re-checked)', 3.82, 9.0, 6.505, 6.505, NULL, NULL, NULL, 12642, 161, 159, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:09:13+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'VT', 'Vertebrate Trait Ontology', 'The Vertebrate Trait Ontology is a controlled vocabulary for the description of traits (measurable or observable characteristics) pertaining to the morphology, physiology, or development of vertebrate organisms.', '', 'OBO', 209, '2026-09-09', '2026-09-09T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/VT', 'd0cfb119c6d7efd337959ffae339651d9696ad08d36095d33fc4ad422e5de5e6', 'scored', NULL, 10.0, 6.65, 6.65, 'same_as_strict (1.0 result, not re-checked)', 7.68, 10.0, 8.5825, 8.5825, NULL, NULL, NULL, 68995, 4134, 4134, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T06:18:52+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'VTO', 'Vertebrate Taxonomy Ontology', 'The Vertebrate Taxonomy Ontology includes both extinct and extant vertebrates, aiming to provide one comprehensive hierarchy. The hierarchy backbone for extant taxa is based on the NCBI taxonomy. Since the NCBI taxonomy only includes species associated with archived genetic data, to complement this, we also incorporate taxonomic information across the vertebrates from the Paleobiology Database (PaleoDB). The Teleost Taxonomy Ontology (TTO) and AmphibiaWeb (AWeb) are incorporated to provide a more authoritative hierarchy and a richer set of names for specific taxonomic groups.', 'Taxonomic_Classification', 'OWL', 14, 'unknown', '2020-11-13T18:16:20.000-08:00', 'https://bioportal.bioontology.org/ontologies/VTO', '02522f07577ac456ddfbe4329d8b292f08d922453e0cac8bf7e33818eb7f7aa5', 'scored', NULL, 10.0, 0.01, 0.01, 'same_as_strict (1.0 result, not re-checked)', 2.96, 10.0, 5.7425, 5.7425, NULL, NULL, NULL, 1505044, 107255, 107255, '0.10.0', 'core4-1.0', 'cuda', '2026-09-23T07:10:13+00:00', '2026-09-23T23:25:10+00:00');
INSERT OR REPLACE INTO ontology_scores (provider, acronym, name, description, categories, ontology_language, submission_id, version, released, bioportal_url, file_sha256, status, status_detail, describe_score, define_score, define_bp_score, define_bp_source, connection_score, flat_score, core_average, core_average_bp, logical_consistency_score, structural_dist_score, semantic_dist_score, triple_count, entity_count, class_count, wiseowl_version, core4_version, device, evaluated_at, updated_at) VALUES ('bioportal', 'VVMM', 'In Vivo Methodologies Ontology for MAATrica metric', 'MAATrica is a novel metric for assessing the coherence of methodologies in research papers within the fields of medicinal and nutraceutical chemistry. MAATrica employs user-controlled and customizable ontologies (in silico, in vitro and in vivo), enabling personalized analysis of research papers in the fields of medicinal and nutraceutical chemistry. Here we present the in vivo ontology we developed for the scope.', 'Anatomy;Biological_Process;Biomedical_Resources;Vocabularies', 'OBO', 1, NULL, '2024-04-21T00:00:00.000+00:00', 'https://bioportal.bioontology.org/ontologies/VVMM', '70af9c102e22663cb11b456b64baa0c2e00d6725ddeed21e792982886f96fd52', 'scored', NULL, 9.92, 0.0, 0.0, 'same_as_strict (1.0 result, not re-checked)', 0.0, 6.0, 3.98, 3.98, NULL, NULL, NULL, 895, 126, 126, '0.10.0', 'core4-1.0', NULL, '2026-09-23T06:05:00+00:00', '2026-09-23T23:25:10+00:00');
